@dataclass
class QueueContinuity:
    address: str
    root: str
    count: int
    cursor: int
    escrow_balance: int
    last_due_at: int
    descriptors: list[Message] = field(default_factory=list)
    active_settlement_address: str = ""
    router_address: str = "active-settlement-router"
    claimable: dict[str, int] = field(default_factory=dict)
    runtime_hash: str = "code:forced-queue:v2"
    config_hash: str = "config:forced-queue:depth64:v2"
    nonproxy: bool = True
    selfdestruct_disabled: bool = True
    delegate_target_reachable: bool = False
    deposit_prefix: list[int] = field(default_factory=list)
    unconsumed_escrow: int | None = None
    total_claimable: int | None = None
    append_fault_point: str | None = field(default=None, compare=False)
    _router_authority: object | None = field(
        default=None, init=False, compare=False, repr=False
    )

    def __setattr__(self, name: str, value: object) -> None:
        immutable = {
            "address", "router_address", "runtime_hash", "config_hash",
            "nonproxy", "selfdestruct_disabled", "delegate_target_reachable",
            "_router_authority",
        }
        if name in immutable and name in self.__dict__:
            raise AttributeError(f"forced queue {name} is immutable")
        object.__setattr__(self, name, value)

    def __post_init__(self) -> None:
        if not self.deposit_prefix:
            self.deposit_prefix = [0]
            for row in self.descriptors:
                self.deposit_prefix.append(
                    self.deposit_prefix[-1] + row.prepaid)
        assert len(self.deposit_prefix) == self.count + 1
        if self.unconsumed_escrow is None:
            self.unconsumed_escrow = (
                self.deposit_prefix[self.count]
                - self.deposit_prefix[self.cursor])
        if self.total_claimable is None:
            self.total_claimable = sum(self.claimable.values())
        assert (self.escrow_balance
                >= self.unconsumed_escrow + self.total_claimable)

    def __deepcopy__(self, memo: dict[int, object]) -> "QueueContinuity":
        """Copy state without traversing an unrelated Router authority graph."""

        duplicate = object.__new__(type(self))
        memo[id(self)] = duplicate
        for key, value in self.__dict__.items():
            if key == "_router_authority":
                authority = memo.get(id(value), value)
                object.__setattr__(duplicate, key, authority)
            else:
                object.__setattr__(duplicate, key, copy.deepcopy(value, memo))
        return duplicate

    def _bind_router_once(self, router: object) -> bool:
        if (self._router_authority is not None
                or type(router) is not ActiveSettlementRouter
                or getattr(router, "forced_queue", None) is not self
                or getattr(router, "address", None) != self.router_address):
            return False
        object.__setattr__(self, "_router_authority", router)
        return True

    def _transaction_snapshot(self) -> dict[str, object]:
        return copy.deepcopy({
            key: value for key, value in self.__dict__.items()
            if key != "_router_authority"
        })

    def _restore_transaction_snapshot(
        self, snapshot: dict[str, object]
    ) -> None:
        authority = self._router_authority
        self.__dict__.clear()
        self.__dict__.update(snapshot)
        object.__setattr__(self, "_router_authority", authority)

    @property
    def accounted_liabilities(self) -> int:
        assert self.unconsumed_escrow is not None
        assert self.total_claimable is not None
        return self.unconsumed_escrow + self.total_claimable

    def force_eth(self, amount: int) -> bool:
        """Model ETH received outside append (for example SELFDESTRUCT)."""
        if amount <= 0:
            return False
        self.escrow_balance += amount
        assert self.escrow_balance >= self.accounted_liabilities
        return True

    def _append_from_router(
        self,
        descriptor: Message,
        *,
        deposit: int,
        due_at: int,
        router: "ActiveSettlementRouter",
    ) -> int | None:
        if (type(router) is not ActiveSettlementRouter
                or router is not self._router_authority
                or router.forced_queue is not self
                or router.address != self.router_address
                or not descriptor.payload_hash or deposit <= 0
                or descriptor.prepaid != deposit
                or due_at < self.last_due_at
                or self.count >= MAX_FORCE_QUEUE_ITEMS
                or self.count != len(self.descriptors)):
            return None
        index = self.count
        stored = replace(descriptor, due_at=due_at)
        self.descriptors.append(stored)
        if self.append_fault_point == "after_descriptor":
            raise RuntimeError("injected queue append fault: after_descriptor")
        self.count += 1
        self.escrow_balance += deposit
        assert self.unconsumed_escrow is not None
        self.unconsumed_escrow += deposit
        self.deposit_prefix.append(self.deposit_prefix[-1] + deposit)
        self.last_due_at = due_at
        self.root = model_force_root(self.descriptors)
        return index

    def _bootstrap_active_settlement_from_router(
        self,
        *,
        expected_old: str,
        settlement: "VersionedSettlementHistory",
        router: "ActiveSettlementRouter",
    ) -> bool:
        if (type(router) is not ActiveSettlementRouter
                or router is not self._router_authority
                or router.forced_queue is not self
                or router.address != self.router_address
                or type(settlement) is not VersionedSettlementHistory
                or router._queue_transition_frame
                    != ("BOOTSTRAP", id(settlement), settlement.address)
                or not settlement.address
                or self.active_settlement_address != expected_old):
            return False
        self.active_settlement_address = settlement.address
        return True

    def _advance_accounting(
        self, expected_start: int, end: int, beneficiary: str
    ) -> bool:
        if (not beneficiary or expected_start != self.cursor
                or not expected_start <= end <= self.count):
            return False
        consumed_deposit = (self.deposit_prefix[end]
                            - self.deposit_prefix[expected_start])
        if consumed_deposit:
            self.claimable[beneficiary] = (
                self.claimable.get(beneficiary, 0) + consumed_deposit)
            assert (self.unconsumed_escrow is not None
                    and self.total_claimable is not None
                    and consumed_deposit <= self.unconsumed_escrow)
            self.unconsumed_escrow -= consumed_deposit
            self.total_claimable += consumed_deposit
        self.cursor = end
        assert self.escrow_balance >= self.accounted_liabilities
        return True

    def _advance_from_active_settlement(
        self,
        *,
        settlement: "VersionedSettlementHistory",
        candidate: Candidate,
    ) -> bool:
        """Adopt only the exact active Settlement's current winner frame."""

        router = self._router_authority
        registration = (
            router.registrations.get(router.active_version)
            if type(router) is ActiveSettlementRouter else None
        )
        protocol = (
            settlement.live_protocol
            if type(settlement) is VersionedSettlementHistory else None
        )
        if (type(router) is not ActiveSettlementRouter
                or type(registration) is not SettlementRegistration
                or registration.settlement is not settlement
                or type(protocol) is not Protocol
                or protocol.forced_queue is not self
                or protocol.versioned_history is not settlement
                or self.active_settlement_address != settlement.address
                or type(candidate) is not Candidate
                or not candidate.blocks
                or protocol._canonical_commit_frame != (
                    id(candidate), candidate_inbox_execution_digest(candidate)
                )):
            return False
        return self._advance_accounting(
            candidate.blocks[0].inbox_pre_cursor,
            candidate.tip.inbox_post_cursor,
            candidate.beneficiary,
        )

    def _activate_and_advance_from_router(
        self,
        *,
        expected_old: str,
        settlement: "VersionedSettlementHistory",
        proof: VerifiedMigrationExecutionOutput,
        router: "ActiveSettlementRouter",
    ) -> bool:
        """Atomically switch authority and adopt one sealed migration range."""

        if (type(router) is not ActiveSettlementRouter
                or router is not self._router_authority
                or router.forced_queue is not self
                or router.address != self.router_address
                or type(settlement) is not VersionedSettlementHistory
                or type(proof) is not VerifiedMigrationExecutionOutput
                or proof.beneficiary != proof.candidate.beneficiary
                or router._queue_transition_frame
                    != ("MIGRATION", id(proof), proof.digest)
                or self.active_settlement_address != expected_old
                or not settlement.address
                or proof.start_cursor != self.cursor
                or not proof.start_cursor <= proof.end_cursor <= self.count):
            return False
        # All fallible checks precede both writes, matching one Router call.
        self.active_settlement_address = settlement.address
        return self._advance_accounting(
            proof.start_cursor, proof.end_cursor, proof.beneficiary
        )

    def withdraw_claimable(self, beneficiary: str) -> int:
        amount = self.claimable.get(beneficiary, 0)
        if amount <= 0 or amount > self.escrow_balance:
            return 0
        self.claimable[beneficiary] = 0
        assert self.total_claimable is not None
        self.total_claimable -= amount
        self.escrow_balance -= amount
        assert self.escrow_balance >= self.accounted_liabilities
        return amount


@dataclass(frozen=True)
class MigrationTransientState:
    normal_best_present: bool
    recovery_active: bool
    live_data_sessions: int
    unsettled_reward_preparation: int
    claim_only_surfaces_preserved: bool

    @property
    def settled(self) -> bool:
        return (not self.normal_best_present and not self.recovery_active
                and self.live_data_sessions == 0
                and self.unsettled_reward_preparation == 0
                and self.claim_only_surfaces_preserved)


@dataclass
class VersionedSettlementHistory:
    """Immutable Settlement whose history ring is written internally."""

    address: str
    runtime_hash: str
    protocol_version: int
    execution_profile_hash: str
    core: CanonicalCore
    canonicalized_at_block: int
    forced_queue: QueueContinuity
    execution_profile: "ExecutionProfile" = field(compare=False, repr=False)
    mode: str = "PREACTIVE"
    nonproxy: bool = True
    selfdestruct_disabled: bool = True
    current_sequence: int = -1
    last_canonical_l1_block: int = 0
    history: dict[int, tuple[int, CanonicalTerminalCommitment]] = field(
        default_factory=dict)
    migration_gate: MigrationGate = field(default_factory=MigrationGate)
    live_protocol: Protocol | None = None
    inbox_apply_descriptor: InboxApplyDeploymentDescriptor | None = None
    builder_registry_id: str = "builder-registry"
    schedule_oracle_id: str = "schedule-oracle"
    release_profile_ingress_specs: tuple[
        tuple[ForceKind, str, str], ...
    ] = (
        (ForceKind.USER_TX, "kind0-adapter", ""),
        (ForceKind.BRIDGE_CREDIT, "bridge-inbox-adapter", "bridge:A"),
    )
    source_bridge_descriptor: "SourceBridgeDescriptor | None" = None
    ingress_fee_schedule: tuple[int, int, int, int, int] = (
        INGRESS_FIXED_WEI,
        INGRESS_EXECUTION_WEI_PER_GAS,
        INGRESS_PROOF_WEI_PER_GAS,
        INGRESS_PERMANENT_WEI_PER_BYTE,
        INGRESS_MAXIMUM_ACCEPTED_FEE_WEI,
    )
    market_settlement_chain_id: int = 1
    market_runtime_hash: bytes = b"r" * 32
    market_configuration_hash: bytes = b"c" * 32
    market_magic: bytes = b"SEAT"
    header_oracle: L1HeaderOracle | None = field(default=None, compare=False)
    _router_authority: object | None = field(
        default=None, compare=False, repr=False
    )

    def __post_init__(self) -> None:
        if (type(self.execution_profile) is not ExecutionProfile
                or not self.execution_profile.structurally_valid()
                or self.execution_profile.protocol_version
                    != self.protocol_version
                or self.execution_profile.execution_profile_hash
                    != self.execution_profile_hash
                or (self.source_bridge_descriptor is not None
                    and type(self.source_bridge_descriptor)
                        is not SourceBridgeDescriptor)):
            raise ValueError("Settlement execution profile is not exact")

    def __setattr__(self, name: str, value: object) -> None:
        immutable = {
            "address", "runtime_hash", "protocol_version",
            "execution_profile_hash", "execution_profile", "forced_queue",
            "migration_gate",
            "inbox_apply_descriptor", "builder_registry_id", "schedule_oracle_id",
            "release_profile_ingress_specs", "source_bridge_descriptor",
            "ingress_fee_schedule",
            "market_settlement_chain_id", "market_runtime_hash",
            "market_configuration_hash", "market_magic", "header_oracle",
            "_router_authority",
        }
        if name in immutable and name in self.__dict__:
            raise AttributeError(f"Settlement {name} is immutable")
        object.__setattr__(self, name, value)

    def exact_market_target_state(self) -> tuple[object, ...]:
        """Derive the Market read word from this exact target-local graph."""

        phases = {
            "ACTIVE": "ACTIVE",
            "MIGRATION_ARMED": "ARMED",
            "MIGRATION_READY": "READY",
            "FROZEN": "FROZEN",
        }
        protocol = self.live_protocol
        router = self._router_authority
        registration = (
            None
            if type(router) is not ActiveSettlementRouter
            else router.registrations.get(self.protocol_version)
        )
        if (
            protocol is None
            or type(router) is not ActiveSettlementRouter
            or registration is None
            or registration.settlement is not self
            or (
                self.mode == "FROZEN"
                and router.active_version <= self.protocol_version
            )
            or (
                self.mode != "FROZEN"
                and router.active_version != self.protocol_version
            )
            or protocol.versioned_history is not self
            or protocol.settlement_address != self.address
            or self.header_oracle is not router.header_oracle
            or protocol.header_oracle is not router.header_oracle
            or self.forced_queue is not router.forced_queue
            or protocol.forced_queue is not router.forced_queue
            or self.inbox_apply_descriptor != router.inbox_apply_descriptor
            or protocol.inbox_apply_descriptor
                != self.inbox_apply_descriptor
            or self.migration_gate is not router.migration_gate
            or protocol.migration_gate is not self.migration_gate
            or self.mode not in phases
        ):
            raise ValueError("Settlement target/history graph is split")
        return (
            self.address,
            self.market_settlement_chain_id,
            self.protocol_version,
            self.market_runtime_hash,
            self.market_configuration_hash,
            self.market_magic,
            phases[self.mode],
            protocol.seat_generation,
        )

    def _entry(self, sequence: int, core: CanonicalCore,
               canonicalized_at_block: int) -> CanonicalTerminalCommitment:
        return CanonicalTerminalCommitment(
            self.protocol_version, self.execution_profile_hash, sequence,
            core.l2_block_number, core.tip_hash, core.state_root,
            core.terminal_root, core.terminal_count, canonicalized_at_block)

    def _install_imported_from_router(
        self,
        *,
        router: object,
        sequence: int,
        clock: Clock,
    ) -> bool:
        """Install one imported core only through the exact bound router."""

        if (type(router) is not ActiveSettlementRouter
                or type(clock) is not Clock
                or self.header_oracle is not router.header_oracle
                or self.migration_gate is not router.migration_gate
                or router.forced_queue is not self.forced_queue
                or self.inbox_apply_descriptor
                    != router.inbox_apply_descriptor
                or (
                    self._router_authority is not None
                    and self._router_authority is not router
                )
                or self.mode != "PREACTIVE" or self.history or sequence < 0
                or sequence >= UINT64_MAX
                or self.canonicalized_at_block <= 0
                or clock.block_number < self.canonicalized_at_block):
            return False
        entry = self._entry(sequence, self.core, self.canonicalized_at_block)
        self.history[sequence % CANONICAL_HISTORY_CAPACITY] = (sequence, entry)
        self.current_sequence = sequence
        self.last_canonical_l1_block = clock.block_number
        object.__setattr__(self, "_router_authority", router)
        return True

    def _record_canonical_from_protocol(
        self,
        *,
        protocol: object,
        clock: Clock,
    ) -> int | None:
        """Derive and append canonical state from the exact live Protocol."""

        router = self._router_authority
        registration = (
            None
            if type(router) is not ActiveSettlementRouter
            else router.registrations.get(self.protocol_version)
        )
        if (type(protocol) is not Protocol
                or type(clock) is not Clock
                or type(router) is not ActiveSettlementRouter
                or protocol is not self.live_protocol
                or protocol.header_oracle is not router.header_oracle
                or self.header_oracle is not router.header_oracle
                or self.migration_gate is not router.migration_gate
                or self.forced_queue is not router.forced_queue
                or self.inbox_apply_descriptor
                    != router.inbox_apply_descriptor
                or protocol.versioned_history is not self
                or protocol.forced_queue is not self.forced_queue
                or protocol.inbox_apply_descriptor
                    != self.inbox_apply_descriptor
                or protocol.migration_gate is not self.migration_gate
                or protocol.settlement_address != self.address
                or protocol.canonical.canonicalized_at_block
                    != clock.block_number
                or registration is None
                or registration.settlement is not self
                or router.active_version != self.protocol_version
                or self.mode not in {"ACTIVE", "MIGRATION_ARMED"}
                or self.inbox_apply_descriptor is None
                or protocol.core.message_cursor != self.forced_queue.cursor
                or clock.block_number <= self.last_canonical_l1_block
                or self.current_sequence < 0
                or self.current_sequence + 1 >= UINT64_MAX
                or protocol.core.l2_block_number <= self.core.l2_block_number
                or protocol.core.terminal_count < self.core.terminal_count
                or (protocol.core.terminal_count == self.core.terminal_count
                    and protocol.core.terminal_root != self.core.terminal_root)):
            return None
        sequence = self.current_sequence + 1
        core = copy.deepcopy(protocol.core)
        entry = self._entry(sequence, core, clock.block_number)
        self.history[sequence % CANONICAL_HISTORY_CAPACITY] = (sequence, entry)
        self.core = core
        self.canonicalized_at_block = clock.block_number
        self.current_sequence = sequence
        self.last_canonical_l1_block = clock.block_number
        return sequence

    def _arm_migration_for_test(self, *, caller_is_version_manager: bool,
                      delayed_manifest_active: bool,
                      generation: int = 1,
                      target_protocol_version: int = 2) -> bool:
        if (self.mode != "ACTIVE" or not caller_is_version_manager
                or not delayed_manifest_active
                or self.migration_gate.mode != "ARMED"
                or self.migration_gate.generation != generation
                or self.migration_gate.active_protocol_version
                    != self.protocol_version
                or self.migration_gate.target_protocol_version
                    != target_protocol_version):
            return False
        self.mode = "MIGRATION_ARMED"
        return True

    def enter_migration_ready(self) -> bool:
        if self.mode == "MIGRATION_READY" and self.migration_gate.mode == "READY":
            return True
        if (self.mode != "MIGRATION_ARMED"
                or self.migration_gate.mode != "READY"):
            return False
        self.mode = "MIGRATION_READY"
        return True

    def canonical_at(self, sequence: int) -> CanonicalTerminalCommitment | None:
        row = self.history.get(sequence % CANONICAL_HISTORY_CAPACITY)
        return row[1] if row is not None and row[0] == sequence else None


@dataclass(frozen=True)
class DestinationIngressDescriptor:
    """Acyclic destination-domain preimage owned by one release profile."""

    destination_chain_id: int
    destination_genesis_hash: str
    adapter_address: str
    router_address: str
    terminal_signal_verifier: str
    inbox_apply_router: str
    inbox_credit_store: str
    protocol_release_authority: str
    terminal_domain_registrar: str
    terminal_accumulator: str
    native_liquidity_pool: str
    destination_bridge: str
    destination_bridge_execution_hash: str
    destination_infrastructure_hash: str
    destination_namespace: str

    @property
    def canonical_domain_preimage(self) -> bytes:
        if (not 0 < self.destination_chain_id <= UINT64_MAX
                or not self.destination_genesis_hash
                or not self.destination_namespace
                or any(not value for value in (
                    self.adapter_address,
                    self.router_address,
                    self.terminal_signal_verifier,
                    self.inbox_apply_router,
                    self.inbox_credit_store,
                    self.protocol_release_authority,
                    self.terminal_domain_registrar,
                    self.terminal_accumulator,
                    self.native_liquidity_pool,
                    self.destination_bridge,
                    self.destination_bridge_execution_hash,
                    self.destination_infrastructure_hash,
                ))):
            raise ValueError("destination domain preimage is incomplete")
        return b"".join((
            _model_uint(self.destination_chain_id, 8,
                        "destination domain chain id"),
            _model_fixed_bytes32(self.destination_genesis_hash),
            _model_address20(self.adapter_address),
            _model_address20(self.router_address),
            _model_address20(self.terminal_signal_verifier),
            _model_address20(self.inbox_apply_router),
            _model_address20(self.inbox_credit_store),
            _model_address20(self.protocol_release_authority),
            _model_address20(self.terminal_domain_registrar),
            _model_address20(self.terminal_accumulator),
            _model_address20(self.native_liquidity_pool),
            _model_address20(self.destination_bridge),
            _model_fixed_bytes32(self.destination_bridge_execution_hash),
            _model_fixed_bytes32(self.destination_infrastructure_hash),
            _model_fixed_bytes32(self.destination_namespace),
        ))

    @property
    def descriptor_id(self) -> bytes:
        # This model-only alias is the exact production domain commitment;
        # no second descriptor identity is admitted by activation.
        return bytes.fromhex(self.destination_domain_id)

    @property
    def destination_domain_id(self) -> str:
        return keccak256(
            D_DESTINATION_DOMAIN + self.canonical_domain_preimage
        ).hex()


@dataclass(frozen=True)
class ImmutableBridgeDeploymentDescriptorV2:
    """Exact fresh nonproxy Bridge code, configuration, and authorities."""

    role: str
    chain_id: int
    bridge: str
    account_runtime_hash: str
    account_configuration_hash: str
    storage_layout_hash: str
    pauser: str
    signal_service: str
    native_quota_manager: str
    native_quota_manager_runtime_hash: str
    native_quota_manager_configuration_hash: str
    native_quota_period: int
    native_eth_quota: int
    v2_endpoints: tuple[str, ...]
    initial_v2_state_commitment: str

    @property
    def topology(self) -> str:
        return "IMMUTABLE_NONPROXY"

    def structurally_valid(self) -> bool:
        return (
            self.role in {
                BRIDGE_ROLE_SOURCE_ONLY, BRIDGE_ROLE_DESTINATION_ONLY
            }
            and 0 < self.chain_id <= UINT64_MAX
            and all((
                self.bridge, self.account_runtime_hash,
                self.account_configuration_hash, self.storage_layout_hash,
                self.pauser, self.signal_service, self.native_quota_manager,
                self.native_quota_manager_runtime_hash,
                self.native_quota_manager_configuration_hash,
            ))
            and self.native_quota_manager_runtime_hash
                == NATIVE_QUOTA_MANAGER_RUNTIME_HASH
            and self.native_quota_period > 0
            and self.native_eth_quota > 0
            and self.native_quota_manager_configuration_hash
                == native_quota_manager_configuration_hash(
                    address=self.native_quota_manager,
                    bridge=self.bridge,
                    quota_period=self.native_quota_period,
                    eth_quota=self.native_eth_quota,
                )
            and type(self.v2_endpoints) is tuple
            and len(self.v2_endpoints) == len(set(self.v2_endpoints))
            and all(self.v2_endpoints)
            and len({self.bridge, self.native_quota_manager,
                     self.signal_service, *self.v2_endpoints})
                == len(self.v2_endpoints) + 3
            and self.pauser not in {
                self.bridge, self.native_quota_manager,
                self.signal_service, *self.v2_endpoints,
            }
            and self.initial_v2_state_commitment
                == EMPTY_V2_BRIDGE_STATE_COMMITMENT
        )

    @property
    def commitment(self) -> str:
        if not self.structurally_valid():
            raise ValueError("immutable Bridge deployment descriptor is invalid")
        fields = tuple(
            getattr(self, row.name)
            for row in self.__dataclass_fields__.values()
        )
        return "deployment:" + hashlib.sha256(
            b"TAIKO_IMMUTABLE_BRIDGE_DEPLOYMENT_V2\x00"
            + repr(fields).encode()
        ).hexdigest()




def native_quota_manager_configuration_hash(
    *, address: str, bridge: str, quota_period: int, eth_quota: int,
) -> str:
    if (not address or not bridge
            or type(quota_period) is not int or quota_period <= 0
            or type(eth_quota) is not int or eth_quota < 0):
        raise ValueError("native QuotaManager configuration is invalid")
    return "config:native-quota-manager:immutable:v2:" + hashlib.sha256(
        repr((address, NATIVE_QUOTA_MANAGER_RUNTIME_HASH, bridge,
              quota_period, eth_quota, "", "")).encode()
    ).hexdigest()


@dataclass
class QuotaStateV2:
    updated_at: int
    quota: int
    available: int


@dataclass
class FrozenNativeQuotaManagerV2:
    """Fresh V2-only ETH quota with immutable cap and dead ownership."""

    address: str
    bridge_address: str
    quota_period: int
    eth_quota_cap: int
    runtime_hash: str = NATIVE_QUOTA_MANAGER_RUNTIME_HASH
    erc20_vault: str = ""
    owner: str = ""
    pending_owner: str = ""
    _state: QuotaStateV2 = field(init=False, repr=False)
    _bridge_authority: object | None = field(
        default=None, init=False, repr=False, compare=False
    )

    def __post_init__(self) -> None:
        if (not self.address or not self.bridge_address
                or self.runtime_hash != NATIVE_QUOTA_MANAGER_RUNTIME_HASH
                or self.erc20_vault or self.owner or self.pending_owner
                or type(self.quota_period) is not int
                or self.quota_period <= 0
                or type(self.eth_quota_cap) is not int
                or not 0 <= self.eth_quota_cap <= SEAT_UINT256_MAX):
            raise ValueError("frozen native QuotaManager graph is invalid")
        object.__setattr__(
            self, "_state",
            QuotaStateV2(0, self.eth_quota_cap, self.eth_quota_cap),
        )

    def __setattr__(self, name: str, value: object) -> None:
        if name in {
            "address", "bridge_address", "quota_period", "eth_quota_cap",
            "runtime_hash", "erc20_vault", "owner", "pending_owner",
            "_bridge_authority",
        } and name in self.__dict__:
            raise AttributeError(f"native QuotaManager {name} is immutable")
        object.__setattr__(self, name, value)

    @property
    def configuration_hash(self) -> str:
        return native_quota_manager_configuration_hash(
            address=self.address,
            bridge=self.bridge_address,
            quota_period=self.quota_period,
            eth_quota=self.eth_quota_cap,
        )

    def _bind_bridge_once(self, bridge: object) -> bool:
        if (type(bridge) not in {SourceBridgeV2, DestinationBridgeLedger}
                or getattr(bridge, "address", None) != self.bridge_address):
            return False
        if self._bridge_authority is not None:
            return self._bridge_authority is bridge
        object.__setattr__(self, "_bridge_authority", bridge)
        return True

    def available_quota(
        self, now: int, leap: int = 0, *, lane: str = NATIVE_QUOTA_LANE_V2,
    ) -> int:
        if (type(now) is not int or now < 0 or type(leap) is not int
                or leap < 0):
            raise ValueError("QuotaManager clock is invalid")
        if lane != NATIVE_QUOTA_LANE_V2:
            raise ValueError("QuotaManager lane is invalid")
        row = self._state
        if row.quota == 0:
            return UNLIMITED_QUOTA
        if row.updated_at == 0:
            return row.quota
        if now < row.updated_at:
            raise ValueError("QuotaManager clock moved backwards")
        elapsed = min(now - row.updated_at + leap, self.quota_period)
        issuance = row.quota * elapsed // self.quota_period
        return min(row.available + issuance, row.quota)

    def _consume_from_bridge(
        self, amount: int, *, bridge: object, frame: object,
        capability: object, lane: str = NATIVE_QUOTA_LANE_V2,
    ) -> bool:
        environment = (
            getattr(bridge, "native_environment", None)
            if type(bridge) is SourceBridgeV2
            else getattr(bridge, "execution_environment", None)
        )
        if (bridge is not self._bridge_authority
                or capability is not _NATIVE_QUOTA_CONSUME_CAPABILITY
                or not getattr(bridge, "entered", False)
                or environment is None
                or frame is not environment._active_frame
                or type(amount) is not int or amount < 0):
            return False
        now = frame.block_timestamp
        if lane != NATIVE_QUOTA_LANE_V2:
            return False
        row = self._state
        if row.quota == 0:
            return True
        available = self.available_quota(now, lane=lane)
        if amount > available:
            return False
        row.available = available - amount
        row.updated_at = now
        return True

    def snapshot(self) -> tuple[int, int, int]:
        return (
            self._state.updated_at,
            self._state.quota,
            self._state.available,
        )

    def restore(
        self, snapshot: tuple[int, int, int], *,
        bridge: object, frame: object, capability: object,
    ) -> None:
        environment = (
            getattr(bridge, "native_environment", None)
            if type(bridge) is SourceBridgeV2
            else getattr(bridge, "execution_environment", None)
        )
        active_bridge_frame = (
            getattr(bridge, "_active_execution_frame", None)
            if type(bridge) is DestinationBridgeLedger else frame
        )
        if (bridge is not self._bridge_authority
                or capability is not _NATIVE_QUOTA_ROLLBACK_CAPABILITY
                or not getattr(bridge, "entered", False)
                or environment is None
                or frame is not getattr(environment, "_active_frame", None)
                or active_bridge_frame is not frame):
            raise ValueError("QuotaManager rollback authority is wrong")
        if type(snapshot) is not tuple or len(snapshot) != 3:
            raise ValueError("QuotaManager rollback snapshot is invalid")
        updated_at, quota, available = snapshot
        if (quota != self._state.quota or type(updated_at) is not int
                or updated_at < 0 or type(available) is not int
                or not 0 <= available <= quota):
            raise ValueError("QuotaManager rollback state is invalid")
        self._state.updated_at = updated_at
        self._state.available = available

    def transfer_ownership(self, _new_owner: str) -> bool:
        return False

    def accept_ownership(self, _caller: str) -> bool:
        return False

    def update_quota(self, _quota: int, *, caller: str) -> bool:
        _ = caller
        return False


def source_bundle_initcode_hash(descriptor: "SourceBridgeDescriptor") -> str:
    """Commit every acyclic initializer primitive into the CREATE2 address."""

    if type(descriptor) is not SourceBridgeDescriptor:
        raise ValueError("source bundle initcode descriptor has wrong type")
    fields = (
        SOURCE_V2_GENERIC_INITCODE_HASH,
        descriptor.settlement_chain_id,
        descriptor.source_chain_id,
        descriptor.source_genesis_hash,
        descriptor.registry_namespace,
        descriptor.bridge_facade_runtime_hash,
        descriptor.bridge_storage_layout_hash,
        descriptor.bridge_kernel_hash,
        descriptor.source_terminal_verifier,
        descriptor.v1_official_vaults,
        descriptor.role,
        descriptor.native_quota_manager_runtime_hash,
        descriptor.native_quota_period,
        descriptor.native_eth_quota,
        descriptor.source_domain_registrar,
        descriptor.source_registration_epoch,
        descriptor.support_registry_address,
        descriptor.support_registry_runtime_hash,
        descriptor.support_registry_configuration_hash,
        descriptor.source_terminal_verifier_runtime_hash,
        descriptor.source_terminal_verifier_configuration_hash,
        descriptor.bundle_deployer_runtime_hash,
        descriptor.legacy_v1_bridge,
    )
    return keccak256(
        b"TAIKO_SOURCE_BUNDLE_INITCODE_V2\x00"
        + b"".join(_ingress_commitment_word(value) for value in fields)
    ).hex()


def source_bridge_account_configuration_hash(
    descriptor: "SourceBridgeDescriptor",
) -> str:
    """Acyclic immutable SourceBridge configuration used by CREATE2."""

    if type(descriptor) is not SourceBridgeDescriptor:
        raise ValueError("source Bridge descriptor has the wrong type")
    # This is the factory-only one-shot CONFIGURED state, not the generic
    # deployment initcode.  It deliberately excludes the CREATE2 tuple,
    # resulting Bridge address, runtime/layout hashes and outer descriptor so
    # no value hashes itself or a value derived from itself.
    fields = (
        descriptor.settlement_chain_id,
        descriptor.source_chain_id,
        descriptor.source_genesis_hash,
        descriptor.registry_namespace,
        descriptor.bridge_credit_registry,
        descriptor.source_terminal_verifier,
        descriptor.v1_official_vaults,
        descriptor.role,
        descriptor.native_quota_manager,
        descriptor.native_quota_manager_runtime_hash,
        descriptor.native_quota_period,
        descriptor.native_eth_quota,
        descriptor.source_domain_registrar,
        descriptor.source_registration_epoch,
        descriptor.support_registry_address,
        descriptor.support_registry_runtime_hash,
        descriptor.support_registry_configuration_hash,
        descriptor.source_terminal_verifier_runtime_hash,
        descriptor.source_terminal_verifier_configuration_hash,
        "bridge-pauser",
        "signal-service",
    )
    return "config:immutable-source-bridge:v2:" + hashlib.sha256(
        b"TAIKO_IMMUTABLE_SOURCE_BRIDGE_CONFIG_V2\x00"
        + b"".join(_ingress_commitment_word(value) for value in fields)
    ).hexdigest()


@dataclass(frozen=True)
class SourceBridgeDescriptor:
    """Acyclic source identity; neither domain nor execution is self-reported."""

    settlement_chain_id: int
    source_chain_id: int
    source_genesis_hash: str
    registry_namespace: str
    source_bridge: str
    bridge_credit_registry: str
    bridge_facade_runtime_hash: str
    bridge_storage_layout_hash: str
    bridge_kernel_hash: str
    source_terminal_verifier: str
    v1_official_vaults: tuple[str, ...] = V1_OFFICIAL_VAULT_ADDRESSES
    role: str = BRIDGE_ROLE_SOURCE_ONLY
    native_quota_manager: str = ""
    native_quota_manager_runtime_hash: str = (
        NATIVE_QUOTA_MANAGER_RUNTIME_HASH
    )
    native_quota_period: int = NATIVE_QUOTA_PERIOD_SECONDS
    native_eth_quota: int = UINT64_MAX
    source_domain_registrar: str = "source-domain-registrar"
    source_registration_epoch: int = 1
    support_registry_address: str = ""
    support_registry_runtime_hash: str = ""
    support_registry_configuration_hash: str = ""
    source_terminal_verifier_runtime_hash: str = (
        SOURCE_TERMINAL_VERIFIER_RUNTIME_HASH
    )
    source_terminal_verifier_configuration_hash: str = ""
    deployment_factory: str = SOURCE_V2_CREATE2_FACTORY
    deployment_factory_runtime_hash: str = (
        SOURCE_V2_CREATE2_FACTORY_RUNTIME_HASH
    )
    deployment_factory_configuration_hash: str = (
        SOURCE_V2_CREATE2_FACTORY_CONFIGURATION_HASH
    )
    deployment_salt: str = SOURCE_V2_CREATE2_SALT
    deployment_initcode_hash: str = ""
    bundle_deployer: str = ""
    bundle_deployer_runtime_hash: str = (
        SOURCE_V2_BUNDLE_DEPLOYER_RUNTIME_HASH
    )
    legacy_v1_bridge: str = LEGACY_V1_SOURCE_BRIDGE
    deployment_descriptor: ImmutableBridgeDeploymentDescriptorV2 | None = None

    def __post_init__(self) -> None:
        expected_initcode_hash = source_bundle_initcode_hash(self)
        if not self.deployment_initcode_hash:
            object.__setattr__(
                self, "deployment_initcode_hash", expected_initcode_hash
            )
        if not self.bundle_deployer:
            object.__setattr__(
                self,
                "bundle_deployer",
                source_bridge_create2_address(
                    self.deployment_factory,
                    self.deployment_salt,
                    self.deployment_initcode_hash,
                ),
            )
        if not self.source_bridge:
            object.__setattr__(
                self,
                "source_bridge",
                source_bundle_child_address(self.bundle_deployer, 1),
            )
        if not self.native_quota_manager:
            object.__setattr__(
                self,
                "native_quota_manager",
                source_native_quota_manager_address(self.bundle_deployer),
            )
        if not self.bridge_credit_registry:
            object.__setattr__(
                self,
                "bridge_credit_registry",
                source_bridge_credit_registry_address(self.bundle_deployer),
            )
        if self.deployment_descriptor is None:
            deployment = ImmutableBridgeDeploymentDescriptorV2(
                self.role,
                self.source_chain_id,
                self.source_bridge,
                self.bridge_facade_runtime_hash,
                source_bridge_account_configuration_hash(self),
                self.bridge_storage_layout_hash,
                "bridge-pauser",
                "signal-service",
                self.native_quota_manager,
                self.native_quota_manager_runtime_hash,
                native_quota_manager_configuration_hash(
                    address=self.native_quota_manager,
                    bridge=self.source_bridge,
                    quota_period=self.native_quota_period,
                    eth_quota=self.native_eth_quota,
                ),
                self.native_quota_period,
                self.native_eth_quota,
                (
                    self.bridge_credit_registry,
                    self.source_terminal_verifier,
                ),
                EMPTY_V2_BRIDGE_STATE_COMMITMENT,
            )
            object.__setattr__(self, "deployment_descriptor", deployment)

    @property
    def canonical_bytes(self) -> bytes:
        """Exact 28-field, 752-byte SourceBridgeDescriptorV2 preimage."""

        # This immutable constructor hash deliberately excludes the derived
        # source domain, execution hash and descriptor id.  Their append-only
        # support relations are authenticated separately after deployment.
        registry_configuration = keccak256(b"".join((
            b"slot-chain-source-credit-registry-config-v2",
            _model_address20(self.bridge_credit_registry),
            _model_address20(self.source_domain_registrar),
            _model_address20(self.source_bridge),
            _model_address20(self.support_registry_address),
            _model_fixed_bytes32(self.support_registry_runtime_hash),
            _model_fixed_bytes32(self.support_registry_configuration_hash),
        ))).hex()
        encoded = b"".join((
            _model_address20(self.deployment_factory),
            _model_fixed_bytes32(self.deployment_factory_runtime_hash),
            _model_fixed_bytes32(
                self.deployment_factory_configuration_hash
            ),
            _model_fixed_bytes32(self.deployment_salt),
            _model_fixed_bytes32(self.deployment_initcode_hash),
            _model_address20(self.bundle_deployer),
            _model_fixed_bytes32(self.bundle_deployer_runtime_hash),
            _model_address20(self.legacy_v1_bridge),
            _model_address20(self.source_bridge),
            _model_fixed_bytes32(self.bridge_facade_runtime_hash),
            _model_fixed_bytes32(source_bridge_account_configuration_hash(self)),
            _model_fixed_bytes32(self.bridge_storage_layout_hash),
            _model_address20(self.bridge_credit_registry),
            _model_fixed_bytes32(BRIDGE_CREDIT_REGISTRY_RUNTIME_HASH),
            _model_fixed_bytes32(registry_configuration),
            _model_address20(self.native_quota_manager),
            _model_fixed_bytes32(self.native_quota_manager_runtime_hash),
            _model_fixed_bytes32(native_quota_manager_configuration_hash(
                address=self.native_quota_manager,
                bridge=self.source_bridge,
                quota_period=self.native_quota_period,
                eth_quota=self.native_eth_quota,
            )),
            _model_address20(self.support_registry_address),
            _model_fixed_bytes32(self.support_registry_runtime_hash),
            _model_fixed_bytes32(
                self.support_registry_configuration_hash
            ),
            _model_address20(self.source_terminal_verifier),
            _model_fixed_bytes32(self.source_terminal_verifier_runtime_hash),
            _model_fixed_bytes32(
                self.source_terminal_verifier_configuration_hash
            ),
            _model_address20("bridge-pauser"),
            _model_address20("signal-service"),
            _model_fixed_bytes32(self.bridge_kernel_hash),
            _model_uint(self.source_registration_epoch, 8, "source epoch"),
        ))
        if len(encoded) != 752:
            raise AssertionError("SourceBridgeDescriptorV2 width drifted")
        return encoded

    @property
    def bridge_execution_hash(self) -> str:
        return keccak256(
            b"slot-chain-source-bridge-execution-v4"
            + _model_uint(len(self.canonical_bytes), 4, "descriptor length")
            + self.canonical_bytes
        ).hex()

    @property
    def descriptor_id(self) -> bytes:
        if (self.v1_official_vaults != V1_OFFICIAL_VAULT_ADDRESSES
                or self.role != BRIDGE_ROLE_SOURCE_ONLY
                or not self.native_quota_manager
                or self.native_quota_manager
                    != source_native_quota_manager_address(
                        self.bundle_deployer
                    )
                or self.bridge_credit_registry
                    != source_bridge_credit_registry_address(
                        self.bundle_deployer
                    )
                or self.native_quota_manager_runtime_hash
                    != NATIVE_QUOTA_MANAGER_RUNTIME_HASH
                or self.native_quota_period <= 0
                or self.native_eth_quota <= 0
                or not self.source_domain_registrar
                or not 0 < self.source_registration_epoch <= UINT64_MAX
                or not self.support_registry_address
                or not self.support_registry_runtime_hash
                or not self.support_registry_configuration_hash
                or not self.source_terminal_verifier_runtime_hash
                or not self.source_terminal_verifier_configuration_hash
                or not self.deployment_factory
                or not self.deployment_factory_runtime_hash
                or not self.deployment_factory_configuration_hash
                or not self.deployment_salt
                or not self.deployment_initcode_hash
                or not self.bundle_deployer
                or not self.bundle_deployer_runtime_hash
                or self.deployment_initcode_hash
                    != source_bundle_initcode_hash(self)
                or not self.legacy_v1_bridge
                or len({
                    self.deployment_factory,
                    self.bundle_deployer,
                    self.legacy_v1_bridge,
                    self.source_bridge,
                    self.bridge_credit_registry,
                    self.native_quota_manager,
                }) != 6
                or self.bundle_deployer != source_bridge_create2_address(
                    self.deployment_factory,
                    self.deployment_salt,
                    self.deployment_initcode_hash,
                )
                or self.source_bridge
                    != source_bundle_child_address(self.bundle_deployer, 1)
                or type(self.deployment_descriptor)
                    is not ImmutableBridgeDeploymentDescriptorV2
                or not self.deployment_descriptor.structurally_valid()
                or self.deployment_descriptor.role != self.role
                or self.deployment_descriptor.chain_id
                    != self.source_chain_id
                or self.deployment_descriptor.bridge
                    != self.source_bridge
                or self.deployment_descriptor.account_runtime_hash
                    != self.bridge_facade_runtime_hash
                or self.deployment_descriptor.account_configuration_hash
                    != source_bridge_account_configuration_hash(self)
                or self.deployment_descriptor.storage_layout_hash
                    != self.bridge_storage_layout_hash
                or self.deployment_descriptor.pauser != "bridge-pauser"
                or self.deployment_descriptor.signal_service
                    != "signal-service"
                or self.deployment_descriptor.native_quota_manager
                    != self.native_quota_manager
                or self.deployment_descriptor
                    .native_quota_manager_runtime_hash
                    != self.native_quota_manager_runtime_hash
                or self.deployment_descriptor.native_quota_period
                    != self.native_quota_period
                or self.deployment_descriptor.native_eth_quota
                    != self.native_eth_quota
                or self.deployment_descriptor.v2_endpoints
                    != (
                        self.bridge_credit_registry,
                        self.source_terminal_verifier,
                    )):
            raise ValueError("source V1 Vault denylist is not exact")
        return bytes.fromhex(self.bridge_execution_hash)

    @property
    def source_domain_id(self) -> str:
        return keccak256(b"".join((
            b"slot-chain-source-domain-v4",
            _model_uint(self.source_chain_id, 8, "source chain id"),
            _model_fixed_bytes32(self.source_genesis_hash),
            _model_address20(self.bridge_credit_registry),
            _model_address20(self.source_terminal_verifier),
            _model_address20(self.source_bridge),
            bytes.fromhex(self.bridge_execution_hash),
            _model_fixed_bytes32(self.registry_namespace),
        ))).hex()


def canonical_source_bridge_descriptor(
    settlement_chain_id: int = 1,
    router: "ActiveSettlementRouter | None" = None,
) -> SourceBridgeDescriptor:
    descriptor = SourceBridgeDescriptor(
        settlement_chain_id,
        settlement_chain_id,
        "genesis:source:v1",
        "source-domain-namespace:v2",
        "",
        "",
        "code:source-bridge:v2",
        "storage:source-bridge:v2",
        "kernel:source-bridge:v2",
        "source-terminal-verifier",
    )
    return (
        descriptor if router is None
        else bind_source_bridge_descriptor_to_router(descriptor, router)
    )


def bind_source_bridge_descriptor_to_router(
    descriptor: SourceBridgeDescriptor,
    router: "ActiveSettlementRouter",
) -> SourceBridgeDescriptor:
    """Fill or verify lifetime source dependencies before descriptor hashing."""

    if (type(descriptor) is not SourceBridgeDescriptor
            or type(router) is not ActiveSettlementRouter):
        raise ValueError("source descriptor lifetime binding has wrong type")
    support_address = "bridge-domain-registry"
    support_runtime = BRIDGE_DOMAIN_REGISTRY_RUNTIME_HASH
    support_configuration = bridge_domain_registry_configuration_hash(
        address=support_address,
        runtime_hash=support_runtime,
        support_authority=router.version_manager,
        router_address=router.address,
        router_runtime_hash=router.runtime_hash,
        router_configuration_hash=router.configuration_hash,
        release_authority_address="release-authority",
        release_authority_runtime_hash="code:authority",
        release_authority_configuration_hash="cfg:authority",
        registration_mpt_verifier_descriptor_hash=(
            canonical_registration_mpt_verifier_descriptor().commitment
        ),
    )
    verifier_configuration = source_terminal_verifier_configuration_hash(
        router_address=router.address,
    )
    expected = {
        "source_domain_registrar": "source-domain-registrar",
        "source_registration_epoch": 1,
        "support_registry_address": support_address,
        "support_registry_runtime_hash": support_runtime,
        "support_registry_configuration_hash": support_configuration,
        "source_terminal_verifier_runtime_hash": (
            SOURCE_TERMINAL_VERIFIER_RUNTIME_HASH
        ),
        "source_terminal_verifier_configuration_hash": (
            verifier_configuration
        ),
    }
    for name, value in expected.items():
        current = getattr(descriptor, name)
        empty = current == "" if type(value) is str else current == value
        if not empty and current != value:
            raise ValueError(f"source descriptor {name} changed lifetime binding")
    return replace(
        descriptor,
        **expected,
        source_bridge="",
        bridge_credit_registry="",
        native_quota_manager="",
        deployment_initcode_hash="",
        bundle_deployer="",
        deployment_descriptor=None,
    )


@dataclass(frozen=True)
class SettlementRegistration:
    settlement: VersionedSettlementHistory
    runtime_hash: str
    execution_profile_hash: str
    execution_profile: "ExecutionProfile"
    activation_block: int
    predecessor_version: int
    release_manifest_hash: str | bytes
    migration_manifest_hash: str | bytes
    release_manifest: "ReleaseManifestV2"
    release_manifests_by_adapter: MappingProxyType
    ingress_authorizations: tuple["ProfileIngressAuthorization", ...]
    ingress_authorizations_by_id: MappingProxyType
    ingress_authorizations_by_address: MappingProxyType
    ingress_authorization_root: bytes
    settlement_chain_context_id: int
    ingress_fee_schedule: tuple[int, int, int, int, int]

    def __deepcopy__(self, memo: dict[int, object]) -> "SettlementRegistration":
        """Registration is an immutable authority capability, not tx state."""

        memo[id(self)] = self
        return self


@dataclass(frozen=True)
class ProfileIngressAuthorization:
    """One exact ingress tuple authenticated by the active release profile."""

    kind: ForceKind
    adapter_address: str
    runtime_hash: str
    configuration_hash: str
    router_address: str
    router_runtime_hash: str
    router_configuration_hash: str
    queue_address: str
    queue_runtime_hash: str
    queue_configuration_hash: str
    source_registry_address: str
    source_registry_runtime_hash: str
    source_registry_configuration_hash: str
    source_registry_domain_registrar: str
    source_bridge_address: str
    source_bridge_runtime_hash: str
    source_bridge_configuration_hash: str
    support_registry_address: str
    support_registry_runtime_hash: str
    support_registry_configuration_hash: str
    source_descriptor_id: bytes
    source_settlement_chain_id: int
    source_chain_id: int
    source_genesis_hash: str
    source_registry_namespace: str
    source_bridge_credit_registry: str
    source_bridge_facade_runtime_hash: str
    source_bridge_storage_layout_hash: str
    source_bridge_kernel_hash: str
    source_terminal_verifier: str
    source_v1_official_vaults: tuple[str, ...]
    source_domain_id: str
    source_registration_epoch: int
    frozen_bridge_execution_hash: str
    destination_domain_id: str
    destination_bridge: str
    destination_descriptor_id: bytes
    destination_chain_id: int
    destination_genesis_hash: str
    terminal_signal_verifier: str
    inbox_apply_router: str
    inbox_credit_store: str
    protocol_release_authority: str
    terminal_domain_registrar: str
    terminal_accumulator: str
    native_liquidity_pool: str
    destination_bridge_execution_hash: str
    destination_infrastructure_hash: str
    destination_namespace: str
    fixed_ingress_wei: int
    execution_wei_per_accounted_gas: int
    proof_wei_per_accounted_gas: int
    permanent_wei_per_byte: int
    maximum_accepted_fee_wei: int
    source_descriptor: SourceBridgeDescriptor | None = None

    @property
    def authorization_id(self) -> bytes:
        return profile_ingress_authorization_id(self)


def _ingress_commitment_word(value: object) -> bytes:
    if type(value) is bytes:
        return b"b" + len(value).to_bytes(4, "big") + value
    if type(value) is str:
        encoded = value.encode()
        return b"s" + len(encoded).to_bytes(4, "big") + encoded
    if type(value) is int:
        if not 0 <= value <= UINT64_MAX:
            raise ValueError("ingress commitment integer is outside uint64")
        return b"i" + value.to_bytes(8, "big")
    if type(value) is ForceKind:
        return b"k" + value.value.to_bytes(1, "big")
    if type(value) is SourceBridgeDescriptor:
        return (
            b"d" + value.descriptor_id
            + _ingress_commitment_word(value.bridge_execution_hash)
        )
    if value is None:
        return b"n"
    if type(value) is tuple:
        encoded = b"".join(_ingress_commitment_word(row) for row in value)
        return b"t" + len(value).to_bytes(2, "big") + encoded
    raise ValueError("ingress commitment field has noncanonical type")


def profile_ingress_authorization_id(
    authorization: ProfileIngressAuthorization,
) -> bytes:
    """Exact 23-word ProfileIngressAuthorizationV2 ABI/Keccak id."""

    if type(authorization) is not ProfileIngressAuthorization:
        raise ValueError("profile ingress authorization has wrong type")
    source_zero = authorization.kind is ForceKind.USER_TX
    source_domain = _model_fixed_bytes32(
        authorization.source_domain_id, zero_if_empty=source_zero
    )
    source_execution = _model_fixed_bytes32(
        authorization.frozen_bridge_execution_hash,
        zero_if_empty=source_zero,
    )
    destination_domain = _model_fixed_bytes32(
        authorization.destination_domain_id, zero_if_empty=source_zero
    )
    destination_bridge = _model_address20(
        authorization.destination_bridge, zero_if_empty=source_zero
    )
    destination_execution = _model_fixed_bytes32(
        authorization.destination_bridge_execution_hash,
        zero_if_empty=source_zero,
    )
    infrastructure = _model_fixed_bytes32(
        authorization.destination_infrastructure_hash,
        zero_if_empty=source_zero,
    )
    fees = (
        authorization.fixed_ingress_wei,
        authorization.execution_wei_per_accounted_gas,
        authorization.proof_wei_per_accounted_gas,
        authorization.permanent_wei_per_byte,
        authorization.maximum_accepted_fee_wei,
    )
    validate_ingress_fee_schedule(fees)
    if (authorization.kind not in {ForceKind.USER_TX, ForceKind.BRIDGE_CREDIT}
            or not authorization.adapter_address
            or not authorization.router_address
            or not authorization.queue_address
            or (source_zero and (
                authorization.source_registration_epoch != 0
                or any(value != bytes(32) for value in (
                    source_domain, source_execution, destination_domain,
                    destination_execution, infrastructure,
                ))
                or destination_bridge != bytes(20)))
            or (not source_zero and (
                not 0 < authorization.source_registration_epoch <= UINT64_MAX
                or any(value == bytes(32) for value in (
                    source_domain, source_execution, destination_domain,
                    destination_execution, infrastructure,
                ))
                or destination_bridge == bytes(20)))):
        raise ValueError("profile ingress authorization fields are invalid")
    encoded = b"".join((
        INGRESS_AUTHORIZATION_TYPEHASH,
        _model_uint(authorization.kind.value, 32, "ingress kind"),
        bytes(12) + _model_address20(authorization.adapter_address),
        _model_fixed_bytes32(authorization.runtime_hash),
        _model_fixed_bytes32(authorization.configuration_hash),
        bytes(12) + _model_address20(authorization.router_address),
        _model_fixed_bytes32(authorization.router_runtime_hash),
        _model_fixed_bytes32(authorization.router_configuration_hash),
        bytes(12) + _model_address20(authorization.queue_address),
        _model_fixed_bytes32(authorization.queue_runtime_hash),
        _model_fixed_bytes32(authorization.queue_configuration_hash),
        source_domain,
        _model_uint(authorization.source_registration_epoch, 32,
                    "source registration epoch"),
        source_execution,
        _model_uint(authorization.destination_chain_id, 32,
                    "destination chain id"),
        destination_domain,
        bytes(12) + destination_bridge,
        destination_execution,
        infrastructure,
        *(_model_uint(value, 32, "ingress fee") for value in fees),
    ))
    if len(encoded) != 24 * 32:
        raise AssertionError("ingress authorization ABI width drifted")
    return keccak256(encoded)


def profile_ingress_authorization_root(
    authorizations: tuple[ProfileIngressAuthorization, ...],
) -> bytes:
    if (type(authorizations) is not tuple
            or not 0 < len(authorizations)
                <= MAX_PROFILE_INGRESS_AUTHORIZATIONS):
        raise ValueError("profile ingress authorization topology is invalid")
    ids = tuple(sorted(row.authorization_id for row in authorizations))
    if len(set(ids)) != len(ids):
        raise ValueError("profile ingress authorization id collision")
    ids_hash = keccak256(b"".join(ids))
    return keccak256(b"".join((
        INGRESS_AUTHORIZATION_ROOT_TYPEHASH,
        _model_uint(len(ids), 32, "ingress authorization count"),
        ids_hash,
    )))


def canonical_destination_release_topology(
    router: "ActiveSettlementRouter", *, adapter_address: str,
    adapter_configuration_hash: str, destination_bridge: str,
) -> tuple[
    tuple["ReleaseComponentV2", ...],
    "DestinationBridgeDescriptorV2",
    str,
    DestinationIngressDescriptor,
]:
    """One acyclic component graph shared by release and ingress models."""

    if (type(router) is not ActiveSettlementRouter
            or not adapter_address or not adapter_configuration_hash
            or not destination_bridge):
        raise ValueError("destination descriptor authority is incomplete")
    store_address = f"inbox-store:{adapter_address}"
    store_runtime = f"codehash:store:{adapter_address}"
    inbox_descriptor = router.inbox_apply_descriptor
    store_config = (
        f"component-config:{inbox_descriptor.address}:"
        f"{destination_bridge}:{inbox_descriptor.registrar_address}"
    )
    facade_runtime_hash = f"facade-code:{destination_bridge}"
    # V2 is always deployed at a fresh immutable address.  The legacy V1
    # proxy remains a separate account and is deliberately absent from this
    # release component graph.
    account_runtime_hash = facade_runtime_hash
    quota_manager_address = destination_native_quota_manager_address(
        destination_bridge
    )
    privileged_target_denyset = tuple(sorted({
        "0x" + "00" * 20,
        adapter_address,
        router.address,
        "terminal-verifier",
        inbox_descriptor.address,
        store_address,
        "release-authority",
        inbox_descriptor.registrar_address,
        "terminal-accumulator",
        destination_bridge,
        "bridge-pauser",
        quota_manager_address,
        NATIVE_LIQUIDITY_POOL,
        *V2_PRIVILEGED_DESTINATION_ADDRESSES,
    }, key=_model_address20))
    bridge_descriptor = DestinationBridgeDescriptorV2(
        destination_bridge,
        facade_runtime_hash,
        f"storage-layout:{destination_bridge}",
        f"kernel-profile:{destination_bridge}",
        store_address,
        "terminal-accumulator",
        inbox_descriptor.registrar_address,
        native_quota_manager=quota_manager_address,
        privileged_target_denyset=privileged_target_denyset,
    )
    bridge_config = destination_bridge_component_config_hash(
        bridge_descriptor,
        topology=bridge_descriptor.deployment_descriptor.topology,
        account_runtime_hash=account_runtime_hash,
    )
    components = (
        ReleaseComponentV2(
            adapter_address,
            BRIDGE_INGRESS_RUNTIME_HASH,
            adapter_configuration_hash,
        ),
        ReleaseComponentV2(
            router.address, router.runtime_hash, router.configuration_hash
        ),
        ReleaseComponentV2(
            "terminal-verifier", "code:verifier",
            source_terminal_verifier_configuration_hash(
                router_address=router.address
            ),
        ),
        ReleaseComponentV2(
            inbox_descriptor.address,
            inbox_descriptor.runtime_hash,
            inbox_descriptor.configuration_hash,
        ),
        ReleaseComponentV2(store_address, store_runtime, store_config),
        ReleaseComponentV2(
            "release-authority", "code:authority", "cfg:authority"
        ),
        ReleaseComponentV2(
            inbox_descriptor.registrar_address,
            "code:registrar",
            "cfg:registrar",
        ),
        ReleaseComponentV2(
            "terminal-accumulator", "code:accumulator", "cfg:accumulator"
        ),
        ReleaseComponentV2(
            NATIVE_LIQUIDITY_POOL,
            NATIVE_LIQUIDITY_POOL_RUNTIME_HASH,
            NATIVE_LIQUIDITY_POOL_CONFIGURATION_HASH,
        ),
        ReleaseComponentV2(
            destination_bridge, account_runtime_hash, bridge_config
        ),
    )
    infrastructure_hash = destination_infrastructure_hash(components)
    descriptor = DestinationIngressDescriptor(
        167_000,
        "genesis:destination:v2",
        adapter_address,
        router.address,
        components[2].address,
        inbox_descriptor.address,
        components[4].address,
        components[5].address,
        inbox_descriptor.registrar_address,
        components[7].address,
        NATIVE_LIQUIDITY_POOL,
        destination_bridge,
        bridge_descriptor.execution_hash,
        infrastructure_hash,
        "domain-namespace:v2",
    )
    return components, bridge_descriptor, infrastructure_hash, descriptor


def profile_ingress_authorization_for(
    router: "ActiveSettlementRouter", *, kind: ForceKind,
    adapter_address: str, destination_bridge: str = "",
    settlement_chain_id: int = 1,
    source_descriptor_override: SourceBridgeDescriptor | None = None,
    fee_schedule: tuple[int, int, int, int, int] = (
        INGRESS_FIXED_WEI,
        INGRESS_EXECUTION_WEI_PER_GAS,
        INGRESS_PROOF_WEI_PER_GAS,
        INGRESS_PERMANENT_WEI_PER_BYTE,
        INGRESS_MAXIMUM_ACCEPTED_FEE_WEI,
    ),
) -> ProfileIngressAuthorization:
    """Construct a typed component tuple before any profile/release labels."""

    if (type(router) is not ActiveSettlementRouter
            or settlement_chain_id != router.settlement_chain_context_id):
        raise ValueError("ingress authorization changed settlement chain context")
    if kind is ForceKind.USER_TX:
        if (adapter_address != "kind0-adapter" or destination_bridge
                or source_descriptor_override is not None):
            raise ValueError("kind-0 profile authorization is noncanonical")
        exact_source_descriptor = None
        bridge_fields: tuple[object, ...] = (
            "", "", "", "", "", "", "", "", "", "",
            b"", 0, 0, "", "", "", "", "", "", "",
            (), "", 0, "", "", "", b"", 167_000,
            "", "", "", "", "", "", "", "", "", "", "",
        )
        runtime_hash = KIND0_INGRESS_RUNTIME_HASH
        configuration_hash = KIND0_INGRESS_CONFIGURATION_HASH
    elif kind is ForceKind.BRIDGE_CREDIT:
        source_runtime = BRIDGE_CREDIT_REGISTRY_RUNTIME_HASH
        source_registrar = "source-domain-registrar"
        source_chain_id = router.settlement_chain_context_id
        source_descriptor = (
            canonical_source_bridge_descriptor(settlement_chain_id, router)
            if source_descriptor_override is None
            else bind_source_bridge_descriptor_to_router(
                source_descriptor_override, router
            )
        )
        if (type(source_descriptor) is not SourceBridgeDescriptor
                or source_descriptor.settlement_chain_id
                    != settlement_chain_id
                or source_descriptor.source_chain_id
                    != settlement_chain_id):
            raise ValueError("source descriptor changed settlement chain")
        source_descriptor.descriptor_id
        exact_source_descriptor = source_descriptor
        source_address = source_descriptor.bridge_credit_registry
        source_bridge = source_descriptor.source_bridge
        source_domain_id = source_descriptor.source_domain_id
        source_registration_epoch = source_descriptor.source_registration_epoch
        frozen_bridge_execution_hash = (
            source_descriptor.bridge_execution_hash
        )
        support_registry_address = source_descriptor.support_registry_address
        support_registry_runtime = source_descriptor.support_registry_runtime_hash
        support_registry_configuration = (
            source_descriptor.support_registry_configuration_hash
        )
        source_configuration = bridge_credit_registry_configuration_hash(
            address=source_address,
            runtime_hash=source_runtime,
            domain_registrar=source_descriptor.source_domain_registrar,
            frozen_bridge=source_bridge,
            support_registry_address=support_registry_address,
            support_registry_runtime_hash=support_registry_runtime,
            support_registry_configuration_hash=(
                support_registry_configuration
            ),
            source_chain_id=source_chain_id,
            source_domain_id=source_domain_id,
            source_registration_epoch=source_registration_epoch,
            frozen_bridge_execution_hash=frozen_bridge_execution_hash,
            source_descriptor_id=source_descriptor.descriptor_id,
        )
        source_bridge_configuration = (
            source_bridge_configuration_hash_for_descriptor(
                source_descriptor,
                source_address,
                source_runtime,
                source_configuration,
            )
        )
        runtime_hash = BRIDGE_INGRESS_RUNTIME_HASH
        configuration_hash = bridge_ingress_component_configuration_hash(
            router_address=router.address,
            router_runtime_hash=router.runtime_hash,
            router_configuration_hash=router.configuration_hash,
            queue_address=router.forced_queue.address,
            queue_runtime_hash=router.forced_queue.runtime_hash,
            queue_configuration_hash=router.forced_queue.config_hash,
            source_registry_address=source_address,
            source_registry_runtime_hash=source_runtime,
            source_registry_configuration_hash=source_configuration,
            source_bridge_address=source_bridge,
            source_bridge_runtime_hash=(
                source_descriptor.bridge_facade_runtime_hash
            ),
            source_bridge_configuration_hash_=(
                source_bridge_configuration
            ),
            seal_authority=router.version_manager,
        )
        _, _, _, descriptor = canonical_destination_release_topology(
            router,
            adapter_address=adapter_address,
            adapter_configuration_hash=configuration_hash,
            destination_bridge=destination_bridge,
        )
        bridge_fields = (
            source_address,
            source_runtime,
            source_configuration,
            source_descriptor.source_domain_registrar,
            source_bridge,
            source_descriptor.bridge_facade_runtime_hash,
            source_bridge_configuration,
            support_registry_address,
            support_registry_runtime,
            support_registry_configuration,
            source_descriptor.descriptor_id,
            source_descriptor.settlement_chain_id,
            source_chain_id,
            source_descriptor.source_genesis_hash,
            source_descriptor.registry_namespace,
            source_descriptor.bridge_credit_registry,
            source_descriptor.bridge_facade_runtime_hash,
            source_descriptor.bridge_storage_layout_hash,
            source_descriptor.bridge_kernel_hash,
            source_descriptor.source_terminal_verifier,
            source_descriptor.v1_official_vaults,
            source_domain_id,
            source_registration_epoch,
            frozen_bridge_execution_hash,
            descriptor.destination_domain_id,
            destination_bridge,
            descriptor.descriptor_id,
            descriptor.destination_chain_id,
            descriptor.destination_genesis_hash,
            descriptor.terminal_signal_verifier,
            descriptor.inbox_apply_router,
            descriptor.inbox_credit_store,
            descriptor.protocol_release_authority,
            descriptor.terminal_domain_registrar,
            descriptor.terminal_accumulator,
            descriptor.native_liquidity_pool,
            descriptor.destination_bridge_execution_hash,
            descriptor.destination_infrastructure_hash,
            descriptor.destination_namespace,
        )
    else:
        raise ValueError("unsupported profile ingress kind")
    return ProfileIngressAuthorization(
        kind,
        adapter_address,
        runtime_hash,
        configuration_hash,
        router.address,
        router.runtime_hash,
        router.configuration_hash,
        router.forced_queue.address,
        router.forced_queue.runtime_hash,
        router.forced_queue.config_hash,
        *bridge_fields,
        *fee_schedule,
        exact_source_descriptor,
    )


def release_profile_ingress_authorizations(
    router: "ActiveSettlementRouter",
    settlement: VersionedSettlementHistory,
) -> tuple[ProfileIngressAuthorization, ...]:
    """Build only the exact tuples named by this authenticated release."""

    specs = settlement.release_profile_ingress_specs
    if (type(specs) is not tuple
            or not 0 < len(specs) <= MAX_PROFILE_INGRESS_AUTHORIZATIONS
            or settlement.market_settlement_chain_id
                != router.settlement_chain_context_id):
        raise ValueError("release ingress topology is outside its fixed cap")
    validate_ingress_fee_schedule(settlement.ingress_fee_schedule)
    rows = tuple(
        profile_ingress_authorization_for(
            router,
            kind=kind,
            adapter_address=address,
            destination_bridge=destination_bridge,
            settlement_chain_id=settlement.market_settlement_chain_id,
            source_descriptor_override=(
                settlement.source_bridge_descriptor
                if kind is ForceKind.BRIDGE_CREDIT else None
            ),
            fee_schedule=settlement.ingress_fee_schedule,
        )
        for kind, address, destination_bridge in specs
    )
    return rows


def settlement_registration(
    router: "ActiveSettlementRouter",
    settlement: VersionedSettlementHistory,
    *, activation_block: int, predecessor_version: int,
    release_manifest_hash: str | bytes | None,
) -> SettlementRegistration:
    profile = settlement.execution_profile
    if (type(router) is not ActiveSettlementRouter
            or type(profile) is not ExecutionProfile
            or not profile.structurally_valid()
            or profile.protocol_version != settlement.protocol_version
            or profile.execution_profile_hash
                != settlement.execution_profile_hash
            or settlement.market_settlement_chain_id
                != router.settlement_chain_context_id
            or router.configuration_hash
                != active_settlement_router_configuration_hash(
                    router.settlement_chain_context_id
                )):
        raise ValueError("Settlement registration changed chain context")
    rows = release_profile_ingress_authorizations(router, settlement)
    if (len(rows) != 2
            or tuple(sorted(row.kind.value for row in rows)) != (0, 1)
            or len({(
                row.router_address, row.router_runtime_hash,
                row.router_configuration_hash, row.queue_address,
                row.queue_runtime_hash, row.queue_configuration_hash,
                row.destination_chain_id,
            ) for row in rows}) != 1):
        raise ValueError("launch ingress authorization graph is split")
    ids = tuple(row.authorization_id for row in rows)
    addresses = tuple(row.adapter_address for row in rows)
    if (len(ids) != len(set(ids))
            or len(addresses) != len(set(addresses))):
        raise ValueError("release profile ingress authorization set is invalid")
    by_id = MappingProxyType({row.authorization_id: row for row in rows})
    by_address = MappingProxyType({row.adapter_address: row for row in rows})
    fee_schedules = {
        (
            row.fixed_ingress_wei,
            row.execution_wei_per_accounted_gas,
            row.proof_wei_per_accounted_gas,
            row.permanent_wei_per_byte,
            row.maximum_accepted_fee_wei,
        )
        for row in rows
    }
    if len(fee_schedules) != 1:
        raise ValueError("release ingress fee schedule is split")
    ingress_fee_schedule = next(iter(fee_schedules))
    predecessor = router.registrations.get(predecessor_version)
    if (predecessor is not None
            and any(new < old for new, old in zip(
                ingress_fee_schedule, predecessor.ingress_fee_schedule
            ))):
        raise ValueError("release ingress fee schedule decreased")
    root = profile_ingress_authorization_root(rows)
    bridge_authorizations = tuple(
        row for row in rows if row.kind is ForceKind.BRIDGE_CREDIT
    )
    if len(bridge_authorizations) != 1:
        raise ValueError("release profile must name exactly one Bridge adapter")
    release_manifests: dict[str, ReleaseManifestV2] = {}
    for bridge_authorization in bridge_authorizations:
        components, bridge_descriptor, infrastructure_hash, descriptor = (
            canonical_destination_release_topology(
                router,
                adapter_address=bridge_authorization.adapter_address,
                adapter_configuration_hash=(
                    bridge_authorization.configuration_hash
                ),
                destination_bridge=bridge_authorization.destination_bridge,
            )
        )
        release_manifest = ReleaseManifestV2(
            settlement.protocol_version,
            settlement.market_settlement_chain_id,
            descriptor.destination_chain_id,
            descriptor.destination_genesis_hash,
            settlement.execution_profile_hash,
            "manifest:v2",
            descriptor.destination_namespace,
            f"anchor:v{settlement.protocol_version}",
            f"code:anchor:v{settlement.protocol_version}",
            descriptor.destination_domain_id,
            descriptor.destination_bridge,
            descriptor.destination_bridge_execution_hash,
            bridge_descriptor,
            infrastructure_hash,
            profile.migration_transition_verifier_descriptor,
            root,
            NATIVE_LIQUIDITY_POOL,
            NATIVE_LIQUIDITY_POOL_RUNTIME_HASH,
            NATIVE_LIQUIDITY_POOL_CONFIGURATION_HASH,
            components,
            profile,
        )
        if (not release_manifest.structurally_valid()
                or release_manifest.destination_domain_id
                    != bridge_authorization.destination_domain_id):
            raise ValueError("release ingress graph is not acyclic and exact")
        release_manifests[bridge_authorization.adapter_address] = release_manifest
    primary_manifest = release_manifests[bridge_authorizations[0].adapter_address]
    if (release_manifest_hash is not None
            and release_manifest_hash != primary_manifest.commitment):
        raise ValueError(
            "migration target manifest does not commit the ingress profile"
        )
    authenticated_manifest_hash = primary_manifest.commitment
    return SettlementRegistration(
        settlement,
        settlement.runtime_hash,
        settlement.execution_profile_hash,
        profile,
        activation_block,
        predecessor_version,
        authenticated_manifest_hash,
        authenticated_manifest_hash,
        primary_manifest,
        MappingProxyType(release_manifests),
        rows,
        by_id,
        by_address,
        root,
        router.settlement_chain_context_id,
        ingress_fee_schedule,
    )


_MIGRATION_EXECUTION_OUTPUT_CAPABILITY = object()
_VERIFIED_MIGRATION_EVM_TRACE_CAPABILITY = object()
_MIGRATION_TRANSITION_VERIFIER_RESULT_CAPABILITY = object()

MIGRATION_VERIFIER_CONFIG_TYPE = (
    "MigrationTransitionVerifierConfigV2(bytes32 verifyingKeyHash,"
    "bytes32 proofSystemId,bytes32 publicInputSchemaHash,bytes4 selector,"
    "uint32 maximumProofBytes,uint64 verificationGasLimit)"
)
MIGRATION_VERIFIER_CONFIG_TYPEHASH = keccak256(
    MIGRATION_VERIFIER_CONFIG_TYPE.encode()
)
MIGRATION_VERIFIER_DESCRIPTOR_TYPE = (
    "MigrationTransitionVerifierDescriptorV2(address verifier,"
    "bytes32 runtimeHash,bytes32 configurationHash,bytes32 verifyingKeyHash,"
    "bytes32 proofSystemId,bytes32 publicInputSchemaHash,bytes4 selector,"
    "uint32 maximumProofBytes,uint64 verificationGasLimit)"
)
MIGRATION_VERIFIER_DESCRIPTOR_TYPEHASH = keccak256(
    MIGRATION_VERIFIER_DESCRIPTOR_TYPE.encode()
)
MIGRATION_VERIFIER_CONFIG_GETTER_GAS = 50_000
MIGRATION_VERIFIER_CONFIG_GETTER_BYTES = 32


def migration_transition_verifier_configuration_hash(
    verifying_key_hash: str,
    proof_system_id: str = "groth16-bn254",
    public_input_schema_hash: str = "schema:migration-transition:v1",
    maximum_proof_bytes: int = 65_536,
    verification_gas_limit: int = 2_000_000,
    selector: bytes = keccak256(
        b"verifyMigrationTransition(bytes,uint256[2])"
    )[:4],
) -> str:
    if (not verifying_key_hash or not proof_system_id
            or not public_input_schema_hash
            or type(selector) is not bytes or len(selector) != 4
            or not 0 < maximum_proof_bytes <= UINT32_MAX
            or not 0 < verification_gas_limit <= UINT64_MAX):
        raise ValueError("migration verifier configuration is invalid")
    return keccak256(b"".join((
        MIGRATION_VERIFIER_CONFIG_TYPEHASH,
        _model_fixed_bytes32(verifying_key_hash),
        _model_fixed_bytes32(proof_system_id),
        _model_fixed_bytes32(public_input_schema_hash),
        selector + bytes(28),
        _model_uint(maximum_proof_bytes, 32, "maximum proof bytes"),
        _model_uint(verification_gas_limit, 32, "verification gas limit"),
    ))).hex()


def migration_transition_encode(value: object) -> bytes:
    """Canonical typed byte encoding for migration verifier public inputs."""

    if value is None:
        return b"N"
    if type(value) is bool:
        return b"B" + (b"\x01" if value else b"\x00")
    if type(value) is int:
        if value < -1 or value > SEAT_UINT256_MAX:
            raise ValueError("migration verifier integer is out of range")
        return b"I" + (value + 1).to_bytes(32, "big")
    if type(value) is str:
        raw = value.encode()
        return b"S" + len(raw).to_bytes(4, "big") + raw
    if type(value) is bytes:
        return b"Y" + len(value).to_bytes(4, "big") + value
    if isinstance(value, Enum):
        return b"E" + migration_transition_encode(type(value).__name__) \
            + migration_transition_encode(value.name)
    if type(value) is tuple:
        return b"T" + len(value).to_bytes(4, "big") + b"".join(
            migration_transition_encode(item) for item in value
        )
    if is_dataclass(value):
        rows = tuple(
            (row.name, getattr(value, row.name))
            for row in dataclass_fields(value)
            if not row.name.startswith("_")
        )
        return b"D" + migration_transition_encode(type(value).__name__) \
            + migration_transition_encode(rows)
    raise ValueError("migration verifier value has no canonical encoding")


def migration_transition_decode(encoded: bytes) -> object:
    """Decode the behavioral typed codec used before Task 7 pins Solidity ABI."""

    if type(encoded) is not bytes:
        raise ValueError("behavioral typed calldata is not bytes")

    def take(offset: int, length: int) -> tuple[bytes, int]:
        end = offset + length
        if length < 0 or end > len(encoded):
            raise ValueError("behavioral typed calldata is truncated")
        return encoded[offset:end], end

    def parse(offset: int) -> tuple[object, int]:
        tag_raw, offset = take(offset, 1)
        if tag_raw == b"N":
            return None, offset
        if tag_raw == b"B":
            raw, offset = take(offset, 1)
            if raw not in {b"\x00", b"\x01"}:
                raise ValueError("behavioral boolean is noncanonical")
            return raw == b"\x01", offset
        if tag_raw == b"I":
            raw, offset = take(offset, 32)
            return int.from_bytes(raw, "big") - 1, offset
        if tag_raw in {b"S", b"Y"}:
            raw_length, offset = take(offset, 4)
            length = int.from_bytes(raw_length, "big")
            raw, offset = take(offset, length)
            if tag_raw == b"Y":
                return raw, offset
            try:
                return raw.decode(), offset
            except UnicodeDecodeError as exc:
                raise ValueError("behavioral string is not UTF-8") from exc
        if tag_raw == b"T":
            raw_count, offset = take(offset, 4)
            count = int.from_bytes(raw_count, "big")
            rows: list[object] = []
            for _ in range(count):
                row, offset = parse(offset)
                rows.append(row)
            return tuple(rows), offset
        raise ValueError("behavioral typed calldata has an unsupported tag")

    value, end = parse(0)
    if end != len(encoded):
        raise ValueError("behavioral typed calldata has trailing bytes")
    return value


@dataclass(frozen=True)
class MigrationTransitionVerifierDescriptor:
    """Immutable L1 descriptor for the one canonical zk/EVM verifier."""

    address: str
    runtime_hash: str
    configuration_hash: str
    verifying_key_hash: str
    proof_system_id: str
    public_input_schema_hash: str
    maximum_proof_bytes: int
    verification_gas_limit: int
    selector: bytes
    nonproxy: bool = True

    @property
    def commitment(self) -> str:
        return keccak256(b"".join((
            MIGRATION_VERIFIER_DESCRIPTOR_TYPEHASH,
            bytes(12) + _model_address20(self.address),
            _model_fixed_bytes32(self.runtime_hash),
            bytes.fromhex(self.configuration_hash),
            _model_fixed_bytes32(self.verifying_key_hash),
            _model_fixed_bytes32(self.proof_system_id),
            _model_fixed_bytes32(self.public_input_schema_hash),
            self.selector + bytes(28),
            _model_uint(self.maximum_proof_bytes, 32, "maximum proof bytes"),
            _model_uint(self.verification_gas_limit, 32,
                        "verification gas limit"),
        ))).hex()

    def structurally_valid(self) -> bool:
        return (
            bool(self.address)
            and bool(self.runtime_hash)
            and bool(self.verifying_key_hash)
            and bool(self.proof_system_id)
            and bool(self.public_input_schema_hash)
            and 0 < self.maximum_proof_bytes <= MAX_MIGRATION_PROOF_BYTES
            and 0 < self.verification_gas_limit <= 30_000_000
            and type(self.selector) is bytes and len(self.selector) == 4
            and self.nonproxy
            and self.configuration_hash
                == migration_transition_verifier_configuration_hash(
                    self.verifying_key_hash,
                    self.proof_system_id,
                    self.public_input_schema_hash,
                    self.maximum_proof_bytes,
                    self.verification_gas_limit,
                    self.selector,
                )
        )


def release_deployment_commitment(
    manifest: "ReleaseManifestV2", *, transition_kind: int,
    retirement_queue_count: int,
) -> str:
    """Derive the sole deployment-policy input from manifest and transition."""

    if (type(manifest) is not ReleaseManifestV2
            or not manifest.structurally_valid()
            or transition_kind not in {1, 2}
            or type(retirement_queue_count) is not int
            or not 0 <= retirement_queue_count <= UINT64_MAX):
        raise ValueError("release deployment commitment is not canonical")
    return hashlib.sha256(
        b"TAIKO_DEPLOYMENT_COMMITMENT_V2\x00"
        + migration_transition_encode((
            transition_kind,
            manifest.protocol_version,
            manifest.commitment,
            manifest.destination_infrastructure_hash,
            manifest.components,
            manifest.destination_bridge_descriptor
                .native_liquidity_pool_configuration_hash,
            retirement_queue_count,
            f"prestate-policy:{transition_kind}",
            f"poststate-policy:{transition_kind}",
        ))
    ).hexdigest()


@dataclass(frozen=True)
class MigrationTransitionPublicInputs:
    """Exact public inputs returned by IMigrationTransitionVerifier."""

    candidate_digest: str
    base_core: CanonicalCore
    output_core: CanonicalCore
    target_protocol_version: int
    execution_profile_hash: str
    settlement_chain_id: int
    router_address: str
    router_runtime_hash: str
    router_configuration_hash: str
    transition_kind: int
    router_generation: int
    canonical_sequence: int
    target_manifest_hash: bytes
    queue_address: str
    queue_runtime_hash: str
    queue_configuration_hash: str
    queue_root: str
    queue_count: int
    start_cursor: int
    end_cursor: int
    descriptor_commitment: str
    beneficiary: str
    anchor_number: int
    anchor_hash: str
    force_root: str
    force_cutoff: int
    source_domain_id: str
    source_registration_epoch: int
    source_bridge_execution_hash: str
    release_system_calldata_hash: str
    inbox_system_calldata_hash: str
    anchor_system_tx_position: int
    inbox_system_tx_position: int
    deployment_commitment: str
    pre_inbox_last_applied_l2_block: int
    post_inbox_last_applied_l2_block: int

    def __post_init__(self) -> None:
        if (not self.candidate_digest
                or self.target_protocol_version <= 0
                or not self.execution_profile_hash
                or not 0 < self.settlement_chain_id <= UINT64_MAX
                or not self.router_address
                or not self.router_runtime_hash
                or not self.router_configuration_hash
                or self.transition_kind not in {1, 2}
                or self.router_generation <= 0
                or self.canonical_sequence < 0
                or type(self.target_manifest_hash) is not bytes
                or len(self.target_manifest_hash) != 32
                or not self.queue_address
                or not self.queue_runtime_hash
                or not self.queue_configuration_hash
                or not self.queue_root
                or not 0 <= self.queue_count <= MAX_FORCE_QUEUE_ITEMS
                or not 0 <= self.start_cursor <= self.end_cursor
                    <= self.queue_count
                or not self.descriptor_commitment
                or not self.beneficiary
                or self.anchor_number < 0
                or not self.anchor_hash
                or not self.force_root
                or not 0 <= self.force_cutoff <= self.queue_count
                or not self.source_domain_id
                or not 0 < self.source_registration_epoch <= UINT64_MAX
                or not self.source_bridge_execution_hash
                or not self.release_system_calldata_hash
                or not self.inbox_system_calldata_hash
                or self.anchor_system_tx_position
                    != ANCHOR_SYSTEM_TX_POSITION
                or self.inbox_system_tx_position
                    != INBOX_SYSTEM_TX_POSITION
                or not self.deployment_commitment
                or type(self.pre_inbox_last_applied_l2_block) is not int
                or self.pre_inbox_last_applied_l2_block < -1
                or type(self.post_inbox_last_applied_l2_block) is not int
                or self.post_inbox_last_applied_l2_block
                    <= self.pre_inbox_last_applied_l2_block
                or self.post_inbox_last_applied_l2_block
                    != self.output_core.l2_block_number):
            raise ValueError("migration transition public inputs are invalid")

    @property
    def digest(self) -> str:
        return hashlib.sha256(
            b"TAIKO_MIGRATION_TRANSITION_PUBLIC_INPUTS_V1\x00"
            + migration_transition_encode(tuple(
                getattr(self, name) for name in self.__dataclass_fields__
            ))
        ).hexdigest()


def migration_transition_public_inputs_from_l1(
    *,
    router: "ActiveSettlementRouter",
    settlement: VersionedSettlementHistory,
    target_manifest_hash: bytes,
    candidate: Candidate,
    rows: tuple["InboxRowV2", ...],
    pre_inbox_last_applied_l2_block: int,
) -> MigrationTransitionPublicInputs:
    """Reconstruct L1 fields and bind the circuit-output state commitment."""

    if (type(router) is not ActiveSettlementRouter
            or type(settlement) is not VersionedSettlementHistory
            or type(candidate) is not Candidate
            or candidate.count != 1
            or type(rows) is not tuple
            or type(pre_inbox_last_applied_l2_block) is not int
            or pre_inbox_last_applied_l2_block < -1
            or type(target_manifest_hash) is not bytes
            or len(target_manifest_hash) != 32):
        raise ValueError("migration L1 statement inputs have wrong types")
    old_registration = router.registrations.get(router.active_version)
    if type(old_registration) is not SettlementRegistration:
        raise ValueError("migration L1 statement has no active registration")
    old = old_registration.settlement
    source = router._source_bridge_authority
    block = candidate.blocks[0]
    output_core = CanonicalCore(
        candidate.end_l2_block_number,
        block.block_hash,
        block.slot,
        candidate.end_state_root,
        block.message_end,
        candidate.winning_data_commitment,
        candidate.next_base_fee,
        candidate.next_excess_blob_gas,
        candidate.end_terminal_root,
        candidate.end_terminal_count,
    )
    preview = settlement_registration(
        router,
        settlement,
        # Activation block is intentionally absent from ReleaseManifest and
        # from the verifier statement; zero makes that independence explicit.
        activation_block=0,
        predecessor_version=router.active_version,
        release_manifest_hash=target_manifest_hash,
    )
    manifest = preview.release_manifest
    if (type(source) is not SourceBridgeV2
            or source.credit_registry
                is not router._bridge_credit_registry_authority
            or old_registration.execution_profile
                is not old.execution_profile
            or preview.execution_profile is not settlement.execution_profile
            or manifest.migration_transition_verifier
                != settlement.execution_profile
                    .migration_transition_verifier_descriptor
            or block.inbox_system_calldata_hash
                != inbox_system_calldata_hash(rows)):
        raise ValueError("migration L1 statement authority graph is split")
    transition_kind = 2
    return MigrationTransitionPublicInputs(
        candidate_inbox_execution_digest(candidate),
        copy.deepcopy(old.core),
        output_core,
        settlement.protocol_version,
        settlement.execution_profile_hash,
        router.settlement_chain_context_id,
        router.address,
        router.runtime_hash,
        router.configuration_hash,
        transition_kind,
        router.migration_gate.generation,
        old.current_sequence,
        target_manifest_hash,
        router.forced_queue.address,
        router.forced_queue.runtime_hash,
        router.forced_queue.config_hash,
        router.forced_queue.root,
        router.forced_queue.count,
        block.message_start,
        block.message_end,
        block.inbox_descriptor_commitment,
        candidate.beneficiary,
        block.anchor_number,
        block.anchor_hash,
        block.force_root,
        block.force_cutoff,
        source.source_domain_id,
        source.source_registration_epoch,
        source.frozen_bridge_execution_hash,
        release_system_calldata_hash(manifest, router.forced_queue.count),
        inbox_system_calldata_hash(rows),
        block.anchor_system_tx_position,
        block.inbox_system_tx_position,
        release_deployment_commitment(
            manifest,
            transition_kind=transition_kind,
            retirement_queue_count=router.forced_queue.count,
        ),
        pre_inbox_last_applied_l2_block,
        output_core.l2_block_number,
    )


@dataclass(frozen=True)
class MigrationTransitionProof:
    """Opaque proof bytes plus their claimed canonical public inputs."""

    public_inputs: MigrationTransitionPublicInputs
    proof_bytes: bytes
    seal: str = field(repr=False)


@dataclass(frozen=True, eq=False)
class MigrationTransitionVerifierResult:
    verifier: "IMigrationTransitionVerifier" = field(compare=False, repr=False)
    descriptor: MigrationTransitionVerifierDescriptor
    public_inputs: MigrationTransitionPublicInputs
    proof_commitment: str
    returndata: bytes
    seal: str = field(repr=False)
    _capability: object = field(repr=False, compare=False)

    def __post_init__(self) -> None:
        if (self._capability
                is not _MIGRATION_TRANSITION_VERIFIER_RESULT_CAPABILITY
                or type(self.descriptor)
                    is not MigrationTransitionVerifierDescriptor
                or not self.descriptor.structurally_valid()
                or type(self.public_inputs)
                    is not MigrationTransitionPublicInputs
                or not self.proof_commitment
                or type(self.returndata) is not bytes
                or not self.seal):
            raise ValueError("migration verifier result is invalid")

    @property
    def digest(self) -> str:
        return migration_transition_result_digest(
            self.descriptor,
            self.public_inputs.digest,
            self.proof_commitment,
        )


def migration_transition_result_digest(
    descriptor: MigrationTransitionVerifierDescriptor,
    statement_digest: str,
    proof_commitment: str,
) -> str:
    if (type(descriptor) is not MigrationTransitionVerifierDescriptor
            or not descriptor.structurally_valid()
            or len(statement_digest) != 64
            or not proof_commitment):
        raise ValueError("migration verifier result inputs are malformed")
    return hashlib.sha256(
        b"TAIKO_MIGRATION_TRANSITION_VERIFIER_RESULT_V1\x00"
        + migration_transition_encode((
            descriptor,
            statement_digest,
            proof_commitment,
            bytes.fromhex(statement_digest),
        ))
    ).hexdigest()


@dataclass
class NativeEthSinkV2:
    """Typed profile sink account used only for native-ETH surplus."""

    address: str
    asset_id: str = "NATIVE_ETH"
    balance: int = 0
    rejects_native: bool = False
    callback: Callable[[object], None] | None = field(
        default=None, compare=False, repr=False
    )

    def structurally_valid(self) -> bool:
        return (bool(self.address) and self.asset_id == "NATIVE_ETH"
                and type(self.balance) is int and self.balance >= 0)

    def _receive_from_bridge(self, bridge: object, amount: int) -> bool:
        if (not self.structurally_valid() or self.rejects_native
                or type(amount) is not int or amount < 0):
            return False
        self.balance = seat_checked_add(
            self.balance, amount, "bridge surplus sink balance"
        )
        if self.callback is not None:
            self.callback(bridge)
        return True


class IMigrationTransitionVerifier:
    """Production interface: verify proof bytes and return exact public inputs."""

    @property
    def descriptor(self) -> MigrationTransitionVerifierDescriptor:
        raise NotImplementedError

    def verify_transition(
        self, proof: MigrationTransitionProof,
    ) -> MigrationTransitionVerifierResult:
        raise NotImplementedError

    def valid_result(self, result: MigrationTransitionVerifierResult) -> bool:
        raise NotImplementedError

    def valid_result_seal(self, digest: str, seal: str) -> bool:
        raise NotImplementedError


@dataclass(frozen=True, eq=False)
class ExecutionProfile:
    """Immutable per-version verifier trust root committed by the release."""

    protocol_version: int
    namespace: str
    migration_transition_verifier_descriptor: (
        MigrationTransitionVerifierDescriptor
    )
    migration_transition_verifier: IMigrationTransitionVerifier = field(
        compare=False, repr=False
    )
    bridge_surplus_sink: NativeEthSinkV2 = field(
        compare=False, repr=False
    )

    def __deepcopy__(self, memo: dict[int, object]) -> "ExecutionProfile":
        # The verifier instance is an immutable deployed-code capability.
        memo[id(self)] = self
        return self

    @property
    def execution_profile_hash(self) -> str:
        return hashlib.sha256(
            b"TAIKO_EXECUTION_PROFILE_V1\x00"
            + migration_transition_encode((
                self.protocol_version,
                self.namespace,
                self.migration_transition_verifier_descriptor,
                self.bridge_surplus_sink.asset_id,
                self.bridge_surplus_sink.address,
            ))
        ).hexdigest()

    def structurally_valid(self) -> bool:
        verifier = self.migration_transition_verifier
        return (
            self.protocol_version > 0
            and bool(self.namespace)
            and type(self.migration_transition_verifier_descriptor)
                is MigrationTransitionVerifierDescriptor
            and self.migration_transition_verifier_descriptor
                .structurally_valid()
            and isinstance(verifier, IMigrationTransitionVerifier)
            and verifier.descriptor
                == self.migration_transition_verifier_descriptor
            and type(self.bridge_surplus_sink) is NativeEthSinkV2
            and self.bridge_surplus_sink.structurally_valid()
        )


class TestMigrationTransitionVerifier(IMigrationTransitionVerifier):
    """Test-only exact mock of the immutable on-chain verifier interface."""

    def __init__(self, descriptor: MigrationTransitionVerifierDescriptor):
        if (type(descriptor) is not MigrationTransitionVerifierDescriptor
                or not descriptor.structurally_valid()):
            raise ValueError("test migration verifier descriptor is invalid")
        self._descriptor = descriptor
        self._seal_secret = object()
        self.returndata_override: bytes | None = None
        self.raise_on_verify = False

    @property
    def descriptor(self) -> MigrationTransitionVerifierDescriptor:
        return self._descriptor

    def _seal(self, namespace: bytes, digest: str) -> str:
        return hashlib.sha256(
            namespace
            + id(self._seal_secret).to_bytes(32, "big")
            + digest.encode()
        ).hexdigest()

    def verify_transition(
        self, proof: MigrationTransitionProof,
    ) -> MigrationTransitionVerifierResult:
        if self.raise_on_verify:
            raise RuntimeError("simulated migration verifier revert/OOG")
        if (type(proof) is not MigrationTransitionProof
                or type(proof.public_inputs)
                    is not MigrationTransitionPublicInputs
                or type(proof.proof_bytes) is not bytes
                or not proof.proof_bytes
                or len(proof.proof_bytes)
                    > self.descriptor.maximum_proof_bytes):
            raise ValueError("migration transition proof is malformed")
        proof_commitment = hashlib.sha256(proof.proof_bytes).hexdigest()
        proof_digest = hashlib.sha256(migration_transition_encode((
            self.descriptor,
            proof.public_inputs.digest,
            proof_commitment,
        ))).hexdigest()
        if proof.seal != self._seal(
                b"TAIKO_TEST_MIGRATION_TRANSITION_PROOF_V1\x00",
                proof_digest,
        ):
            raise ValueError("migration transition proof did not verify")
        result = MigrationTransitionVerifierResult(
            self,
            self.descriptor,
            proof.public_inputs,
            proof_commitment,
            (
                bytes.fromhex(proof.public_inputs.digest)
                if self.returndata_override is None
                else self.returndata_override
            ),
            "PENDING",
            _MIGRATION_TRANSITION_VERIFIER_RESULT_CAPABILITY,
        )
        return replace(
            result,
            seal=self._seal(
                b"TAIKO_MIGRATION_TRANSITION_VERIFIER_RESULT_SEAL_V1\x00",
                result.digest,
            ),
        )

    def valid_result(self, result: MigrationTransitionVerifierResult) -> bool:
        return (
            type(result) is MigrationTransitionVerifierResult
            and result.verifier is self
            and result.descriptor == self.descriptor
            and result.seal == self._seal(
                b"TAIKO_MIGRATION_TRANSITION_VERIFIER_RESULT_SEAL_V1\x00",
                result.digest,
            )
        )

    def valid_result_seal(self, digest: str, seal: str) -> bool:
        return (
            bool(digest)
            and seal == self._seal(
                b"TAIKO_MIGRATION_TRANSITION_VERIFIER_RESULT_SEAL_V1\x00",
                digest,
            )
        )


def execution_profile_for_test(
    protocol_version: int,
    namespace: str | None = None,
    *,
    verifier_revision: str | None = None,
) -> ExecutionProfile:
    """Fixture-only deployment of one exact per-profile verifier instance."""

    if protocol_version <= 0:
        raise ValueError("test execution profile version must be positive")
    profile_namespace = namespace or f"profile:test:{protocol_version}"
    revision = verifier_revision or f"v{protocol_version}"
    address = f"migration-transition-verifier:{revision}"
    runtime_hash = f"code:migration-transition-verifier:{revision}"
    verifying_key_hash = f"vk:migration-transition:{revision}"
    schema_hash = f"schema:migration-transition:{revision}"
    descriptor = MigrationTransitionVerifierDescriptor(
        address,
        runtime_hash,
        migration_transition_verifier_configuration_hash(
            verifying_key_hash,
            public_input_schema_hash=schema_hash,
        ),
        verifying_key_hash,
        "groth16-bn254",
        schema_hash,
        65_536,
        2_000_000,
        keccak256(b"verifyMigrationTransition(bytes,uint256[2])")[:4],
    )
    verifier = TestMigrationTransitionVerifier(descriptor)
    profile = ExecutionProfile(
        protocol_version,
        profile_namespace,
        descriptor,
        verifier,
        NativeEthSinkV2(f"bridge-surplus:{profile_namespace}"),
    )
    if not profile.structurally_valid():
        raise AssertionError("test execution profile is malformed")
    return profile


def issue_migration_transition_proof_for_test(
    verifier: TestMigrationTransitionVerifier,
    public_inputs: MigrationTransitionPublicInputs,
    proof_bytes: bytes,
) -> MigrationTransitionProof:
    """Fixture-only proof generator, outside the production verifier ABI."""

    if (type(verifier) is not TestMigrationTransitionVerifier
            or type(public_inputs) is not MigrationTransitionPublicInputs
            or type(proof_bytes) is not bytes or not proof_bytes):
        raise ValueError("test migration proof is not canonical")
    proof_commitment = hashlib.sha256(proof_bytes).hexdigest()
    digest = hashlib.sha256(migration_transition_encode((
        verifier.descriptor,
        public_inputs.digest,
        proof_commitment,
    ))).hexdigest()
    return MigrationTransitionProof(
        public_inputs,
        proof_bytes,
        verifier._seal(
            b"TAIKO_TEST_MIGRATION_TRANSITION_PROOF_V1\x00", digest
        ),
    )


@dataclass(frozen=True, eq=False)
class VerifiedMigrationEvmTrace:
    """Opaque zk/EVM verifier output for the complete activation block."""

    verifier: "InboxValidityExecutionAuthority" = field(
        compare=False, repr=False
    )
    transition_verifier: IMigrationTransitionVerifier = field(
        compare=False, repr=False
    )
    transition_verifier_descriptor: MigrationTransitionVerifierDescriptor
    transition_result_digest: str
    transition_result_seal: str
    transition_proof: MigrationTransitionProof = field(
        compare=False, repr=False
    )
    transition_statement_digest: str
    router_generation: int
    source_canonical_sequence: int
    candidate_digest: str
    base_core: CanonicalCore
    output_core: CanonicalCore
    target_protocol_version: int
    execution_profile_hash: str
    target_manifest_hash: bytes
    queue_root: str
    queue_count: int
    start_cursor: int
    end_cursor: int
    release_system_calldata_hash: str
    system_calldata_hash: str
    deployment_commitment: str
    observed_deployment_digest: str
    observed_deployment_seal: str
    pre_inbox_last_applied_l2_block: int
    post_inbox_last_applied_l2_block: int
    proof_commitment: str
    seal: str
    _capability: object = field(repr=False, compare=False)

    def __post_init__(self) -> None:
        if (self._capability
                is not _VERIFIED_MIGRATION_EVM_TRACE_CAPABILITY
                or type(self.verifier)
                    is not InboxValidityExecutionAuthority
                or self.transition_verifier
                    is not self.verifier.migration_transition_verifier
                or self.transition_verifier_descriptor
                    != self.transition_verifier.descriptor
                or not self.transition_verifier_descriptor.structurally_valid()
                or not self.transition_result_digest
                or not self.transition_result_seal
                or type(self.transition_proof) is not MigrationTransitionProof
                or len(self.transition_statement_digest) != 64
                or self.router_generation <= 0
                or self.source_canonical_sequence < 0
                or not self.candidate_digest
                or self.target_protocol_version <= 0
                or not self.execution_profile_hash
                or type(self.target_manifest_hash) is not bytes
                or len(self.target_manifest_hash) != 32
                or not self.queue_root
                or not 0 <= self.queue_count <= MAX_FORCE_QUEUE_ITEMS
                or not 0 <= self.start_cursor <= self.end_cursor
                    <= self.queue_count
                or not self.release_system_calldata_hash
                or not self.system_calldata_hash
                or not self.deployment_commitment
                or not self.observed_deployment_digest
                or not self.observed_deployment_seal
                or self.pre_inbox_last_applied_l2_block < -1
                or self.post_inbox_last_applied_l2_block
                    <= self.pre_inbox_last_applied_l2_block
                or not self.proof_commitment
                or not self.seal):
            raise ValueError("migration EVM trace is not canonical")

    @property
    def digest(self) -> str:
        projection = (
            id(self.verifier), id(self.transition_verifier),
            self.transition_verifier_descriptor,
            self.transition_result_digest,
            self.transition_result_seal,
            self.transition_proof.public_inputs.digest,
            hashlib.sha256(self.transition_proof.proof_bytes).hexdigest(),
            self.transition_statement_digest,
            self.router_generation,
            self.source_canonical_sequence,
            self.candidate_digest,
            self.base_core, self.output_core,
            self.target_protocol_version,
            self.execution_profile_hash,
            self.target_manifest_hash,
            self.queue_root, self.queue_count,
            self.start_cursor, self.end_cursor,
            self.release_system_calldata_hash,
            self.system_calldata_hash,
            self.deployment_commitment,
            self.observed_deployment_digest,
            self.observed_deployment_seal,
            self.pre_inbox_last_applied_l2_block,
            self.post_inbox_last_applied_l2_block,
            self.proof_commitment,
        )
        return hashlib.sha256(
            b"TAIKO_VERIFIED_MIGRATION_EVM_TRACE_V1\x00"
            + repr(projection).encode()
        ).hexdigest()


@dataclass(frozen=True)
class MigrationActivationCallV2:
    """Untrusted value-only L1 activation calldata.

    The Router reconstructs the statement and invokes the profile-pinned
    verifier itself. No L2 authority object, capability, or opaque seal is an
    authorization input.
    """

    candidate: Candidate
    transition_proof: MigrationTransitionProof
    base_core: CanonicalCore
    output_core: CanonicalCore
    target_protocol_version: int
    target_manifest_hash: bytes
    transition_statement_digest: str
    router_generation: int
    source_canonical_sequence: int
    start_cursor: int
    end_cursor: int
    beneficiary: str
    rows: tuple["InboxRowV2", ...]
    pre_inbox_last_applied_l2_block: int
    post_inbox_last_applied_l2_block: int

    def __post_init__(self) -> None:
        if (type(self.target_manifest_hash) is not bytes
                or len(self.target_manifest_hash) != 32
                or len(self.transition_statement_digest) != 64
                or self.router_generation <= 0
                or self.source_canonical_sequence < 0
                or type(self.candidate) is not Candidate
                or type(self.transition_proof)
                    is not MigrationTransitionProof
                or self.target_protocol_version <= 0
                or not 0 <= self.start_cursor <= self.end_cursor
                or not self.beneficiary
                or type(self.rows) is not tuple
                or self.pre_inbox_last_applied_l2_block < -1
                or self.post_inbox_last_applied_l2_block
                    <= self.pre_inbox_last_applied_l2_block):
            raise ValueError("migration activation proof is not canonical")

    @property
    def digest(self) -> str:
        projection = (
            candidate_inbox_execution_digest(self.candidate),
            self.transition_proof.public_inputs.digest,
            hashlib.sha256(self.transition_proof.proof_bytes).hexdigest(),
            self.base_core,
            self.output_core,
            self.target_protocol_version,
            self.target_manifest_hash,
            self.transition_statement_digest,
            self.router_generation,
            self.source_canonical_sequence,
            self.start_cursor,
            self.end_cursor,
            self.beneficiary,
            inbox_system_calldata_hash(self.rows),
            self.pre_inbox_last_applied_l2_block,
            self.post_inbox_last_applied_l2_block,
        )
        return hashlib.sha256(
            b"TAIKO_MIGRATION_ACTIVATION_CALL_V2\x00"
            + repr(projection).encode()
        ).hexdigest()


# Compatibility alias for node-local test helper annotations. Production
# semantics are the plain value-only MigrationActivationCallV2 above.
VerifiedMigrationExecutionOutput = MigrationActivationCallV2

@dataclass(frozen=True)
class MigrationActivationReceipt:
    router_generation: int
    old_protocol_version: int
    new_protocol_version: int
    old_target: str
    new_target: str
    target_manifest_hash: bytes
    seat_generation: int
    old_authorization_id: bytes
    new_authorization_id: bytes
    activation_block: int
    migration_stage_id: bytes | None
    migration_lineup_commitment: bytes | None

    @property
    def key(self) -> tuple[int, bytes]:
        return self.router_generation, self.target_manifest_hash


@dataclass(frozen=True, eq=False)
class IngressBinding:
    adapter: object
    kind: ForceKind
    address: str
    runtime_hash: str
    configuration_hash: str


@dataclass
class ActiveSettlementRouter:
    """Append-only immutable registry and read-only history router."""

    version_manager: str
    forced_queue: QueueContinuity
    inbox_apply_descriptor: InboxApplyDeploymentDescriptor
    migration_gate: MigrationGate
    header_oracle: L1HeaderOracle
    settlement_chain_context_id: int = MODEL_SETTLEMENT_CHAIN_CONTEXT_ID
    address: str = "active-settlement-router"
    runtime_hash: str = ACTIVE_SETTLEMENT_ROUTER_RUNTIME_HASH
    configuration_hash: str = ACTIVE_SETTLEMENT_ROUTER_CONFIGURATION_HASH
    bootstrap_release_manifest_hash: bytes = b"\x00" * 32
    forced_queue_runtime_hash: str = "code:forced-queue:v2"
    forced_queue_config_hash: str = "config:forced-queue:depth64:v2"
    builder_registry_id: str = "builder-registry"
    schedule_oracle_id: str = "schedule-oracle"
    active_version: int = 0
    registrations: dict[int, SettlementRegistration] = field(default_factory=dict)
    activation_receipts: dict[
        tuple[int, bytes], MigrationActivationReceipt
    ] = field(default_factory=dict)
    activation_receipt_keys_by_generation: dict[
        int, tuple[int, bytes]
    ] = field(default_factory=dict)
    successor_receipt_key_by_old_authorization_id: dict[
        bytes, tuple[int, bytes]
    ] = field(default_factory=dict)
    used_target_addresses: set[str] = field(default_factory=set)
    _authorized_ingress: tuple[IngressBinding, ...] = field(
        default_factory=tuple, repr=False
    )
    _authorized_ingress_by_address: dict[str, IngressBinding] = field(
        default_factory=dict, repr=False
    )
    _authorized_ingress_adapter_ids: frozenset[int] = field(
        default_factory=frozenset, repr=False
    )
    _version_manager_authority: object | None = field(
        default=None, compare=False, repr=False
    )
    _bridge_credit_registry_authority: object | None = field(
        default=None, compare=False, repr=False
    )
    _source_bridge_authority: object | None = field(
        default=None, compare=False, repr=False
    )
    _bridge_domain_registry_authority: object | None = field(
        default=None, compare=False, repr=False
    )
    _source_bridge_factories_by_address: dict[str, object] = field(
        default_factory=dict, compare=False, repr=False
    )
    _source_bundles_by_descriptor_id: dict[bytes, tuple[object, ...]] = field(
        default_factory=dict, compare=False, repr=False
    )
    _source_descriptor_id_by_version: dict[int, bytes] = field(
        default_factory=dict, compare=False, repr=False
    )
    _used_source_component_addresses: set[str] = field(
        default_factory=set, compare=False, repr=False
    )
    _profile_deployments_by_version: dict[int, MappingProxyType] = field(
        default_factory=dict, compare=False, repr=False
    )
    ingress_entered: bool = field(default=False, compare=False)
    ingress_lookup_probes: int = field(default=0, compare=False)
    _queue_transition_frame: tuple[str, int, str] | None = field(
        default=None, compare=False, repr=False
    )

    def __post_init__(self) -> None:
        if (
            type(self.header_oracle) is not L1HeaderOracle
            or type(self.settlement_chain_context_id) is not int
            or not 0 < self.settlement_chain_context_id <= UINT64_MAX
            or self.configuration_hash
                != active_settlement_router_configuration_hash(
                    self.settlement_chain_context_id
                )
            or type(self.bootstrap_release_manifest_hash) is not bytes
            or len(self.bootstrap_release_manifest_hash) != 32
            or self.header_oracle.address != L1_HEADER_ORACLE_ADDRESS
            or self.header_oracle.runtime_hash
                != L1_HEADER_ORACLE_RUNTIME_HASH
            or self.header_oracle.configuration_hash
                != L1_HEADER_ORACLE_CONFIGURATION_HASH
            or type(self.inbox_apply_descriptor)
                is not InboxApplyDeploymentDescriptor
            or not self.inbox_apply_descriptor.structurally_valid()
        ):
            raise ValueError("active router header oracle is not exact")
        if not self.forced_queue._bind_router_once(self):
            raise ValueError("forced queue is bound to another active router")

    def __deepcopy__(
        self, memo: dict[int, object]
    ) -> "ActiveSettlementRouter":
        """Preserve the exact Router capability across transaction snapshots."""

        memo[id(self)] = self
        return self

    def __setattr__(self, name: str, value: object) -> None:
        if name in {
            "version_manager", "forced_queue", "inbox_apply_descriptor",
            "migration_gate", "header_oracle", "settlement_chain_context_id",
            "address",
            "runtime_hash", "configuration_hash",
            "bootstrap_release_manifest_hash",
            "forced_queue_runtime_hash", "forced_queue_config_hash",
            "builder_registry_id", "schedule_oracle_id", "_authorized_ingress",
            "_authorized_ingress_by_address",
            "_authorized_ingress_adapter_ids",
            "_version_manager_authority",
            "_bridge_credit_registry_authority",
            "_source_bridge_authority",
            "_bridge_domain_registry_authority",
            "_queue_transition_frame",
        } and name in self.__dict__:
            raise AttributeError(f"active-router {name} is immutable")
        object.__setattr__(self, name, value)

    @property
    def authorized_ingress(self) -> tuple[IngressBinding, ...]:
        return self._authorized_ingress

    @property
    def authorized_ingress_by_address(self) -> MappingProxyType:
        return MappingProxyType(self._authorized_ingress_by_address)

    def _bind_version_manager_once(self, manager: object) -> bool:
        if (self._version_manager_authority is not None
                or type(manager) is not ProtocolVersionManager
                or getattr(manager, "router", None) is not self
                or getattr(manager, "address", None) != self.version_manager):
            return False
        object.__setattr__(self, "_version_manager_authority", manager)
        return True

    def _append_ingress_binding(
        self, adapter: object, authorization: ProfileIngressAuthorization
    ) -> bool:
        """Bind one release-factory deployment by exact object identity."""

        expected_type = {
            ForceKind.USER_TX: Kind0IngressAdapter,
            ForceKind.BRIDGE_CREDIT: BridgeAdapter,
        }.get(authorization.kind)
        address = getattr(adapter, "address", None)
        existing = self._authorized_ingress_by_address.get(address)
        if existing is not None:
            return (
                existing.adapter is adapter
                and existing.kind is authorization.kind
                and existing.runtime_hash == authorization.runtime_hash
                and existing.configuration_hash
                    == authorization.configuration_hash
            )
        if (expected_type is None or type(adapter) is not expected_type
                or getattr(adapter, "router", None) is not self
                or address != authorization.adapter_address
                or getattr(adapter, "runtime_hash", None)
                    != authorization.runtime_hash
                or getattr(adapter, "configuration_hash", None)
                    != authorization.configuration_hash
                or id(adapter) in self._authorized_ingress_adapter_ids):
            return False
        binding = IngressBinding(
            adapter,
            authorization.kind,
            authorization.adapter_address,
            authorization.runtime_hash,
            authorization.configuration_hash,
        )
        object.__setattr__(
            self, "_authorized_ingress", self._authorized_ingress + (binding,)
        )
        by_address = dict(self._authorized_ingress_by_address)
        by_address[authorization.adapter_address] = binding
        object.__setattr__(self, "_authorized_ingress_by_address", by_address)
        object.__setattr__(
            self,
            "_authorized_ingress_adapter_ids",
            self._authorized_ingress_adapter_ids | {id(adapter)},
        )
        return True

    def _install_profile_deployments(
        self,
        registration: SettlementRegistration,
        *,
        manager: "ProtocolVersionManager | None",
    ) -> bool:
        """Materialize exact release-owned capabilities without governance."""

        if (type(registration) is not SettlementRegistration
                or self.registrations.get(
                    registration.settlement.protocol_version
                ) is not registration
                or (manager is not None
                    and (type(manager) is not ProtocolVersionManager
                         or manager is not self._version_manager_authority))):
            return False

        # A release may not add a new Bridge-trusting endpoint to a historical
        # Bridge/domain whose already-queued messages were admitted under a
        # smaller denyset.  New authority requires a fresh Bridge and domain;
        # exact endpoint reuse keeps the immutable policy byte-for-byte.
        if not all(
            historical_v2_privileged_policy_compatible(
                prior.release_manifest, registration.release_manifest
            )
            for prior in self.registrations.values()
            if prior is not registration
        ):
            return False

        bindings_before = self._authorized_ingress
        by_address_before = self._authorized_ingress_by_address
        ids_before = self._authorized_ingress_adapter_ids
        deployments_before = dict(self._profile_deployments_by_version)
        source_registry_before = self._bridge_credit_registry_authority
        source_bridge_before = self._source_bridge_authority
        support_registry_before = self._bridge_domain_registry_authority
        source_factories_before = dict(
            self._source_bridge_factories_by_address
        )
        source_bundles_before = dict(self._source_bundles_by_descriptor_id)
        source_versions_before = dict(self._source_descriptor_id_by_version)
        used_source_addresses_before = set(
            self._used_source_component_addresses
        )
        source_factory_states = {
            address: (
                factory,
                dict(factory._deployments),
                dict(factory._bundles),
            )
            for address, factory
            in self._source_bridge_factories_by_address.items()
            if type(factory) is ImmutableV2BridgeFactory
        }
        source_bundle_states_before: dict[int, tuple[object, ...]] = {}
        for factory, _, bundles in source_factory_states.values():
            for bundle in bundles.values():
                if (len(bundle) == 5
                        and type(bundle[0]) is SourceBridgeV2
                        and type(bundle[1]) is BridgeCreditRegistryV2):
                    bridge, registry = bundle[:2]
                    source_bundle_states_before.setdefault(
                        id(bridge),
                        (
                            bridge,
                            bridge._transaction_snapshot(),
                            registry,
                            registry._authorization_snapshot(),
                        ),
                    )
        source_registry_state = (
            support_registry_before._transaction_snapshot()
            if type(support_registry_before) is BridgeDomainRegistry else None
        )
        try:
            deployments = dict(
                self._profile_deployments_by_version.get(
                    registration.settlement.protocol_version, {}
                )
            )
            kind0_authorizations = tuple(
                row for row in registration.ingress_authorizations
                if row.kind is ForceKind.USER_TX
            )
            bridge_authorizations = tuple(
                row for row in registration.ingress_authorizations
                if row.kind is ForceKind.BRIDGE_CREDIT
            )
            if len(kind0_authorizations) != 1 or len(bridge_authorizations) != 1:
                raise ValueError("release ingress roles are not exact")
            kind0_authorization = kind0_authorizations[0]
            existing_kind0 = self._authorized_ingress_by_address.get(
                kind0_authorization.adapter_address
            )
            kind0 = (
                existing_kind0.adapter
                if existing_kind0 is not None
                else Kind0IngressAdapter(
                    self, address=kind0_authorization.adapter_address
                )
            )
            if not self._append_ingress_binding(kind0, kind0_authorization):
                raise ValueError("release Kind0 deployment is not exact")
            deployments[kind0_authorization.authorization_id] = kind0

            if manager is not None:
                bridge_authorization = bridge_authorizations[0]
                # L1 cutover authenticates and stages the exact manifest from
                # SettlementRegistration.  It must not pre-write the L2
                # ReleaseAuthority/Registrar: those writes occur only in the
                # proof-authenticated activation block's tx0.
                manifest = registration.release_manifest
                source_descriptor = bridge_authorization.source_descriptor
                if type(source_descriptor) is not SourceBridgeDescriptor:
                    raise ValueError("source descriptor is not committed")
                descriptor_id = source_descriptor.descriptor_id
                if descriptor_id != bridge_authorization.source_descriptor_id:
                    raise ValueError("source descriptor commitment changed")

                l1_authority_descriptor = (
                    release_authority_descriptor_from_manifest(manifest)
                )
                support_registry = self._bridge_domain_registry_authority
                if support_registry is None:
                    support_registry = BridgeDomainRegistry(
                        self,
                        manager,
                        l1_authority_descriptor,
                        TestRegistrationMptVerifier(
                            canonical_registration_mpt_verifier_descriptor()
                        ),
                    )
                    object.__setattr__(
                        self,
                        "_bridge_domain_registry_authority",
                        support_registry,
                    )
                elif (type(support_registry) is not BridgeDomainRegistry
                        or support_registry.router is not self
                        or support_registry.manager is not manager
                        or support_registry.release_authority_descriptor
                            != l1_authority_descriptor):
                    raise ValueError(
                        "source support registry lifetime authority changed"
                    )

                source_bridge_factory = (
                    self._source_bridge_factories_by_address.get(
                        source_descriptor.deployment_factory
                    )
                )
                if source_bridge_factory is None:
                    source_bridge_factory = ImmutableV2BridgeFactory(
                        source_descriptor.deployment_factory,
                        source_descriptor.deployment_factory_runtime_hash,
                        source_descriptor
                            .deployment_factory_configuration_hash,
                    )
                    self._source_bridge_factories_by_address[
                        source_descriptor.deployment_factory
                    ] = source_bridge_factory
                elif (type(source_bridge_factory)
                        is not ImmutableV2BridgeFactory
                        or source_bridge_factory.runtime_hash
                            != source_descriptor.deployment_factory_runtime_hash
                        or source_bridge_factory.configuration_hash
                            != source_descriptor
                                .deployment_factory_configuration_hash):
                    raise ValueError("source Bridge factory identity changed")

                bundle = self._source_bundles_by_descriptor_id.get(
                    descriptor_id
                )
                if bundle is None:
                    component_addresses = {
                        source_descriptor.source_bridge,
                        source_descriptor.bridge_credit_registry,
                        source_descriptor.native_quota_manager,
                    }
                    if (len(component_addresses) != 3
                            or source_descriptor.legacy_v1_bridge
                                in component_addresses
                            or component_addresses
                                & self._used_source_component_addresses):
                        raise ValueError(
                            "source Bridge successor accounts are not fresh"
                        )
                    (
                        source_bridge,
                        credit_registry,
                        source_deployment_receipt,
                    ) = source_bridge_factory.deploy_source_bundle(
                        source_descriptor,
                        support_registry,
                        caller="permissionless-deployer",
                    )
                    _ = source_deployment_receipt
                    bundle = (
                        source_bridge,
                        credit_registry,
                        source_bridge.quota_manager,
                    )
                    self._source_bundles_by_descriptor_id[
                        descriptor_id
                    ] = bundle
                    self._used_source_component_addresses.update(
                        component_addresses
                    )
                source_bridge, credit_registry, quota_manager = bundle
                if (type(source_bridge) is not SourceBridgeV2
                        or type(credit_registry) is not BridgeCreditRegistryV2
                        or type(quota_manager) is not FrozenNativeQuotaManagerV2
                        or source_bridge.credit_registry is not credit_registry
                        or source_bridge.quota_manager is not quota_manager
                        or source_bridge.deployment_factory
                            is not source_bridge_factory
                        or source_bridge.source_descriptor.descriptor_id
                            != descriptor_id
                        or source_bridge.address
                            != source_descriptor.source_bridge
                        or credit_registry.address
                            != source_descriptor.bridge_credit_registry
                        or quota_manager.address
                            != source_descriptor.native_quota_manager):
                    raise ValueError("source Bridge bundle identity is split")
                if (not source_bridge.v2_active
                        and not source_bridge.activate(
                        bridge_authorization,
                        registration,
                        router=self,
                        caller="permissionless-activator",
                    )):
                        raise ValueError(
                            "source Bridge inactive-to-active seal failed"
                        )
                prior_descriptor_id = self._source_descriptor_id_by_version.get(
                    registration.settlement.protocol_version
                )
                if prior_descriptor_id not in {None, descriptor_id}:
                    raise ValueError("release source descriptor changed")
                self._source_descriptor_id_by_version[
                    registration.settlement.protocol_version
                ] = descriptor_id
                object.__setattr__(
                    self, "_bridge_credit_registry_authority", credit_registry
                )
                object.__setattr__(
                    self, "_source_bridge_authority", source_bridge
                )
                if (type(credit_registry) is not BridgeCreditRegistryV2
                        or type(source_bridge) is not SourceBridgeV2
                        or source_bridge.credit_registry is not credit_registry
                        or credit_registry.source_bridge is not source_bridge
                        or source_bridge.source_descriptor.descriptor_id
                            != bridge_authorization.source_descriptor_id
                        or credit_registry.configuration_hash
                            != bridge_authorization.source_registry_configuration_hash
                        or source_bridge.configuration_hash
                            != bridge_authorization.source_bridge_configuration_hash
                        or credit_registry.domain_registry.manager is not manager
                        or credit_registry.domain_registry is not support_registry
                        or support_registry.release_authority_descriptor
                            != l1_authority_descriptor):
                    raise ValueError("source Bridge deployment is split")
                registry = support_registry
                stage_clock = Clock(
                    registration.activation_block,
                    GENESIS_TIMESTAMP,
                )
                if not registry.stage(
                    source_bridge.source_domain_id,
                    source_bridge.frozen_bridge_execution_hash,
                    manifest,
                    manager=manager,
                    clock=stage_clock,
                ):
                    raise ValueError("release Bridge support was not staged")
                existing_bridge = self._authorized_ingress_by_address.get(
                    bridge_authorization.adapter_address
                )
                if (existing_bridge is not None
                        and (type(existing_bridge.adapter) is not BridgeAdapter
                             or not existing_bridge.adapter.destination_sealed
                             or existing_bridge.adapter.destination_domain_id
                                != bridge_authorization.destination_domain_id)):
                    raise ValueError(
                        "Bridge adapter address cannot cross destination domains"
                    )
                bridge = (
                    deployments.get(bridge_authorization.authorization_id)
                    if deployments.get(
                        bridge_authorization.authorization_id
                    ) is not None
                    else (existing_bridge.adapter
                          if existing_bridge is not None
                          else BridgeAdapter(
                        self,
                        credit_registry,
                        source_bridge,
                        address=bridge_authorization.adapter_address,
                    ))
                )
                if (type(bridge) is not BridgeAdapter
                        or bridge.credit_registry is not credit_registry
                        or bridge.source_bridge is not source_bridge
                        or bridge.configuration_hash
                            != bridge_authorization.configuration_hash):
                    raise ValueError("release Bridge deployment is not exact")
                deployments[bridge_authorization.authorization_id] = bridge
            self._profile_deployments_by_version[
                registration.settlement.protocol_version
            ] = MappingProxyType(deployments)
            return True
        except BaseException:
            object.__setattr__(self, "_authorized_ingress", bindings_before)
            object.__setattr__(
                self, "_authorized_ingress_by_address", by_address_before
            )
            object.__setattr__(
                self, "_authorized_ingress_adapter_ids", ids_before
            )
            self._profile_deployments_by_version = deployments_before
            object.__setattr__(
                self,
                "_bridge_credit_registry_authority",
                source_registry_before,
            )
            object.__setattr__(
                self, "_source_bridge_authority", source_bridge_before
            )
            object.__setattr__(
                self,
                "_bridge_domain_registry_authority",
                support_registry_before,
            )
            self._source_bridge_factories_by_address = source_factories_before
            self._source_bundles_by_descriptor_id = source_bundles_before
            self._source_descriptor_id_by_version = source_versions_before
            self._used_source_component_addresses = used_source_addresses_before
            for factory, deployments_state, bundles_state in (
                source_factory_states.values()
            ):
                factory._deployments = deployments_state
                factory._bundles = bundles_state
            for bridge, bridge_state, registry, registry_state in (
                source_bundle_states_before.values()
            ):
                bridge._restore_transaction_snapshot(
                    bridge_state, capability=_SOURCE_BRIDGE_ROLLBACK_CAPABILITY
                )
                registry._restore_authorization_snapshot(
                    registry_state,
                    source_bridge=bridge,
                    capability=_SOURCE_BRIDGE_ROLLBACK_CAPABILITY,
                )
            if (source_registry_state is not None
                    and type(support_registry_before)
                        is BridgeDomainRegistry):
                support_registry_before._restore_transaction_snapshot(
                    source_registry_state
                )
            return False

    def _valid_migration_activation_proof(
        self,
        proof: VerifiedMigrationExecutionOutput,
        *,
        settlement: VersionedSettlementHistory,
        target_manifest_hash: bytes,
        clock: Clock,
    ) -> bool:
        if (type(proof) is not VerifiedMigrationExecutionOutput
                or type(clock) is not Clock):
            return False
        candidate = proof.candidate
        block = (
            candidate.blocks[0]
            if type(candidate) is Candidate and candidate.count == 1 else None
        )
        derived_output = (
            CanonicalCore(
                candidate.end_l2_block_number,
                block.block_hash,
                block.slot,
                candidate.end_state_root,
                block.message_end,
                candidate.winning_data_commitment,
                candidate.next_base_fee,
                candidate.next_excess_blob_gas,
                candidate.end_terminal_root,
                candidate.end_terminal_count,
            )
            if block is not None else None
        )
        old_registration = self.registrations.get(self.active_version)
        try:
            expected_registration = settlement_registration(
                self,
                settlement,
                activation_block=clock.block_number,
                predecessor_version=self.active_version,
                release_manifest_hash=target_manifest_hash,
            )
            expected_manifest = expected_registration.release_manifest
            claimed_inputs = proof.transition_proof.public_inputs
            expected_statement = migration_transition_public_inputs_from_l1(
                router=self,
                settlement=settlement,
                target_manifest_hash=target_manifest_hash,
                candidate=candidate,
                rows=proof.rows,
                pre_inbox_last_applied_l2_block=(
                    claimed_inputs.pre_inbox_last_applied_l2_block
                ),
            )
            verifier = expected_registration.execution_profile \
                .migration_transition_verifier
            descriptor = expected_registration.execution_profile \
                .migration_transition_verifier_descriptor
            result = verifier.verify_transition(proof.transition_proof)
        except (AttributeError, RuntimeError, TypeError, ValueError):
            return False
        descriptors = tuple(self.forced_queue.descriptors[
            proof.start_cursor:proof.end_cursor
        ])
        if (type(proof) is not VerifiedMigrationExecutionOutput
                or proof.target_manifest_hash != target_manifest_hash
                or proof.target_protocol_version
                    != settlement.protocol_version
                or type(proof.transition_proof)
                    is not MigrationTransitionProof
                or expected_registration.execution_profile
                    is not settlement.execution_profile
                or not expected_registration.execution_profile
                    .structurally_valid()
                or descriptor != expected_manifest.migration_transition_verifier
                or verifier is not settlement.execution_profile
                    .migration_transition_verifier
                or not verifier.valid_result(result)
                or result.verifier is not verifier
                or result.descriptor != descriptor
                or result.public_inputs != expected_statement
                or result.returndata != bytes.fromhex(expected_statement.digest)
                or proof.transition_statement_digest
                    != expected_statement.digest
                or proof.router_generation
                    != expected_statement.router_generation
                or proof.source_canonical_sequence
                    != expected_statement.canonical_sequence
                or claimed_inputs.candidate_digest
                    != candidate_inbox_execution_digest(candidate)
                or claimed_inputs.base_core != proof.base_core
                or claimed_inputs.output_core != proof.output_core
                or claimed_inputs.target_manifest_hash != target_manifest_hash
                or claimed_inputs.release_system_calldata_hash
                    != release_system_calldata_hash(
                        expected_manifest, claimed_inputs.queue_count
                    )
                or claimed_inputs.inbox_system_calldata_hash
                    != inbox_system_calldata_hash(proof.rows)
                or claimed_inputs.queue_root != self.forced_queue.root
                or claimed_inputs.queue_count != self.forced_queue.count
                or claimed_inputs.start_cursor != proof.start_cursor
                or claimed_inputs.end_cursor != proof.end_cursor
                or claimed_inputs.pre_inbox_last_applied_l2_block
                    != proof.pre_inbox_last_applied_l2_block
                or claimed_inputs.post_inbox_last_applied_l2_block
                    != proof.post_inbox_last_applied_l2_block
                or proof.beneficiary != candidate.beneficiary
                or derived_output != proof.output_core
                or type(old_registration) is not SettlementRegistration
                or proof.base_core != old_registration.settlement.core
                or proof.start_cursor != proof.base_core.message_cursor
                or block.inbox_system_calldata_hash
                    != inbox_system_calldata_hash(proof.rows)
                or block.inbox_descriptor_commitment
                    != inbox_descriptor_commitment(descriptors)
                or expected_manifest.commitment != target_manifest_hash
                or expected_manifest.protocol_version
                    != settlement.protocol_version
                or proof.post_inbox_last_applied_l2_block
                    != proof.output_core.l2_block_number
                or proof.end_cursor != proof.output_core.message_cursor
                or not InboxValidityExecutionAuthority._rows_match_descriptors(
                    proof.rows, descriptors,
                )):
            return False
        # One direct, bounded verifier call precedes every write. The Router
        # consumes only this value statement; target-L2 objects and prover
        # capabilities are deliberately unreachable from this path.
        return True

    def activate_profile_bridge_adapter(
        self, adapter: object, *, protocol_version: int,
        executor: str, clock: Clock
    ) -> bool:
        """Permissionlessly bind the exact release deployment after support."""

        registration = self.registrations.get(protocol_version)
        authorization = (
            None if registration is None
            else registration.ingress_authorizations_by_address.get(
                getattr(adapter, "address", None)
            )
        )
        deployment = (
            None if type(authorization) is not ProfileIngressAuthorization
            else self._profile_deployments_by_version.get(
                protocol_version, {}
            ).get(authorization.authorization_id)
        )
        source = getattr(adapter, "source_bridge", None)
        credit_registry = getattr(adapter, "credit_registry", None)
        descriptor_id = self._source_descriptor_id_by_version.get(
            protocol_version
        )
        bundle = self._source_bundles_by_descriptor_id.get(descriptor_id)
        destination_domain_id = getattr(
            authorization, "destination_domain_id", ""
        )
        support = (
            None if type(source) is not SourceBridgeV2
            or type(credit_registry) is not BridgeCreditRegistryV2
            or source.credit_registry is not credit_registry
            else source.domain_registry.final_entry(
                source.source_domain_id,
                source.frozen_bridge_execution_hash,
                destination_domain_id,
                clock,
            )
        )
        if (not executor or type(clock) is not Clock
                or type(protocol_version) is not int
                or type(adapter) is not BridgeAdapter
                or type(authorization) is not ProfileIngressAuthorization
                or authorization.kind is not ForceKind.BRIDGE_CREDIT
                or adapter is not deployment
                or adapter.router is not self
                or bundle is None or len(bundle) != 3
                or source is not bundle[0]
                or credit_registry is not bundle[1]
                or source.quota_manager is not bundle[2]
                or authorization.source_descriptor_id != descriptor_id
                or support is None
                or support.manifest is not registration.release_manifest
                or support.source_chain_id != authorization.source_chain_id
                or support.source_registration_epoch
                    != authorization.source_registration_epoch):
            return False
        existing = self._authorized_ingress_by_address.get(adapter.address)
        if existing is not None:
            return (
                existing.adapter is adapter
                and existing.kind is ForceKind.BRIDGE_CREDIT
                and existing.runtime_hash == authorization.runtime_hash
                and existing.configuration_hash
                    == authorization.configuration_hash
                and adapter.destination_sealed
                and adapter.destination_domain_id
                    == authorization.destination_domain_id
            )
        bindings_before = self._authorized_ingress
        by_address_before = self._authorized_ingress_by_address
        ids_before = self._authorized_ingress_adapter_ids
        domain_before = adapter.destination_domain_id
        try:
            if (not adapter._seal_destination_from_profile(
                    authorization=authorization,
                    registration=registration,
                    router=self,
                    protocol_version=protocol_version)
                    or not self._append_ingress_binding(
                        adapter, authorization
                    )):
                raise ValueError("profile Bridge deployment rejected")
            return True
        except BaseException:
            object.__setattr__(self, "_authorized_ingress", bindings_before)
            object.__setattr__(
                self, "_authorized_ingress_by_address", by_address_before
            )
            object.__setattr__(
                self, "_authorized_ingress_adapter_ids", ids_before
            )
            object.__setattr__(
                adapter, "_destination_domain_id", domain_before
            )
            return False

    def _ingress_binding(self, adapter: object) -> IngressBinding | None:
        address = getattr(adapter, "address", None)
        self.ingress_lookup_probes = 1 if type(address) is str else 0
        binding = self._authorized_ingress_by_address.get(address)
        if (binding is not None and binding.adapter is adapter
                and getattr(adapter, "router", None) is self
                and address == binding.address
                and getattr(adapter, "runtime_hash", None)
                    == binding.runtime_hash
                and getattr(adapter, "configuration_hash", None)
                    == binding.configuration_hash
                and getattr(adapter, "queue_address", None)
                    == self.forced_queue_address):
            return binding
        return None

    @property
    def forced_queue_address(self) -> str:
        return self.forced_queue.address

    def bootstrap(self, settlement: VersionedSettlementHistory, *, sequence: int,
                  clock: Clock, caller: str) -> bool:
        if (type(clock) is not Clock or caller != self.version_manager
                or self.registrations or settlement.protocol_version <= 0
                or settlement.migration_gate is not self.migration_gate
                or settlement.header_oracle is not self.header_oracle
                or (
                    settlement.live_protocol is not None
                    and settlement.live_protocol.migration_gate
                        is not self.migration_gate
                )
                or (
                    settlement.live_protocol is not None
                    and settlement.live_protocol.header_oracle
                        is not self.header_oracle
                )
                or settlement.forced_queue is not self.forced_queue
                or self.forced_queue.router_address != self.address
                or self.forced_queue.runtime_hash
                    != self.forced_queue_runtime_hash
                or self.forced_queue.config_hash
                    != self.forced_queue_config_hash
                or not self.forced_queue.nonproxy
                or not self.forced_queue.selfdestruct_disabled
                or self.forced_queue.delegate_target_reachable
                or settlement.builder_registry_id != self.builder_registry_id
                or settlement.schedule_oracle_id != self.schedule_oracle_id
                or self.forced_queue.active_settlement_address
                    not in {"", settlement.address}
                or settlement.inbox_apply_descriptor
                    != self.inbox_apply_descriptor
                or (
                    settlement.live_protocol is not None
                    and settlement.live_protocol.inbox_apply_descriptor
                        != settlement.inbox_apply_descriptor
                )
                or settlement.core.message_cursor != self.forced_queue.cursor
                or not settlement.nonproxy or not settlement.selfdestruct_disabled):
            return False
        authority_keys = {
            "migration_gate", "forced_queue", "inbox_apply_descriptor", "live_protocol",
            "_router_authority",
        }
        settlement_snapshot = copy.deepcopy({
            key: value for key, value in settlement.__dict__.items()
            if key not in authority_keys
        })
        gate = settlement.migration_gate
        live_protocol = settlement.live_protocol
        local_inbox_descriptor = settlement.inbox_apply_descriptor
        prior_router_authority = settlement._router_authority
        gate_snapshot = copy.deepcopy(gate.__dict__)
        queue_snapshot = self.forced_queue._transaction_snapshot()
        registrations_snapshot = dict(self.registrations)
        active_snapshot = self.active_version
        used_targets_snapshot = set(self.used_target_addresses)
        ingress_snapshot = (
            self._authorized_ingress,
            self._authorized_ingress_by_address,
            self._authorized_ingress_adapter_ids,
            dict(self._profile_deployments_by_version),
        )
        try:
            activation_block = clock.block_number
            object.__setattr__(self, "_queue_transition_frame", (
                "BOOTSTRAP", id(settlement), settlement.address
            ))
            try:
                queue_bootstrapped = (
                    gate._bootstrap_from_router(
                    settlement.protocol_version, self.version_manager
                    )
                    and settlement._install_imported_from_router(
                        router=self, sequence=sequence, clock=clock
                    )
                    and self.forced_queue
                    ._bootstrap_active_settlement_from_router(
                        expected_old=(
                            self.forced_queue.active_settlement_address
                        ),
                        settlement=settlement,
                        router=self,
                    )
                )
            finally:
                object.__setattr__(self, "_queue_transition_frame", None)
            if not queue_bootstrapped:
                raise ValueError("router bootstrap transition rejected")
            settlement.mode = "ACTIVE"
            self.registrations[settlement.protocol_version] = (
                settlement_registration(
                    self,
                    settlement,
                    activation_block=activation_block,
                    predecessor_version=0,
                    release_manifest_hash=self.bootstrap_release_manifest_hash,
                )
            )
            if not self._install_profile_deployments(
                self.registrations[settlement.protocol_version],
                manager=None,
            ):
                raise ValueError("bootstrap ingress deployment failed")
            self.active_version = settlement.protocol_version
            self.used_target_addresses.add(settlement.address)
            return True
        except BaseException:
            settlement.__dict__.clear()
            settlement.__dict__.update(settlement_snapshot)
            gate.__dict__.clear()
            gate.__dict__.update(gate_snapshot)
            self.forced_queue._restore_transaction_snapshot(queue_snapshot)
            object.__setattr__(settlement, "migration_gate", gate)
            object.__setattr__(settlement, "forced_queue", self.forced_queue)
            object.__setattr__(
                settlement, "inbox_apply_descriptor", local_inbox_descriptor
            )
            settlement.live_protocol = live_protocol
            object.__setattr__(
                settlement, "_router_authority", prior_router_authority
            )
            if live_protocol is not None:
                object.__setattr__(live_protocol, "migration_gate", gate)
                object.__setattr__(
                    live_protocol, "forced_queue", self.forced_queue
                )
                live_protocol.versioned_history = settlement
            self.registrations = registrations_snapshot
            self.active_version = active_snapshot
            self.used_target_addresses = used_targets_snapshot
            object.__setattr__(
                self, "_authorized_ingress", ingress_snapshot[0]
            )
            object.__setattr__(
                self, "_authorized_ingress_by_address", ingress_snapshot[1]
            )
            object.__setattr__(
                self, "_authorized_ingress_adapter_ids", ingress_snapshot[2]
            )
            self._profile_deployments_by_version = ingress_snapshot[3]
            return False

    def _activate_version_with_proof(
            self, *, settlement: VersionedSettlementHistory, clock: Clock,
            target_manifest_hash: bytes,
            activation_proof: VerifiedMigrationExecutionOutput) -> bool:
        old_registration = self.registrations.get(self.active_version)
        if old_registration is None:
            return False
        old = old_registration.settlement
        if (type(clock) is not Clock
                or not self._valid_migration_activation_proof(
                    activation_proof,
                    settlement=settlement,
                    target_manifest_hash=target_manifest_hash,
                    clock=clock,
                )
                or settlement.protocol_version <= self.active_version
                or settlement.protocol_version in self.registrations
                or settlement.address in self.used_target_addresses
                or not settlement.execution_profile_hash
                or not settlement.runtime_hash
                or not settlement.nonproxy or not settlement.selfdestruct_disabled
                or settlement.mode != "PREACTIVE" or settlement.history
                or settlement.current_sequence != -1
                or settlement.last_canonical_l1_block != 0
                or settlement._router_authority is not None
                or settlement.header_oracle is not self.header_oracle
                or old.header_oracle is not self.header_oracle
                or old.mode != "MIGRATION_READY"
                or old.migration_gate.mode != "READY"
                or old.migration_gate.active_protocol_version
                    != self.active_version
                or old.migration_gate is not self.migration_gate
                or settlement.migration_gate is not self.migration_gate
                or old.migration_gate.target_protocol_version
                    != settlement.protocol_version
                or old.migration_gate.target_manifest_hash
                    != target_manifest_hash
                or activation_proof.target_protocol_version
                    != settlement.protocol_version
                or activation_proof.target_manifest_hash
                    != target_manifest_hash
                or activation_proof.base_core != old.core
                or settlement.core != old.core
                or settlement.canonicalized_at_block
                    != old.canonicalized_at_block
                or settlement.forced_queue is not self.forced_queue
                or old.forced_queue is not self.forced_queue
                or self.forced_queue.active_settlement_address != old.address
                or self.forced_queue.runtime_hash
                    != self.forced_queue_runtime_hash
                or self.forced_queue.config_hash
                    != self.forced_queue_config_hash
                or not self.forced_queue.nonproxy
                or not self.forced_queue.selfdestruct_disabled
                or self.forced_queue.delegate_target_reachable
                or settlement.builder_registry_id != self.builder_registry_id
                or old.builder_registry_id != self.builder_registry_id
                or settlement.schedule_oracle_id != self.schedule_oracle_id
                or old.schedule_oracle_id != self.schedule_oracle_id
                or old.core.message_cursor != self.forced_queue.cursor
                or activation_proof.start_cursor != old.core.message_cursor
                or not activation_proof.start_cursor
                    <= activation_proof.end_cursor <= self.forced_queue.count
                or not activation_proof.beneficiary
                or activation_proof.output_core.message_cursor
                    != activation_proof.end_cursor
                or activation_proof.output_core.l2_block_number
                    <= old.core.l2_block_number
                or activation_proof.output_core.tip_slot <= old.core.tip_slot
                or activation_proof.output_core.terminal_count
                    < old.core.terminal_count
                or (activation_proof.output_core.terminal_count
                    == old.core.terminal_count
                    and activation_proof.output_core.terminal_root
                        != old.core.terminal_root)
                or self.forced_queue.escrow_balance
                    < self.forced_queue.accounted_liabilities
                or old.current_sequence + 1 >= UINT64_MAX
                or clock.block_number <= old.last_canonical_l1_block):
            return False
        l1_block = clock.block_number
        old_version = self.active_version
        # L1 adopts only the verifier's commitments.  The destination tx0
        # ReleaseAuthority/Registrar calls and tx1 InboxApply writes occur in
        # the proved L2 transition and are never replayed as L1 object calls.
        object.__setattr__(self, "_queue_transition_frame", (
            "MIGRATION", id(activation_proof), activation_proof.digest
        ))
        try:
            queue_activated = (
                self.forced_queue._activate_and_advance_from_router(
                    expected_old=old.address,
                    settlement=settlement,
                    proof=activation_proof,
                    router=self,
                )
            )
        finally:
            object.__setattr__(self, "_queue_transition_frame", None)
        if not queue_activated:
            raise AssertionError(
                "validated queue switch/advance transaction failed"
            )
        settlement.core = copy.deepcopy(activation_proof.output_core)
        settlement.canonicalized_at_block = l1_block
        if not settlement._install_imported_from_router(
                router=self, sequence=old.current_sequence + 1, clock=clock):
            raise AssertionError("validated target history write failed")
        old.mode = "FROZEN"
        settlement.mode = "ACTIVE"
        self.registrations[settlement.protocol_version] = settlement_registration(
            self,
            settlement,
            activation_block=l1_block,
            predecessor_version=old_version,
            release_manifest_hash=target_manifest_hash,
        )
        manager = self._version_manager_authority
        if (type(manager) is not ProtocolVersionManager
                or not self._install_profile_deployments(
                    self.registrations[settlement.protocol_version],
                    manager=manager,
                )):
            raise ValueError("target release deployments are not exact")
        self.active_version = settlement.protocol_version
        self.used_target_addresses.add(settlement.address)
        active_gate = old.migration_gate
        activated = active_gate._activate_from_router(
            active_gate.generation, old_version,
            settlement.protocol_version)
        assert activated
        return True

    def _abort_migration_for_test(self, *, generation: int,
                        target_protocol_version: int,
                        target_manifest_hash: str,
                        cancel_manifest_active: bool,
                        clock: Clock) -> bool:
        """Permissionless execution after an exact delayed cancel manifest."""
        registration = self.registrations.get(self.active_version)
        if registration is None:
            return False
        old = registration.settlement
        if (old.mode not in {"MIGRATION_ARMED", "MIGRATION_READY"}
                or self.forced_queue.active_settlement_address != old.address
                or old.live_protocol is None
                or not old.migration_gate._abort_from_manager(
                    generation, self.active_version, target_protocol_version,
                    target_manifest_hash,
                    cancel_manifest_active=cancel_manifest_active,
                    caller=self.version_manager)):
            return False
        old.mode = "ACTIVE"
        old.live_protocol.sync(clock)
        return True

    def canonical_at(self, protocol_version: int,
                     sequence: int) -> CanonicalTerminalCommitment | None:
        registration = self.registrations.get(protocol_version)
        if registration is None:
            return None
        settlement = registration.settlement
        if (settlement.runtime_hash != registration.runtime_hash
                or settlement.execution_profile_hash
                    != registration.execution_profile_hash
                or settlement.execution_profile
                    is not registration.execution_profile
                or not settlement.nonproxy or not settlement.selfdestruct_disabled
                or settlement.mode not in {
                    "ACTIVE", "MIGRATION_ARMED", "MIGRATION_READY", "FROZEN"}):
            return None
        entry = settlement.canonical_at(sequence)
        if (entry is None or entry.protocol_version != protocol_version
                or entry.execution_profile_hash
                    != registration.execution_profile_hash):
            return None
        return entry

    def _active_ingress_graph(
        self,
    ) -> tuple[VersionedSettlementHistory, Protocol] | None:
        """Resolve the one exact active Settlement graph for forced ingress."""

        registration = self.registrations.get(self.active_version)
        if (registration is None
                or not registration.release_manifest_hash
                or registration.runtime_hash
                    != registration.settlement.runtime_hash
                or registration.execution_profile_hash
                    != registration.settlement.execution_profile_hash
                or registration.execution_profile
                    is not registration.settlement.execution_profile
                or registration.settlement.protocol_version
                    != self.active_version
                or registration.settlement.live_protocol is None
                or registration.settlement.mode
                    not in {"ACTIVE", "MIGRATION_ARMED", "MIGRATION_READY"}):
            return None
        settlement = registration.settlement
        live_protocol = settlement.live_protocol
        if (settlement._router_authority is not self
                or settlement.header_oracle is not self.header_oracle
                or settlement.migration_gate is not self.migration_gate
                or settlement.forced_queue is not self.forced_queue
                or settlement.inbox_apply_descriptor
                    != self.inbox_apply_descriptor
                or live_protocol.versioned_history is not settlement
                or live_protocol.settlement_address != settlement.address
                or live_protocol.header_oracle is not self.header_oracle
                or live_protocol.migration_gate is not self.migration_gate
                or live_protocol.forced_queue is not self.forced_queue
                or live_protocol.inbox_apply_descriptor
                    != settlement.inbox_apply_descriptor
                or self.forced_queue.router_address != self.address
                or self.forced_queue._router_authority is not self
                or self.forced_queue.active_settlement_address
                    != settlement.address
                or self.forced_queue.runtime_hash
                    != self.forced_queue_runtime_hash
                or self.forced_queue.config_hash
                    != self.forced_queue_config_hash
                or not self.forced_queue.nonproxy
                or not self.forced_queue.selfdestruct_disabled
                or self.forced_queue.delegate_target_reachable
                or self.migration_gate.active_protocol_version
                    != self.active_version):
            return None
        return settlement, live_protocol

    def required_ingress_deposit(
        self, descriptor: Message, caller_adapter: object
    ) -> int:
        binding = self._ingress_binding(caller_adapter)
        if binding is None or descriptor.kind is not binding.kind:
            raise ValueError("ingress fee profile is not authorized")
        registration = self.registrations.get(self.active_version)
        if registration is None:
            raise ValueError("ingress fee profile has no active release")
        if registration.settlement_chain_context_id \
                != self.settlement_chain_context_id:
            raise ValueError("ingress fee profile changed chain context")
        return ingress_deposit_for_schedule(
            descriptor.accounted_gas,
            descriptor.byte_length,
            registration.ingress_fee_schedule,
        )

    @staticmethod
    def _valid_ingress_static(
        descriptor: Message, *, clock: Clock, deposit: int
    ) -> bool:
        if (type(descriptor) not in {Message, BridgeQueueDescriptorV11}
                or type(clock) is not Clock
                or type(deposit) is not int or isinstance(deposit, bool)
                or deposit <= 0 or not descriptor.payload_hash):
            return False
        if descriptor.kind is ForceKind.BRIDGE_CREDIT:
            return (
                type(descriptor) is BridgeQueueDescriptorV11
                and descriptor.structurally_valid()
                and descriptor.valid_until == UINT64_MAX
                and descriptor.accounted_gas == MAX_FORCE_MESSAGE_GAS
                and 0 <= descriptor.byte_length <= MAX_FORCE_MESSAGE_BYTES
            )
        if (type(descriptor) is not Message
                or descriptor.kind is not ForceKind.USER_TX):
            return False
        return (
            descriptor.outer_authorized
            and descriptor.intrinsic_gas > 0
            and descriptor.chain_id_ok
            and descriptor.signature_ok
            and bool(descriptor.sender)
            and descriptor.valid_until > clock.timestamp
            and descriptor.valid_until
                <= clock.timestamp + MAX_FORCE_VALIDITY_SECONDS
            and 0 < descriptor.byte_length <= MAX_FORCE_MESSAGE_BYTES
            and descriptor.raw_tx_length == descriptor.byte_length
            and 0 < descriptor.l2_chain_id <= UINT64_MAX
            and 0 <= descriptor.gas_limit <= UINT64_MAX
            and 0 < descriptor.max_fee <= SEAT_UINT256_MAX
            and descriptor.refund_address == descriptor.sender
            and descriptor.accounted_gas == max(
                descriptor.gas_limit,
                descriptor.intrinsic_gas,
                MIN_FORCE_ACCOUNTED_GAS,
            )
            and descriptor.accounted_gas <= MAX_FORCE_MESSAGE_GAS
        )

    def sync_ingress(
        self, *, clock: Clock, caller_adapter: object
    ) -> tuple[str, tuple[int, int] | None]:
        """Persist one nonpayable sync decision or issue an exact live stamp."""

        if type(clock) is not Clock or self._ingress_binding(caller_adapter) is None:
            return "REJECTED", None
        if self.ingress_entered:
            raise RuntimeError("active router ingress is non-reentrant")
        self.ingress_entered = True
        try:
            graph = self._active_ingress_graph()
            if graph is None:
                return "REJECTED", None
            settlement, live_protocol = graph
            if live_protocol.mode is Mode.PREACTIVE:
                return "REJECTED_PREACTIVE", None
            changed = live_protocol.sync(clock)
            graph = self._active_ingress_graph()
            if (graph is None or graph[0] is not settlement
                    or graph[1] is not live_protocol):
                return "SYNCED" if changed else "REJECTED", None
            if (changed or settlement.mode != "ACTIVE"
                    or self.migration_gate.mode != "ACTIVE"):
                return "SYNCED", None
            return "ACTIVE", (
                self.active_version,
                self.migration_gate.generation,
            )
        finally:
            self.ingress_entered = False

    def append_from_adapter(
        self,
        descriptor: Message,
        *,
        clock: Clock,
        stamp: tuple[int, int],
        deposit: int,
        caller_adapter: object,
    ) -> str:
        """Append without a second sync after rechecking the exact live stamp."""

        binding = self._ingress_binding(caller_adapter)
        if type(clock) is not Clock or binding is None:
            raise ValueError("forced ingress caller or Clock is invalid")
        if self.ingress_entered:
            raise RuntimeError("active router ingress is non-reentrant")
        graph = self._active_ingress_graph()
        expected_stamp = (
            self.active_version,
            self.migration_gate.generation,
        )
        stamp_exact = (
            type(stamp) is tuple
            and len(stamp) == 2
            and all(type(word) is int for word in stamp)
        )
        if (graph is None or not stamp_exact or stamp != expected_stamp
                or self.migration_gate.mode != "ACTIVE"):
            raise ValueError("forced ingress stamp is stale")
        settlement, live_protocol = graph
        registration = self.registrations.get(self.active_version)
        if settlement.mode != "ACTIVE" or live_protocol.mode is Mode.PREACTIVE:
            raise ValueError("forced ingress target is not active")
        if (self.forced_queue.count >= live_protocol.queue_capacity
                or registration is None
                or binding.kind is not descriptor.kind
                or (descriptor.kind is ForceKind.USER_TX
                    and descriptor.l2_chain_id
                        != registration.release_manifest.destination_chain_id)
                or (descriptor.kind is ForceKind.BRIDGE_CREDIT
                    and descriptor.bridge_dest_chain_id
                        != registration.release_manifest.destination_chain_id)
                or descriptor.prepaid != deposit
                or deposit != self.required_ingress_deposit(
                    descriptor, caller_adapter
                )
                or not self._valid_ingress_static(
                    descriptor, clock=clock, deposit=deposit
                )):
            raise ValueError("forced ingress descriptor is invalid")
        enqueued_at = checked_u64_add(
            clock.timestamp, 0, "forced ingress enqueuedAt"
        )
        base_due_at = checked_u64_add(
            enqueued_at, FORCE_DELAY, "forced ingress base dueAt"
        )
        last_due_at = checked_u64_add(
            self.forced_queue.last_due_at,
            0,
            "forced ingress previous dueAt",
        )
        deferred = 0
        if (live_protocol.mode is Mode.RECOVERY
                and live_protocol.recovery is not None):
            deferred = checked_u64_add(
                live_protocol.recovery.expires_at,
                1,
                "forced ingress recovery dueAt",
            )
        due_at = max(
            base_due_at,
            last_due_at,
            deferred,
        )
        expected_index = self.forced_queue.count
        queue_before = self.forced_queue._transaction_snapshot()
        self.ingress_entered = True
        try:
            index = self.forced_queue._append_from_router(
                replace(descriptor, enqueued_at=enqueued_at),
                deposit=deposit,
                due_at=due_at,
                router=self,
            )
            if index != expected_index:
                raise ValueError("forced queue rejected validated append")
            return f"QUEUED:{index}"
        except BaseException:
            self.forced_queue._restore_transaction_snapshot(queue_before)
            raise
        finally:
            self.ingress_entered = False


@dataclass
class ProtocolVersionManager:
    """Exact global migration coordinator bound to one immutable router."""

    address: str
    router: ActiveSettlementRouter
    release_manager: object | None = field(default=None, compare=False)
    market_chain_id: int = 0
    market_address: str = ""
    governance: str = "seat-governance"
    manifest_delay_seconds: int = SEAT_MIGRATION_MANIFEST_DELAY
    cancel_delay_seconds: int = SEAT_MIGRATION_CANCEL_DELAY
    arm_manifests: dict[
        tuple[int, int, int, bytes], ScheduledSeatMigration
    ] = field(default_factory=dict)
    cancel_manifests: dict[
        tuple[int, int, int, bytes], ScheduledSeatMigration
    ] = field(default_factory=dict)
    arm_responses: dict[int, bytes] = field(default_factory=dict)
    abort_responses: dict[int, bytes] = field(default_factory=dict)
    fault_point: str | None = None

    def __post_init__(self) -> None:
        bound = self.release_manager is not None
        if (
            type(self.router) is not ActiveSettlementRouter
            or self.router.version_manager != self.address
            or self.router.migration_gate.coordinator != self.address
            or bound != (self.market_chain_id > 0 and bool(self.market_address))
            or not self.governance
            or self.manifest_delay_seconds != SEAT_MIGRATION_MANIFEST_DELAY
            or self.cancel_delay_seconds != SEAT_MIGRATION_CANCEL_DELAY
            or (
                bound
                and getattr(self.release_manager, "activation_authority", None)
                is not self.router
            )
        ):
            raise ValueError("manager Market binding must be all-or-none")
        if (self.router._version_manager_authority is not None
                and self.router._version_manager_authority is not self):
            raise ValueError("active router is bound to another version manager")
        if (self.router._version_manager_authority is None
                and not self.router._bind_version_manager_once(self)):
            raise ValueError("active router rejected its version manager")
        registration = self.router.registrations.get(self.router.active_version)
        if (registration is not None
                and not self.router._install_profile_deployments(
                    registration, manager=self
                )):
            raise ValueError("manager could not install release deployments")

    def __setattr__(self, name: str, value: object) -> None:
        if name in {
            "address", "router", "release_manager",
            "market_chain_id", "market_address", "governance",
            "manifest_delay_seconds", "cancel_delay_seconds",
        } and name in self.__dict__:
            raise AttributeError(f"{name} is immutable after deployment")
        object.__setattr__(self, name, value)

    def activate_seat_migration(
        self,
        *,
        manifest_key: tuple[int, int, int, bytes],
        activation_proof: VerifiedMigrationExecutionOutput,
        executor: str,
        clock: Clock,
    ) -> MigrationActivationReceipt:
        """Consume the exact arm and activate a distinct target-local ledger."""

        old_history, old_protocol, gate = self._active_target()
        if type(clock) is not Clock:
            raise ValueError("activation requires the exact environment clock")
        l1_block = clock.block_number
        release_manager = self.release_manager
        market_chain_id = self.market_chain_id
        market_address = self.market_address
        manifest = self.arm_manifests.get(manifest_key)
        old_auth_id = manifest.old_authorization_id if manifest is not None else b""
        new_auth_id = manifest.new_authorization_id if manifest is not None else b""
        authorizations = getattr(release_manager, "authorizations", {})
        runtimes = getattr(release_manager, "target_runtimes", {})
        old_auth = authorizations.get(old_auth_id)
        new_auth = authorizations.get(new_auth_id)
        old_runtime = runtimes.get(old_auth_id)
        new_runtime = runtimes.get(new_auth_id)
        settlement = None if new_runtime is None else new_runtime.authority
        target_bindings = getattr(release_manager, "target_bindings", {})
        if (
            manifest is None
            or type(settlement) is not VersionedSettlementHistory
            or release_manager is None
            or not executor
            or manifest.generation not in self.arm_responses
            or gate.mode != "READY"
            or old_history.mode != "MIGRATION_READY"
            or manifest.generation != gate.generation
            or manifest.active_protocol_version != self.router.active_version
            or manifest.target_protocol_version != settlement.protocol_version
            or manifest.target_manifest_hash != activation_proof.target_manifest_hash
            or len(old_auth_id) != 32
            or len(new_auth_id) != 32
            or getattr(release_manager, "activation_authority", None)
            is not self.router
            or old_auth is None
            or new_auth is None
            or release_manager.exact_authorization_id(
                market_chain_id, market_address, old_auth
            ) != old_auth_id
            or release_manager.exact_authorization_id(
                market_chain_id, market_address, new_auth
            ) != new_auth_id
            or old_runtime is None
            or new_runtime is None
            or old_runtime.authority is not old_history
            or new_runtime.authority is not settlement
            or target_bindings.get(old_auth_id)
            != (market_chain_id, market_address)
            or target_bindings.get(new_auth_id)
            != (market_chain_id, market_address)
            or old_auth.target != old_history.address
            or new_auth.target != settlement.address
            or old_auth.settlement_chain_id
            != old_history.market_settlement_chain_id
            or new_auth.settlement_chain_id
            != settlement.market_settlement_chain_id
            or old_history.market_settlement_chain_id
                != self.router.settlement_chain_context_id
            or settlement.market_settlement_chain_id
                != self.router.settlement_chain_context_id
            or old_auth.protocol_version != old_history.protocol_version
            or new_auth.protocol_version != settlement.protocol_version
            or old_auth.runtime_hash != old_history.market_runtime_hash
            or new_auth.runtime_hash != settlement.market_runtime_hash
            or old_auth.configuration_hash
            != old_history.market_configuration_hash
            or new_auth.configuration_hash
            != settlement.market_configuration_hash
            or old_auth.expected_magic != old_history.market_magic
            or new_auth.expected_magic != settlement.market_magic
            or old_protocol.seat_market_address != market_address
            or old_protocol.seat_authorization_id != old_auth_id
        ):
            raise ValueError("seat migration activation authority is invalid")
        receipt_key = (manifest.generation, manifest.target_manifest_hash)
        if (
            receipt_key in self.router.activation_receipts
            or old_auth_id
            in self.router.successor_receipt_key_by_old_authorization_id
            or release_manager.activation_receipt(receipt_key) is not None
        ):
            raise ValueError("seat migration activation receipt was consumed")

        old_protocol._assert_canonical_history_binding()
        old_snapshot = old_protocol._canonical_transaction_snapshot(
            activation_proof
        )
        target_authority_refs = (
            settlement.forced_queue,
            settlement.inbox_apply_descriptor,
            settlement.migration_gate,
            settlement.live_protocol,
            settlement._router_authority,
        )
        target_snapshot = copy.deepcopy({
            key: value for key, value in settlement.__dict__.items()
            if key not in {
                "forced_queue", "inbox_apply_descriptor", "migration_gate", "live_protocol",
                "_router_authority",
            }
        })
        router_snapshot = (
            self.router.active_version,
            dict(self.router.registrations),
            dict(self.router.activation_receipts),
            dict(self.router.activation_receipt_keys_by_generation),
            dict(self.router.successor_receipt_key_by_old_authorization_id),
            set(self.router.used_target_addresses),
            self.router._authorized_ingress,
            self.router._authorized_ingress_by_address,
            self.router._authorized_ingress_adapter_ids,
            dict(self.router._profile_deployments_by_version),
            self.router._bridge_credit_registry_authority,
            self.router._source_bridge_authority,
            self.router._bridge_domain_registry_authority,
            dict(self.router._source_bridge_factories_by_address),
            dict(self.router._source_bundles_by_descriptor_id),
            dict(self.router._source_descriptor_id_by_version),
            set(self.router._used_source_component_addresses),
        )
        source_factory_states = {
            address: (
                factory,
                dict(factory._deployments),
                dict(factory._bundles),
            )
            for address, factory
            in self.router._source_bridge_factories_by_address.items()
            if type(factory) is ImmutableV2BridgeFactory
        }
        source_bundle_states: dict[int, tuple[object, ...]] = {}
        for factory, _, bundles in source_factory_states.values():
            for bundle in bundles.values():
                if (len(bundle) == 5
                        and type(bundle[0]) is SourceBridgeV2
                        and type(bundle[1]) is BridgeCreditRegistryV2):
                    bridge, registry = bundle[:2]
                    source_bundle_states.setdefault(
                        id(bridge),
                        (
                            bridge,
                            bridge._transaction_snapshot(),
                            registry,
                            registry._authorization_snapshot(),
                        ),
                    )
        source_registry_state = (
            self.router._bridge_domain_registry_authority
                ._transaction_snapshot()
            if type(self.router._bridge_domain_registry_authority)
                is BridgeDomainRegistry else None
        )
        try:
            activated = self.router._activate_version_with_proof(
                settlement=settlement,
                clock=clock,
                target_manifest_hash=manifest.target_manifest_hash,
                activation_proof=activation_proof,
            )
            if not activated:
                raise ValueError("seat migration activation proof was rejected")
            if self.fault_point == "after_target_import":
                raise RuntimeError("injected activation fault: after_target_import")
            arm = old_protocol.seat_migration_arm
            if arm is None or arm.router_word.generation != manifest.generation:
                raise AssertionError("activation lost exact local arm")
            receipt = MigrationActivationReceipt(
                manifest.generation,
                manifest.active_protocol_version,
                manifest.target_protocol_version,
                old_history.address,
                settlement.address,
                manifest.target_manifest_hash,
                arm.seat_generation,
                old_auth_id,
                new_auth_id,
                l1_block,
                arm.migration_stage_id,
                arm.migration_lineup_commitment,
            )
            self.router.activation_receipts[receipt.key] = receipt
            self.router.activation_receipt_keys_by_generation[
                receipt.router_generation
            ] = receipt.key
            self.router.successor_receipt_key_by_old_authorization_id[
                receipt.old_authorization_id
            ] = receipt.key
            if self.fault_point == "after_activation_receipt_write":
                raise RuntimeError(
                    "injected activation fault: after_activation_receipt_write"
                )
            return receipt
        except BaseException:
            old_protocol._restore_canonical_transaction(old_snapshot)
            settlement.__dict__.clear()
            settlement.__dict__.update(target_snapshot)
            (
                settlement.forced_queue,
                settlement.inbox_apply_descriptor,
                settlement.migration_gate,
                settlement.live_protocol,
                settlement._router_authority,
            ) = target_authority_refs
            (
                self.router.active_version,
                self.router.registrations,
                self.router.activation_receipts,
                self.router.activation_receipt_keys_by_generation,
                self.router.successor_receipt_key_by_old_authorization_id,
                self.router.used_target_addresses,
            ) = router_snapshot[:6]
            object.__setattr__(
                self.router, "_authorized_ingress", router_snapshot[6]
            )
            object.__setattr__(
                self.router,
                "_authorized_ingress_by_address",
                router_snapshot[7],
            )
            object.__setattr__(
                self.router,
                "_authorized_ingress_adapter_ids",
                router_snapshot[8],
            )
            self.router._profile_deployments_by_version = router_snapshot[9]
            object.__setattr__(
                self.router,
                "_bridge_credit_registry_authority",
                router_snapshot[10],
            )
            object.__setattr__(
                self.router, "_source_bridge_authority", router_snapshot[11]
            )
            object.__setattr__(
                self.router,
                "_bridge_domain_registry_authority",
                router_snapshot[12],
            )
            self.router._source_bridge_factories_by_address = (
                router_snapshot[13]
            )
            self.router._source_bundles_by_descriptor_id = router_snapshot[14]
            self.router._source_descriptor_id_by_version = router_snapshot[15]
            self.router._used_source_component_addresses = router_snapshot[16]
            for factory, deployments_state, bundles_state in (
                source_factory_states.values()
            ):
                factory._deployments = deployments_state
                factory._bundles = bundles_state
            for bridge, bridge_state, registry, registry_state in (
                source_bundle_states.values()
            ):
                bridge._restore_transaction_snapshot(
                    bridge_state, capability=_SOURCE_BRIDGE_ROLLBACK_CAPABILITY
                )
                registry._restore_authorization_snapshot(
                    registry_state,
                    source_bridge=bridge,
                    capability=_SOURCE_BRIDGE_ROLLBACK_CAPABILITY,
                )
            source_registry = self.router._bridge_domain_registry_authority
            if (source_registry_state is not None
                    and type(source_registry) is BridgeDomainRegistry):
                source_registry._restore_transaction_snapshot(
                    source_registry_state
                )
            raise

    def schedule_seat_migration(
        self,
        manifest: ScheduledSeatMigration,
        *,
        caller: str,
        clock: Clock,
        cancel: bool = False,
    ) -> tuple[int, int, int, bytes]:
        if (
            caller != self.governance
            or type(manifest) is not ScheduledSeatMigration
            or type(clock) is not Clock
            or manifest.scheduled_at != clock.timestamp
            or type(manifest.target_manifest_hash) is not bytes
            or len(manifest.target_manifest_hash) != 32
            or manifest.generation <= 0
            or manifest.active_protocol_version <= 0
            or manifest.target_protocol_version
            <= manifest.active_protocol_version
            or manifest.executable_at < 0
            or (
                (manifest.old_authorization_id, manifest.new_authorization_id)
                != (b"", b"")
                and (
                    type(manifest.old_authorization_id) is not bytes
                    or len(manifest.old_authorization_id) != 32
                    or type(manifest.new_authorization_id) is not bytes
                    or len(manifest.new_authorization_id) != 32
                )
            )
            or type(cancel) is not bool
        ):
            raise ValueError("scheduled seat migration manifest is invalid")
        delay = (
            self.cancel_delay_seconds if cancel else self.manifest_delay_seconds
        )
        if manifest.executable_at < seat_checked_add(
            clock.timestamp, delay, "seat migration schedule delay"
        ):
            raise ValueError("seat migration manifest delay is too short")
        records = self.cancel_manifests if cancel else self.arm_manifests
        if manifest.key in records:
            raise ValueError("scheduled seat migration manifest is append-only")
        records[manifest.key] = manifest
        return manifest.key

    def _active_target(
        self,
    ) -> tuple[VersionedSettlementHistory, Protocol, MigrationGate]:
        if (
            type(self.router) is not ActiveSettlementRouter
            or self.router.version_manager != self.address
        ):
            raise ValueError("version manager is not bound to the active router")
        registration = self.router.registrations.get(self.router.active_version)
        if registration is None:
            raise ValueError("active Settlement registration is absent")
        history = registration.settlement
        protocol = history.live_protocol
        if (
            protocol is None
            or protocol.versioned_history is not history
            or protocol.header_oracle is not self.router.header_oracle
            or history.header_oracle is not self.router.header_oracle
            or protocol.migration_gate is not self.router.migration_gate
            or history.migration_gate is not self.router.migration_gate
            or self.router.migration_gate.coordinator != self.address
            or protocol.forced_queue is not self.router.forced_queue
            or history.forced_queue is not self.router.forced_queue
            or history.inbox_apply_descriptor
                != self.router.inbox_apply_descriptor
            or protocol.inbox_apply_descriptor
                != history.inbox_apply_descriptor
            or protocol.settlement_address != history.address
            or history.protocol_version != self.router.active_version
        ):
            raise ValueError("active router/Settlement graph is split")
        return history, protocol, self.router.migration_gate

    @staticmethod
    def _response_matches(
        response: SeatMigrationResponse,
        magic: bytes,
        word: RouterWord,
        seat_generation: int,
    ) -> bool:
        return (
            response.magic == magic
            and response.router_generation == word.generation
            and response.active_protocol_version == word.active_version
            and response.target_protocol_version == word.target_version
            and response.target_manifest_hash == word.target_manifest_hash
            and response.seat_generation == seat_generation
        )

    def arm_seat_migration(
        self,
        *,
        manifest_key: tuple[int, int, int, bytes],
        executor: str,
        clock: Clock,
    ) -> bytes:
        history, protocol, gate = self._active_target()
        manifest = self.arm_manifests.get(manifest_key)
        if (
            manifest is None
            or not executor
            or clock.timestamp < manifest.executable_at
            or manifest.generation in self.arm_responses
            or gate.mode != "ACTIVE"
            or manifest.generation != gate.generation + 1
            or manifest.active_protocol_version != self.router.active_version
            or manifest.active_protocol_version != gate.active_protocol_version
            or history.mode != "ACTIVE"
        ):
            raise ValueError("global seat migration arm is invalid")
        protocol._assert_canonical_history_binding()
        protocol_snapshot = protocol._canonical_transaction_snapshot()
        manager_snapshot = copy.deepcopy(
            (self.arm_responses, self.abort_responses)
        )
        try:
            if not gate._arm_from_manager(
                manifest.generation,
                manifest.active_protocol_version,
                manifest.target_protocol_version,
                manifest.target_manifest_hash,
                caller=self.address,
            ):
                raise AssertionError("validated router arm failed")
            history.mode = "MIGRATION_ARMED"
            word = gate.router_word
            raw = protocol.complete_seat_migration_arm(
                caller=self.address, router_word=word, clock=clock
            )
            decoded = decode_seat_migration_response(raw)
            if not self._response_matches(
                decoded, SEAT_ARMED_MAGIC, word, protocol.seat_generation
            ):
                raise ValueError("local arm response does not bind global tuple")
            self.arm_responses[manifest.generation] = raw
            return raw
        except BaseException:
            protocol._restore_canonical_transaction(protocol_snapshot)
            self.arm_responses, self.abort_responses = manager_snapshot
            raise

    def abort_seat_migration(
        self,
        *,
        manifest_key: tuple[int, int, int, bytes],
        executor: str,
        clock: Clock,
    ) -> bytes:
        history, protocol, gate = self._active_target()
        manifest = self.cancel_manifests.get(manifest_key)
        if (
            manifest is None
            or not executor
            or clock.timestamp < manifest.executable_at
            or manifest.generation not in self.arm_responses
            or manifest.generation in self.abort_responses
            or gate.mode not in {"ARMED", "READY"}
            or manifest.generation != gate.generation
            or manifest.active_protocol_version != self.router.active_version
            or manifest.active_protocol_version != gate.active_protocol_version
            or manifest.target_protocol_version != gate.target_protocol_version
            or manifest.target_manifest_hash != gate.target_manifest_hash
            or history.mode not in {"MIGRATION_ARMED", "MIGRATION_READY"}
        ):
            raise ValueError("global seat migration abort is invalid")
        protocol._assert_canonical_history_binding()
        protocol_snapshot = protocol._canonical_transaction_snapshot()
        manager_snapshot = copy.deepcopy(
            (self.arm_responses, self.abort_responses)
        )
        try:
            canceled_word = gate.router_word
            if not gate._abort_from_manager(
                manifest.generation,
                manifest.active_protocol_version,
                manifest.target_protocol_version,
                manifest.target_manifest_hash,
                cancel_manifest_active=True,
                caller=self.address,
            ):
                raise AssertionError("validated router abort failed")
            history.mode = "ACTIVE"
            raw = protocol.complete_seat_migration_abort(
                caller=self.address,
                canceled_arm=canceled_word,
                clock=clock,
            )
            decoded = decode_seat_migration_response(raw)
            if not self._response_matches(
                decoded,
                SEAT_ABORTED_MAGIC,
                canceled_word,
                protocol.seat_generation,
            ):
                raise ValueError("local abort response does not bind canceled tuple")
            self.abort_responses[manifest.generation] = raw
            return raw
        except BaseException:
            protocol._restore_canonical_transaction(protocol_snapshot)
            self.arm_responses, self.abort_responses = manager_snapshot
            raise


def _terminal_hash(namespace: bytes, *parts: bytes) -> bytes:
    """Domain-separated hash primitive for the fixed-depth terminal tree."""

    if (type(namespace) is not bytes
            or any(type(part) is not bytes for part in parts)):
        raise ValueError("terminal hash preimage is not canonical")
    return keccak256(namespace + b"".join(parts))


def terminal_zero_hashes() -> tuple[bytes, ...]:
    """Return the canonical empty subtree hashes for depths zero through 64."""

    rows = [_terminal_hash(b"slot-chain-terminal-empty-v2")]
    for level in range(TERMINAL_TREE_DEPTH):
        rows.append(_terminal_hash(
            b"slot-chain-terminal-node-v2",
            level.to_bytes(1, "big"), rows[-1], rows[-1],
        ))
    return tuple(rows)


TERMINAL_ZERO_HASHES = terminal_zero_hashes()


def _terminal_leaf_bytes(
    index: int,
    destination_domain_id: str,
    destination_bridge: str,
    credit_id: str,
    terminal: str,
    liquidity_settlement_hash: str,
) -> bytes:
    if (type(index) is not int
            or not 0 <= index < UINT64_MAX
            or any(type(word) is not str or not word for word in (
                destination_domain_id, destination_bridge, credit_id,
                terminal,
            ))
            or terminal not in {"DONE", "FAILED"}
            or type(liquidity_settlement_hash) is not str
            or len(liquidity_settlement_hash) != 64
            or (terminal == "DONE"
                and liquidity_settlement_hash == "00" * 32)
            or (terminal == "FAILED"
                and liquidity_settlement_hash != "00" * 32)):
        raise ValueError("terminal leaf fields are not canonical")
    return _terminal_hash(
        b"slot-chain-terminal-leaf-v2",
        index.to_bytes(8, "big"),
        _model_fixed_bytes32(destination_domain_id),
        _model_address20(destination_bridge),
        _model_fixed_bytes32(credit_id),
        (1 if terminal == "DONE" else 2).to_bytes(1, "big"),
        bytes.fromhex(liquidity_settlement_hash),
    )


def liquidity_settlement_hash_v1(
    ticket_id: str, l1_recipient: str, settlement_amount: int,
) -> str:
    if (not ticket_id or not l1_recipient
            or type(settlement_amount) is not int
            or not 0 < settlement_amount <= SEAT_UINT256_MAX):
        raise ValueError("liquidity settlement tuple is noncanonical")
    return keccak256(b"".join((
        b"slot-chain-liquidity-settlement-v1",
        _model_fixed_bytes32(ticket_id),
        _model_address20(l1_recipient),
        _model_uint(settlement_amount, 32, "liquidity settlement amount"),
    ))).hex()


def terminal_merkle_root(leaves: tuple[str, ...] | list[str]) -> str:
    """Compute the fixed-depth sparse root for canonical bytes32 leaves."""

    if (type(leaves) not in {tuple, list}
            or len(leaves) > UINT64_MAX
            or any(type(leaf) is not str or len(leaf) != 64
                   for leaf in leaves)):
        raise ValueError("terminal leaves are not canonical bytes32 values")
    try:
        nodes = {index: bytes.fromhex(leaf)
                 for index, leaf in enumerate(leaves)}
    except ValueError as exc:
        raise ValueError("terminal leaf is not hexadecimal") from exc
    for level in range(TERMINAL_TREE_DEPTH):
        parents: dict[int, bytes] = {}
        for parent in {index >> 1 for index in nodes}:
            left = nodes.get(parent << 1, TERMINAL_ZERO_HASHES[level])
            right = nodes.get((parent << 1) | 1, TERMINAL_ZERO_HASHES[level])
            parents[parent] = _terminal_hash(
                b"slot-chain-terminal-node-v2",
                level.to_bytes(1, "big"), left, right,
            )
        nodes = parents
    return nodes.get(0, TERMINAL_ZERO_HASHES[TERMINAL_TREE_DEPTH]).hex()


def terminal_merkle_branch(
    leaves: tuple[str, ...] | list[str], index: int,
) -> tuple[str, ...]:
    """Fixture/prover helper returning the exact 64 ordered sibling hashes."""

    if (type(index) is not int or not 0 <= index < len(leaves)
            or len(leaves) > UINT64_MAX):
        raise ValueError("terminal branch index is outside the vector")
    try:
        nodes = {offset: bytes.fromhex(leaf)
                 for offset, leaf in enumerate(leaves)}
    except (TypeError, ValueError) as exc:
        raise ValueError("terminal branch leaves are not bytes32") from exc
    branch: list[str] = []
    cursor = index
    for level in range(TERMINAL_TREE_DEPTH):
        branch.append(
            nodes.get(cursor ^ 1, TERMINAL_ZERO_HASHES[level]).hex()
        )
        parents: dict[int, bytes] = {}
        for parent in {offset >> 1 for offset in nodes}:
            left = nodes.get(parent << 1, TERMINAL_ZERO_HASHES[level])
            right = nodes.get((parent << 1) | 1, TERMINAL_ZERO_HASHES[level])
            parents[parent] = _terminal_hash(
                b"slot-chain-terminal-node-v2",
                level.to_bytes(1, "big"), left, right,
            )
        nodes = parents
        cursor >>= 1
    return tuple(branch)


def fold_terminal_merkle_branch(
    leaf_hash: str, index: int, siblings: tuple[str, ...],
) -> str:
    """Fold one canonical depth-64 branch using little-endian index bits."""

    if (type(leaf_hash) is not str or len(leaf_hash) != 64
            or type(index) is not int or not 0 <= index < UINT64_MAX
            or type(siblings) is not tuple
            or len(siblings) != TERMINAL_TREE_DEPTH
            or any(type(sibling) is not str or len(sibling) != 64
                   for sibling in siblings)):
        raise ValueError("terminal branch is not canonical")
    try:
        node = bytes.fromhex(leaf_hash)
        sibling_bytes = tuple(bytes.fromhex(row) for row in siblings)
    except ValueError as exc:
        raise ValueError("terminal branch is not hexadecimal") from exc
    for level, sibling in enumerate(sibling_bytes):
        left, right = (
            (node, sibling) if ((index >> level) & 1) == 0
            else (sibling, node)
        )
        node = _terminal_hash(
            b"slot-chain-terminal-node-v2",
            level.to_bytes(1, "big"), left, right,
        )
    return node.hex()


@dataclass(frozen=True)
class TerminalProof:
    protocol_version: int
    canonical_sequence: int
    leaf_index: int
    siblings: tuple[str, ...]
    ticket_id: str = ""
    l1_recipient: str = ""
    settlement_amount: int = 0


@dataclass(frozen=True)
class TerminalSignalVerifier:
    router: ActiveSettlementRouter
    support_registry: BridgeDomainRegistry | None = field(
        default=None, compare=False, repr=False
    )
    address: str = "source-terminal-verifier"
    runtime_hash: str = SOURCE_TERMINAL_VERIFIER_RUNTIME_HASH
    configuration_hash: str = ""

    def __post_init__(self) -> None:
        support = self.support_registry
        if support is None:
            support = self.router._bridge_domain_registry_authority
            object.__setattr__(self, "support_registry", support)
        if type(support) is not BridgeDomainRegistry:
            raise ValueError("terminal verifier support Registry is missing")
        expected = source_terminal_verifier_configuration_hash(
            router_address=self.router.address,
        )
        if (type(self.router) is not ActiveSettlementRouter
                or support.router is not self.router
                or self.runtime_hash != SOURCE_TERMINAL_VERIFIER_RUNTIME_HASH
                or self.configuration_hash not in {"", expected}):
            raise ValueError("terminal verifier authority graph is split")
        object.__setattr__(self, "configuration_hash", expected)

    @staticmethod
    def terminal_leaf(index: int, destination_domain_id: str,
                      destination_bridge: str, credit_id: str,
                      terminal: str, ticket_id: str = "",
                      l1_recipient: str = "",
                      settlement_amount: int = 0) -> str:
        settlement_hash = (
            "00" * 32 if terminal == "FAILED"
            else liquidity_settlement_hash_v1(
                ticket_id, l1_recipient, settlement_amount
            )
        )
        return _terminal_leaf_bytes(
            index,
            destination_domain_id,
            destination_bridge,
            credit_id,
            terminal,
            settlement_hash,
        ).hex()

    def verify(self, *, proof: TerminalProof, credit_id: str,
               terminal: str, destination_domain_id: str,
               destination_bridge: str) -> bool:
        canonical = (
            self.router.canonical_at(
                proof.protocol_version, proof.canonical_sequence
            ) if type(proof) is TerminalProof else None
        )
        if canonical is None:
            return False
        try:
            expected_leaf = self.terminal_leaf(
                proof.leaf_index, destination_domain_id,
                destination_bridge, credit_id, terminal,
                proof.ticket_id, proof.l1_recipient,
                proof.settlement_amount,
            )
            folded_root = fold_terminal_merkle_branch(
                expected_leaf, proof.leaf_index, proof.siblings
            )
        except ValueError:
            return False
        return (type(self.support_registry) is BridgeDomainRegistry
                and self.support_registry.router is self.router
                and self.router._bridge_domain_registry_authority
                    is self.support_registry
                and self.configuration_hash
                    == source_terminal_verifier_configuration_hash(
                        router_address=self.router.address,
                )
                and terminal in {"DONE", "FAILED"}
                and canonical.protocol_version == proof.protocol_version
                and canonical.canonical_sequence
                    == proof.canonical_sequence
                and folded_root == canonical.terminal_root
                and 0 <= proof.leaf_index < canonical.terminal_count)


def source_send_mode(selector: str) -> str:
    if selector == "sendMessage(Message)":
        return "V1"
    if selector == "sendMessageV2(MessageV1,uint64)":
        return "V2_DIRECT"
    return "REJECTED"






def fund_v2_native_for_test(bridge: object, amount: int) -> None:
    """Model forced/native surplus in one fresh V2 Bridge account."""

    if (type(bridge) not in {SourceBridgeV2, DestinationBridgeLedger}
            or type(amount) is not int or amount < 0):
        raise ValueError("V2 native funding is invalid")
    bridge.balance = seat_checked_add(
        bridge.balance, amount, "V2 Bridge explicit funding"
    )


def set_source_v2_accounting_for_test(
    bridge: "SourceBridgeV2", *,
    credits: dict[str, SourceCredit] | None = None,
    authorizations: dict[str, CreditAuthorization] | None = None,
    refunds: dict[str, int] | None = None,
    liquidity_claims: dict[str, int] | None = None,
    total_liability: int | None = None,
) -> None:
    """Fixture-only seeding of private in-Bridge accounting."""

    if type(bridge) is not SourceBridgeV2:
        raise ValueError("source accounting fixture Bridge is invalid")
    bridge._credits = copy.deepcopy(
        dict(bridge.credits) if credits is None else credits
    )
    if authorizations is not None:
        bridge.credit_registry._authorizations.clear()
        bridge.credit_registry._authorizations.update(authorizations)
    bridge._refunds = dict(
        dict(bridge.refunds) if refunds is None else refunds
    )
    bridge._lp_pulls = dict(
        dict(bridge.liquidity_claims)
        if liquidity_claims is None else liquidity_claims
    )
    liability = (
        bridge.total_live_liability
        if total_liability is None else total_liability
    )
    if type(liability) is not int or liability < 0:
        raise ValueError("source accounting fixture liability is invalid")
    bridge._total_live_liability = liability


def set_destination_v2_accounting_for_test(
    bridge: "DestinationBridgeLedger", *,
    pull_credits: dict[str, int] | None = None,
    total_liability: int | None = None,
    status: dict[str, str] | None = None,
    terminal_index: dict[str, int] | None = None,
    terminal_settlements: dict[
        str, NativeLiquiditySettlementV2
    ] | None = None,
) -> None:
    """Fixture-only seeding of private in-Bridge accounting."""

    if type(bridge) is not DestinationBridgeLedger:
        raise ValueError("destination accounting fixture Bridge is invalid")
    bridge._pull_credits = dict(
        dict(bridge.pull_credits)
        if pull_credits is None else pull_credits
    )
    liability = (
        bridge.total_pull_liability
        if total_liability is None else total_liability
    )
    if type(liability) is not int or liability < 0:
        raise ValueError("destination accounting fixture liability is invalid")
    bridge._total_pull_liability = liability
    bridge._status = dict(bridge.status) if status is None else dict(status)
    bridge._terminal_index = (
        dict(bridge.terminal_index)
        if terminal_index is None else dict(terminal_index)
    )
    bridge._terminal_settlements = (
        dict(bridge._terminal_settlements)
        if terminal_settlements is None else dict(terminal_settlements)
    )


def restore_destination_bridge_snapshot_for_test(
    bridge: "DestinationBridgeLedger", snapshot: dict[str, object],
) -> None:
    """Fixture-only restoration; production rollback remains frame-gated."""

    if (type(bridge) is not DestinationBridgeLedger
            or type(snapshot) is not dict or bridge.entered):
        raise ValueError("destination snapshot fixture is invalid")
    updated_at, quota, available = snapshot["quota_snapshot"]
    if (quota != bridge.quota_manager.eth_quota_cap
            or type(updated_at) is not int or updated_at < 0
            or type(available) is not int or not 0 <= available <= quota):
        raise ValueError("destination snapshot quota is invalid")
    bridge.balance = snapshot["balance"]
    bridge.quota_manager._state.updated_at = updated_at
    bridge.quota_manager._state.available = available
    bridge._pull_credits = dict(snapshot["pull_credits"])
    bridge._total_pull_liability = snapshot["total_pull_liability"]
    bridge._status = dict(snapshot["status"])
    bridge._terminal_index = dict(snapshot["terminal_index"])
    bridge._terminal_settlements = dict(snapshot["terminal_settlements"])
    bridge.liquidity_pool._restore(snapshot["liquidity_pool"])
    bridge.terminal_accumulator.leaves[:] = snapshot["terminal_leaves"]
    bridge.terminal_accumulator.terminalized_pinned_count.clear()
    bridge.terminal_accumulator.terminalized_pinned_count.update(
        snapshot["terminalized_pinned_count"]
    )
    bridge.terminal_accumulator._terminalized_credits.clear()
    bridge.terminal_accumulator._terminalized_credits.update(
        snapshot["terminalized_credits"]
    )


@dataclass
class SourceNativeReceiverV2:
    """One source-chain native receiver used to model refund CALL behavior."""

    address: str
    rejects_native: bool = False
    balance: int = 0
    callback: Callable[["SourceBridgeV2"], None] | None = field(
        default=None, compare=False, repr=False
    )
    _environment_authority: object | None = field(
        default=None, init=False, compare=False, repr=False
    )

    def _bind_environment_once(
        self, environment: "SourceNativeExecutionEnvironmentV2"
    ) -> bool:
        if (type(environment) is not SourceNativeExecutionEnvironmentV2
                or not self.address):
            return False
        if self._environment_authority is not None:
            return self._environment_authority is environment
        object.__setattr__(self, "_environment_authority", environment)
        return True


@dataclass(frozen=True)
class SourceNativeTransactionFrameV2:
    environment: "SourceNativeExecutionEnvironmentV2" = field(
        compare=False, repr=False
    )
    caller: str
    nonce: int
    operation: str
    block_timestamp: int


@dataclass
class SourceNativeExecutionEnvironmentV2:
    """Source-chain account journal; it is chain state, not Bridge policy."""

    chain_id: int
    block_timestamp: int = GENESIS_TIMESTAMP
    eoa_balances: dict[str, int] = field(default_factory=dict)
    _receivers: dict[str, SourceNativeReceiverV2] = field(
        default_factory=dict, init=False, compare=False, repr=False
    )
    _bridge_authority: object | None = field(
        default=None, init=False, compare=False, repr=False
    )
    _active_frame: SourceNativeTransactionFrameV2 | None = field(
        default=None, init=False, compare=False, repr=False
    )
    _next_nonce: int = field(
        default=1, init=False, compare=False, repr=False
    )

    def __post_init__(self) -> None:
        if (type(self.chain_id) is not int
                or not 0 < self.chain_id <= UINT64_MAX
                or type(self.block_timestamp) is not int
                or not 0 <= self.block_timestamp <= UINT64_MAX):
            raise ValueError("source native execution chain is invalid")

    def _bind_bridge_once(self, bridge: object) -> bool:
        if (type(bridge) is not SourceBridgeV2
                or bridge.native_environment is not self
                or bridge.source_chain_id != self.chain_id):
            return False
        if self._bridge_authority is not None:
            return self._bridge_authority is bridge
        object.__setattr__(self, "_bridge_authority", bridge)
        return True

    def deploy_receiver(self, receiver: SourceNativeReceiverV2) -> bool:
        """Model a later source-chain CREATE without making an allowlist."""

        if (self._active_frame is not None
                or type(receiver) is not SourceNativeReceiverV2
                or not receiver.address
                or receiver.address in self._receivers
                or not receiver._bind_environment_once(self)):
            return False
        receiver.balance = seat_checked_add(
            receiver.balance,
            self.eoa_balances.pop(receiver.address, 0),
            "source deployed receiver balance",
        )
        self._receivers[receiver.address] = receiver
        return True

    def _open_frame(
        self, caller: str, operation: str
    ) -> SourceNativeTransactionFrameV2:
        if self._active_frame is not None or not caller:
            raise RuntimeError("source native transaction frame is active")
        frame = SourceNativeTransactionFrameV2(
            self, caller, self._next_nonce, operation, self.block_timestamp
        )
        object.__setattr__(self, "_next_nonce", self._next_nonce + 1)
        object.__setattr__(self, "_active_frame", frame)
        return frame

    def _close_frame(self, frame: SourceNativeTransactionFrameV2) -> None:
        if self._active_frame is not frame:
            raise RuntimeError("source native frame identity changed")
        object.__setattr__(self, "_active_frame", None)

    def withdraw_bridge_refund(
        self,
        bridge: "SourceBridgeV2",
        *,
        caller: str,
        recipient: str,
    ) -> int:
        try:
            frame = self._open_frame(caller, "WITHDRAW_REFUND")
        except RuntimeError:
            return 0
        try:
            return bridge._withdraw_refund_from_environment(
                recipient=recipient, frame=frame
            )
        finally:
            self._close_frame(frame)

    def withdraw_bridge_liquidity_claim(
        self,
        bridge: "SourceBridgeV2",
        *,
        caller: str,
        recipient: str,
    ) -> int:
        try:
            frame = self._open_frame(caller, "WITHDRAW_LP_CLAIM")
        except RuntimeError:
            return 0
        try:
            return bridge._withdraw_lp_claim_from_environment(
                recipient=recipient, frame=frame
            )
        finally:
            self._close_frame(frame)




    def _transaction_snapshot(self) -> dict[str, object]:
        return {
            "eoa_balances": dict(self.eoa_balances),
            "receiver_balances": {
                address: receiver.balance
                for address, receiver in self._receivers.items()
            },
        }

    def _restore_transaction_snapshot(
        self, snapshot: dict[str, object]
    ) -> None:
        self.eoa_balances.clear()
        self.eoa_balances.update(snapshot["eoa_balances"])
        for address, balance in snapshot["receiver_balances"].items():
            self._receivers[address].balance = balance

    def _transfer_native(
        self,
        bridge: "SourceBridgeV2",
        recipient: str,
        amount: int,
        *,
        frame: SourceNativeTransactionFrameV2,
    ) -> bool:
        if (bridge is not self._bridge_authority
                or bridge.native_environment is not self
                or frame is not self._active_frame
                or frame.environment is not self
                or frame.operation not in {
                    "WITHDRAW_REFUND", "WITHDRAW_LP_CLAIM",
                    "V1_PROCESS", "V1_RETRY",
                    "V1_RECALL",
                }
                or not bridge.entered or not recipient
                or type(amount) is not int or amount < 0):
            return False
        receiver = self._receivers.get(recipient)
        if receiver is None:
            self.eoa_balances[recipient] = seat_checked_add(
                self.eoa_balances.get(recipient, 0),
                amount,
                "source refund recipient balance",
            )
            return True
        if receiver.rejects_native:
            return False
        receiver.balance = seat_checked_add(
            receiver.balance, amount, "source refund receiver balance"
        )
        if receiver.callback is not None:
            receiver.callback(bridge)
        return True


@dataclass(frozen=True)
class CreditAuthorization:
    src_chain_id: int
    source_domain_id: str
    src_epoch: int
    src_bridge: str
    destination_domain_id: str
    destination_bridge: str
    bridge_execution_hash: str
    emitted_at_block: int
    escrow_id: str
    msg_hash: str
    calldata_hash: str
    calldata_length: int
    enqueue_by: int
    sender: str
    owner: str
    destination_owner: str
    value: int
    fee: int
    refund_mode: str = "DIRECT"
    refund_vault: str = ""
    liquidity_fee: int = 0
    protocol_version: int = 1
    destination_chain_id: int = 0
    release_manifest_hash: bytes = bytes(32)
    execution_profile_hash: str = ""


def encode_credit_authorization_v2(
    authorization: CreditAuthorization,
) -> bytes:
    if type(authorization) is not CreditAuthorization:
        raise ValueError("credit authorization has the wrong type")
    encoded = b"".join((
        _model_fixed_bytes32(authorization.source_domain_id),
        _model_uint(authorization.src_epoch, 32, "authorization source epoch"),
        bytes(12) + _model_address20(authorization.src_bridge),
        _model_fixed_bytes32(authorization.bridge_execution_hash),
        _model_uint(authorization.emitted_at_block, 32,
                    "authorization emission block"),
        _model_fixed_bytes32(authorization.msg_hash),
        _model_fixed_bytes32(authorization.destination_domain_id),
        _model_uint(authorization.destination_chain_id, 32,
                    "authorization destination chain id"),
        _model_uint(authorization.enqueue_by, 32,
                    "authorization enqueue deadline"),
        bytes(12) + _model_address20(authorization.sender),
        bytes(12) + _model_address20(authorization.owner),
        bytes(12) + _model_address20(authorization.destination_owner),
        _model_uint(authorization.value, 32, "authorization value"),
        _model_uint(authorization.fee, 32, "authorization execution fee"),
        _model_uint(authorization.liquidity_fee, 32,
                    "authorization liquidity fee"),
        _model_fixed_bytes32(authorization.calldata_hash),
        _model_uint(authorization.calldata_length, 32,
                    "authorization calldata length"),
        _model_fixed_bytes32(authorization.escrow_id),
    ))
    if len(encoded) != 576:
        raise AssertionError("creditAuthorizationV2 return width drifted")
    return encoded


@dataclass
class SourceCredit:
    value: int
    fee: int
    status: str = "NEW"
    queue_index: int | None = None
    liquidity_fee: int = 0
    liability_class: str = "PENDING"
    pull_beneficiary: str = ""
    pull_amount: int = 0


def encode_credit_liability_v2(
    credit: SourceCredit, total_live_liability: int,
) -> bytes:
    status_codes = {
        "NEW": 1,
        "QUEUED": 2,
        "DELIVERED": 3,
        "RECALLED": 4,
        "CANCELLED": 5,
    }
    pull_codes = {"PENDING": 0, "USER_PULL": 1, "LP_PULL": 2}
    if (type(credit) is not SourceCredit
            or credit.status not in status_codes
            or credit.liability_class not in pull_codes
            or type(total_live_liability) is not int
            or not 0 <= total_live_liability <= SEAT_UINT256_MAX):
        raise ValueError("source credit liability is invalid")
    queue_index = UINT64_MAX if credit.queue_index is None else credit.queue_index
    encoded = b"".join((
        _model_uint(credit.value, 32, "liability value"),
        _model_uint(credit.fee, 32, "liability execution fee"),
        _model_uint(credit.liquidity_fee, 32, "liability liquidity fee"),
        _model_uint(status_codes[credit.status], 32, "liability status"),
        _model_uint(queue_index, 32, "liability queue index"),
        _model_uint(pull_codes[credit.liability_class], 32,
                    "liability pull class"),
        bytes(12) + _model_address20(
            credit.pull_beneficiary, zero_if_empty=True
        ),
        _model_uint(credit.pull_amount, 32, "liability pull amount"),
        _model_uint(total_live_liability, 32, "total live liability"),
    ))
    if len(encoded) != 288:
        raise AssertionError("creditLiabilityV2 return width drifted")
    return encoded


@dataclass(frozen=True)
class SourceSendReceipt:
    """The exact normalized Message and commitments returned by source send."""

    credit_id: str
    msg_hash: str
    envelope: BridgeAdmissionEnvelope


def bridge_escrow_id(credit_id: str) -> str:
    if not credit_id:
        raise ValueError("Bridge credit identity is empty")
    return keccak256(
        b"slot-chain-bridge-escrow-v2" + _model_fixed_bytes32(credit_id)
    ).hex()


@dataclass(frozen=True)
class BridgeQueueDescriptorV11:
    """Exact durable 541-byte kind-1 leaf, not an admission envelope.

    The complete IBridge.Message is authenticated once by the L1 adapter and
    source authorization.  Fields that are absent from the normative durable
    descriptor (message id, invocation gas, target and data length) cannot be
    consulted by the L2 consumer and therefore are deliberately not stored.
    """

    enqueued_at: int
    accounted_gas: int
    byte_length: int
    payload_hash: str
    prepaid: int
    sender: str
    bridge_fee: int
    bridge_src_chain_id: int
    bridge_src_owner: str
    bridge_dest_chain_id: int
    bridge_dest_owner: str
    bridge_value: int
    bridge_data_hash: str
    source_domain_id: str
    source_registration_epoch: int
    source_bridge: str
    bridge_execution_hash: str
    emitted_at_block: int
    destination_domain_id: str
    enqueue_by: int
    refund_mode: str
    refund_address: str
    refund_vault: str
    refund_capsule_hash: str
    escrow_id: str
    bridge_liquidity_fee: int = 0
    kind: ForceKind = ForceKind.BRIDGE_CREDIT
    valid_until: int = UINT64_MAX
    due_at: int = 0

    @property
    def msg_hash(self) -> str:
        return self.payload_hash

    @property
    def credit_id(self) -> str:
        return BridgeAdapter.credit_id(
            self.bridge_src_chain_id,
            self.source_domain_id,
            self.source_registration_epoch,
            self.source_bridge,
            self.destination_domain_id,
            self.msg_hash,
            self.bridge_liquidity_fee,
        )

    @property
    def inbox_route(self) -> tuple[str, str, str]:
        return (
            self.destination_domain_id,
            self.credit_id,
            self.msg_hash,
        )

    @property
    def canonical_bytes(self) -> bytes:
        """Return the exact packed V11 descriptor body committed by the Queue."""

        encoded = b"".join((
            _model_fixed_bytes32(self.msg_hash),
            _model_uint(
                self.bridge_src_chain_id, 32, "V11 source chain id"
            ),
            _model_fixed_bytes32(self.source_domain_id),
            _model_uint(
                self.source_registration_epoch, 8,
                "V11 source registration epoch",
            ),
            _model_address20(self.source_bridge),
            _model_fixed_bytes32(self.bridge_execution_hash),
            _model_uint(
                self.emitted_at_block, 8, "V11 source emission block"
            ),
            _model_fixed_bytes32(self.destination_domain_id),
            _model_uint(
                self.bridge_dest_chain_id, 32, "V11 destination chain id"
            ),
            _model_uint(self.enqueue_by, 8, "V11 enqueue deadline"),
            _model_address20(self.sender),
            _model_address20(self.bridge_src_owner),
            _model_address20(self.bridge_dest_owner),
            _model_uint(self.bridge_value, 32, "V11 value"),
            _model_uint(self.bridge_fee, 8, "V11 execution fee"),
            _model_uint(self.bridge_liquidity_fee, 8, "V11 liquidity fee"),
            _model_fixed_bytes32(self.bridge_data_hash),
            _model_uint(1 if self.refund_mode == "DIRECT" else 0, 1,
                        "V11 refund mode"),
            _model_address20(self.refund_vault, zero_if_empty=True),
            _model_fixed_bytes32(
                self.refund_capsule_hash, zero_if_empty=True
            ),
            _model_fixed_bytes32(self.escrow_id),
            _model_uint(self.byte_length, 4, "V11 calldata length"),
            _model_uint(self.accounted_gas, 8, "V11 accounted gas"),
            _model_address20(self.refund_address),
            _model_uint(self.enqueued_at, 8, "V11 enqueue time"),
            _model_uint(self.due_at, 8, "V11 due time"),
            _model_uint(self.prepaid, 32, "V11 ingress deposit"),
        ))
        if len(encoded) != BRIDGE_QUEUE_DESCRIPTOR_V11_BYTES:
            raise AssertionError("V11 descriptor byte geometry drifted")
        return encoded

    def structurally_valid(self) -> bool:
        expected_credit_id = self.credit_id
        refund_exact = (
            self.refund_mode == "DIRECT"
            and not self.refund_vault
            and not self.refund_capsule_hash
        )
        try:
            encoded_length = len(self.canonical_bytes)
        except ValueError:
            return False
        return (
            self.kind is ForceKind.BRIDGE_CREDIT
            and self.valid_until == UINT64_MAX
            and self.accounted_gas == MAX_FORCE_MESSAGE_GAS
            and 0 <= self.byte_length <= MAX_FORCE_MESSAGE_BYTES
            and bool(self.payload_hash)
            and bool(self.sender)
            and 0 < self.bridge_src_chain_id <= UINT64_MAX
            and bool(self.bridge_src_owner)
            and 0 < self.bridge_dest_chain_id <= UINT64_MAX
            and self.bridge_dest_chain_id != self.bridge_src_chain_id
            and bool(self.bridge_dest_owner)
            and 0 <= self.bridge_value <= SEAT_UINT256_MAX
            and 0 <= self.bridge_fee <= UINT64_MAX
            and 0 < self.bridge_liquidity_fee <= UINT64_MAX
            and self.bridge_value <= SEAT_UINT256_MAX - self.bridge_fee
            and self.bridge_value + self.bridge_fee
                <= SEAT_UINT256_MAX - self.bridge_liquidity_fee
            and bool(self.bridge_data_hash)
            and self.credit_id == expected_credit_id
            and self.escrow_id == bridge_escrow_id(self.credit_id)
            and bool(self.source_domain_id)
            and 0 < self.source_registration_epoch <= UINT64_MAX
            and bool(self.source_bridge)
            and bool(self.bridge_execution_hash)
            and 0 < self.emitted_at_block <= UINT64_MAX
            and bool(self.destination_domain_id)
            and bool(self.refund_address)
            and 0 <= self.enqueue_by <= UINT64_MAX
            and refund_exact
            and encoded_length == BRIDGE_QUEUE_DESCRIPTOR_V11_BYTES
        )


@dataclass
class BridgeCreditRegistryV2:
    """Immutable source authorization registry with no ETH custody."""

    domain_registry: BridgeDomainRegistry = field(compare=False, repr=False)
    source_descriptor: SourceBridgeDescriptor = field(compare=False)
    _authorizations: dict[str, CreditAuthorization] = field(
        default_factory=dict, init=False, repr=False
    )
    address: str = "bridge-credit-registry-v2"
    runtime_hash: str = BRIDGE_CREDIT_REGISTRY_RUNTIME_HASH
    domain_registrar: str = "source-domain-registrar"
    source_registration_epoch: int = 1
    configuration_hash: str = ""
    fault_point: str | None = field(default=None, compare=False)
    _source_bridge_authority: object | None = field(
        default=None, init=False, compare=False, repr=False
    )

    def __post_init__(self) -> None:
        expected = bridge_credit_registry_configuration_hash(
            address=self.address,
            runtime_hash=self.runtime_hash,
            domain_registrar=self.domain_registrar,
            frozen_bridge=self.source_descriptor.source_bridge,
            support_registry_address=self.domain_registry.address,
            support_registry_runtime_hash=self.domain_registry.runtime_hash,
            support_registry_configuration_hash=(
                self.domain_registry.configuration_hash
            ),
            source_chain_id=self.source_descriptor.source_chain_id,
            source_domain_id=self.source_descriptor.source_domain_id,
            source_registration_epoch=self.source_registration_epoch,
            frozen_bridge_execution_hash=(
                self.source_descriptor.bridge_execution_hash
            ),
            source_descriptor_id=self.source_descriptor.descriptor_id,
        )
        if self.configuration_hash and self.configuration_hash != expected:
            raise ValueError("Bridge credit registry configuration is wrong")
        if (type(self.domain_registry) is not BridgeDomainRegistry
                or type(self.source_descriptor) is not SourceBridgeDescriptor
                or self.source_descriptor.settlement_chain_id
                    != self.domain_registry.router.settlement_chain_context_id
                or self.source_descriptor.settlement_chain_id
                    != self.source_descriptor.source_chain_id
                or self.source_descriptor.bridge_credit_registry
                    != self.address
                or self.domain_registrar
                    != self.source_descriptor.source_domain_registrar
                or self.source_registration_epoch
                    != self.source_descriptor.source_registration_epoch
                or self.domain_registry.address
                    != self.source_descriptor.support_registry_address
                or self.domain_registry.runtime_hash
                    != self.source_descriptor.support_registry_runtime_hash
                or self.domain_registry.configuration_hash
                    != self.source_descriptor
                        .support_registry_configuration_hash
                or not 0 < self.source_registration_epoch <= UINT64_MAX):
            raise ValueError("Bridge credit registry graph is invalid")
        object.__setattr__(self, "configuration_hash", expected)

    def __setattr__(self, name: str, value: object) -> None:
        if name in {
            "domain_registry", "source_descriptor", "address",
            "runtime_hash", "domain_registrar",
            "source_registration_epoch", "configuration_hash",
            "_source_bridge_authority",
        } and name in self.__dict__:
            raise AttributeError(f"Bridge credit registry {name} is immutable")
        object.__setattr__(self, name, value)

    @property
    def source_bridge(self) -> "SourceBridgeV2 | None":
        authority = self._source_bridge_authority
        return authority if type(authority) is SourceBridgeV2 else None

    @property
    def authorizations(self) -> MappingProxyType:
        """Append-only authorization records exposed read-only."""

        return MappingProxyType(self._authorizations)

    def credit_authorization_v2(
        self, calldata: bytes, *, gas: int,
    ) -> bytes | None:
        if (type(calldata) is not bytes or len(calldata) != 36
                or calldata[:4] != CREDIT_AUTHORIZATION_SELECTOR
                or gas != SOURCE_READ_GAS
                or getattr(self, "credit_authorization_call_fault", False)):
            return None
        credit_word = calldata[4:]
        matches = tuple(
            authorization
            for credit_id, authorization in self._authorizations.items()
            if _model_fixed_bytes32(credit_id) == credit_word
        )
        if len(matches) != 1:
            return None
        override = getattr(
            self, "credit_authorization_return_override", None
        )
        return (
            encode_credit_authorization_v2(matches[0])
            if override is None else override
        )

    def decode_credit_authorization_v2(
        self, credit_id: str, returndata: bytes | None,
    ) -> CreditAuthorization | None:
        authorization = self._authorizations.get(credit_id)
        if (authorization is None or type(returndata) is not bytes
                or len(returndata) != 576
                or returndata != encode_credit_authorization_v2(
                    authorization
                )):
            return None
        return authorization

    def _authorization_snapshot(self) -> dict[str, CreditAuthorization]:
        return copy.deepcopy(self._authorizations)

    def _restore_authorization_snapshot(
        self,
        snapshot: dict[str, CreditAuthorization],
        *,
        source_bridge: object, capability: object,
    ) -> None:
        if (source_bridge is not self._source_bridge_authority
                or capability is not _SOURCE_BRIDGE_ROLLBACK_CAPABILITY):
            raise ValueError("credit registry rollback authority is wrong")
        self._authorizations.clear()
        self._authorizations.update(snapshot)

    def _bind_source_bridge_once(self, bridge: object) -> bool:
        if (self._source_bridge_authority is not None
                or type(bridge) is not SourceBridgeV2
                or bridge.credit_registry is not self
                or bridge.source_descriptor is not self.source_descriptor
                or bridge.address != self.source_descriptor.source_bridge):
            return False
        object.__setattr__(self, "_source_bridge_authority", bridge)
        return True

    def _authorize_from_source_bridge(
        self,
        credit_id: str,
        authorization: CreditAuthorization,
        *,
        source_bridge: object,
    ) -> bool:
        if (type(source_bridge) is not SourceBridgeV2
                or source_bridge is not self._source_bridge_authority
                or source_bridge.credit_registry is not self
                or type(authorization) is not CreditAuthorization
                or authorization.src_bridge != source_bridge.address
                or authorization.src_chain_id
                    != self.source_descriptor.source_chain_id
                or authorization.source_domain_id
                    != self.source_descriptor.source_domain_id
                or authorization.src_epoch != self.source_registration_epoch
                or authorization.bridge_execution_hash
                    != self.source_descriptor.bridge_execution_hash
                or authorization.msg_hash == ""
                or not authorization.sender
                or not authorization.owner
                or not authorization.destination_owner
                or not 0 < authorization.destination_chain_id <= UINT64_MAX
                or not authorization.destination_domain_id
                or authorization.calldata_hash == ""
                or type(authorization.calldata_length) is not int
                or not 0 <= authorization.calldata_length
                    <= MAX_FORCE_MESSAGE_BYTES
                or authorization.value < 0 or authorization.fee < 0
                or not 0 < authorization.liquidity_fee <= UINT64_MAX
                or authorization.refund_mode != "DIRECT"
                or authorization.refund_vault
                or credit_id != BridgeAdapter.credit_id(
                    authorization.src_chain_id,
                    authorization.source_domain_id,
                    authorization.src_epoch,
                    authorization.src_bridge,
                    authorization.destination_domain_id,
                    authorization.msg_hash,
                    authorization.liquidity_fee,
                )
                or credit_id in self._authorizations):
            return False
        self._authorizations[credit_id] = authorization
        if self.fault_point == "after_authorization_write":
            raise RuntimeError(
                "injected credit registry fault: after_authorization_write"
            )
        return True


def source_bridge_configuration_hash_for_descriptor(
    descriptor: SourceBridgeDescriptor,
    registry_address: str,
    registry_runtime_hash: str,
    registry_configuration_hash: str,
) -> str:
    if (type(descriptor) is not SourceBridgeDescriptor
            or not registry_address or not registry_runtime_hash
            or not registry_configuration_hash
            or registry_address != descriptor.bridge_credit_registry
            or registry_runtime_hash != BRIDGE_CREDIT_REGISTRY_RUNTIME_HASH
            or type(descriptor.deployment_descriptor)
                is not ImmutableBridgeDeploymentDescriptorV2
            or descriptor.deployment_descriptor.account_configuration_hash
                != source_bridge_account_configuration_hash(descriptor)):
        raise ValueError("source Bridge configuration graph is invalid")
    return descriptor.deployment_descriptor.account_configuration_hash


def source_bridge_configuration_hash(
    descriptor: SourceBridgeDescriptor,
    registry: BridgeCreditRegistryV2,
) -> str:
    if type(registry) is not BridgeCreditRegistryV2:
        raise ValueError("source Bridge registry has the wrong type")
    return source_bridge_configuration_hash_for_descriptor(
        descriptor,
        registry.address,
        registry.runtime_hash,
        registry.configuration_hash,
    )


_V2_BRIDGE_FACTORY_RECEIPT_CAPABILITY = object()


@dataclass(frozen=True, eq=False)
class V2BridgeFactoryDeploymentReceipt:
    """Test-only deployment observation; activation never trusts this row."""

    factory: "ImmutableV2BridgeFactory" = field(compare=False, repr=False)
    bridge: str
    salt: str
    initcode_hash: str
    runtime_hash: str
    configuration_hash: str
    registry_address: str
    registry_runtime_hash: str
    registry_configuration_hash: str
    quota_manager_address: str
    quota_manager_runtime_hash: str
    quota_manager_configuration_hash: str
    terminal_verifier_address: str
    terminal_verifier_runtime_hash: str
    terminal_verifier_configuration_hash: str
    created_now: bool
    seal: str
    _capability: object = field(compare=False, repr=False)

    @property
    def digest(self) -> str:
        return hashlib.sha256(
            b"TAIKO_V2_BRIDGE_FACTORY_RECEIPT_V1\x00"
            + repr((
                id(self.factory), self.bridge, self.salt,
                self.initcode_hash, self.runtime_hash,
                self.configuration_hash,
                self.registry_address, self.registry_runtime_hash,
                self.registry_configuration_hash,
                self.quota_manager_address,
                self.quota_manager_runtime_hash,
                self.quota_manager_configuration_hash,
                self.terminal_verifier_address,
                self.terminal_verifier_runtime_hash,
                self.terminal_verifier_configuration_hash,
                self.created_now,
            )).encode()
        ).hexdigest()


@dataclass(eq=False)
class ImmutableV2BridgeFactory:
    """Permissionless deterministic deployment with exact-code idempotence."""

    address: str
    runtime_hash: str
    configuration_hash: str
    immutable_nonproxy: bool = True
    selfdestruct_disabled: bool = True
    _deployments: dict[str, tuple[str, ...]] = field(
        default_factory=dict, init=False, repr=False
    )
    _bundles: dict[str, tuple[object, ...]] = field(
        default_factory=dict, init=False, repr=False
    )
    _secret: object = field(default_factory=object, init=False, repr=False)

    def __setattr__(self, name: str, value: object) -> None:
        if name in {
            "address", "runtime_hash", "configuration_hash",
            "immutable_nonproxy", "selfdestruct_disabled",
        } \
                and name in self.__dict__:
            raise AttributeError(f"V2 Bridge factory {name} is immutable")
        object.__setattr__(self, name, value)

    def _seal(self, digest: str) -> str:
        return hashlib.sha256(
            b"TAIKO_V2_BRIDGE_FACTORY_SEAL_V1\x00"
            + id(self._secret).to_bytes(32, "big") + digest.encode()
        ).hexdigest()

    def _receipt(
        self, descriptor: SourceBridgeDescriptor,
        registry: BridgeCreditRegistryV2,
        quota_manager: FrozenNativeQuotaManagerV2,
        terminal_verifier: TerminalSignalVerifier, *,
        created_now: bool,
    ) -> V2BridgeFactoryDeploymentReceipt:
        pending = V2BridgeFactoryDeploymentReceipt(
            self,
            descriptor.source_bridge,
            descriptor.deployment_salt,
            descriptor.deployment_initcode_hash,
            descriptor.bridge_facade_runtime_hash,
            source_bridge_configuration_hash(descriptor, registry),
            registry.address,
            registry.runtime_hash,
            registry.configuration_hash,
            quota_manager.address,
            quota_manager.runtime_hash,
            quota_manager.configuration_hash,
            terminal_verifier.address,
            terminal_verifier.runtime_hash,
            terminal_verifier.configuration_hash,
            created_now,
            "PENDING",
            _V2_BRIDGE_FACTORY_RECEIPT_CAPABILITY,
        )
        return replace(pending, seal=self._seal(pending.digest))

    def deploy_source_bundle(
        self, descriptor: SourceBridgeDescriptor,
        support_registry: BridgeDomainRegistry, *,
        caller: str,
    ) -> tuple[
        "SourceBridgeV2", BridgeCreditRegistryV2,
        V2BridgeFactoryDeploymentReceipt,
    ]:
        """Deploy or exactly reuse the canonical inactive source bundle."""

        if (type(descriptor) is not SourceBridgeDescriptor
                or not caller
                or type(support_registry) is not BridgeDomainRegistry
                or support_registry.address
                    != descriptor.support_registry_address
                or support_registry.runtime_hash
                    != descriptor.support_registry_runtime_hash
                or support_registry.configuration_hash
                    != descriptor.support_registry_configuration_hash
                or support_registry.router.address == ""
                or descriptor.bundle_deployer
                    != source_bridge_create2_address(
                        self.address,
                        descriptor.deployment_salt,
                        descriptor.deployment_initcode_hash,
                    )
                or descriptor.source_bridge != source_bundle_child_address(
                    descriptor.bundle_deployer, 1
                )
                or descriptor.source_bridge == descriptor.legacy_v1_bridge
                or support_registry.router.settlement_chain_context_id
                    != descriptor.settlement_chain_id
                or self.address != descriptor.deployment_factory
                or self.runtime_hash
                    != descriptor.deployment_factory_runtime_hash
                or self.configuration_hash
                    != descriptor.deployment_factory_configuration_hash
                or not self.immutable_nonproxy
                or not self.selfdestruct_disabled):
            raise ValueError("source Bridge factory identity is wrong")
        descriptor.descriptor_id
        existing_bundle = self._bundles.get(descriptor.source_bridge)
        if existing_bundle is not None:
            (
                bridge, registry, quota_manager,
                terminal_verifier, bound_support,
            ) = existing_bundle
            if (type(bridge) is not SourceBridgeV2
                    or type(registry) is not BridgeCreditRegistryV2
                    or type(quota_manager) is not FrozenNativeQuotaManagerV2
                    or type(terminal_verifier) is not TerminalSignalVerifier
                    or bound_support is not support_registry
                    or bridge.credit_registry is not registry
                    or bridge.quota_manager is not quota_manager
                    or bridge.source_descriptor != descriptor
                    or registry.source_registration_epoch
                        != descriptor.source_registration_epoch
                    or bridge.terminal_verifier is not terminal_verifier):
                raise ValueError("CREATE2 source bundle identity is split")
            receipt = self._receipt(
                descriptor, registry, quota_manager, terminal_verifier,
                created_now=False,
            )
            if not self.valid_source_receipt(
                    receipt, descriptor, registry, quota_manager,
                    terminal_verifier,
                    require_live_bundle=True):
                raise ValueError("CREATE2 source bundle current code changed")
            return bridge, registry, receipt

        registry = BridgeCreditRegistryV2(
            support_registry,
            descriptor,
            address=descriptor.bridge_credit_registry,
            runtime_hash=BRIDGE_CREDIT_REGISTRY_RUNTIME_HASH,
            domain_registrar=descriptor.source_domain_registrar,
            source_registration_epoch=descriptor.source_registration_epoch,
        )
        quota_manager = FrozenNativeQuotaManagerV2(
            descriptor.native_quota_manager,
            descriptor.source_bridge,
            descriptor.native_quota_period,
            descriptor.native_eth_quota,
        )
        terminal_verifier = TerminalSignalVerifier(
            support_registry.router,
            support_registry,
            descriptor.source_terminal_verifier,
            descriptor.source_terminal_verifier_runtime_hash,
            descriptor.source_terminal_verifier_configuration_hash,
        )
        expected = (
            descriptor.bundle_deployer,
            descriptor.bundle_deployer_runtime_hash,
            descriptor.deployment_salt,
            descriptor.deployment_initcode_hash,
            descriptor.bridge_facade_runtime_hash,
            source_bridge_configuration_hash(descriptor, registry),
            registry.address,
            registry.runtime_hash,
            registry.configuration_hash,
            quota_manager.address,
            quota_manager.runtime_hash,
            quota_manager.configuration_hash,
            terminal_verifier.address,
            terminal_verifier.runtime_hash,
            terminal_verifier.configuration_hash,
        )
        existing = self._deployments.get(descriptor.source_bridge)
        if existing is not None and existing != expected:
            raise ValueError("CREATE2 slot contains wrong Bridge code/config")
        created = existing is None
        self._deployments.setdefault(descriptor.source_bridge, expected)
        receipt = self._receipt(
            descriptor, registry, quota_manager, terminal_verifier,
            created_now=created,
        )
        bridge = SourceBridgeV2(
            registry,
            descriptor,
            terminal_verifier=terminal_verifier,
            deployment_factory=self,
            deployment_receipt=receipt,
            quota_manager=quota_manager,
            v2_active=False,
            frozen_bridge=descriptor.source_bridge,
            address=descriptor.source_bridge,
            runtime_hash=descriptor.bridge_facade_runtime_hash,
            source_chain_id=descriptor.source_chain_id,
            source_domain_id=descriptor.source_domain_id,
            source_registration_epoch=descriptor.source_registration_epoch,
            frozen_bridge_execution_hash=descriptor.bridge_execution_hash,
        )
        self._bundles[descriptor.source_bridge] = (
            bridge, registry, quota_manager, terminal_verifier,
            support_registry,
        )
        return bridge, registry, receipt

    def source_bundle_exact(
        self, descriptor: SourceBridgeDescriptor,
        registry: BridgeCreditRegistryV2,
        quota_manager: FrozenNativeQuotaManagerV2,
        terminal_verifier: TerminalSignalVerifier,
        bridge: "SourceBridgeV2 | None", *, require_live_bundle: bool,
    ) -> bool:
        """Direct current-code/config verification; no receipt is trusted."""

        try:
            descriptor.descriptor_id
        except ValueError:
            return False
        expected_bundle = source_bridge_create2_address(
            self.address,
            descriptor.deployment_salt,
            descriptor.deployment_initcode_hash,
        )
        expected_bridge = source_bundle_child_address(expected_bundle, 1)
        deployed = self._deployments.get(expected_bridge)
        support_registry = registry.domain_registry
        exact = (
            descriptor.bundle_deployer == expected_bundle
            and descriptor.source_bridge == expected_bridge
            and descriptor.bridge_credit_registry
                == source_bundle_child_address(expected_bundle, 2)
            and descriptor.native_quota_manager
                == source_bundle_child_address(expected_bundle, 3)
            and self.address == descriptor.deployment_factory
            and exact_component_config_staticcall(
                self,
                expected_runtime_hash=(
                    descriptor.deployment_factory_runtime_hash
                ),
                expected_configuration_hash=(
                    descriptor.deployment_factory_configuration_hash
                ),
            )
            and type(registry) is BridgeCreditRegistryV2
            and registry.address == descriptor.bridge_credit_registry
            and exact_component_config_staticcall(
                registry,
                expected_runtime_hash=BRIDGE_CREDIT_REGISTRY_RUNTIME_HASH,
                expected_configuration_hash=(
                    registry.configuration_hash
                ),
            )
            and type(quota_manager) is FrozenNativeQuotaManagerV2
            and quota_manager.address == descriptor.native_quota_manager
            and exact_component_config_staticcall(
                quota_manager,
                expected_runtime_hash=(
                    descriptor.native_quota_manager_runtime_hash
                ),
                expected_configuration_hash=(
                    quota_manager.configuration_hash
                ),
            )
            and type(support_registry) is BridgeDomainRegistry
            and support_registry.address
                == descriptor.support_registry_address
            and exact_component_config_staticcall(
                support_registry,
                expected_runtime_hash=(
                    descriptor.support_registry_runtime_hash
                ),
                expected_configuration_hash=(
                    descriptor.support_registry_configuration_hash
                ),
            )
            and type(terminal_verifier) is TerminalSignalVerifier
            and terminal_verifier.address
                == descriptor.source_terminal_verifier
            and exact_component_config_staticcall(
                terminal_verifier,
                expected_runtime_hash=(
                    descriptor.source_terminal_verifier_runtime_hash
                ),
                expected_configuration_hash=(
                    descriptor.source_terminal_verifier_configuration_hash
                ),
            )
            and bridge is not None
            and bridge.address == descriptor.source_bridge
            and exact_component_config_staticcall(
                bridge,
                expected_runtime_hash=descriptor.bridge_facade_runtime_hash,
                expected_configuration_hash=bridge.configuration_hash,
            )
            and deployed == (
                descriptor.bundle_deployer,
                descriptor.bundle_deployer_runtime_hash,
                descriptor.deployment_salt,
                descriptor.deployment_initcode_hash,
                descriptor.bridge_facade_runtime_hash,
                bridge.configuration_hash,
                registry.address,
                registry.runtime_hash,
                registry.configuration_hash,
                quota_manager.address,
                quota_manager.runtime_hash,
                quota_manager.configuration_hash,
                terminal_verifier.address,
                terminal_verifier.runtime_hash,
                terminal_verifier.configuration_hash,
            )
        )
        return bool(
            exact
            and (
                not require_live_bundle
                or self._bundles.get(expected_bridge) == (
                    bridge, registry, quota_manager, terminal_verifier,
                    support_registry,
                )
            )
        )

    def valid_source_receipt(
        self, receipt: V2BridgeFactoryDeploymentReceipt,
        descriptor: SourceBridgeDescriptor,
        registry: BridgeCreditRegistryV2,
        quota_manager: FrozenNativeQuotaManagerV2,
        terminal_verifier: TerminalSignalVerifier,
        *, require_live_bundle: bool = True,
    ) -> bool:
        expected_bundle = source_bridge_create2_address(
            self.address,
            descriptor.deployment_salt,
            descriptor.deployment_initcode_hash,
        )
        expected_bridge = source_bundle_child_address(expected_bundle, 1)
        deployed = self._deployments.get(expected_bridge)
        return (
            type(receipt) is V2BridgeFactoryDeploymentReceipt
            and receipt._capability is _V2_BRIDGE_FACTORY_RECEIPT_CAPABILITY
            and receipt.factory is self
            and receipt.bridge == expected_bridge
            and descriptor.source_bridge == expected_bridge
            and descriptor.bundle_deployer == expected_bundle
            and descriptor.source_bridge != descriptor.legacy_v1_bridge
            and self.address == descriptor.deployment_factory
            and self.runtime_hash
                == descriptor.deployment_factory_runtime_hash
            and self.configuration_hash
                == descriptor.deployment_factory_configuration_hash
            and self.immutable_nonproxy
            and self.selfdestruct_disabled
            and deployed is not None
            and deployed == (
                descriptor.bundle_deployer,
                descriptor.bundle_deployer_runtime_hash,
                receipt.salt, receipt.initcode_hash,
                receipt.runtime_hash, receipt.configuration_hash,
                receipt.registry_address,
                receipt.registry_runtime_hash,
                receipt.registry_configuration_hash,
                receipt.quota_manager_address,
                receipt.quota_manager_runtime_hash,
                receipt.quota_manager_configuration_hash,
                receipt.terminal_verifier_address,
                receipt.terminal_verifier_runtime_hash,
                receipt.terminal_verifier_configuration_hash,
            )
            and receipt.salt == descriptor.deployment_salt
            and receipt.initcode_hash == descriptor.deployment_initcode_hash
            and receipt.runtime_hash == descriptor.bridge_facade_runtime_hash
            and type(registry) is BridgeCreditRegistryV2
            and registry.source_descriptor == descriptor
            and registry.address == descriptor.bridge_credit_registry
            and receipt.registry_address == registry.address
            and receipt.registry_runtime_hash == registry.runtime_hash
            and receipt.registry_configuration_hash
                == registry.configuration_hash
            and type(quota_manager) is FrozenNativeQuotaManagerV2
            and quota_manager.address == descriptor.native_quota_manager
            and quota_manager.bridge_address == descriptor.source_bridge
            and quota_manager.runtime_hash
                == descriptor.native_quota_manager_runtime_hash
            and quota_manager.configuration_hash
                == descriptor.deployment_descriptor
                    .native_quota_manager_configuration_hash
            and receipt.quota_manager_address == quota_manager.address
            and receipt.quota_manager_runtime_hash
                == quota_manager.runtime_hash
            and receipt.quota_manager_configuration_hash
                == quota_manager.configuration_hash
            and type(terminal_verifier) is TerminalSignalVerifier
            and terminal_verifier.router is registry.domain_registry.router
            and terminal_verifier.support_registry is registry.domain_registry
            and terminal_verifier.address
                == descriptor.source_terminal_verifier
            and terminal_verifier.runtime_hash
                == descriptor.source_terminal_verifier_runtime_hash
            and terminal_verifier.configuration_hash
                == descriptor.source_terminal_verifier_configuration_hash
            and receipt.terminal_verifier_address
                == terminal_verifier.address
            and receipt.terminal_verifier_runtime_hash
                == terminal_verifier.runtime_hash
            and receipt.terminal_verifier_configuration_hash
                == terminal_verifier.configuration_hash
            and quota_manager.snapshot() == (
                0, descriptor.native_eth_quota,
                descriptor.native_eth_quota,
            )
            and (not require_live_bundle
                 or self._bundles.get(expected_bridge) == (
                     registry.source_bridge, registry, quota_manager,
                     terminal_verifier, registry.domain_registry,
                 ))
            and receipt.seal == self._seal(receipt.digest)
        )

    def preseed_wrong_code_for_test(
        self, bridge: str, *, runtime_hash: str,
    ) -> None:
        self._deployments[bridge] = (
            "wrong-bundle", "wrong-bundle-code",
            "wrong-salt", "wrong-initcode", runtime_hash, "wrong-config",
            "wrong-registry", "wrong-registry-code", "wrong-registry-config",
            "wrong-quota", "wrong-quota-code", "wrong-quota-config",
            "wrong-verifier", "wrong-verifier-code", "wrong-verifier-config",
        )


@dataclass
class SourceBridgeV2:
    """Fresh immutable V2 source Bridge and its private accounting state."""

    credit_registry: BridgeCreditRegistryV2 = field(
        compare=False, repr=False
    )
    source_descriptor: SourceBridgeDescriptor = field(compare=False)
    terminal_verifier: TerminalSignalVerifier | None = field(
        default=None, compare=False, repr=False
    )
    deployment_factory: ImmutableV2BridgeFactory | None = field(
        default=None, compare=False, repr=False
    )
    deployment_receipt: V2BridgeFactoryDeploymentReceipt | None = field(
        default=None, compare=False, repr=False
    )
    native_environment: SourceNativeExecutionEnvironmentV2 | None = field(
        default=None, compare=False, repr=False
    )
    quota_manager: FrozenNativeQuotaManagerV2 | None = field(
        default=None, compare=False, repr=False
    )
    _credits: dict[str, SourceCredit] = field(
        default_factory=dict, init=False, repr=False
    )
    _refunds: dict[str, int] = field(
        default_factory=dict, init=False, repr=False
    )
    _lp_pulls: dict[str, int] = field(
        default_factory=dict, init=False, repr=False
    )
    _total_live_liability: int = field(default=0, init=False, repr=False)
    balance: int = 0
    v2_active: bool = False
    activation_surplus: int | None = None
    paused: bool = False
    next_message_id: int = 0
    entered: bool = field(default=False, compare=False)
    fault_point: str | None = field(default=None, compare=False)
    frozen_bridge: str = "bridge:A"
    address: str = "bridge:A"
    runtime_hash: str = "code:source-bridge-facade:v1"
    source_chain_id: int = 1
    source_domain_id: str = ""
    source_registration_epoch: int = 1
    frozen_bridge_execution_hash: str = ""
    configuration_hash: str = ""

    def __post_init__(self) -> None:
        if self.terminal_verifier is None:
            object.__setattr__(
                self,
                "terminal_verifier",
                TerminalSignalVerifier(
                    self.credit_registry.domain_registry.router,
                    self.credit_registry.domain_registry,
                    self.source_descriptor.source_terminal_verifier,
                    self.source_descriptor.source_terminal_verifier_runtime_hash,
                    self.source_descriptor
                        .source_terminal_verifier_configuration_hash,
                ),
            )
        if self.native_environment is None:
            object.__setattr__(
                self,
                "native_environment",
                SourceNativeExecutionEnvironmentV2(self.source_chain_id),
            )
        if self.quota_manager is None:
            object.__setattr__(
                self,
                "quota_manager",
                FrozenNativeQuotaManagerV2(
                    self.source_descriptor.native_quota_manager,
                    self.address,
                    self.source_descriptor.native_quota_period,
                    self.source_descriptor.native_eth_quota,
                ),
            )
        if not self.source_domain_id:
            object.__setattr__(
                self, "source_domain_id", self.source_descriptor.source_domain_id
            )
        if not self.frozen_bridge_execution_hash:
            object.__setattr__(
                self,
                "frozen_bridge_execution_hash",
                self.source_descriptor.bridge_execution_hash,
            )
        expected = source_bridge_configuration_hash(
            self.source_descriptor, self.credit_registry
        )
        if self.configuration_hash and self.configuration_hash != expected:
            raise ValueError("source Bridge configuration hash is wrong")
        object.__setattr__(self, "configuration_hash", expected)
        if (type(self.credit_registry) is not BridgeCreditRegistryV2
                or type(self.source_descriptor) is not SourceBridgeDescriptor
                or self.credit_registry.source_descriptor
                    is not self.source_descriptor
                or self.source_descriptor.settlement_chain_id
                    != self.domain_registry.router.settlement_chain_context_id
                or self.source_descriptor.settlement_chain_id
                    != self.source_descriptor.source_chain_id
                or self.source_descriptor.source_chain_id
                    != self.source_chain_id
                or self.source_descriptor.source_bridge != self.address
                or self.source_descriptor.role != BRIDGE_ROLE_SOURCE_ONLY
                or self.frozen_bridge != self.address
                or self.source_descriptor.bridge_credit_registry
                    != self.credit_registry.address
                or type(self.terminal_verifier) is not TerminalSignalVerifier
                or self.terminal_verifier.router
                    is not self.credit_registry.domain_registry.router
                or self.terminal_verifier.support_registry
                    is not self.credit_registry.domain_registry
                or self.terminal_verifier.address
                    != self.source_descriptor.source_terminal_verifier
                or self.terminal_verifier.runtime_hash
                    != self.source_descriptor
                        .source_terminal_verifier_runtime_hash
                or self.terminal_verifier.configuration_hash
                    != self.source_descriptor
                        .source_terminal_verifier_configuration_hash
                or self.runtime_hash
                    != self.source_descriptor.bridge_facade_runtime_hash
                or self.source_descriptor.source_domain_id
                    != self.source_domain_id
                or self.source_descriptor.bridge_execution_hash
                    != self.frozen_bridge_execution_hash
                or type(self.source_chain_id) is not int
                or not 0 < self.source_chain_id <= UINT64_MAX
                or not self.source_domain_id
                or not 0 < self.source_registration_epoch <= UINT64_MAX
                or self.source_registration_epoch
                    != self.credit_registry.source_registration_epoch
                or not self.frozen_bridge_execution_hash
                or type(self.native_environment)
                    is not SourceNativeExecutionEnvironmentV2
                or self.native_environment.chain_id != self.source_chain_id
                or type(self.quota_manager)
                    is not FrozenNativeQuotaManagerV2
                or self.quota_manager.address
                    != self.source_descriptor.native_quota_manager
                or self.quota_manager.runtime_hash
                    != self.source_descriptor.native_quota_manager_runtime_hash
                or self.quota_manager.quota_period
                    != self.source_descriptor.native_quota_period
                or self.quota_manager.eth_quota_cap
                    != self.source_descriptor.native_eth_quota
                or self.quota_manager.eth_quota_cap == 0
                or type(self.deployment_factory)
                    is not ImmutableV2BridgeFactory
                or not self.deployment_factory.source_bundle_exact(
                    self.source_descriptor,
                    self.credit_registry,
                    self.quota_manager,
                    self.terminal_verifier,
                    self,
                    require_live_bundle=False,
                )
                or self.v2_active
                or self.activation_surplus is not None
                or self.paused
                or self.entered
                or self.next_message_id != 0
                or type(self.balance) is not int or self.balance < 0
                or self._credits or self._refunds or self._lp_pulls
                or self._total_live_liability != 0
                or self.credit_registry.authorizations
                or self.quota_manager.snapshot() != (
                    0,
                    self.source_descriptor.native_eth_quota,
                    self.source_descriptor.native_eth_quota,
                )
                or not self.quota_manager._bind_bridge_once(self)
                or not self.native_environment._bind_bridge_once(self)
                or not self.credit_registry._bind_source_bridge_once(self)):
            raise ValueError("source Bridge authority graph is invalid")

    def __setattr__(self, name: str, value: object) -> None:
        if name in {
            "credit_registry", "address", "runtime_hash",
            "frozen_bridge",
            "source_chain_id", "source_domain_id",
            "source_registration_epoch",
            "frozen_bridge_execution_hash",
            "source_descriptor",
            "terminal_verifier",
            "deployment_factory", "deployment_receipt",
            "native_environment",
            "quota_manager",
            "configuration_hash", "v2_active", "activation_surplus", "paused",
        } and name in self.__dict__:
            raise AttributeError(f"source Bridge {name} is immutable")
        object.__setattr__(self, name, value)

    @property
    def domain_registry(self) -> BridgeDomainRegistry:
        return self.credit_registry.domain_registry

    def activate(
        self, authorization: ProfileIngressAuthorization,
        registration: SettlementRegistration, *,
        router: ActiveSettlementRouter, caller: str,
    ) -> bool:
        """Permissionlessly consume the exact inactive bundle once."""

        if (not caller or self.v2_active or self.paused or self.entered
                or type(router) is not ActiveSettlementRouter
                or router is not self.domain_registry.router
                or type(registration) is not SettlementRegistration
                or router.registrations.get(
                    registration.settlement.protocol_version
                ) is not registration
                or type(authorization) is not ProfileIngressAuthorization
                or authorization.kind is not ForceKind.BRIDGE_CREDIT
                or registration.ingress_authorizations_by_address.get(
                    authorization.adapter_address
                ) is not authorization
                or authorization.source_descriptor_id
                    != self.source_descriptor.descriptor_id
                or authorization.source_bridge_address != self.address
                or authorization.source_registry_address
                    != self.credit_registry.address
                or authorization.source_bridge_runtime_hash
                    != self.runtime_hash
                or authorization.source_bridge_configuration_hash
                    != self.configuration_hash
                or authorization.source_registry_runtime_hash
                    != self.credit_registry.runtime_hash
                or authorization.source_registry_configuration_hash
                    != self.credit_registry.configuration_hash
                or authorization.source_registry_domain_registrar
                    != self.source_descriptor.source_domain_registrar
                or authorization.source_registration_epoch
                    != self.source_descriptor.source_registration_epoch
                or authorization.support_registry_address
                    != self.source_descriptor.support_registry_address
                or authorization.support_registry_runtime_hash
                    != self.source_descriptor.support_registry_runtime_hash
                or authorization.support_registry_configuration_hash
                    != self.source_descriptor
                        .support_registry_configuration_hash
                or authorization.source_terminal_verifier
                    != self.terminal_verifier.address
                or self.next_message_id != 0
                or type(self.balance) is not int or self.balance < 0
                or self._credits or self._refunds or self._lp_pulls
                or self._total_live_liability != 0
                or self.credit_registry.authorizations
                or self.quota_manager.snapshot() != (
                    0,
                    self.source_descriptor.native_eth_quota,
                    self.source_descriptor.native_eth_quota,
                )
                or not self.deployment_factory.source_bundle_exact(
                    self.source_descriptor,
                    self.credit_registry,
                    self.quota_manager,
                    self.terminal_verifier,
                    self,
                    require_live_bundle=True,
                )):
            return False
        object.__setattr__(self, "activation_surplus", self.balance)
        object.__setattr__(self, "v2_active", True)
        return True

    def set_paused(
        self, paused: bool, *, caller: str, chain_id: int,
    ) -> bool:
        """Apply the deployment-pinned source pauser on the source chain."""

        if (type(paused) is not bool
                or caller
                    != self.source_descriptor.deployment_descriptor.pauser
                or chain_id != self.source_chain_id
                or not self.v2_active or self.entered):
            return False
        object.__setattr__(self, "paused", paused)
        return True

    def _transaction_snapshot(self) -> dict[str, object]:
        snapshot = copy.deepcopy({
            key: value for key, value in self.__dict__.items()
            if key not in {
                "credit_registry", "source_descriptor", "terminal_verifier",
                "deployment_factory", "deployment_receipt",
                "native_environment", "quota_manager", "fault_point",
            }
        })
        snapshot["quota_snapshot"] = self.quota_manager.snapshot()
        return snapshot

    def _restore_transaction_snapshot(
        self, snapshot: dict[str, object], *, capability: object,
    ) -> None:
        if capability is not _SOURCE_BRIDGE_ROLLBACK_CAPABILITY:
            raise ValueError("source Bridge rollback capability is wrong")
        immutable = {
            "credit_registry": self.credit_registry,
            "source_descriptor": self.source_descriptor,
            "terminal_verifier": self.terminal_verifier,
            "deployment_factory": self.deployment_factory,
            "deployment_receipt": self.deployment_receipt,
            "native_environment": self.native_environment,
            "quota_manager": self.quota_manager,
        }
        fault_point = self.fault_point
        quota_snapshot = snapshot["quota_snapshot"]
        self.__dict__.clear()
        self.__dict__.update({
            key: value for key, value in snapshot.items()
            if key != "quota_snapshot"
        })
        for key, value in immutable.items():
            object.__setattr__(self, key, value)
        if self.quota_manager.snapshot() != quota_snapshot:
            self.quota_manager.restore(
                quota_snapshot,
                bridge=self,
                frame=self.native_environment._active_frame,
                capability=_NATIVE_QUOTA_ROLLBACK_CAPABILITY,
            )
        object.__setattr__(self, "fault_point", fault_point)

    @property
    def credits(self) -> MappingProxyType:
        return MappingProxyType(copy.deepcopy(self._credits))

    @property
    def refunds(self) -> MappingProxyType:
        return MappingProxyType(dict(self._refunds))

    @property
    def liquidity_claims(self) -> MappingProxyType:
        return MappingProxyType(dict(self._lp_pulls))

    @property
    def total_live_liability(self) -> int:
        return self._total_live_liability

    def credit_liability_v2(
        self, calldata: bytes, *, gas: int,
    ) -> bytes | None:
        if (type(calldata) is not bytes or len(calldata) != 36
                or calldata[:4] != CREDIT_LIABILITY_SELECTOR
                or gas != SOURCE_READ_GAS
                or getattr(self, "credit_liability_call_fault", False)):
            return None
        credit_word = calldata[4:]
        matches = tuple(
            credit for credit_id, credit in self._credits.items()
            if _model_fixed_bytes32(credit_id) == credit_word
        )
        if len(matches) != 1:
            return None
        override = getattr(self, "credit_liability_return_override", None)
        return (
            encode_credit_liability_v2(matches[0], self.total_live_liability)
            if override is None else override
        )

    def decode_credit_liability_v2(
        self, credit_id: str, returndata: bytes | None,
    ) -> tuple[SourceCredit, int] | None:
        credit = self._credits.get(credit_id)
        if (credit is None or type(returndata) is not bytes
                or len(returndata) != 288
                or returndata != encode_credit_liability_v2(
                    credit, self.total_live_liability
                )):
            return None
        return copy.deepcopy(credit), self.total_live_liability

    @property
    def ether_quota(self) -> int:
        assert type(self.quota_manager) is FrozenNativeQuotaManagerV2
        assert type(self.native_environment) is SourceNativeExecutionEnvironmentV2
        return self.quota_manager.available_quota(
            self.native_environment.block_timestamp,
        )


    def support_final_clock(self, timestamp: int) -> Clock:
        confirmed = tuple(
            entry.confirmed_at_block
            for entry in self.domain_registry.entries.values()
            if entry.confirmed_at_block is not None
        )
        if not confirmed:
            raise ValueError("source Bridge has no confirmed support")
        return Clock(max(confirmed) + SUPPORT_FINALITY_BLOCKS, timestamp)

    def credit_id_for(
        self,
        envelope: BridgeAdmissionEnvelope,
        clock: Clock,
        *,
        caller: str | None = None,
    ) -> str:
        raw_message = bridge_message_calldata(envelope)
        normalized = replace(
            raw_message,
            message_id=self.next_message_id,
            sender=raw_message.sender if caller is None else caller,
            source_chain_id=self.source_chain_id,
        )
        normalized_envelope = replace(envelope, message=normalized)
        preimage = bridge_message_preimage(normalized_envelope)
        msg_hash = bridge_message_hash(preimage)
        support_entry = self.domain_registry.latest_final_entry(
            preimage.destination_chain_id, clock
        )
        if (support_entry is None
                or not preimage.sender
                or preimage.sender == self.address
                or preimage.sender
                    == support_entry.manifest.destination_bridge
                or support_entry.source_chain_id != self.source_chain_id
                or support_entry.source_registration_epoch
                    != self.source_registration_epoch):
            raise ValueError("Bridge Message has no current final destination")
        return BridgeAdapter.credit_id(
            self.source_chain_id,
            self.source_domain_id,
            self.source_registration_epoch,
            self.frozen_bridge,
            support_entry.manifest.destination_domain_id,
            msg_hash,
            normalized_envelope.liquidity_fee,
        )

    def send_message(
        self,
        envelope: BridgeAdmissionEnvelope,
        *,
        caller: str,
        msg_value: int,
        clock: Clock,
        enqueue_by: int,
    ) -> SourceSendReceipt:
        """The direct IBridge selector; it always creates DIRECT credit."""

        if caller in self.source_descriptor.v1_official_vaults:
            raise ValueError("V1 Vault caller is outside the V2 DIRECT launch")
        return self._send_message(
            envelope,
            effective_caller=caller,
            msg_value=msg_value,
            clock=clock,
            enqueue_by=enqueue_by,
        )

    def _send_message(
        self,
        envelope: BridgeAdmissionEnvelope,
        *,
        effective_caller: str,
        msg_value: int,
        clock: Clock,
        enqueue_by: int,
    ) -> SourceSendReceipt:
        if self.entered:
            raise RuntimeError("source Bridge is non-reentrant")
        try:
            raw_message = bridge_message_calldata(envelope)
        except (AttributeError, ValueError) as exc:
            raise ValueError("source Bridge message decode reverted") from exc
        normalized_preimage = replace(
            raw_message,
            message_id=self.next_message_id,
            sender=effective_caller,
            source_chain_id=self.source_chain_id,
        )
        normalized_envelope = replace(
            envelope,
            message=normalized_preimage,
            refund_address=effective_caller,
        )
        bridge_message_preimage(normalized_envelope)
        msg_hash = bridge_message_hash(normalized_preimage)
        support_entry = self.domain_registry.latest_final_entry(
            normalized_preimage.destination_chain_id, clock
        )
        destination_domain_id = (
            "" if support_entry is None
            else support_entry.manifest.destination_domain_id
        )
        destination_bridge = (
            None if support_entry is None
            else support_entry.manifest.destination_bridge
        )
        expected_credit_id = BridgeAdapter.credit_id(
            self.source_chain_id,
            self.source_domain_id,
            self.source_registration_epoch,
            self.frozen_bridge,
            destination_domain_id,
            msg_hash,
            normalized_envelope.liquidity_fee,
        )
        credit_id = expected_credit_id
        if (not self.v2_active
                or self.paused
                or not normalized_preimage.source_owner
                or not 0 < self.source_registration_epoch <= UINT64_MAX
                or not self.source_domain_id or not msg_hash
                or not self.frozen_bridge_execution_hash
                or not effective_caller
                or normalized_preimage.sender == self.address
                or destination_bridge is None
                or normalized_preimage.sender == destination_bridge
                or normalized_preimage.to in (
                    () if support_entry is None
                    else support_entry.manifest
                        .destination_bridge_descriptor
                        .privileged_target_denyset
                )
                or support_entry.source_chain_id != self.source_chain_id
                or support_entry.source_registration_epoch
                    != self.source_registration_epoch
                or support_entry.manifest.destination_chain_id
                    != normalized_preimage.destination_chain_id
                or type(clock) is not Clock
                or not 0 < clock.block_number <= UINT64_MAX
                or type(enqueue_by) is not int
                or not 0 <= enqueue_by <= UINT64_MAX
                or enqueue_by != checked_u64_add(
                    clock.timestamp,
                    MAX_BRIDGE_ENQUEUE_DELAY,
                    "Bridge enqueue deadline",
                )
                or support_entry is None
                or normalized_preimage.value < 0
                or normalized_preimage.fee < 0
                or normalized_envelope.liquidity_fee <= 0
                or type(msg_value) is not int
                or isinstance(msg_value, bool)
                or msg_value != (
                    normalized_preimage.value + normalized_preimage.fee
                    + normalized_envelope.liquidity_fee
                )):
            raise ValueError("source Bridge payable send reverted")
        authorization = CreditAuthorization(
            src_chain_id=self.source_chain_id,
            source_domain_id=self.source_domain_id,
            src_epoch=self.source_registration_epoch,
            src_bridge=self.frozen_bridge,
            destination_domain_id=destination_domain_id,
            destination_bridge=destination_bridge,
            bridge_execution_hash=self.frozen_bridge_execution_hash,
            emitted_at_block=clock.block_number,
            escrow_id=bridge_escrow_id(credit_id),
            msg_hash=msg_hash,
            calldata_hash=normalized_preimage.data_hash,
            calldata_length=normalized_preimage.data_length,
            enqueue_by=enqueue_by,
            sender=normalized_preimage.sender,
            owner=normalized_preimage.source_owner,
            destination_owner=normalized_preimage.destination_owner,
            value=normalized_preimage.value,
            fee=normalized_preimage.fee,
            refund_mode="DIRECT",
            refund_vault="",
            liquidity_fee=normalized_envelope.liquidity_fee,
            protocol_version=support_entry.protocol_version,
            destination_chain_id=support_entry.manifest.destination_chain_id,
            release_manifest_hash=support_entry.manifest.commitment,
            execution_profile_hash=(
                support_entry.manifest.execution_profile_hash
            ),
        )
        registry_before = self.credit_registry._authorization_snapshot()
        bridge_before = self._transaction_snapshot()
        self.entered = True
        try:
            if not self.credit_registry._authorize_from_source_bridge(
                    credit_id, authorization, source_bridge=self):
                raise ValueError("source authorization registry rejected")
            if self.fault_point == "after_registry_write":
                raise RuntimeError(
                    "injected source Bridge fault: after_registry_write"
                )
            self._credits[credit_id] = SourceCredit(
                normalized_preimage.value,
                normalized_preimage.fee,
                "NEW",
                liquidity_fee=normalized_envelope.liquidity_fee,
            )
            self.balance += msg_value
            self._total_live_liability = seat_checked_add(
                self.total_live_liability,
                msg_value,
                "source live liability",
            )
            self.next_message_id = checked_u64_add(
                self.next_message_id, 1, "shared Bridge message id"
            )
            if self.fault_point == "after_liability_write":
                raise RuntimeError(
                    "injected source Bridge fault: after_liability_write"
                )
            return SourceSendReceipt(
                credit_id, msg_hash, normalized_envelope
            )
        except BaseException:
            self.credit_registry._restore_authorization_snapshot(
                registry_before,
                source_bridge=self,
                capability=_SOURCE_BRIDGE_ROLLBACK_CAPABILITY,
            )
            self._restore_transaction_snapshot(
                bridge_before,
                capability=_SOURCE_BRIDGE_ROLLBACK_CAPABILITY,
            )
            raise
        finally:
            self.entered = False

    def _mark_queued_from_adapter(
        self,
        credit_id: str,
        queue_index: int,
        *,
        adapter: object,
    ) -> bool:
        credit = self._credits.get(credit_id)
        authorization = self.credit_registry.authorizations.get(credit_id)
        if (type(adapter) is not BridgeAdapter
                or adapter.source_bridge is not self
                or adapter.credit_registry is not self.credit_registry
                or not adapter.destination_sealed
                or adapter.router._ingress_binding(adapter) is None
                or authorization is None
                or authorization.destination_domain_id
                    != adapter.destination_domain_id
                or credit is None or credit.status != "NEW"
                or queue_index < 0):
            return False
        credit.status = "QUEUED"
        credit.queue_index = queue_index
        return True

    def cancel(self, credit_id: str, *, now: int) -> bool:
        if self.entered:
            return False
        self.entered = True
        try:
            credit = self._credits.get(credit_id)
            authorization = self.credit_registry.authorizations.get(credit_id)
            if (credit is None or credit.status != "NEW"
                    or authorization is None
                    or now <= authorization.enqueue_by):
                return False
            credit.status = "CANCELLED"
            credit.liability_class = "USER_PULL"
            credit.pull_beneficiary = authorization.owner
            credit.pull_amount = credit.value + credit.fee + credit.liquidity_fee
            self._refunds[authorization.owner] = seat_checked_add(
                self._refunds.get(authorization.owner, 0),
                credit.value + credit.fee + credit.liquidity_fee,
                "source cancellation refund",
            )
            return True
        finally:
            self.entered = False

    def finalize_done(self, credit_id: str, *, proof: TerminalProof) -> bool:
        if self.entered:
            return False
        self.entered = True
        try:
            credit = self._credits.get(credit_id)
            authorization = self.credit_registry.authorizations.get(credit_id)
            if (credit is None or credit.status != "QUEUED"
                    or authorization is None
                    or proof.settlement_amount != credit.value + credit.fee
                    or proof.settlement_amount <= 0
                    or not proof.ticket_id or not proof.l1_recipient
                    or not self.terminal_verifier.verify(
                        proof=proof, credit_id=credit_id, terminal="DONE",
                        destination_domain_id=(
                            authorization.destination_domain_id
                        ),
                        destination_bridge=authorization.destination_bridge)):
                return False
            credit.status = "DELIVERED"
            credit.liability_class = "LP_PULL"
            amount = credit.value + credit.fee + credit.liquidity_fee
            credit.pull_beneficiary = proof.l1_recipient
            credit.pull_amount = amount
            if amount:
                self._lp_pulls[proof.l1_recipient] = seat_checked_add(
                    self._lp_pulls.get(proof.l1_recipient, 0),
                    amount,
                    "source LP settlement pull",
                )
            return True
        finally:
            self.entered = False

    def recall_failed(self, credit_id: str, *, proof: TerminalProof) -> bool:
        if self.entered:
            return False
        self.entered = True
        try:
            credit = self._credits.get(credit_id)
            authorization = self.credit_registry.authorizations.get(credit_id)
            if (credit is None or credit.status != "QUEUED"
                    or authorization is None
                    or not self.terminal_verifier.verify(
                        proof=proof, credit_id=credit_id, terminal="FAILED",
                        destination_domain_id=(
                            authorization.destination_domain_id
                        ),
                        destination_bridge=authorization.destination_bridge)):
                return False
            credit.status = "RECALLED"
            credit.liability_class = "USER_PULL"
            credit.pull_beneficiary = authorization.owner
            credit.pull_amount = credit.value + credit.fee + credit.liquidity_fee
            self._refunds[authorization.owner] = seat_checked_add(
                self._refunds.get(authorization.owner, 0),
                credit.value + credit.fee + credit.liquidity_fee,
                "source terminal refund",
            )
            return True
        finally:
            self.entered = False




    def _consume_source_quota(
        self, debit: int, frame: SourceNativeTransactionFrameV2
    ) -> bool:
        return self.quota_manager._consume_from_bridge(
            debit, bridge=self, frame=frame,
            capability=_NATIVE_QUOTA_CONSUME_CAPABILITY,
            lane=NATIVE_QUOTA_LANE_V2,
        )




    def _withdraw_refund_from_environment(
        self,
        *,
        recipient: str,
        frame: SourceNativeTransactionFrameV2,
    ) -> int:
        """Consume only the exact transaction caller's refund under CEI."""

        environment = self.native_environment
        if (self.entered or not recipient
                or type(environment) is not SourceNativeExecutionEnvironmentV2
                or frame is not environment._active_frame
                or frame.environment is not environment
                or frame.operation != "WITHDRAW_REFUND"):
            return 0
        bridge_snapshot = self._transaction_snapshot()
        environment_snapshot = environment._transaction_snapshot()
        self.entered = True
        try:
            amount = self._refunds.get(frame.caller, 0)
            if (amount == 0 or amount > self.balance
                    or amount > self.total_live_liability):
                return 0
            self._refunds.pop(frame.caller, None)
            self._total_live_liability = self.total_live_liability - amount
            self.balance -= amount
            try:
                transferred = environment._transfer_native(
                    self, recipient, amount, frame=frame
                )
            except BaseException:
                transferred = False
            if not transferred:
                self._restore_transaction_snapshot(
                    bridge_snapshot,
                    capability=_SOURCE_BRIDGE_ROLLBACK_CAPABILITY,
                )
                environment._restore_transaction_snapshot(environment_snapshot)
                return 0
            return amount
        finally:
            self.entered = False

    def withdraw_refund(self, caller: str, recipient: str | None = None) -> int:
        """Unpausable refund; `caller` is the modeled transaction sender."""

        environment = self.native_environment
        recipient = caller if recipient is None else recipient
        if type(environment) is not SourceNativeExecutionEnvironmentV2:
            return 0
        return environment.withdraw_bridge_refund(
            self, caller=caller, recipient=recipient
        )

    def _withdraw_lp_claim_from_environment(
        self,
        *,
        recipient: str,
        frame: SourceNativeTransactionFrameV2,
    ) -> int:
        environment = self.native_environment
        if (self.entered or not recipient
                or type(environment) is not SourceNativeExecutionEnvironmentV2
                or frame is not environment._active_frame
                or frame.environment is not environment
                or frame.operation != "WITHDRAW_LP_CLAIM"):
            return 0
        bridge_snapshot = self._transaction_snapshot()
        environment_snapshot = environment._transaction_snapshot()
        self.entered = True
        try:
            amount = self._lp_pulls.get(frame.caller, 0)
            if (amount == 0 or amount > self.balance
                    or amount > self.total_live_liability):
                return 0
            self._lp_pulls.pop(frame.caller, None)
            self._total_live_liability -= amount
            self.balance -= amount
            try:
                transferred = environment._transfer_native(
                    self, recipient, amount, frame=frame
                )
            except BaseException:
                transferred = False
            if not transferred:
                self._restore_transaction_snapshot(
                    bridge_snapshot,
                    capability=_SOURCE_BRIDGE_ROLLBACK_CAPABILITY,
                )
                environment._restore_transaction_snapshot(environment_snapshot)
                return 0
            return amount
        finally:
            self.entered = False

    def withdraw_liquidity_claim(
        self, caller: str, recipient: str | None = None
    ) -> int:
        environment = self.native_environment
        recipient = caller if recipient is None else recipient
        if type(environment) is not SourceNativeExecutionEnvironmentV2:
            return 0
        return environment.withdraw_bridge_liquidity_claim(
            self, caller=caller, recipient=recipient
        )


@dataclass
class Kind0IngressAdapter:
    router: ActiveSettlementRouter
    address: str = "kind0-adapter"
    queue_address: str = ""
    runtime_hash: str = KIND0_INGRESS_RUNTIME_HASH
    configuration_hash: str = KIND0_INGRESS_CONFIGURATION_HASH
    refunds: dict[str, int] = field(default_factory=dict)
    balance: int = 0
    entered: bool = field(default=False, compare=False)

    def __post_init__(self) -> None:
        if not self.queue_address:
            object.__setattr__(
                self, "queue_address", self.router.forced_queue_address
            )

    def __setattr__(self, name: str, value: object) -> None:
        if name in {
            "router", "address", "queue_address", "runtime_hash",
            "configuration_hash",
        } and name in self.__dict__:
            raise AttributeError(f"kind-0 adapter {name} is immutable")
        object.__setattr__(self, name, value)

    def enqueue(
        self, clock: Clock, envelope: Message, *, caller: str, deposit: int
    ) -> str:
        registration = self.router.registrations.get(self.router.active_version)
        if (type(self.router) is not ActiveSettlementRouter
                or registration is None
                or self.router._ingress_binding(self) is None
                or self.queue_address != self.router.forced_queue_address
                or not caller or caller != envelope.sender
                or envelope.kind is not ForceKind.USER_TX
                or envelope.l2_chain_id
                    != registration.release_manifest.destination_chain_id
                or type(deposit) is not int or isinstance(deposit, bool)
                or deposit <= 0 or envelope.prepaid != deposit
                or deposit != self.router.required_ingress_deposit(
                    envelope, self
                )
                or not self.router._valid_ingress_static(
                    envelope, clock=clock, deposit=deposit
                )):
            raise ValueError("kind-0 payable ingress precheck reverted")
        if self.entered:
            raise RuntimeError("kind-0 adapter is non-reentrant")
        self.entered = True
        try:
            status, stamp = self.router.sync_ingress(
                clock=clock, caller_adapter=self
            )
            if stamp is None:
                if status == "SYNCED":
                    self.balance += deposit
                    self.refunds[caller] = self.refunds.get(caller, 0) + deposit
                    return "SYNCED_REFUNDED"
                raise ValueError(
                    f"kind-0 payable ingress sync reverted: {status}"
                )
            return self.router.append_from_adapter(
                envelope,
                clock=clock,
                stamp=stamp,
                deposit=deposit,
                caller_adapter=self,
            )
        finally:
            self.entered = False

    def withdraw_refund(self, caller: str) -> int:
        if self.entered:
            raise RuntimeError("kind-0 adapter is non-reentrant")
        self.entered = True
        try:
            amount = self.refunds.pop(caller, 0)
            if amount > self.balance:
                self.refunds[caller] = amount
                return 0
            self.balance -= amount
            return amount
        finally:
            self.entered = False


@dataclass
class BridgeAdapter:
    router: ActiveSettlementRouter
    credit_registry: BridgeCreditRegistryV2
    source_bridge: SourceBridgeV2
    address: str = "bridge-inbox-adapter"
    queue_address: str = ""
    runtime_hash: str = BRIDGE_INGRESS_RUNTIME_HASH
    records: dict[str, BridgeRecord] = field(default_factory=dict)
    refunds: dict[str, int] = field(default_factory=dict)
    balance: int = 0
    entered: bool = field(default=False, compare=False)
    fault_point: str | None = field(default=None, compare=False)
    _destination_domain_id: str = field(
        default="", init=False, compare=False, repr=False
    )
    _component_configuration_hash: str = field(
        default="", init=False, compare=False, repr=False
    )

    def __post_init__(self) -> None:
        if (type(self.router) is not ActiveSettlementRouter
                or type(self.credit_registry) is not BridgeCreditRegistryV2
                or type(self.source_bridge) is not SourceBridgeV2
                or self.source_bridge.credit_registry is not self.credit_registry
                or self.credit_registry.source_bridge is not self.source_bridge
                or not self.address
                or self.source_bridge.address
                    != self.source_bridge.frozen_bridge
                or self.credit_registry.runtime_hash
                    != BRIDGE_CREDIT_REGISTRY_RUNTIME_HASH
                or self.credit_registry.configuration_hash
                    != bridge_credit_registry_configuration_hash(
                        address=self.credit_registry.address,
                        runtime_hash=self.credit_registry.runtime_hash,
                        domain_registrar=self.credit_registry.domain_registrar,
                        frozen_bridge=self.source_bridge.address,
                        support_registry_address=(
                            self.credit_registry.domain_registry.address
                        ),
                        support_registry_runtime_hash=(
                            self.credit_registry.domain_registry.runtime_hash
                        ),
                        support_registry_configuration_hash=(
                            self.credit_registry.domain_registry.configuration_hash
                        ),
                        source_chain_id=self.source_bridge.source_chain_id,
                        source_domain_id=self.source_bridge.source_domain_id,
                        source_registration_epoch=(
                            self.source_bridge.source_registration_epoch
                        ),
                        frozen_bridge_execution_hash=(
                            self.source_bridge.frozen_bridge_execution_hash
                        ),
                        source_descriptor_id=(
                            self.source_bridge.source_descriptor.descriptor_id
                        ),
                    )
                or self.source_bridge.configuration_hash
                    != source_bridge_configuration_hash(
                        self.source_bridge.source_descriptor,
                        self.credit_registry,
                    )):
            raise ValueError("Bridge adapter authority graph is invalid")
        if not self.queue_address:
            object.__setattr__(
                self, "queue_address", self.router.forced_queue_address
            )
        object.__setattr__(
            self,
            "_component_configuration_hash",
            bridge_ingress_component_configuration_hash(
                router_address=self.router.address,
                router_runtime_hash=self.router.runtime_hash,
                router_configuration_hash=self.router.configuration_hash,
                queue_address=self.queue_address,
                queue_runtime_hash=self.router.forced_queue.runtime_hash,
                queue_configuration_hash=self.router.forced_queue.config_hash,
                source_registry_address=self.credit_registry.address,
                source_registry_runtime_hash=self.credit_registry.runtime_hash,
                source_registry_configuration_hash=(
                    self.credit_registry.configuration_hash
                ),
                source_bridge_address=self.source_bridge.address,
                source_bridge_runtime_hash=self.source_bridge.runtime_hash,
                source_bridge_configuration_hash_=(
                    self.source_bridge.configuration_hash
                ),
                seal_authority=self.router.version_manager,
            ),
        )

    def __setattr__(self, name: str, value: object) -> None:
        if name in {
            "router", "credit_registry", "source_bridge", "address",
            "queue_address", "runtime_hash", "_destination_domain_id",
            "_component_configuration_hash",
        } and name in self.__dict__:
            raise AttributeError(f"bridge adapter {name} is immutable")
        object.__setattr__(self, name, value)

    @property
    def destination_domain_id(self) -> str:
        return self._destination_domain_id

    @property
    def destination_sealed(self) -> bool:
        return bool(self._destination_domain_id)

    @property
    def configuration_hash(self) -> str:
        return self._component_configuration_hash

    def expected_component_configuration_hash(self) -> str:
        return bridge_ingress_component_configuration_hash(
            router_address=self.router.address,
            router_runtime_hash=self.router.runtime_hash,
            router_configuration_hash=self.router.configuration_hash,
            queue_address=self.queue_address,
            queue_runtime_hash=self.router.forced_queue.runtime_hash,
            queue_configuration_hash=self.router.forced_queue.config_hash,
            source_registry_address=self.credit_registry.address,
            source_registry_runtime_hash=self.credit_registry.runtime_hash,
            source_registry_configuration_hash=(
                self.credit_registry.configuration_hash
            ),
            source_bridge_address=self.source_bridge.address,
            source_bridge_runtime_hash=self.source_bridge.runtime_hash,
            source_bridge_configuration_hash_=(
                self.source_bridge.configuration_hash
            ),
            seal_authority=self.router.version_manager,
        )

    def _seal_destination_from_profile(
        self,
        *,
        authorization: ProfileIngressAuthorization,
        registration: SettlementRegistration,
        router: ActiveSettlementRouter,
        protocol_version: int,
    ) -> bool:
        """One-shot seal reached only from an exact historical release."""

        if (self.destination_sealed
                or router is not self.router
                or type(authorization) is not ProfileIngressAuthorization
                or authorization.kind is not ForceKind.BRIDGE_CREDIT
                or registration.ingress_authorizations_by_id.get(
                    authorization.authorization_id
                ) != authorization
                or router.registrations.get(protocol_version)
                    is not registration
                or router._profile_deployments_by_version.get(
                    protocol_version, {}
                ).get(authorization.authorization_id) is not self
                or authorization.adapter_address != self.address
                or authorization.configuration_hash
                    != self.configuration_hash
                or authorization.destination_domain_id == ""):
            return False
        object.__setattr__(
            self,
            "_destination_domain_id",
            authorization.destination_domain_id,
        )
        return True

    @staticmethod
    def credit_id(src_chain_id: int, source_domain_id: str, src_epoch: int,
                  src_bridge: str, destination_domain_id: str,
                  msg_hash: str, liquidity_fee: int) -> str:
        return keccak256(b"".join((
            b"slot-chain-bridge-credit-id-v6",
            _model_uint(src_chain_id, 8, "credit source chain id"),
            _model_fixed_bytes32(source_domain_id),
            _model_uint(src_epoch, 8, "credit source epoch"),
            _model_address20(src_bridge),
            _model_fixed_bytes32(destination_domain_id),
            _model_fixed_bytes32(msg_hash),
            _model_uint(liquidity_fee, 8, "credit liquidity fee"),
        ))).hex()

    @staticmethod
    def _durable_descriptor(
        envelope: BridgeAdmissionEnvelope,
        credit_id: str,
        authorization: CreditAuthorization,
        credit: SourceCredit,
        refund_address: str,
    ) -> BridgeQueueDescriptorV11:
        preimage = bridge_message_preimage(envelope)
        descriptor = BridgeQueueDescriptorV11(
            envelope.enqueued_at,
            envelope.accounted_gas,
            preimage.data_length,
            authorization.msg_hash,
            envelope.prepaid,
            preimage.sender,
            preimage.fee,
            preimage.source_chain_id,
            preimage.source_owner,
            preimage.destination_chain_id,
            preimage.destination_owner,
            preimage.value,
            preimage.data_hash,
            authorization.source_domain_id,
            authorization.src_epoch,
            authorization.src_bridge,
            authorization.bridge_execution_hash,
            authorization.emitted_at_block,
            authorization.destination_domain_id,
            authorization.enqueue_by,
            "DIRECT",
            refund_address,
            "",
            "",
            escrow_id=authorization.escrow_id,
            bridge_liquidity_fee=envelope.liquidity_fee,
            due_at=envelope.due_at,
        )
        if (descriptor.credit_id != credit_id
                or authorization.escrow_id != bridge_escrow_id(credit_id)
                or descriptor.msg_hash != authorization.msg_hash
                or descriptor.sender != authorization.sender
                or descriptor.bridge_src_owner != authorization.owner
                or descriptor.bridge_dest_owner
                    != authorization.destination_owner
                or descriptor.bridge_value != credit.value
                or descriptor.bridge_fee != credit.fee
                or descriptor.bridge_liquidity_fee != credit.liquidity_fee
                or authorization.liquidity_fee != credit.liquidity_fee
                or authorization.refund_mode != "DIRECT"
                or authorization.refund_vault
                or not descriptor.structurally_valid()):
            raise ValueError("Bridge durable queue descriptor is not exact")
        return descriptor

    def enqueue(self, clock_: Clock, *,
                envelope: BridgeAdmissionEnvelope,
                caller: str, deposit: int) -> str:
        source_bridge = self.source_bridge
        credit_registry = self.credit_registry
        destination_domain_id = self.destination_domain_id
        active_registration = self.router.registrations.get(
            self.router.active_version
        )
        active_authorization = (
            None if active_registration is None
            else active_registration.ingress_authorizations_by_address.get(
                self.address
            )
        )
        active_deployment = (
            None if type(active_authorization)
                is not ProfileIngressAuthorization
            else self.router._profile_deployments_by_version.get(
                self.router.active_version, {}
            ).get(active_authorization.authorization_id)
        )
        try:
            preimage = bridge_message_preimage(envelope)
            msg_hash = bridge_message_hash(preimage)
        except (AttributeError, ValueError) as exc:
            raise ValueError("Bridge payable ingress precheck reverted") from exc
        credit_id = self.credit_id(
            source_bridge.source_chain_id,
            source_bridge.source_domain_id,
            source_bridge.source_registration_epoch,
            source_bridge.frozen_bridge,
            destination_domain_id, msg_hash, envelope.liquidity_fee)
        existing = self.records.get(credit_id)
        if existing is not None:
            if deposit == 0:
                return f"QUEUED:{existing.index}"
            raise ValueError("funded duplicate Bridge ingress reverted")
        source_read_calldata = _model_fixed_bytes32(credit_id)
        source_authorization = None
        source_credit = None
        observed_total_live_liability = -1
        source_reads_valid = (
            exact_component_config_staticcall(
                credit_registry,
                expected_runtime_hash=(
                    active_authorization.source_registry_runtime_hash
                    if type(active_authorization)
                        is ProfileIngressAuthorization else ""
                ),
                expected_configuration_hash=(
                    active_authorization.source_registry_configuration_hash
                    if type(active_authorization)
                        is ProfileIngressAuthorization else ""
                ),
            )
            and exact_component_config_staticcall(
                source_bridge,
                expected_runtime_hash=(
                    active_authorization.source_bridge_runtime_hash
                    if type(active_authorization)
                        is ProfileIngressAuthorization else ""
                ),
                expected_configuration_hash=(
                    active_authorization.source_bridge_configuration_hash
                    if type(active_authorization)
                        is ProfileIngressAuthorization else ""
                ),
            )
        )
        if source_reads_valid:
            source_authorization = (
                credit_registry.decode_credit_authorization_v2(
                    credit_id,
                    credit_registry.credit_authorization_v2(
                        CREDIT_AUTHORIZATION_SELECTOR + source_read_calldata,
                        gas=SOURCE_READ_GAS,
                    ),
                )
            )
            decoded_liability = source_bridge.decode_credit_liability_v2(
                credit_id,
                source_bridge.credit_liability_v2(
                    CREDIT_LIABILITY_SELECTOR + source_read_calldata,
                    gas=SOURCE_READ_GAS,
                ),
            )
            if decoded_liability is not None:
                source_credit, observed_total_live_liability = (
                    decoded_liability
                )
        support_entry = (
            None if source_authorization is None
            else credit_registry.domain_registry.final_entry(
                source_authorization.source_domain_id,
                source_authorization.bridge_execution_hash,
                source_authorization.destination_domain_id,
                clock_,
            )
        )
        queue_descriptor = None
        if (source_authorization is not None and source_credit is not None):
            try:
                queue_descriptor = self._durable_descriptor(
                    envelope, credit_id, source_authorization, source_credit,
                    caller,
                )
            except ValueError:
                queue_descriptor = None
        if (type(self.router) is not ActiveSettlementRouter
                or self.router._ingress_binding(self) is None
                or type(active_authorization)
                    is not ProfileIngressAuthorization
                or active_authorization.kind is not ForceKind.BRIDGE_CREDIT
                or active_deployment is not self
                or not source_reads_valid
                or active_authorization.source_descriptor_id
                    != source_bridge.source_descriptor.descriptor_id
                or active_authorization.destination_domain_id
                    != destination_domain_id
                or not self.destination_sealed
                or self.queue_address != self.router.forced_queue_address
                or not caller or deposit <= 0
                or envelope.prepaid != deposit
                or deposit != self.router.required_ingress_deposit(
                    envelope, self
                )
                or envelope.kind is not ForceKind.BRIDGE_CREDIT
                or envelope.payload_hash != msg_hash
                or envelope.sender != preimage.sender
                or source_credit is None
                or source_authorization is None
                or queue_descriptor is None
                or source_credit.status != "NEW"
                or source_authorization.src_chain_id
                    != source_bridge.source_chain_id
                or source_authorization.source_domain_id
                    != source_bridge.source_domain_id
                or source_authorization.src_epoch
                    != source_bridge.source_registration_epoch
                or source_authorization.src_bridge
                    != source_bridge.frozen_bridge
                or source_authorization.destination_domain_id
                    != destination_domain_id
                or source_authorization.msg_hash != msg_hash
                or source_authorization.sender != preimage.sender
                or source_authorization.owner != preimage.source_owner
                or source_authorization.destination_owner
                    != preimage.destination_owner
                or source_authorization.calldata_hash
                    != preimage.data_hash
                or source_authorization.calldata_length
                    != preimage.data_length
                or not 0 < source_authorization.emitted_at_block <= UINT64_MAX
                or source_authorization.emitted_at_block > clock_.block_number
                or support_entry is None
                or source_authorization.destination_bridge
                    != support_entry.manifest.destination_bridge
                or source_credit.value != source_authorization.value
                or source_credit.fee != source_authorization.fee
                or source_credit.liquidity_fee
                    != source_authorization.liquidity_fee
                or observed_total_live_liability
                    < (source_credit.value + source_credit.fee
                       + source_credit.liquidity_fee)
                or source_bridge.balance
                    < observed_total_live_liability
                or clock_.timestamp > source_authorization.enqueue_by
                or not self.router._valid_ingress_static(
                    queue_descriptor, clock=clock_, deposit=deposit
                )):
            raise ValueError("Bridge payable ingress precheck reverted")
        if self.entered:
            raise RuntimeError("bridge adapter is non-reentrant")
        self.entered = True
        try:
            status, stamp = self.router.sync_ingress(
                clock=clock_, caller_adapter=self
            )
            if stamp is None:
                if status != "SYNCED":
                    raise ValueError(
                        f"Bridge payable ingress sync reverted: {status}"
                    )
                # The nonpayable sync persists while the entire caller fee
                # remains local and independently claimable.
                self.balance += deposit
                self.refunds[caller] = self.refunds.get(caller, 0) + deposit
                return "SYNCED_REFUNDED"
            queue_snapshot = (
                self.router.forced_queue._transaction_snapshot()
            )
            source_snapshot = source_bridge._transaction_snapshot()
            registry_snapshot = credit_registry._authorization_snapshot()
            adapter_snapshot = copy.deepcopy({
                key: value for key, value in self.__dict__.items()
                if key not in {"router", "credit_registry", "source_bridge"}
            })
            index = self.router.forced_queue.count
            try:
                result = self.router.append_from_adapter(
                    queue_descriptor,
                    clock=clock_,
                    stamp=stamp,
                    deposit=deposit,
                    caller_adapter=self,
                )
                if result != f"QUEUED:{index}":
                    raise AssertionError("validated bridge append index changed")
                if not source_bridge._mark_queued_from_adapter(
                        credit_id, index, adapter=self):
                    raise ValueError("source Bridge queue mark rejected")
                if self.fault_point == "after_source_mark":
                    raise RuntimeError(
                        "injected bridge adapter fault: after_source_mark"
                    )
                self.records[credit_id] = BridgeRecord(
                    queue_descriptor, index, caller, deposit)
                if self.fault_point == "after_adapter_record":
                    raise RuntimeError(
                        "injected bridge adapter fault: after_adapter_record"
                    )
                return result
            except BaseException:
                self.router.forced_queue._restore_transaction_snapshot(
                    queue_snapshot
                )
                source_bridge._restore_transaction_snapshot(
                    source_snapshot,
                    capability=_SOURCE_BRIDGE_ROLLBACK_CAPABILITY,
                )
                credit_registry._restore_authorization_snapshot(
                    registry_snapshot,
                    source_bridge=source_bridge,
                    capability=_SOURCE_BRIDGE_ROLLBACK_CAPABILITY,
                )
                router = self.router
                exact_credit_registry = self.credit_registry
                exact_source_bridge = self.source_bridge
                self.__dict__.clear()
                self.__dict__.update(adapter_snapshot)
                object.__setattr__(self, "router", router)
                object.__setattr__(
                    self, "credit_registry", exact_credit_registry
                )
                object.__setattr__(
                    self, "source_bridge", exact_source_bridge
                )
                raise
        finally:
            self.entered = False

    def withdraw_refund(self, caller: str) -> int:
        if self.entered:
            raise RuntimeError("bridge adapter is non-reentrant")
        self.entered = True
        try:
            amount = self.refunds.pop(caller, 0)
            if amount > self.balance:
                self.refunds[caller] = amount
                return 0
            self.balance -= amount
            return amount
        finally:
            self.entered = False


@dataclass(frozen=True)
class InboxPin:
    result_hash: str
    process_by: int
    liquidity_fee: int = 0
    queue_index: int = 0
    src_chain_id: int = 0
    source_domain_id: str = ""
    src_epoch: int = 0
    src_bridge: str = ""
    destination_domain_id: str = ""
    msg_hash: str = ""
    source_context_hash: str = ""
    value: int = 0
    execution_fee: int = 0

    @property
    def packed_terms(self) -> int:
        return (
            self.process_by
            | self.execution_fee << 64
            | self.liquidity_fee << 128
        )


def inbox_pin_from_descriptor(
    descriptor: BridgeQueueDescriptorV11,
    *, queue_index: int, result_hash: str, process_by: int,
    route: "InboxRoute",
) -> InboxPin:
    credit_id = descriptor.credit_id
    source = SourceContextV2(
        route.protocol_version,
        ForceKind.BRIDGE_CREDIT.value,
        credit_id,
        descriptor.msg_hash,
        descriptor.source_domain_id,
        descriptor.source_registration_epoch,
        descriptor.source_bridge,
        descriptor.bridge_execution_hash,
        descriptor.emitted_at_block,
        queue_index,
        descriptor.enqueue_by,
        descriptor.refund_mode,
        descriptor.refund_vault,
        descriptor.refund_capsule_hash,
        descriptor.escrow_id,
    )
    return InboxPin(
        result_hash,
        process_by,
        descriptor.bridge_liquidity_fee,
        queue_index,
        descriptor.bridge_src_chain_id,
        descriptor.source_domain_id,
        descriptor.source_registration_epoch,
        descriptor.source_bridge,
        descriptor.destination_domain_id,
        descriptor.msg_hash,
        source.context_hash,
        descriptor.bridge_value,
        descriptor.bridge_fee,
    )


@dataclass
class InboxCreditStoreV2:
    authorized_inbox_apply: str
    destination_bridge: str
    destination_domain_id: str
    address: str = ""
    terminal_registrar: str = "terminal-domain-registrar"
    pins: dict[str, InboxPin] = field(default_factory=dict)
    pinned_count: int = 0
    runtime_codehash: str = ""
    batch_return_data: bytes = INBOX_BATCH_OK_V2_WORD
    batch_writes_enabled: bool = True
    _inbox_apply_authority: object | None = field(
        default=None, init=False, compare=False, repr=False
    )

    def __post_init__(self) -> None:
        if not self.address:
            suffix = self.destination_domain_id.split(":")[-1]
            self.address = f"inbox-store:{suffix}"
        if not self.runtime_codehash:
            suffix = self.destination_domain_id.split(":")[-1]
            self.runtime_codehash = f"codehash:store:{suffix}"
        if (type(self.pinned_count) is not int
                or not 0 <= self.pinned_count <= UINT64_MAX
                or self.pinned_count != len(self.pins)):
            raise ValueError("Inbox Store pinned counter is invalid")

    def __deepcopy__(
        self, memo: dict[int, object]
    ) -> "InboxCreditStoreV2":
        duplicate = object.__new__(type(self))
        memo[id(self)] = duplicate
        for key, value in self.__dict__.items():
            object.__setattr__(
                duplicate,
                key,
                value if key == "_inbox_apply_authority"
                else copy.deepcopy(value, memo),
            )
        return duplicate

    def _bind_inbox_apply(self, router: "InboxApplyRouterV2") -> bool:
        if (type(router) is not InboxApplyRouterV2
                or router.address != self.authorized_inbox_apply):
            return False
        existing = self._inbox_apply_authority
        if existing is not None:
            return existing is router
        object.__setattr__(self, "_inbox_apply_authority", router)
        return True

    @property
    def route_config_hash(self) -> str:
        return (f"config:{self.authorized_inbox_apply}:"
                f"{self.destination_bridge}:"
                f"{self.terminal_registrar}:{self.destination_domain_id}")

    @property
    def component_config_hash(self) -> str:
        return (f"component-config:{self.authorized_inbox_apply}:"
                f"{self.destination_bridge}:"
                f"{self.terminal_registrar}")

    def read(self, credit_id: str, *, caller: str,
             destination_domain_id: str) -> InboxPin | None:
        if (caller != self.destination_bridge
                or destination_domain_id != self.destination_domain_id):
            return None
        return self.pins.get(credit_id)

    def verify_inbox_credit(
        self, *, src_chain_id: int, source_domain_id: str, src_epoch: int,
        src_bridge: str, destination_domain_id: str, msg_hash: str,
        caller: str,
    ) -> bytes | None:
        if (caller != self.destination_bridge
                or destination_domain_id != self.destination_domain_id):
            return None
        matches = tuple(
            (credit_id, pin) for credit_id, pin in self.pins.items()
            if (pin.src_chain_id == src_chain_id
                and pin.source_domain_id == source_domain_id
                and pin.src_epoch == src_epoch
                and pin.src_bridge == src_bridge
                and pin.destination_domain_id == destination_domain_id
                and pin.msg_hash == msg_hash)
        )
        if len(matches) != 1:
            return None
        credit_id, pin = matches[0]
        encoded = b"".join((
            _model_fixed_bytes32(credit_id),
            _model_uint(pin.process_by, 32, "Inbox processBy"),
            _model_uint(pin.value, 32, "Inbox value"),
            _model_uint(pin.execution_fee, 32, "Inbox execution fee"),
            _model_uint(pin.liquidity_fee, 32, "Inbox liquidity fee"),
            _model_fixed_bytes32(pin.source_context_hash),
        ))
        if len(encoded) != 192:
            raise AssertionError("verifyInboxCredit return width drifted")
        return encoded

    def liquidity_quote_v2(self, credit_id: str) -> bytes | None:
        pin = self.pins.get(credit_id)
        if pin is None or not pin.result_hash:
            return None
        encoded = b"".join((
            _model_fixed_bytes32(pin.result_hash),
            _model_uint(pin.value, 32, "liquidity quote value"),
            _model_uint(pin.execution_fee, 32,
                        "liquidity quote execution fee"),
            _model_uint(pin.liquidity_fee, 32,
                        "liquidity quote liquidity fee"),
            _model_uint(pin.process_by, 32, "liquidity quote processBy"),
        ))
        if len(encoded) != 160:
            raise AssertionError("liquidityQuoteV2 return width drifted")
        return encoded

    def _pin_batch_from_router(
        self,
        rows: tuple[tuple[str, InboxPin], ...],
        *,
        process_by: int,
        router: "InboxApplyRouterV2",
    ) -> bytes | None:
        route = router.routes.get(self.destination_domain_id)
        if (router is not self._inbox_apply_authority
                or type(router) is not InboxApplyRouterV2
                or route is None or route.store is not self):
            return None
        for credit_id, pin in rows:
            existing = self.pins.get(credit_id)
            if (not credit_id or type(pin) is not InboxPin
                    or not pin.result_hash or pin.process_by != process_by
                    or pin.destination_domain_id != self.destination_domain_id
                    or not 0 <= pin.queue_index <= UINT64_MAX
                    or not 0 < pin.src_chain_id <= UINT64_MAX
                    or not 0 < pin.src_epoch <= UINT64_MAX
                    or not pin.src_bridge or not pin.msg_hash
                    or not pin.source_context_hash
                    or not 0 <= pin.value <= SEAT_UINT256_MAX
                    or not 0 <= pin.execution_fee <= UINT64_MAX
                    or not 0 < pin.liquidity_fee <= UINT64_MAX
                    or (existing is not None and existing != pin)):
                return None
        if self.batch_writes_enabled:
            for credit_id, pin in rows:
                if credit_id not in self.pins:
                    self.pins[credit_id] = pin
                    self.pinned_count = checked_u64_add(
                        self.pinned_count, 1, "Inbox Store pinned count"
                    )
        return self.batch_return_data


@dataclass(frozen=True)
class InboxRoute:
    store: InboxCreditStoreV2
    destination_bridge: str
    store_codehash: str
    store_config_hash: str
    protocol_version: int = 1
    release_manifest_hash: bytes = bytes(32)
    execution_profile_hash: str = ""
    destination_chain_id: int = 0


def inbox_kind1_result(index: int, descriptor: BridgeQueueDescriptorV11) -> str:
    if (type(index) is not int or index < 0
            or type(descriptor) is not BridgeQueueDescriptorV11
            or not descriptor.structurally_valid()):
        raise ValueError("InboxApply result has no durable queue descriptor")
    return keccak256(b"".join((
        b"slot-chain-bridge-credit-result-v11",
        _model_uint(index, 8, "Inbox queue index"),
        _model_fixed_bytes32(descriptor.credit_id),
        _model_fixed_bytes32(descriptor.msg_hash),
        _model_uint(descriptor.bridge_src_chain_id, 32,
                    "Inbox source chain id"),
        _model_fixed_bytes32(descriptor.source_domain_id),
        _model_uint(descriptor.source_registration_epoch, 8,
                    "Inbox source epoch"),
        _model_address20(descriptor.source_bridge),
        _model_fixed_bytes32(descriptor.bridge_execution_hash),
        _model_uint(descriptor.emitted_at_block, 8,
                    "Inbox emission block"),
        _model_fixed_bytes32(descriptor.destination_domain_id),
        _model_uint(descriptor.bridge_dest_chain_id, 32,
                    "Inbox destination chain id"),
        _model_uint(descriptor.enqueue_by, 8, "Inbox enqueue deadline"),
        _model_address20(descriptor.sender),
        _model_address20(descriptor.bridge_src_owner),
        _model_address20(descriptor.bridge_dest_owner),
        _model_uint(descriptor.bridge_value, 32, "Inbox value"),
        _model_uint(descriptor.bridge_fee, 8, "Inbox execution fee"),
        _model_uint(descriptor.bridge_liquidity_fee, 8,
                    "Inbox liquidity fee"),
        _model_fixed_bytes32(descriptor.bridge_data_hash),
        _model_uint(1 if descriptor.refund_mode == "DIRECT" else 0, 1,
                    "Inbox refund mode"),
        _model_address20(descriptor.refund_vault, zero_if_empty=True),
        _model_fixed_bytes32(
            descriptor.refund_capsule_hash, zero_if_empty=True
        ),
        _model_fixed_bytes32(descriptor.escrow_id),
    ))).hex()


_INBOX_EXECUTION_AUTHORITY_CAPABILITY = object()
_INBOX_EXECUTION_FRAME_CAPABILITY = object()
_INBOX_BATCH_CAPABILITY = object()
_INBOX_RECEIPT_CAPABILITY = object()
_VERIFIED_CANDIDATE_PROOF_CAPABILITY = object()
_INBOX_APPLY_ROWS_CAPABILITY = object()
_OBSERVED_RELEASE_DEPLOYMENT_CAPABILITY = object()
ANCHOR_SYSTEM_TX_POSITION = 0
INBOX_SYSTEM_TX_POSITION = 1

InboxCalldataDescriptor = Optional[BridgeQueueDescriptorV11]
InboxRowV2 = tuple[int, int, int, str, InboxCalldataDescriptor]


def inbox_descriptor_commitment(
    descriptors: tuple[Message | BridgeQueueDescriptorV11, ...],
) -> str:
    return hashlib.sha256(
        b"TAIKO_INBOX_DESCRIPTOR_RANGE_V11\x00"
        + b"".join(durable_queue_leaf_hash(row).encode() for row in descriptors)
    ).hexdigest()


def inbox_apply_calldata(
    force_start: int, rows: tuple[InboxRowV2, ...],
) -> bytes:
    if (type(force_start) is not int or not 0 <= force_start <= UINT64_MAX
            or type(rows) is not tuple or len(rows) > MAX_FORCE_MESSAGES):
        raise ValueError("InboxApply calldata shape is invalid")
    elements: list[bytes] = []
    for row in rows:
        if type(row) is not tuple or len(row) != 5:
            raise ValueError("Inbox row is not the exact five-field ABI")
        index, disposition, tx_index, result_hash, descriptor = row
        if (type(index) is not int or not 0 <= index <= UINT64_MAX
                or type(disposition) is not int or disposition not in range(6)
                or type(tx_index) is not int
                or not 0 <= tx_index <= UINT32_MAX):
            raise ValueError("Inbox row fixed words are noncanonical")
        if disposition == 5 and type(descriptor) is BridgeQueueDescriptorV11:
            descriptor_bytes = descriptor.canonical_bytes
        elif disposition != 5 and descriptor is None:
            descriptor_bytes = b""
        else:
            raise ValueError("Inbox calldata descriptor has wrong type")
        padded = ((len(descriptor_bytes) + 31) // 32) * 32
        element = b"".join((
            _model_uint(index, 32, "Inbox row queue index"),
            _model_uint(disposition, 32, "Inbox row disposition"),
            _model_uint(tx_index, 32, "Inbox row tx index"),
            _model_fixed_bytes32(result_hash, zero_if_empty=True),
            _model_uint(5 * 32, 32, "Inbox row descriptor offset"),
            _model_uint(len(descriptor_bytes), 32,
                        "Inbox row descriptor length"),
            descriptor_bytes + bytes(padded - len(descriptor_bytes)),
        ))
        elements.append(element)
    cursor = len(rows) * 32
    offsets: list[bytes] = []
    for element in elements:
        offsets.append(_model_uint(cursor, 32, "Inbox row offset"))
        cursor += len(element)
    encoded = b"".join((
        INBOX_APPLY_SELECTOR_BYTES,
        _model_uint(force_start, 32, "Inbox forceStart"),
        _model_uint(2 * 32, 32, "Inbox rows offset"),
        _model_uint(len(rows), 32, "Inbox row count"),
        *offsets,
        *elements,
    ))
    expected = 100 + 32 * len(rows) + sum(map(len, elements))
    if len(encoded) != expected:
        raise AssertionError("InboxApply calldata width drifted")
    return encoded


def inbox_system_calldata_hash(rows: tuple[InboxRowV2, ...]) -> str:
    force_start = rows[0][0] if rows else 0
    return keccak256(inbox_apply_calldata(force_start, rows)).hex()


@dataclass(frozen=True)
class IssuedInboxBatchRecord:
    nonce: int
    batch_object_id: int
    batch_digest: str
    execution_frame: tuple[int, int]


@dataclass(frozen=True)
class InboxTouchedSlotState:
    domain_id: str
    store: "InboxCreditStoreV2" = field(compare=False, repr=False)
    store_object_id: int
    destination_bridge: str
    store_codehash: str
    store_config_hash: str
    observed_runtime_codehash: str
    credit_id: str
    prior_pinned_count: int
    post_pinned_count: int
    prior_pin: "InboxPin | None"
    post_pin: "InboxPin | None"


def inbox_touched_slots_commitment(
    rows: tuple[InboxTouchedSlotState, ...],
) -> str:
    """Commit bounded L2 effects without exporting live Store objects to L1."""

    if (type(rows) is not tuple
            or any(type(row) is not InboxTouchedSlotState for row in rows)):
        raise ValueError("Inbox touched-slot journal is not canonical")
    projection = tuple(
        (
            row.domain_id,
            row.destination_bridge,
            row.store_codehash,
            row.store_config_hash,
            row.observed_runtime_codehash,
            row.credit_id,
            row.prior_pinned_count,
            row.post_pinned_count,
            row.prior_pin,
            row.post_pin,
        )
        for row in rows
    )
    return hashlib.sha256(
        b"TAIKO_INBOX_TOUCHED_SLOTS_V1\x00" + repr(projection).encode()
    ).hexdigest()


@dataclass(frozen=True)
class ReleaseDeploymentWitness:
    """Execution-verifier witness for independently observed L2 accounts."""

    manifest_commitment: bytes
    prestate_root: str
    observed_components: tuple["ReleaseComponentV2", ...]
    observed_bridge_descriptor: "DestinationBridgeDescriptorV2"
    store: "InboxCreditStoreV2" = field(compare=False, repr=False)
    endpoint_state: "EndpointActivationStateV2" = field(
        compare=False, repr=False
    )
    endpoint_prestate: tuple[object, ...]
    bridge_deployment: "BridgeDeploymentStateV2"
    pool_observation: tuple[str, str, str, int]


def release_deployment_observation_commitment(
    *,
    manifest_commitment: bytes,
    prestate_root: str,
    observed_components: tuple["ReleaseComponentV2", ...],
    observed_bridge_descriptor: "DestinationBridgeDescriptorV2",
    endpoint_prestate: tuple[object, ...],
    bridge_deployment: "BridgeDeploymentStateV2",
    pool_observation: tuple[str, str, str, int],
) -> str:
    """Commit every circuit-observed fresh immutable deployment fact."""

    if (type(manifest_commitment) is not bytes
            or len(manifest_commitment) != 32
            or not prestate_root
            or type(observed_components) is not tuple
            or type(observed_bridge_descriptor)
                is not DestinationBridgeDescriptorV2
            or type(endpoint_prestate) is not tuple
            or type(bridge_deployment) is not BridgeDeploymentStateV2
            or type(pool_observation) is not tuple
            or len(pool_observation) != 4
            or any(type(value) is not str or not value
                   for value in pool_observation[:3])
            or type(pool_observation[3]) is not int
            or not 0 <= pool_observation[3] <= SEAT_UINT256_MAX):
        raise ValueError("release deployment observation is incomplete")
    return hashlib.sha256(
        b"TAIKO_ACTUAL_RELEASE_DEPLOYMENT_OBSERVATION_V2\x00"
        + repr((
            manifest_commitment,
            prestate_root,
            observed_components,
            observed_bridge_descriptor,
            endpoint_prestate,
            bridge_deployment.observation_commitment,
            pool_observation,
        )).encode()
    ).hexdigest()


@dataclass(frozen=True, eq=False)
class ObservedReleaseDeployment:
    """Verifier observation of independently deployed L2 tx0 accounts."""

    authority: "InboxValidityExecutionAuthority" = field(
        compare=False, repr=False
    )
    transition_verifier: IMigrationTransitionVerifier = field(
        compare=False, repr=False
    )
    transition_verifier_descriptor: MigrationTransitionVerifierDescriptor
    transition_result_digest: str
    transition_result_seal: str
    manifest_commitment: bytes
    prestate_root: str
    observed_components: tuple["ReleaseComponentV2", ...]
    observed_bridge_descriptor: "DestinationBridgeDescriptorV2"
    store: "InboxCreditStoreV2" = field(compare=False, repr=False)
    store_object_id: int
    endpoint_state: "EndpointActivationStateV2" = field(
        compare=False, repr=False
    )
    endpoint_object_id: int
    endpoint_prestate: tuple[object, ...]
    bridge_deployment: "BridgeDeploymentStateV2"
    pool_observation: tuple[str, str, str, int]
    seal: str
    _capability: object = field(repr=False, compare=False)

    def __post_init__(self) -> None:
        if (self._capability is not _OBSERVED_RELEASE_DEPLOYMENT_CAPABILITY
                or type(self.authority)
                    is not InboxValidityExecutionAuthority
                or self.transition_verifier
                    is not self.authority.migration_transition_verifier
                or self.transition_verifier_descriptor
                    != self.transition_verifier.descriptor
                or not self.transition_verifier_descriptor.structurally_valid()
                or not self.transition_result_digest
                or not self.transition_result_seal
                or type(self.manifest_commitment) is not bytes
                or len(self.manifest_commitment) != 32
                or not self.prestate_root
                or len(self.observed_components) != 7
                or any(type(row) is not ReleaseComponentV2
                       for row in self.observed_components)
                or type(self.observed_bridge_descriptor)
                    is not DestinationBridgeDescriptorV2
                or type(self.store) is not InboxCreditStoreV2
                or self.store_object_id != id(self.store)
                or type(self.endpoint_state)
                    is not EndpointActivationStateV2
                or self.endpoint_object_id != id(self.endpoint_state)
                or self.endpoint_prestate
                    != endpoint_activation_projection(self.endpoint_state)
                or type(self.bridge_deployment)
                    is not BridgeDeploymentStateV2
                or type(self.pool_observation) is not tuple
                or len(self.pool_observation) != 4
                or any(type(value) is not str or not value
                       for value in self.pool_observation[:3])
                or type(self.pool_observation[3]) is not int
                or not 0 <= self.pool_observation[3]
                    <= SEAT_UINT256_MAX
                or not self.seal):
            raise ValueError("observed release deployment is not canonical")

    @property
    def digest(self) -> str:
        projection = (
            id(self.authority), id(self.transition_verifier),
            self.transition_verifier_descriptor,
            self.transition_result_digest,
            self.transition_result_seal,
            self.manifest_commitment,
            self.prestate_root, self.observed_components,
            self.observed_bridge_descriptor, self.store_object_id,
            self.endpoint_object_id, self.endpoint_prestate,
            self.bridge_deployment,
            self.pool_observation,
        )
        return hashlib.sha256(
            b"TAIKO_OBSERVED_RELEASE_DEPLOYMENT_V1\x00"
            + repr(projection).encode()
        ).hexdigest()

    @property
    def actual_observation_commitment(self) -> str:
        return release_deployment_observation_commitment(
            manifest_commitment=self.manifest_commitment,
            prestate_root=self.prestate_root,
            observed_components=self.observed_components,
            observed_bridge_descriptor=self.observed_bridge_descriptor,
            endpoint_prestate=self.endpoint_prestate,
            bridge_deployment=self.bridge_deployment,
            pool_observation=self.pool_observation,
        )


@dataclass(frozen=True)
class InboxRouteActivationDelta:
    """Bounded tx0 ReleaseAuthority/Registrar transition for one domain."""

    registrar: "TerminalDomainRegistrarV2" = field(compare=False, repr=False)
    registrar_object_id: int
    manifest: "ReleaseManifestV2"
    store: "InboxCreditStoreV2" = field(compare=False, repr=False)
    store_object_id: int
    endpoint_state: "EndpointActivationStateV2" = field(
        compare=False, repr=False
    )
    endpoint_prestate: tuple[object, ...]
    bridge_deployment: "BridgeDeploymentStateV2"
    route_preexisting: bool
    observed_deployment: ObservedReleaseDeployment

    def __post_init__(self) -> None:
        if (type(self.registrar) is not TerminalDomainRegistrarV2
                or self.registrar_object_id != id(self.registrar)
                or type(self.manifest) is not ReleaseManifestV2
                or not self.manifest.structurally_valid()
                or type(self.store) is not InboxCreditStoreV2
                or self.store_object_id != id(self.store)
                or type(self.endpoint_state) is not EndpointActivationStateV2
                or self.endpoint_prestate
                    != endpoint_activation_projection(self.endpoint_state)
                or type(self.bridge_deployment)
                    is not BridgeDeploymentStateV2
                or type(self.observed_deployment)
                    is not ObservedReleaseDeployment
                or self.observed_deployment.store is not self.store
                or self.observed_deployment.endpoint_state
                    is not self.endpoint_state
                or self.observed_deployment.bridge_deployment
                    != self.bridge_deployment):
            raise ValueError("Inbox route activation delta is not exact")

    @property
    def digest_projection(self) -> tuple[object, ...]:
        return (
            self.registrar_object_id,
            self.manifest.commitment,
            self.store_object_id,
            self.endpoint_prestate,
            self.bridge_deployment,
            self.route_preexisting,
            self.observed_deployment.digest,
            self.observed_deployment.seal,
        )

    @property
    def commitment(self) -> str:
        """Commit tx0 effects without exposing Registrar/Store identities."""

        projection = (
            self.manifest.commitment,
            self.manifest.protocol_version,
            self.manifest.destination_domain_id,
            self.manifest.destination_bridge,
            self.endpoint_prestate,
            self.bridge_deployment,
            self.route_preexisting,
            self.observed_deployment.digest,
            self.observed_deployment.seal,
        )
        return hashlib.sha256(
            b"TAIKO_INBOX_ROUTE_ACTIVATION_V1\x00"
            + repr(projection).encode()
        ).hexdigest()


@dataclass(frozen=True, eq=False)
class InboxExecutionReceipt:
    authority: "InboxValidityExecutionAuthority"
    candidate_digest: str
    base_canonical_hash: str
    protocol_version: int
    execution_profile_hash: str
    pre_cursor: int
    pre_last_applied_l2_block: int
    post_cursor: int
    post_last_applied_l2_block: int
    release_system_calldata_hashes: tuple[str, ...]
    inbox_system_calldata_hashes: tuple[str, ...]
    seal: str
    _capability: object = field(repr=False, compare=False)

    def __post_init__(self) -> None:
        if (self._capability is not _INBOX_RECEIPT_CAPABILITY
                or type(self.authority) is not InboxValidityExecutionAuthority
                or not self.candidate_digest or not self.base_canonical_hash
                or self.protocol_version <= 0
                or not self.execution_profile_hash
                or self.pre_cursor < 0
                or self.post_cursor < self.pre_cursor
                or self.post_last_applied_l2_block
                    < self.pre_last_applied_l2_block
                or type(self.release_system_calldata_hashes) is not tuple
                or type(self.inbox_system_calldata_hashes) is not tuple
                or len(self.release_system_calldata_hashes)
                    != len(self.inbox_system_calldata_hashes)
                or any(type(row) is not str
                       for row in self.release_system_calldata_hashes)
                or any(type(row) is not str or not row
                       for row in self.inbox_system_calldata_hashes)
                or not self.seal
        ):
            raise ValueError("Inbox execution receipt is not canonical")

    @property
    def digest(self) -> str:
        projection = (
            id(self.authority), self.candidate_digest,
            self.base_canonical_hash, self.protocol_version,
            self.execution_profile_hash, self.pre_cursor,
            self.pre_last_applied_l2_block,
            self.post_cursor, self.post_last_applied_l2_block,
            self.release_system_calldata_hashes,
            self.inbox_system_calldata_hashes,
        )
        return hashlib.sha256(
            b"TAIKO_INBOX_EXECUTION_RECEIPT_V1\x00"
            + repr(projection).encode()
        ).hexdigest()


def candidate_inbox_execution_digest(candidate: Candidate) -> str:
    if type(candidate) is not Candidate:
        raise ValueError("Inbox execution candidate has wrong type")
    projection = tuple(
        getattr(candidate, name)
        for name in Candidate.__dataclass_fields__
        if name != "inbox_execution_receipt"
    )
    return hashlib.sha256(
        b"TAIKO_INBOX_EXECUTION_CANDIDATE_V1\x00"
        + repr(projection).encode()
    ).hexdigest()


@dataclass(frozen=True, eq=False)
class VerifiedCandidateProof:
    verifier: "InboxValidityExecutionAuthority"
    candidate_digest: str
    base_canonical_hash: str
    protocol_version: int
    execution_profile_hash: str
    clock_block_number: int
    clock_timestamp: int
    purpose: str
    seal: str
    _capability: object = field(repr=False, compare=False)

    def __post_init__(self) -> None:
        if (self._capability is not _VERIFIED_CANDIDATE_PROOF_CAPABILITY
                or type(self.verifier) is not InboxValidityExecutionAuthority
                or not self.candidate_digest or not self.base_canonical_hash
                or self.protocol_version <= 0
                or not self.execution_profile_hash
                or self.clock_block_number < 0
                or self.clock_timestamp < 0
                or self.purpose not in {
                    "CANONICAL_CANDIDATE", "MIGRATION_ACTIVATION"
                }
                or not self.seal):
            raise ValueError("candidate proof output is not canonical")


def verified_candidate_proof_digest(output: VerifiedCandidateProof) -> str:
    return hashlib.sha256(repr((
        output.candidate_digest,
        output.base_canonical_hash,
        output.protocol_version,
        output.execution_profile_hash,
        output.clock_block_number,
        output.clock_timestamp,
        output.purpose,
    )).encode()).hexdigest()


@dataclass(frozen=True, eq=False)
class AuthenticatedInboxBatch:
    """Immutable proof/fork output consumed by the L2 system call once."""

    authority: "InboxValidityExecutionAuthority"
    inbox: "InboxApplyRouterV2"
    settlement_chain_id: int
    protocol_version: int
    execution_profile_hash: str
    base_canonical_hash: str
    context_id: str
    candidate_id: str
    block_index: int
    l2_block_number: int
    evm_timestamp: int
    anchor_number: int
    anchor_hash: str
    force_root: str
    force_cutoff: int
    force_start: int
    force_end: int
    descriptor_commitment: str
    system_calldata_hash: str
    system_tx_position: int
    nonce: int
    _capability: object = field(repr=False, compare=False)

    def __post_init__(self) -> None:
        if (self._capability is not _INBOX_BATCH_CAPABILITY
                or type(self.authority) is not InboxValidityExecutionAuthority
                or type(self.inbox) is not InboxApplyRouterV2
                or self.authority.protocol.inbox_apply_router is not self.inbox
                or not 0 < self.settlement_chain_id <= UINT64_MAX
                or self.protocol_version <= 0
                or not self.execution_profile_hash
                or not self.base_canonical_hash or not self.context_id
                or not self.candidate_id
                or not 0 <= self.block_index < MAX_BLOCKS_PER_CANDIDATE
                or self.l2_block_number < 0
                or not 0 <= self.evm_timestamp <= UINT64_MAX
                or self.anchor_number < 0 or not self.anchor_hash
                or not self.force_root
                or not 0 <= self.force_cutoff <= MAX_FORCE_QUEUE_ITEMS
                or not 0 <= self.force_start <= self.force_end
                or self.force_end - self.force_start > MAX_FORCE_MESSAGES
                or not self.descriptor_commitment
                or not self.system_calldata_hash
                or self.system_tx_position != INBOX_SYSTEM_TX_POSITION):
            raise ValueError("Inbox batch is not proof-authenticated")

    @property
    def digest(self) -> str:
        projection = (
            id(self.authority), id(self.inbox), self.settlement_chain_id,
            self.protocol_version, self.execution_profile_hash,
            self.base_canonical_hash, self.context_id, self.candidate_id,
            self.block_index, self.l2_block_number,
            self.evm_timestamp, self.anchor_number, self.anchor_hash,
            self.force_root, self.force_cutoff, self.force_start,
            self.force_end, self.descriptor_commitment,
            self.system_calldata_hash, self.system_tx_position, self.nonce,
        )
        return hashlib.sha256(
            b"TAIKO_AUTHENTICATED_INBOX_BATCH_V1\x00"
            + repr(projection).encode()
        ).hexdigest()


@dataclass(eq=False)
class InboxValidityExecutionAuthority:
    """Behavioral stand-in for the validity circuit and fork system sender."""

    protocol: Protocol
    _capability: object = field(repr=False)
    _seal_secret: object = field(init=False, repr=False, compare=False)
    _issued: dict[int, IssuedInboxBatchRecord] = field(
        default_factory=dict, init=False, repr=False
    )
    _consumed: set[int] = field(default_factory=set, init=False, repr=False)
    _next_nonce: int = field(default=1, init=False, repr=False)
    _execution_frame: tuple[int, int] | None = field(
        default=None, init=False, repr=False
    )
    _preparing_candidate_id: int | None = field(
        default=None, init=False, repr=False
    )
    _verifying_candidate_id: int | None = field(
        default=None, init=False, repr=False
    )
    _release_activation_frame: tuple[int, bytes, int, str] | None = field(
        default=None, init=False, repr=False
    )
    _observed_release_deployments: dict[
        bytes, ObservedReleaseDeployment
    ] = field(default_factory=dict, init=False, repr=False)

    def __post_init__(self) -> None:
        if (self._capability is not _INBOX_EXECUTION_AUTHORITY_CAPABILITY
                or type(self.protocol) is not Protocol):
            raise ValueError("Inbox execution authority is not canonical")
        object.__setattr__(self, "_seal_secret", object())

    def __setattr__(self, name: str, value: object) -> None:
        if name == "protocol" and name in self.__dict__:
            raise AttributeError(
                f"Inbox execution authority {name} is immutable"
            )
        object.__setattr__(self, name, value)

    @property
    def execution_profile(self) -> ExecutionProfile:
        history = self.protocol.versioned_history
        if (type(history) is not VersionedSettlementHistory
                or type(history.execution_profile) is not ExecutionProfile
                or not history.execution_profile.structurally_valid()
                or history.execution_profile.execution_profile_hash
                    != history.execution_profile_hash):
            raise ValueError("execution authority has no exact profile")
        return history.execution_profile

    @property
    def migration_transition_verifier(self) -> IMigrationTransitionVerifier:
        return self.execution_profile.migration_transition_verifier

    @property
    def migration_transition_verifier_descriptor(
        self,
    ) -> MigrationTransitionVerifierDescriptor:
        return self.execution_profile.migration_transition_verifier_descriptor

    def _opaque_seal(self, namespace: bytes, digest: str) -> str:
        return hashlib.sha256(
            namespace
            + id(self._seal_secret).to_bytes(32, "big")
            + digest.encode()
        ).hexdigest()

    def _valid_observed_release_deployment(
        self,
        observed: ObservedReleaseDeployment,
        manifest: "ReleaseManifestV2",
        *,
        expected_prestate_root: str | None = None,
    ) -> bool:
        prestate_root = (
            self.protocol.core.state_root
            if expected_prestate_root is None else expected_prestate_root
        )
        return (
            type(observed) is ObservedReleaseDeployment
            and observed.authority is self
            and observed.transition_verifier
                is self.migration_transition_verifier
            and observed.transition_verifier_descriptor
                == self.migration_transition_verifier_descriptor
            and self.migration_transition_verifier.valid_result_seal(
                observed.transition_result_digest,
                observed.transition_result_seal,
            )
            and observed.manifest_commitment == manifest.commitment
            and observed.prestate_root == prestate_root
            and observed.observed_components == manifest.components[3:]
            and observed.observed_bridge_descriptor
                == manifest.destination_bridge_descriptor
            and observed.pool_observation == (
                self.protocol.inbox_apply_router
                    ._terminal_registrar_authority
                    .liquidity_pool.address,
                self.protocol.inbox_apply_router
                    ._terminal_registrar_authority
                    .liquidity_pool.runtime_hash,
                self.protocol.inbox_apply_router
                    ._terminal_registrar_authority
                    .liquidity_pool.configuration_hash,
                self.protocol.inbox_apply_router
                    ._terminal_registrar_authority
                    .liquidity_pool.balance,
            )
            and manifest.destination_domain_id
                not in self.protocol.inbox_apply_router.routes
            and observed.endpoint_state.activatable
            and observed.bridge_deployment.authenticates(
                manifest, require_fresh=True,
            )
            and observed.seal == self._opaque_seal(
                b"TAIKO_OBSERVED_RELEASE_DEPLOYMENT_SEAL_V1\x00",
                observed.digest,
            )
            and self._observed_release_deployments.get(
                manifest.commitment
            ) is observed
        )

    @staticmethod
    def _rows_match_descriptors(
        rows: tuple[InboxRowV2, ...],
        descriptors: tuple[Message | BridgeQueueDescriptorV11, ...],
    ) -> bool:
        if len(rows) != len(descriptors):
            return False
        for row, queued in zip(rows, descriptors):
            if type(row) is not tuple or len(row) != 5:
                return False
            descriptor = row[4]
            if type(queued) is Message:
                if (queued.kind is not ForceKind.USER_TX
                        or descriptor is not None):
                    return False
            elif type(queued) is BridgeQueueDescriptorV11:
                if (type(descriptor) is not BridgeQueueDescriptorV11
                        or durable_queue_leaf_fields(descriptor)
                            != durable_queue_leaf_fields(queued)):
                    return False
            else:
                return False
        return True

    @staticmethod
    def _manifest_hash_matches(
        manifest: "ReleaseManifestV2", committed: object
    ) -> bool:
        return committed in {
            manifest.commitment,
            manifest.commitment.hex(),
            "0x" + manifest.commitment.hex(),
        }

    def _release_activation_delta(
        self, candidate: Candidate
    ) -> InboxRouteActivationDelta | None:
        """Resolve the one manifest-owned tx0 deployment for this block."""

        first = candidate.blocks[0]
        if not first.release_activation:
            return None
        protocol = self.protocol
        history = protocol.versioned_history
        router = getattr(history, "_router_authority", None)
        registrar = protocol.inbox_apply_router._terminal_registrar_authority
        registration = (
            router.registrations.get(first.release_protocol_version)
            if type(router) is ActiveSettlementRouter else None
        )
        if (type(registrar) is not TerminalDomainRegistrarV2
                or type(registration) is not SettlementRegistration):
            raise ValueError("release activation has no exact deployment graph")
        matches = tuple(
            manifest
            for manifest in registration.release_manifests_by_adapter.values()
            if manifest.protocol_version == first.release_protocol_version
            and self._manifest_hash_matches(
                manifest, first.release_manifest_hash
            )
        )
        if len(matches) != 1:
            raise ValueError("release activation manifest is not unique")
        return self._route_activation_delta_for_manifest(matches[0])

    def _route_activation_delta_for_manifest(
        self, manifest: "ReleaseManifestV2", *,
        expected_prestate_root: str | None = None,
    ) -> InboxRouteActivationDelta:
        if (type(manifest) is not ReleaseManifestV2
                or not manifest.structurally_valid()):
            raise ValueError("release route manifest is not canonical")
        protocol = self.protocol
        registrar = protocol.inbox_apply_router._terminal_registrar_authority
        if type(registrar) is not TerminalDomainRegistrarV2:
            raise ValueError("release route registrar is not exact")
        observed = self._observed_release_deployments.get(
            manifest.commitment
        )
        if (type(observed) is not ObservedReleaseDeployment
                or not self._valid_observed_release_deployment(
                    observed,
                    manifest,
                    expected_prestate_root=expected_prestate_root,
                )):
            raise ValueError("release deployment prestate was not observed")
        route = protocol.inbox_apply_router.routes.get(
            manifest.destination_domain_id
        )
        if route is None:
            store = observed.store
            endpoint = observed.endpoint_state
            preexisting = False
        else:
            if (route.destination_bridge != manifest.destination_bridge
                    or route.store_codehash
                        != manifest.components[4].runtime_hash
                    or route.store_config_hash
                        != route.store.route_config_hash):
                raise ValueError("release activation reuses a split route")
            if observed.store is not route.store:
                raise ValueError("observed release store identity is split")
            store = observed.store
            endpoint = observed.endpoint_state
            preexisting = True
        return InboxRouteActivationDelta(
            registrar,
            id(registrar),
            manifest,
            store,
            id(store),
            endpoint,
            endpoint_activation_projection(endpoint),
            observed.bridge_deployment,
            preexisting,
            observed,
        )

    @staticmethod
    def _activation_transaction_snapshot(
        delta: InboxRouteActivationDelta,
    ) -> dict[str, object]:
        registrar = delta.registrar
        return {
            "releases": dict(registrar.authority.releases),
            "release_manifests": dict(
                registrar.authority.release_manifests
            ),
            "registrations": dict(registrar.registrations),
            "bridge_identities": dict(registrar.bridge_identities),
            "bridge_activation_receipts": dict(
                registrar.bridge_activation_receipts
            ),
            "active_destination_bridge": registrar.active_destination_bridge,
            "retirement_queue_watermarks": dict(
                registrar.retirement_queue_watermarks
            ),
            "liquidity_pool": registrar.liquidity_pool._snapshot(),
            "bridge_deployment": copy.deepcopy(
                delta.bridge_deployment.__dict__
            ),
            "routes": dict(registrar.inbox_router.routes),
            "domains": dict(registrar.accumulator.domains),
            "terminalized_pinned_count": dict(
                registrar.accumulator.terminalized_pinned_count
            ),
            "endpoint": copy.deepcopy(delta.endpoint_state.__dict__),
            "store_writer": delta.store._inbox_apply_authority,
        }

    @staticmethod
    def _restore_activation_transaction(
        delta: InboxRouteActivationDelta,
        snapshot: dict[str, object],
    ) -> None:
        registrar = delta.registrar
        registrar.authority.releases = snapshot["releases"]
        registrar.authority.release_manifests = snapshot[
            "release_manifests"
        ]
        registrar.registrations = snapshot["registrations"]
        registrar.bridge_identities = snapshot["bridge_identities"]
        registrar.bridge_activation_receipts = snapshot[
            "bridge_activation_receipts"
        ]
        registrar.active_destination_bridge = snapshot[
            "active_destination_bridge"
        ]
        registrar.retirement_queue_watermarks = snapshot[
            "retirement_queue_watermarks"
        ]
        registrar.liquidity_pool._restore(snapshot["liquidity_pool"])
        delta.bridge_deployment.__dict__.clear()
        delta.bridge_deployment.__dict__.update(
            snapshot["bridge_deployment"]
        )
        registrar.inbox_router.routes = snapshot["routes"]
        registrar.accumulator.domains = snapshot["domains"]
        registrar.accumulator.terminalized_pinned_count = snapshot[
            "terminalized_pinned_count"
        ]
        delta.endpoint_state.__dict__.clear()
        delta.endpoint_state.__dict__.update(snapshot["endpoint"])
        object.__setattr__(
            delta.store, "_inbox_apply_authority", snapshot["store_writer"]
        )

    def _activation_prestate_exact(
        self, delta: InboxRouteActivationDelta, *,
        expected_prestate_root: str | None = None,
    ) -> bool:
        registrar = delta.registrar
        manifest = delta.manifest
        route = registrar.inbox_router.routes.get(
            manifest.destination_domain_id
        )
        return (
            registrar is self.protocol.inbox_apply_router
                ._terminal_registrar_authority
            and self._valid_observed_release_deployment(
                delta.observed_deployment,
                manifest,
                expected_prestate_root=expected_prestate_root,
            )
            and registrar.inbox_router is self.protocol.inbox_apply_router
            and delta.registrar_object_id == id(registrar)
            and delta.store_object_id == id(delta.store)
            and endpoint_activation_projection(delta.endpoint_state)
                == delta.endpoint_prestate
            and manifest.protocol_version
                not in registrar.registrations
            and (
                (
                    not delta.route_preexisting
                    and route is None
                    and manifest.destination_domain_id
                        not in registrar.accumulator.domains
                )
                or (
                    delta.route_preexisting
                    and route is not None
                    and route.store is delta.store
                    and route.destination_bridge
                        == manifest.destination_bridge
                    and registrar.accumulator.domains.get(
                        manifest.destination_domain_id
                    ) == manifest.destination_bridge
                )
            )
        )

    def _activate_release_delta(
        self, delta: InboxRouteActivationDelta, *,
        expected_prestate_root: str | None = None,
    ) -> bool:
        if not self._activation_prestate_exact(
            delta, expected_prestate_root=expected_prestate_root
        ):
            return False
        manifest = delta.manifest
        anchor = AnchorV4Model(
            manifest.anchor,
            manifest.anchor_runtime_hash,
            manifest.commitment,
        )
        if self._release_activation_frame is not None:
            return False
        self._release_activation_frame = (
            id(manifest), manifest.commitment,
            self.protocol.forced_queue.count,
            release_system_calldata_hash(
                manifest, self.protocol.forced_queue.count
            ),
        )
        try:
            return activate_release_transaction(
                delta.registrar.authority,
                delta.registrar,
                manifest=manifest,
                execution_authority=self,
                execution_capability=_RELEASE_SYSTEM_EXECUTION_CAPABILITY,
                anchor=anchor,
                store=delta.store,
                observed_l2_components=(
                    delta.observed_deployment.observed_components
                ),
                observed_bridge_descriptor=(
                    delta.observed_deployment.observed_bridge_descriptor
                ),
                endpoint_state=delta.endpoint_state,
                bridge_deployment=delta.bridge_deployment,
                retirement_queue_watermark=(
                    self.protocol.forced_queue.count
                ),
            )
        finally:
            self._release_activation_frame = None

    def _issue_verified_block(
        self,
        candidate: Candidate,
        rows: tuple[InboxRowV2, ...],
        clock: Clock,
        block_index: int,
        execution_capability: object,
    ) -> AuthenticatedInboxBatch:
        """Issue one block only inside the atomic candidate execution frame."""

        protocol = self.protocol
        history = protocol.versioned_history
        router = getattr(history, "_router_authority", None)
        if (protocol._inbox_execution_authority is not self
                or type(candidate) is not Candidate
                or type(clock) is not Clock
                or execution_capability is not _INBOX_EXECUTION_FRAME_CAPABILITY
                or self._execution_frame != (id(candidate), block_index)
                or not 0 <= block_index < candidate.count
                or type(history) is not VersionedSettlementHistory
                or type(router) is not ActiveSettlementRouter):
            raise ValueError("Inbox execution authority is split")
        block = candidate.blocks[block_index]
        queue = protocol.forced_queue
        header = protocol.header_oracle.header(block.anchor_number)
        descriptors = tuple(
            queue.descriptors[block.message_start:block.message_end]
        )
        descriptor_commitment = inbox_descriptor_commitment(descriptors)
        calldata_hash = inbox_system_calldata_hash(rows)
        anchor_force_exact = (
            (
                protocol.mode is Mode.NORMAL
                and block.force_root == header.force_root
                and block.force_cutoff == header.force_cutoff
            )
            or (
                protocol.mode is Mode.RECOVERY
                and protocol.recovery is not None
                and block.force_root == protocol.recovery.force_root
                and block.force_cutoff == protocol.recovery.force_cutoff
            )
        )
        if (block.message_start
                    != protocol.inbox_apply_router.next_queue_index
                or block.message_end != protocol._prefix_end(
                    block.message_start,
                    block.force_cutoff,
                    gas_budget=block.force_gas_budget,
                )
                or block.inbox_pre_cursor != block.message_start
                or block.inbox_post_cursor != block.message_end
                or not anchor_force_exact
                or block.message_end > block.force_cutoff
                or block.force_root != model_force_root(
                    queue.descriptors[:block.force_cutoff]
                )
                or not self._rows_match_descriptors(rows, descriptors)
                or block.inbox_descriptor_commitment
                    != descriptor_commitment
                or block.inbox_system_calldata_hash != calldata_hash
                or block.anchor_system_tx_position
                    != ANCHOR_SYSTEM_TX_POSITION
                or block.inbox_system_tx_position
                    != INBOX_SYSTEM_TX_POSITION):
            raise ValueError("Inbox batch is not a verified maximal prefix")
        if self._next_nonce > UINT64_MAX:
            raise ValueError("Inbox execution nonce exhausted")
        nonce = self._next_nonce
        self._next_nonce += 1
        batch = AuthenticatedInboxBatch(
            self,
            protocol.inbox_apply_router,
            router.settlement_chain_context_id,
            history.protocol_version,
            history.execution_profile_hash,
            candidate.base_canonical_hash,
            block.context_id,
            candidate.candidate_id,
            block_index,
            protocol.core.l2_block_number + block_index + 1,
            block.evm_timestamp,
            block.anchor_number,
            block.anchor_hash,
            block.force_root,
            block.force_cutoff,
            block.message_start,
            block.message_end,
            descriptor_commitment,
            calldata_hash,
            block.inbox_system_tx_position,
            nonce,
            _INBOX_BATCH_CAPABILITY,
        )
        self._issued[nonce] = IssuedInboxBatchRecord(
            nonce, id(batch), batch.digest, (id(candidate), block_index)
        )
        return batch

    def _execute_candidate_frame(
        self,
        candidate: Candidate,
        rows_by_block: tuple[tuple[InboxRowV2, ...], ...],
        clock: Clock,
        execution_capability: object,
    ) -> bool:
        """Verify and execute every block atomically in strict block order."""

        protocol = self.protocol
        if (protocol._inbox_execution_authority is not self
                or type(candidate) is not Candidate
                or type(rows_by_block) is not tuple
                or len(rows_by_block) != candidate.count
                or type(clock) is not Clock
                or execution_capability is not _INBOX_EXECUTION_FRAME_CAPABILITY
                or self._preparing_candidate_id != id(candidate)
                or self._execution_frame is not None):
            return False
        valid_candidate = (
            protocol._valid_normal(candidate, clock)
            if protocol.mode is Mode.NORMAL
            else protocol._valid_recovery(candidate, clock)
        )
        if not valid_candidate:
            return False
        inbox = protocol.inbox_apply_router
        touched: dict[
            tuple[int, str], tuple[InboxCreditStoreV2, InboxPin | None]
        ] = {}
        touched_counts: dict[int, tuple[InboxCreditStoreV2, int]] = {}
        for rows in rows_by_block:
            for row in rows:
                descriptor = row[4]
                if type(descriptor) is not BridgeQueueDescriptorV11:
                    continue
                route = inbox.routes.get(descriptor.destination_domain_id)
                if route is None:
                    continue
                key = (id(route.store), descriptor.credit_id)
                touched_counts.setdefault(
                    id(route.store), (route.store, route.store.pinned_count)
                )
                touched.setdefault(
                    key, (route.store, route.store.pins.get(descriptor.credit_id))
                )
        cursor_snapshot = inbox.next_queue_index
        last_block_snapshot = inbox.last_applied_l2_block
        issued_snapshot = dict(self._issued)
        consumed_snapshot = set(self._consumed)
        nonce_snapshot = self._next_nonce
        try:
            for block_index, rows in enumerate(rows_by_block):
                self._execution_frame = (id(candidate), block_index)
                batch = self._issue_verified_block(
                    candidate,
                    rows,
                    clock,
                    block_index,
                    _INBOX_EXECUTION_FRAME_CAPABILITY,
                )
                if not inbox.apply(batch, rows):
                    raise ValueError("InboxApply rejected a verified block")
            self._execution_frame = None
            if self._issued:
                raise AssertionError("executed Inbox capability remained live")
            return True
        except BaseException:
            for (_, credit_id), (store, prior) in touched.items():
                if prior is None:
                    store.pins.pop(credit_id, None)
                else:
                    store.pins[credit_id] = prior
            for store, prior_count in touched_counts.values():
                store.pinned_count = prior_count
            inbox.next_queue_index = cursor_snapshot
            inbox.last_applied_l2_block = last_block_snapshot
            self._issued = issued_snapshot
            self._consumed = consumed_snapshot
            self._next_nonce = nonce_snapshot
            self._execution_frame = None
            return False

    def prepare_candidate_execution(
        self,
        candidate: Candidate,
        rows_by_block: tuple[tuple[InboxRowV2, ...], ...],
        clock: Clock,
        verified_proof: VerifiedCandidateProof,
    ) -> Candidate:
        """Dry-run exact L2 system calldata and issue an immutable receipt."""

        protocol = self.protocol
        if (protocol._inbox_execution_authority is not self
                or type(candidate) is not Candidate
                or type(verified_proof) is not VerifiedCandidateProof
                or verified_proof.verifier is not self
                or verified_proof.seal != self._opaque_seal(
                    b"TAIKO_VERIFIED_CANDIDATE_SEAL_V1\x00",
                    verified_candidate_proof_digest(verified_proof),
                )
                or verified_proof.candidate_digest
                    != candidate_inbox_execution_digest(candidate)
                or verified_proof.base_canonical_hash
                    != protocol.canonical.base_hash
                or verified_proof.base_canonical_hash
                    != candidate.base_canonical_hash
                or type(protocol.versioned_history)
                    is not VersionedSettlementHistory
                or verified_proof.protocol_version
                    != protocol.versioned_history.protocol_version
                or verified_proof.execution_profile_hash
                    != protocol.versioned_history.execution_profile_hash
                or verified_proof.clock_block_number != clock.block_number
                or verified_proof.clock_timestamp != clock.timestamp
                or verified_proof.purpose != "CANONICAL_CANDIDATE"
                or candidate.inbox_execution_receipt is not None
                or self._preparing_candidate_id is not None
                or self._execution_frame is not None):
            raise ValueError("Inbox candidate cannot enter execution")
        inbox = protocol.inbox_apply_router
        activation = self._release_activation_delta(candidate)
        if ((candidate.blocks[0].release_activation)
                != (activation is not None)):
            raise ValueError("candidate release activation is incomplete")
        activation_snapshot = (
            self._activation_transaction_snapshot(activation)
            if activation is not None else None
        )
        touched: dict[
            tuple[str, str], tuple[InboxRoute, InboxPin | None]
        ] = {}
        touched_counts: dict[int, tuple[InboxCreditStoreV2, int]] = {}
        cursor_snapshot = inbox.next_queue_index
        last_block_snapshot = inbox.last_applied_l2_block
        issued_snapshot = dict(self._issued)
        consumed_snapshot = set(self._consumed)
        batch_nonce_snapshot = self._next_nonce
        self._preparing_candidate_id = id(candidate)
        try:
            # The release block executes Anchor/ReleaseAuthority/Registrar at
            # tx0.  Only its candidate-local route is visible to tx1.
            if (activation is not None
                    and not self._activate_release_delta(activation)):
                raise ValueError("candidate release tx0 activation failed")
            for rows in rows_by_block:
                for row in rows:
                    descriptor = row[4]
                    if type(descriptor) is not BridgeQueueDescriptorV11:
                        continue
                    domain_id = descriptor.destination_domain_id
                    route = inbox.routes.get(domain_id)
                    if route is None:
                        continue
                    key = (domain_id, descriptor.credit_id)
                    touched_counts.setdefault(
                        id(route.store),
                        (route.store, route.store.pinned_count),
                    )
                    touched.setdefault(
                        key,
                        (route, route.store.pins.get(descriptor.credit_id)),
                    )
            if not self._execute_candidate_frame(
                    candidate,
                    rows_by_block,
                    clock,
                    _INBOX_EXECUTION_FRAME_CAPABILITY):
                raise ValueError("Inbox candidate system execution failed")
            touched_slots = tuple(
                InboxTouchedSlotState(
                    domain_id,
                    route.store,
                    id(route.store),
                    route.destination_bridge,
                    route.store_codehash,
                    route.store_config_hash,
                    route.store.runtime_codehash,
                    credit_id,
                    touched_counts[id(route.store)][1],
                    route.store.pinned_count,
                    prior,
                    route.store.pins.get(credit_id),
                )
                for (domain_id, credit_id), (route, prior)
                in sorted(touched.items())
            )
            post_cursor = inbox.next_queue_index
            post_last_block = inbox.last_applied_l2_block
        finally:
            for (_, credit_id), (route, prior) in touched.items():
                if prior is None:
                    route.store.pins.pop(credit_id, None)
                else:
                    route.store.pins[credit_id] = prior
            for store, prior_count in touched_counts.values():
                store.pinned_count = prior_count
            inbox.next_queue_index = cursor_snapshot
            inbox.last_applied_l2_block = last_block_snapshot
            self._issued = issued_snapshot
            self._consumed = consumed_snapshot
            self._next_nonce = batch_nonce_snapshot
            self._execution_frame = None
            self._preparing_candidate_id = None
            if activation is not None:
                assert activation_snapshot is not None
                self._restore_activation_transaction(
                    activation, activation_snapshot
                )
        history = protocol.versioned_history
        if type(history) is not VersionedSettlementHistory:
            raise ValueError("Inbox receipt has no exact release history")
        receipt = InboxExecutionReceipt(
            self,
            candidate_inbox_execution_digest(candidate),
            candidate.base_canonical_hash,
            history.protocol_version,
            history.execution_profile_hash,
            cursor_snapshot,
            last_block_snapshot,
            post_cursor,
            post_last_block,
            tuple(
                release_system_calldata_hash(
                    activation.manifest, protocol.forced_queue.count
                )
                if index == 0 and activation is not None else ""
                for index in range(candidate.count)
            ),
            tuple(inbox_system_calldata_hash(rows)
                  for rows in rows_by_block),
            "PENDING",
            _INBOX_RECEIPT_CAPABILITY,
        )
        receipt = replace(
            receipt,
            seal=self._opaque_seal(
                b"TAIKO_INBOX_RECEIPT_SEAL_V1\x00", receipt.digest
            ),
        )
        return replace(candidate, inbox_execution_receipt=receipt)

    def verify_candidate_proof(
        self, candidate: Candidate, clock: Clock
    ) -> VerifiedCandidateProof:
        """Return the typed output of the canonical proof/fork verifier."""

        protocol = self.protocol
        history = protocol.versioned_history
        if (protocol._inbox_execution_authority is not self
                or type(candidate) is not Candidate
                or type(clock) is not Clock
                or type(history) is not VersionedSettlementHistory
                or self._verifying_candidate_id is not None
                or self._preparing_candidate_id is not None):
            raise ValueError("candidate proof verifier is split")
        self._verifying_candidate_id = id(candidate)
        try:
            verified = (
                protocol._valid_normal(candidate, clock)
                if protocol.mode is Mode.NORMAL
                else protocol._valid_recovery(candidate, clock)
            )
        finally:
            self._verifying_candidate_id = None
        if not verified:
            raise ValueError("candidate proof public inputs do not verify")
        output = VerifiedCandidateProof(
            self,
            candidate_inbox_execution_digest(candidate),
            protocol.canonical.base_hash,
            history.protocol_version,
            history.execution_profile_hash,
            clock.block_number,
            clock.timestamp,
            "CANONICAL_CANDIDATE",
            "PENDING",
            _VERIFIED_CANDIDATE_PROOF_CAPABILITY,
        )
        return replace(
            output,
            seal=self._opaque_seal(
                b"TAIKO_VERIFIED_CANDIDATE_SEAL_V1\x00",
                verified_candidate_proof_digest(output),
            ),
        )

    def _migration_candidate_public_inputs_exact(
        self,
        candidate: Candidate,
        clock: Clock,
        *,
        router: ActiveSettlementRouter,
        settlement: VersionedSettlementHistory,
        target_manifest_hash: bytes,
    ) -> bool:
        """Check migration public inputs without issuing an authorization."""

        protocol = self.protocol
        old_registration = router.registrations.get(router.active_version)
        old = old_registration.settlement if old_registration else None
        if (protocol._inbox_execution_authority is not self
                or type(candidate) is not Candidate
                or type(clock) is not Clock
                or type(router) is not ActiveSettlementRouter
                or type(settlement) is not VersionedSettlementHistory
                or settlement.live_protocol is not protocol
                or type(old_registration) is not SettlementRegistration
                or type(old) is not VersionedSettlementHistory
                or old.live_protocol is None
                or protocol.forced_queue is not router.forced_queue
                or protocol.inbox_apply_descriptor
                    != settlement.inbox_apply_descriptor
                or protocol.inbox_apply_descriptor
                    != router.inbox_apply_descriptor
                or protocol.header_oracle is not router.header_oracle
                or type(target_manifest_hash) is not bytes
                or len(target_manifest_hash) != 32
                or candidate.inbox_execution_receipt is not None
                or self._verifying_candidate_id is not None
                or self._preparing_candidate_id is not None):
            return False
        preview = settlement_registration(
            router,
            settlement,
            activation_block=clock.block_number,
            predecessor_version=router.active_version,
            release_manifest_hash=target_manifest_hash,
        )
        block = candidate.blocks[0] if candidate.count == 1 else None
        try:
            header = (
                protocol.header_oracle.header(block.anchor_number)
                if block is not None else None
            )
        except KeyError:
            header = None
        expected_end = old.live_protocol._prefix_end(
            old.core.message_cursor,
            block.force_cutoff if block is not None else 0,
            gas_budget=ACTIVATION_FORCE_GAS_BUDGET,
        )
        manifest_texts = {
            target_manifest_hash.hex(),
            "0x" + target_manifest_hash.hex(),
        }
        verified = (
            block is not None
            and candidate.proof_ok
            and candidate.force_range_proof_ok
            and candidate.manifest_exact
            and candidate.base_canonical_hash
                == old.live_protocol.canonical.base_hash
            and candidate.end_l2_block_number
                == old.core.l2_block_number + 1
            and candidate.tier is Tier.ESCAPE_UNSIGNED
            and candidate.recovery_fields_zero
            and block.parent_hash == old.core.tip_hash
            and block.slot > old.core.tip_slot
            and block.evm_timestamp == GENESIS_TIMESTAMP + block.slot
            and block.slot <= clock.l2_slot + CLOCK_SKEW
            and block.message_start == old.core.message_cursor
            and block.message_end == expected_end
            and block.inbox_pre_cursor == block.message_start
            and block.inbox_post_cursor == block.message_end
            and block.release_activation
            and block.release_protocol_version == settlement.protocol_version
            and block.release_manifest_hash in manifest_texts
            and block.force_gas_budget == ACTIVATION_FORCE_GAS_BUDGET
            and not block.scheduled_signature_ok
            and not block.discretionary_body
            and block.anchor_system_tx_position
                == ANCHOR_SYSTEM_TX_POSITION
            and block.inbox_system_tx_position
                == INBOX_SYSTEM_TX_POSITION
            and bool(block.inbox_descriptor_commitment)
            and bool(block.inbox_system_calldata_hash)
            and header is not None
            and header.block_hash == block.anchor_hash
            and header.force_root == block.force_root
            and header.force_cutoff == block.force_cutoff
            and block.force_cutoff <= router.forced_queue.count
            and block.force_root == model_force_root(
                router.forced_queue.descriptors[:block.force_cutoff]
            )
            and candidate.next_due_at == old.live_protocol.next_due_at(
                block.message_end, block.force_cutoff
            )
            and candidate.end_terminal_count >= old.core.terminal_count
            and (
                candidate.end_terminal_count > old.core.terminal_count
                or candidate.end_terminal_root == old.core.terminal_root
            )
            and preview.release_manifest.commitment == target_manifest_hash
        )
        return verified

    def _migration_transition_public_inputs(
        self,
        *,
        router: ActiveSettlementRouter,
        settlement: VersionedSettlementHistory,
        clock: Clock,
        target_manifest_hash: bytes,
        candidate: Candidate,
        rows: tuple[InboxRowV2, ...],
        witness: ReleaseDeploymentWitness,
    ) -> MigrationTransitionPublicInputs:
        """Derive the byte-exact verifier inputs from authenticated objects."""

        if (not self._migration_candidate_public_inputs_exact(
                candidate,
                clock,
                router=router,
                settlement=settlement,
                target_manifest_hash=target_manifest_hash,
        ) or type(witness) is not ReleaseDeploymentWitness):
            raise ValueError("migration transition inputs are not canonical")
        manifest = settlement_registration(
            router,
            settlement,
            activation_block=0,
            predecessor_version=router.active_version,
            release_manifest_hash=target_manifest_hash,
        ).release_manifest
        if (witness.manifest_commitment != manifest.commitment
                or manifest.migration_transition_verifier
                    != self.migration_transition_verifier_descriptor
                or witness.prestate_root != self.protocol.core.state_root
                or witness.observed_components != manifest.components[3:]
                or witness.observed_bridge_descriptor
                    != manifest.destination_bridge_descriptor
                or witness.pool_observation != (
                    self.protocol.inbox_apply_router
                        ._terminal_registrar_authority
                        .liquidity_pool.address,
                    self.protocol.inbox_apply_router
                        ._terminal_registrar_authority
                        .liquidity_pool.runtime_hash,
                    self.protocol.inbox_apply_router
                        ._terminal_registrar_authority
                        .liquidity_pool.configuration_hash,
                    self.protocol.inbox_apply_router
                        ._terminal_registrar_authority
                        .liquidity_pool.balance,
                )
                or type(witness.store) is not InboxCreditStoreV2
                or witness.store.address != manifest.components[4].address
                or witness.store.runtime_codehash
                    != manifest.components[4].runtime_hash
                or type(witness.endpoint_state)
                    is not EndpointActivationStateV2
                or witness.endpoint_prestate
                    != endpoint_activation_projection(witness.endpoint_state)
                or type(witness.bridge_deployment)
                    is not BridgeDeploymentStateV2
                or not witness.bridge_deployment.authenticates(
                    manifest, require_fresh=True,
                )
                or not witness.endpoint_state.activatable
                or manifest.destination_domain_id
                    in self.protocol.inbox_apply_router.routes):
            raise ValueError("migration deployment observation is inexact")
        return migration_transition_public_inputs_from_l1(
            router=router,
            settlement=settlement,
            target_manifest_hash=target_manifest_hash,
            candidate=candidate,
            rows=rows,
            pre_inbox_last_applied_l2_block=(
                self.protocol.inbox_apply_router.last_applied_l2_block
            ),
        )

    def verify_migration_transition(
        self,
        *,
        router: ActiveSettlementRouter,
        settlement: VersionedSettlementHistory,
        clock: Clock,
        target_manifest_hash: bytes,
        candidate: Candidate,
        rows: tuple[InboxRowV2, ...],
        witness: ReleaseDeploymentWitness,
        proof: MigrationTransitionProof,
    ) -> VerifiedMigrationEvmTrace:
        """Mint trace/observation only from the exact verifier return value."""

        verifier = self.migration_transition_verifier
        if (not isinstance(verifier, IMigrationTransitionVerifier)
                or self.migration_transition_verifier_descriptor
                    != verifier.descriptor):
            raise ValueError("migration transition verifier is not exact")
        expected = self._migration_transition_public_inputs(
            router=router,
            settlement=settlement,
            clock=clock,
            target_manifest_hash=target_manifest_hash,
            candidate=candidate,
            rows=rows,
            witness=witness,
        )
        result = verifier.verify_transition(proof)
        if (not verifier.valid_result(result)
                or result.verifier is not verifier
                or result.descriptor
                    != self.migration_transition_verifier_descriptor
                or result.public_inputs != expected
                or result.returndata != bytes.fromhex(expected.digest)):
            raise ValueError("migration transition verifier output is inexact")
        observed = ObservedReleaseDeployment(
            authority=self,
            transition_verifier=verifier,
            transition_verifier_descriptor=result.descriptor,
            transition_result_digest=result.digest,
            transition_result_seal=result.seal,
            manifest_commitment=witness.manifest_commitment,
            prestate_root=witness.prestate_root,
            observed_components=witness.observed_components,
            observed_bridge_descriptor=witness.observed_bridge_descriptor,
            store=witness.store,
            store_object_id=id(witness.store),
            endpoint_state=witness.endpoint_state,
            endpoint_object_id=id(witness.endpoint_state),
            endpoint_prestate=witness.endpoint_prestate,
            bridge_deployment=witness.bridge_deployment,
            pool_observation=witness.pool_observation,
            seal="PENDING",
            _capability=_OBSERVED_RELEASE_DEPLOYMENT_CAPABILITY,
        )
        observed = replace(
            observed,
            seal=self._opaque_seal(
                b"TAIKO_OBSERVED_RELEASE_DEPLOYMENT_SEAL_V1\x00",
                observed.digest,
            ),
        )
        trace = VerifiedMigrationEvmTrace(
            verifier=self,
            transition_verifier=verifier,
            transition_verifier_descriptor=result.descriptor,
            transition_result_digest=result.digest,
            transition_result_seal=result.seal,
            transition_proof=proof,
            transition_statement_digest=expected.digest,
            router_generation=expected.router_generation,
            source_canonical_sequence=expected.canonical_sequence,
            candidate_digest=expected.candidate_digest,
            base_core=expected.base_core,
            output_core=expected.output_core,
            target_protocol_version=expected.target_protocol_version,
            execution_profile_hash=expected.execution_profile_hash,
            target_manifest_hash=expected.target_manifest_hash,
            queue_root=expected.queue_root,
            queue_count=expected.queue_count,
            start_cursor=expected.start_cursor,
            end_cursor=expected.end_cursor,
            release_system_calldata_hash=(
                expected.release_system_calldata_hash
            ),
            system_calldata_hash=expected.inbox_system_calldata_hash,
            deployment_commitment=expected.deployment_commitment,
            observed_deployment_digest=observed.digest,
            observed_deployment_seal=observed.seal,
            pre_inbox_last_applied_l2_block=(
                self.protocol.inbox_apply_router.last_applied_l2_block
            ),
            post_inbox_last_applied_l2_block=(
                expected.output_core.l2_block_number
            ),
            proof_commitment=result.proof_commitment,
            seal="PENDING",
            _capability=_VERIFIED_MIGRATION_EVM_TRACE_CAPABILITY,
        )
        trace = replace(
            trace,
            seal=self._opaque_seal(
                b"TAIKO_VERIFIED_MIGRATION_EVM_TRACE_SEAL_V1\x00",
                trace.digest,
            ),
        )
        prior = self._observed_release_deployments.get(
            witness.manifest_commitment
        )
        if prior is not None and prior.digest != observed.digest:
            raise ValueError("release deployment observation conflicts")
        self._observed_release_deployments[
            witness.manifest_commitment
        ] = observed
        return trace

    def valid_migration_evm_trace(
        self, trace: VerifiedMigrationEvmTrace,
    ) -> bool:
        return (
            type(trace) is VerifiedMigrationEvmTrace
            and trace.verifier is self
            and trace.transition_verifier
                is self.migration_transition_verifier
            and trace.transition_verifier_descriptor
                == self.migration_transition_verifier_descriptor
            and trace.transition_result_digest
                == migration_transition_result_digest(
                    trace.transition_verifier_descriptor,
                    trace.transition_statement_digest,
                    trace.proof_commitment,
                )
            and self.migration_transition_verifier.valid_result_seal(
                trace.transition_result_digest,
                trace.transition_result_seal,
            )
            and trace.seal == self._opaque_seal(
                b"TAIKO_VERIFIED_MIGRATION_EVM_TRACE_SEAL_V1\x00",
                trace.digest,
            )
        )

    def verify_migration_execution_output(
        self,
        *,
        router: ActiveSettlementRouter,
        settlement: VersionedSettlementHistory,
        clock: Clock,
        target_manifest_hash: bytes,
        candidate: Candidate,
        evm_validity: VerifiedMigrationEvmTrace,
        rows: tuple[InboxRowV2, ...] | None = None,
    ) -> VerifiedMigrationExecutionOutput:
        """Issue the one sealed output covering migration tx0 and tx1.

        The Router has no output-signing key and never reads or executes the
        target L2 graph.  This exact verifier checks its already-sealed EVM
        public outputs against the L1 commitments, then wraps that immutable
        output for the Router to consume.
        """

        old_registration = router.registrations.get(router.active_version)
        old = old_registration.settlement if old_registration else None
        old_protocol = old.live_protocol if old is not None else None
        block = candidate.blocks[0] if type(candidate) is Candidate \
            and candidate.count == 1 else None
        output_core = (
            CanonicalCore(
                candidate.end_l2_block_number,
                block.block_hash,
                block.slot,
                candidate.end_state_root,
                block.message_end,
                candidate.winning_data_commitment,
                candidate.next_base_fee,
                candidate.next_excess_blob_gas,
                candidate.end_terminal_root,
                candidate.end_terminal_count,
            )
            if block is not None else None
        )
        if (self.protocol._inbox_execution_authority is not self
                or type(router) is not ActiveSettlementRouter
                or type(settlement) is not VersionedSettlementHistory
                or settlement.live_protocol is not self.protocol
                or type(old_registration) is not SettlementRegistration
                or type(old_protocol) is not Protocol
                or output_core is None
                or type(clock) is not Clock
                or type(evm_validity) is not VerifiedMigrationEvmTrace
                or not self.valid_migration_evm_trace(evm_validity)
                or not self._migration_candidate_public_inputs_exact(
                    candidate,
                    clock,
                    router=router,
                    settlement=settlement,
                    target_manifest_hash=target_manifest_hash,
                )
                or evm_validity.candidate_digest
                    != candidate_inbox_execution_digest(candidate)
                or evm_validity.base_core != old.core
                or evm_validity.output_core != output_core
                or evm_validity.target_protocol_version
                    != settlement.protocol_version
                or evm_validity.execution_profile_hash
                    != settlement.execution_profile_hash
                or evm_validity.target_manifest_hash
                    != target_manifest_hash
                or evm_validity.queue_root != router.forced_queue.root
                or evm_validity.queue_count != router.forced_queue.count
                or evm_validity.start_cursor != old.core.message_cursor
                or evm_validity.end_cursor != output_core.message_cursor
                or evm_validity.post_inbox_last_applied_l2_block
                    != output_core.l2_block_number):
            raise ValueError("migration execution verifier graph is split")
        preview = settlement_registration(
            router,
            settlement,
            activation_block=clock.block_number,
            predecessor_version=router.active_version,
            release_manifest_hash=target_manifest_hash,
        )
        manifest = preview.release_manifest
        start = old.core.message_cursor
        end = output_core.message_cursor
        descriptors = tuple(router.forced_queue.descriptors[start:end])
        exact_rows = (
            tuple(
                (
                    index, 0, UINT32_MAX, "", None,
                )
                if type(descriptor) is Message
                and descriptor.kind is ForceKind.USER_TX
                else (
                    index,
                    5,
                    UINT32_MAX,
                    inbox_kind1_result(index, descriptor),
                    descriptor,
                )
                for index, descriptor in enumerate(descriptors, start)
            )
            if rows is None else rows
        )
        expected_statement = migration_transition_public_inputs_from_l1(
            router=router,
            settlement=settlement,
            target_manifest_hash=target_manifest_hash,
            candidate=candidate,
            rows=exact_rows,
            pre_inbox_last_applied_l2_block=(
                evm_validity.transition_proof.public_inputs
                    .pre_inbox_last_applied_l2_block
            ),
        )
        if (evm_validity.transition_statement_digest
                != expected_statement.digest
                or evm_validity.router_generation
                    != expected_statement.router_generation
                or evm_validity.source_canonical_sequence
                    != expected_statement.canonical_sequence
                or evm_validity.transition_result_digest
                    != migration_transition_result_digest(
                        evm_validity.transition_verifier_descriptor,
                        expected_statement.digest,
                        evm_validity.proof_commitment,
                    )
                or evm_validity.release_system_calldata_hash
                != release_system_calldata_hash(
                    manifest, evm_validity.queue_count
                )
                or evm_validity.system_calldata_hash
                    != inbox_system_calldata_hash(exact_rows)
                or block.inbox_descriptor_commitment
                    != inbox_descriptor_commitment(descriptors)
                or block.inbox_system_calldata_hash
                    != inbox_system_calldata_hash(exact_rows)
                or not self._rows_match_descriptors(exact_rows, descriptors)):
            raise ValueError("migration execution calldata is not exact")
        return MigrationActivationCallV2(
            candidate,
            evm_validity.transition_proof,
            copy.deepcopy(old.core),
            copy.deepcopy(output_core),
            settlement.protocol_version,
            target_manifest_hash,
            evm_validity.transition_statement_digest,
            evm_validity.router_generation,
            evm_validity.source_canonical_sequence,
            start,
            end,
            candidate.beneficiary,
            exact_rows,
            evm_validity.pre_inbox_last_applied_l2_block,
            evm_validity.post_inbox_last_applied_l2_block,
        )

    def valid_receipt(self, candidate: Candidate) -> bool:
        receipt = candidate.inbox_execution_receipt
        protocol = self.protocol
        history = protocol.versioned_history
        if (type(receipt) is not InboxExecutionReceipt
                or receipt.authority is not self
                or type(history) is not VersionedSettlementHistory):
            return False
        router = history._router_authority
        registration = (
            router.registrations.get(history.protocol_version)
            if type(router) is ActiveSettlementRouter else None
        )
        expected_release_hashes: list[str] = []
        for block in candidate.blocks:
            if not block.release_activation:
                expected_release_hashes.append("")
                continue
            manifests = (
                registration.release_manifests_by_adapter.values()
                if type(registration) is SettlementRegistration else ()
            )
            matches = tuple(
                manifest for manifest in manifests
                if manifest.protocol_version
                    == block.release_protocol_version
                and self._manifest_hash_matches(
                    manifest, block.release_manifest_hash
                )
            )
            if len(matches) != 1:
                return False
            expected_release_hashes.append(
                release_system_calldata_hash(
                    matches[0], protocol.forced_queue.count
                )
            )
        return (
            receipt.seal == self._opaque_seal(
                b"TAIKO_INBOX_RECEIPT_SEAL_V1\x00", receipt.digest
            )
            and receipt.candidate_digest
                == candidate_inbox_execution_digest(candidate)
            and receipt.base_canonical_hash == protocol.canonical.base_hash
            and receipt.base_canonical_hash == candidate.base_canonical_hash
            and receipt.protocol_version == history.protocol_version
            and receipt.execution_profile_hash
                == history.execution_profile_hash
            and receipt.pre_cursor == protocol.core.message_cursor
            and receipt.post_cursor == candidate.tip.message_end
            and receipt.post_last_applied_l2_block
                == candidate.end_l2_block_number
            and receipt.release_system_calldata_hashes
                == tuple(expected_release_hashes)
            and receipt.inbox_system_calldata_hashes
                == tuple(
                    block.inbox_system_calldata_hash
                    for block in candidate.blocks
                )
        )

    def valid_for(
        self,
        batch: AuthenticatedInboxBatch,
        inbox: "InboxApplyRouterV2",
        rows: tuple[InboxRowV2, ...],
    ) -> bool:
        if (type(batch) is not AuthenticatedInboxBatch
                or batch.authority is not self
                or inbox is not batch.inbox
                or batch.nonce in self._consumed):
            return False
        record = self._issued.get(batch.nonce)
        protocol = self.protocol
        history = protocol.versioned_history
        router = getattr(history, "_router_authority", None)
        try:
            header = protocol.header_oracle.header(batch.anchor_number)
        except KeyError:
            return False
        anchor_force_exact = (
            (
                protocol.mode is Mode.NORMAL
                and header.force_root == batch.force_root
                and header.force_cutoff == batch.force_cutoff
            )
            or (
                protocol.mode is Mode.RECOVERY
                and protocol.recovery is not None
                and protocol.recovery.force_root == batch.force_root
                and protocol.recovery.force_cutoff == batch.force_cutoff
            )
        )
        return (
            type(record) is IssuedInboxBatchRecord
            and record.nonce == batch.nonce
            and record.batch_object_id == id(batch)
            and record.batch_digest == batch.digest
            and record.execution_frame == self._execution_frame
            and record.execution_frame
                == (record.execution_frame[0], batch.block_index)
            and type(history) is VersionedSettlementHistory
            and type(router) is ActiveSettlementRouter
            and history.protocol_version == batch.protocol_version
            and history.execution_profile_hash == batch.execution_profile_hash
            and router.settlement_chain_context_id
                == batch.settlement_chain_id
            and protocol.canonical.base_hash == batch.base_canonical_hash
            and batch.l2_block_number
                == protocol.core.l2_block_number + batch.block_index + 1
            and protocol.inbox_apply_router.next_queue_index
                == batch.force_start
            and header.block_hash == batch.anchor_hash
            and anchor_force_exact
            and batch.force_root == model_force_root(
                protocol.forced_queue.descriptors[:batch.force_cutoff]
            )
            and batch.system_calldata_hash == inbox_system_calldata_hash(rows)
        )

    def consume(self, batch: AuthenticatedInboxBatch) -> None:
        record = self._issued.pop(batch.nonce, None)
        if (type(record) is not IssuedInboxBatchRecord
                or record.batch_digest != batch.digest):
            raise ValueError("Inbox batch capability was not issued")
        self._consumed.add(batch.nonce)


def release_deployment_witness_for_test(
    authority: InboxValidityExecutionAuthority,
    manifest: "ReleaseManifestV2",
) -> ReleaseDeploymentWitness:
    """Fixture-only raw prestate consumed by the exact verifier mock."""

    if (type(authority) is not InboxValidityExecutionAuthority
            or type(manifest) is not ReleaseManifestV2
            or not manifest.structurally_valid()):
        raise ValueError("test release prestate is invalid")
    protocol = authority.protocol
    registrar = protocol.inbox_apply_router._terminal_registrar_authority
    if type(registrar) is not TerminalDomainRegistrarV2:
        raise ValueError("test release prestate has no local registrar")
    if (manifest.destination_domain_id
            in protocol.inbox_apply_router.routes
            or manifest.destination_bridge in registrar.bridge_identities):
        raise ValueError("V2 release must use a fresh domain and Bridge")
    store_row = manifest.components[4]
    store = InboxCreditStoreV2(
        protocol.inbox_apply_router.address,
        manifest.destination_bridge,
        manifest.destination_domain_id,
        address=store_row.address,
        terminal_registrar=registrar.address,
        runtime_codehash=store_row.runtime_hash,
    )
    endpoint = EndpointActivationStateV2()
    deployment = bridge_deployment_state_for_test(manifest)
    pool_observation = (
        registrar.liquidity_pool.address,
        registrar.liquidity_pool.runtime_hash,
        registrar.liquidity_pool.configuration_hash,
        registrar.liquidity_pool.balance,
    )
    return ReleaseDeploymentWitness(
        manifest.commitment,
        protocol.core.state_root,
        manifest.components[3:],
        manifest.destination_bridge_descriptor,
        store,
        endpoint,
        endpoint_activation_projection(endpoint),
        deployment,
        pool_observation,
    )


def issue_verified_migration_evm_trace_for_test(
    authority: InboxValidityExecutionAuthority,
    *,
    router: ActiveSettlementRouter,
    settlement: VersionedSettlementHistory,
    clock: Clock,
    target_manifest_hash: bytes,
    candidate: Candidate,
    rows: tuple[InboxRowV2, ...],
) -> VerifiedMigrationEvmTrace:
    """Drive the production interface with a test-only valid proof blob."""

    if (type(authority) is not InboxValidityExecutionAuthority
            or not authority._migration_candidate_public_inputs_exact(
                candidate,
                clock,
                router=router,
                settlement=settlement,
                target_manifest_hash=target_manifest_hash,
            )):
        raise ValueError("test migration trace public inputs do not verify")
    manifest = settlement_registration(
        router,
        settlement,
        activation_block=clock.block_number,
        predecessor_version=router.active_version,
        release_manifest_hash=target_manifest_hash,
    ).release_manifest
    witness = release_deployment_witness_for_test(authority, manifest)
    public_inputs = authority._migration_transition_public_inputs(
        router=router,
        settlement=settlement,
        clock=clock,
        target_manifest_hash=target_manifest_hash,
        candidate=candidate,
        rows=rows,
        witness=witness,
    )
    verifier = authority.migration_transition_verifier
    if type(verifier) is not TestMigrationTransitionVerifier:
        raise ValueError("test fixture requires the exact test verifier mock")
    proof = issue_migration_transition_proof_for_test(
        verifier,
        public_inputs,
        b"test-zk-migration-proof:" + public_inputs.digest.encode(),
    )
    return authority.verify_migration_transition(
        router=router,
        settlement=settlement,
        clock=clock,
        target_manifest_hash=target_manifest_hash,
        candidate=candidate,
        rows=rows,
        witness=witness,
        proof=proof,
    )


_FORK_LOCAL_L2_POSTSTATE_CAPABILITY = object()


def l2_execution_state_commitment_for_test(protocol: Protocol) -> str:
    """Commit node-local L2 state without placing it in the L1 graph.

    This deliberately unbounded projection is a test-node snapshot, not a
    receipt/public input and never an on-chain operation.  Production nodes
    use their execution database/state root instead.
    """

    if type(protocol) is not Protocol:
        raise ValueError("L2 state commitment requires exact Protocol")
    inbox = protocol.inbox_apply_router
    registrar = inbox._terminal_registrar_authority
    if type(registrar) is not TerminalDomainRegistrarV2:
        raise ValueError("L2 state commitment has no exact registrar")
    routes = tuple(sorted(
        (
            domain_id,
            route.destination_bridge,
            route.store_codehash,
            route.store_config_hash,
            route.store.address,
            route.store.runtime_codehash,
            route.store.route_config_hash,
            route.store.pinned_count,
            tuple(sorted(route.store.pins.items())),
        )
        for domain_id, route in inbox.routes.items()
    ))
    observations = tuple(sorted(
        (
            manifest_hash,
            endpoint_activation_projection(observed.endpoint_state),
            observed.bridge_deployment,
        )
        for manifest_hash, observed
        in protocol._inbox_execution_authority
            ._observed_release_deployments.items()
    ))
    projection = (
        inbox.next_queue_index,
        inbox.last_applied_l2_block,
        routes,
        tuple(sorted(registrar.authority.releases.items())),
        tuple(sorted(registrar.registrations.items())),
        tuple(sorted(registrar.bridge_identities.items())),
        registrar.active_destination_bridge,
        tuple(sorted(registrar.retirement_queue_watermarks.items())),
        registrar.liquidity_pool._snapshot(),
        tuple(sorted(registrar.accumulator.domains.items())),
        tuple(sorted(
            registrar.accumulator.terminalized_pinned_count.items()
        )),
        tuple(sorted(registrar.accumulator._terminalized_credits)),
        observations,
    )
    return hashlib.sha256(
        b"TAIKO_NODE_LOCAL_L2_STATE_V1\x00" + repr(projection).encode()
    ).hexdigest()


@dataclass(frozen=True, eq=False)
class ForkLocalL2Poststate:
    """Immutable fork-local replay result selected only after L1 success."""

    authority: "InboxValidityExecutionAuthority" = field(
        compare=False, repr=False
    )
    protocol: Protocol = field(compare=False, repr=False)
    candidate: Candidate
    rows_by_block: tuple[tuple["InboxRowV2", ...], ...]
    migration_output: VerifiedMigrationExecutionOutput | None
    prestate_commitment: str
    poststate_commitment: str
    pre_cursor: int
    post_cursor: int
    pre_last_applied_l2_block: int
    post_last_applied_l2_block: int
    target_protocol_version: int
    target_manifest_hash: bytes
    l1_block_number: int
    l1_timestamp: int
    seal: str
    _capability: object = field(repr=False, compare=False)

    def __post_init__(self) -> None:
        if (self._capability is not _FORK_LOCAL_L2_POSTSTATE_CAPABILITY
                or type(self.authority) is not InboxValidityExecutionAuthority
                or type(self.protocol) is not Protocol
                or self.authority.protocol is not self.protocol
                or type(self.candidate) is not Candidate
                or type(self.rows_by_block) is not tuple
                or not self.rows_by_block
                or any(type(rows) is not tuple for rows in self.rows_by_block)
                or len(self.rows_by_block) != self.candidate.count
                or (self.migration_output is not None
                    and type(self.migration_output)
                        is not VerifiedMigrationExecutionOutput)
                or not self.prestate_commitment
                or not self.poststate_commitment
                or self.pre_cursor < 0
                or self.post_cursor < self.pre_cursor
                or self.pre_last_applied_l2_block < -1
                or self.post_last_applied_l2_block
                    <= self.pre_last_applied_l2_block
                or self.target_protocol_version <= 0
                or type(self.target_manifest_hash) is not bytes
                or len(self.target_manifest_hash) != 32
                or self.l1_block_number < 0
                or self.l1_timestamp < 0
                or not self.seal):
            raise ValueError("fork-local L2 poststate is not canonical")

    @property
    def digest(self) -> str:
        projection = (
            id(self.authority), id(self.protocol),
            candidate_inbox_execution_digest(self.candidate),
            tuple(inbox_system_calldata_hash(rows)
                  for rows in self.rows_by_block),
            (
                "" if self.migration_output is None
                else self.migration_output.digest
            ),
            self.prestate_commitment,
            self.poststate_commitment,
            self.pre_cursor,
            self.post_cursor,
            self.pre_last_applied_l2_block,
            self.post_last_applied_l2_block,
            self.target_protocol_version,
            self.target_manifest_hash,
            self.l1_block_number,
            self.l1_timestamp,
        )
        return hashlib.sha256(
            b"TAIKO_FORK_LOCAL_L2_POSTSTATE_V1\x00"
            + repr(projection).encode()
        ).hexdigest()


def _execute_verified_migration_l2_replay_for_test(
    protocol: Protocol,
    output: VerifiedMigrationExecutionOutput,
    router: ActiveSettlementRouter,
    *,
    persist: bool,
    expected_poststate_commitment: str | None = None,
) -> tuple[str, str] | None:
    """Execute one migration replay, restoring unless canonically selected.

    The L1 Router consumes only commitments.  This helper models the
    independent L2 node/circuit replay without giving L1 an InboxApply/Store
    capability.
    """

    if (type(protocol) is not Protocol
            or type(output) is not VerifiedMigrationExecutionOutput
            or type(router) is not ActiveSettlementRouter
            or output.transition_proof.public_inputs.digest
                != output.transition_statement_digest
            or output.transition_proof.public_inputs.candidate_digest
                != candidate_inbox_execution_digest(output.candidate)
            or output.transition_proof.public_inputs.inbox_system_calldata_hash
                != inbox_system_calldata_hash(output.rows)):
        return None
    authority = protocol._inbox_execution_authority
    history = protocol.versioned_history
    if type(history) is not VersionedSettlementHistory:
        return None
    registration = None
    if (type(router) is ActiveSettlementRouter
            and type(history) is VersionedSettlementHistory):
        registration = router.registrations.get(history.protocol_version)
        if registration is None:
            try:
                registration = settlement_registration(
                    router,
                    history,
                    activation_block=(
                        output.candidate.blocks[0].anchor_number + F_L1
                    ),
                    predecessor_version=router.active_version,
                    release_manifest_hash=output.target_manifest_hash,
                )
            except ValueError:
                registration = None
    manifests = (
        tuple(registration.release_manifests_by_adapter.values())
        if type(registration) is SettlementRegistration else ()
    )
    matches = tuple(
        manifest for manifest in manifests
        if manifest.commitment == output.target_manifest_hash
    )
    if len(matches) != 1:
        return None
    try:
        activation = authority._route_activation_delta_for_manifest(
            matches[0],
            expected_prestate_root=output.base_core.state_root,
        )
    except ValueError:
        return None
    snapshot = authority._activation_transaction_snapshot(activation)
    inbox = protocol.inbox_apply_router
    cursor_snapshot = inbox.next_queue_index
    last_snapshot = inbox.last_applied_l2_block
    prestate_commitment = l2_execution_state_commitment_for_test(protocol)
    prior_frame = authority._execution_frame
    touched: dict[
        tuple[str, str], tuple[InboxRoute, InboxPin | None]
    ] = {}
    touched_counts: dict[int, tuple[InboxCreditStoreV2, int]] = {}
    try:
        if (cursor_snapshot != output.start_cursor
                or not authority._activate_release_delta(
                    activation,
                    expected_prestate_root=output.base_core.state_root,
                )):
            raise ValueError("L2 replay tx0 failed")
        for row in output.rows:
            descriptor = row[4]
            if type(descriptor) is not BridgeQueueDescriptorV11:
                continue
            route = inbox.routes.get(descriptor.destination_domain_id)
            if route is None:
                raise ValueError("L2 replay route is absent")
            touched.setdefault(
                (descriptor.destination_domain_id, descriptor.credit_id),
                (route, route.store.pins.get(descriptor.credit_id)),
            )
            touched_counts.setdefault(
                id(route.store), (route.store, route.store.pinned_count)
            )
        authority._execution_frame = (id(output), 0)
        if not inbox._apply_verified_rows(
            output.rows,
            force_start=output.start_cursor,
            l2_block_number=output.output_core.l2_block_number,
            evm_timestamp=GENESIS_TIMESTAMP + output.output_core.tip_slot,
            authority=authority,
            capability=_INBOX_APPLY_ROWS_CAPABILITY,
        ):
            raise ValueError("L2 replay tx1 failed")
        if (inbox.next_queue_index != output.end_cursor
                or inbox.last_applied_l2_block
                    != output.post_inbox_last_applied_l2_block):
            raise ValueError("L2 replay poststate differs from proof")
        poststate_commitment = l2_execution_state_commitment_for_test(protocol)
        if (persist
                and expected_poststate_commitment is not None
                and poststate_commitment != expected_poststate_commitment):
            raise ValueError("L2 replay poststate differs from fork snapshot")
        if not persist:
            for (_, credit_id), (route, prior) in touched.items():
                if prior is None:
                    route.store.pins.pop(credit_id, None)
                else:
                    route.store.pins[credit_id] = prior
            for store, prior_count in touched_counts.values():
                store.pinned_count = prior_count
            inbox.next_queue_index = cursor_snapshot
            inbox.last_applied_l2_block = last_snapshot
            authority._restore_activation_transaction(activation, snapshot)
        return prestate_commitment, poststate_commitment
    except BaseException:
        for (_, credit_id), (route, prior) in touched.items():
            if prior is None:
                route.store.pins.pop(credit_id, None)
            else:
                route.store.pins[credit_id] = prior
        for store, prior_count in touched_counts.values():
            store.pinned_count = prior_count
        inbox.next_queue_index = cursor_snapshot
        inbox.last_applied_l2_block = last_snapshot
        authority._restore_activation_transaction(activation, snapshot)
        return None
    finally:
        authority._execution_frame = prior_frame


def _execute_prepared_candidate_l2_replay_for_test(
    authority: InboxValidityExecutionAuthority,
    candidate: Candidate,
    rows_by_block: tuple[tuple[InboxRowV2, ...], ...],
    clock: Clock,
    *,
    persist: bool,
    expected_poststate_commitment: str | None = None,
) -> tuple[str, str] | None:
    """Execute normal/recovery replay, restoring unless selected by L1."""

    receipt = (
        candidate.inbox_execution_receipt
        if type(candidate) is Candidate else None
    )
    protocol = (
        authority.protocol
        if type(authority) is InboxValidityExecutionAuthority else None
    )
    if (type(authority) is not InboxValidityExecutionAuthority
            or type(candidate) is not Candidate
            or type(receipt) is not InboxExecutionReceipt
            or type(protocol) is not Protocol
            or receipt.authority is not authority
            or receipt.seal != authority._opaque_seal(
                b"TAIKO_INBOX_RECEIPT_SEAL_V1\x00", receipt.digest
            )
            or receipt.candidate_digest
                != candidate_inbox_execution_digest(candidate)
            or type(rows_by_block) is not tuple
            or len(rows_by_block) != candidate.count
            or tuple(inbox_system_calldata_hash(rows)
                     for rows in rows_by_block)
                != receipt.inbox_system_calldata_hashes
            or receipt.pre_cursor
                != protocol.inbox_apply_router.next_queue_index
            or receipt.post_cursor != candidate.tip.message_end
            or authority._preparing_candidate_id is not None
            or authority._execution_frame is not None):
        return None
    try:
        activation = authority._release_activation_delta(candidate)
    except ValueError:
        return None
    snapshot = (
        authority._activation_transaction_snapshot(activation)
        if activation is not None else None
    )
    inbox = protocol.inbox_apply_router
    cursor_snapshot = inbox.next_queue_index
    last_snapshot = inbox.last_applied_l2_block
    prestate_commitment = l2_execution_state_commitment_for_test(protocol)
    touched: dict[
        tuple[int, str], tuple[InboxCreditStoreV2, InboxPin | None]
    ] = {}
    touched_counts: dict[int, tuple[InboxCreditStoreV2, int]] = {}
    try:
        if (activation is not None
                and not authority._activate_release_delta(activation)):
            raise ValueError("canonical L2 replay rejected tx0")
        for rows in rows_by_block:
            for row in rows:
                descriptor = row[4]
                if type(descriptor) is not BridgeQueueDescriptorV11:
                    continue
                route = inbox.routes.get(descriptor.destination_domain_id)
                if route is None:
                    raise ValueError("canonical L2 replay route is absent")
                touched.setdefault(
                    (id(route.store), descriptor.credit_id),
                    (route.store, route.store.pins.get(descriptor.credit_id)),
                )
                touched_counts.setdefault(
                    id(route.store), (route.store, route.store.pinned_count)
                )
        for block_index, (block, rows) in enumerate(
                zip(candidate.blocks, rows_by_block)):
            authority._execution_frame = (id(candidate), block_index)
            if not inbox._apply_verified_rows(
                rows,
                force_start=block.message_start,
                l2_block_number=(
                    candidate.end_l2_block_number
                    - candidate.count + block_index + 1
                ),
                evm_timestamp=block.evm_timestamp,
                authority=authority,
                capability=_INBOX_APPLY_ROWS_CAPABILITY,
            ):
                raise ValueError("canonical L2 replay rejected tx1")
        poststate_commitment = l2_execution_state_commitment_for_test(protocol)
        if (persist
                and expected_poststate_commitment is not None
                and poststate_commitment != expected_poststate_commitment):
            raise ValueError("L2 replay poststate differs from fork snapshot")
        if not persist:
            for (_, credit_id), (store, prior) in touched.items():
                if prior is None:
                    store.pins.pop(credit_id, None)
                else:
                    store.pins[credit_id] = prior
            for store, prior_count in touched_counts.values():
                store.pinned_count = prior_count
            inbox.next_queue_index = cursor_snapshot
            inbox.last_applied_l2_block = last_snapshot
            if activation is not None:
                assert snapshot is not None
                authority._restore_activation_transaction(activation, snapshot)
        return prestate_commitment, poststate_commitment
    except BaseException:
        for (_, credit_id), (store, prior) in touched.items():
            if prior is None:
                store.pins.pop(credit_id, None)
            else:
                store.pins[credit_id] = prior
        for store, prior_count in touched_counts.values():
            store.pinned_count = prior_count
        inbox.next_queue_index = cursor_snapshot
        inbox.last_applied_l2_block = last_snapshot
        if activation is not None:
            assert snapshot is not None
            authority._restore_activation_transaction(activation, snapshot)
        return None
    finally:
        authority._execution_frame = None


def _sealed_fork_local_l2_poststate_for_test(
    authority: InboxValidityExecutionAuthority,
    *,
    candidate: Candidate,
    rows_by_block: tuple[tuple[InboxRowV2, ...], ...],
    migration_output: VerifiedMigrationExecutionOutput | None,
    prestate_commitment: str,
    poststate_commitment: str,
    pre_cursor: int,
    post_cursor: int,
    pre_last_applied_l2_block: int,
    post_last_applied_l2_block: int,
    target_protocol_version: int,
    target_manifest_hash: bytes,
    clock: Clock,
) -> ForkLocalL2Poststate:
    poststate = ForkLocalL2Poststate(
        authority,
        authority.protocol,
        candidate,
        rows_by_block,
        migration_output,
        prestate_commitment,
        poststate_commitment,
        pre_cursor,
        post_cursor,
        pre_last_applied_l2_block,
        post_last_applied_l2_block,
        target_protocol_version,
        target_manifest_hash,
        clock.block_number,
        clock.timestamp,
        "PENDING",
        _FORK_LOCAL_L2_POSTSTATE_CAPABILITY,
    )
    return replace(
        poststate,
        seal=authority._opaque_seal(
            b"TAIKO_FORK_LOCAL_L2_POSTSTATE_SEAL_V1\x00",
            poststate.digest,
        ),
    )


def replay_verified_migration_output_on_l2_for_test(
    protocol: Protocol,
    output: VerifiedMigrationExecutionOutput,
    router: ActiveSettlementRouter,
) -> ForkLocalL2Poststate | None:
    """Build an immutable migration fork; never switch canonical L2 state."""

    result = _execute_verified_migration_l2_replay_for_test(
        protocol,
        output,
        router,
        persist=False,
    )
    if result is None:
        return None
    prestate_commitment, poststate_commitment = result
    inbox = protocol.inbox_apply_router
    return _sealed_fork_local_l2_poststate_for_test(
        protocol._inbox_execution_authority,
        candidate=output.candidate,
        rows_by_block=(output.rows,),
        migration_output=output,
        prestate_commitment=prestate_commitment,
        poststate_commitment=poststate_commitment,
        pre_cursor=output.start_cursor,
        post_cursor=output.end_cursor,
        pre_last_applied_l2_block=inbox.last_applied_l2_block,
        post_last_applied_l2_block=(
            output.post_inbox_last_applied_l2_block
        ),
        target_protocol_version=output.target_protocol_version,
        target_manifest_hash=output.target_manifest_hash,
        # A fork-local migration replay exists before the L1 transaction lands.
        # Zero is an explicit "not yet observed" sentinel: neither the
        # transition statement nor this sealed node-local snapshot predicts a
        # future landing block or timestamp.
        clock=Clock(0, 0),
    )


def replay_prepared_candidate_on_l2_for_test(
    authority: InboxValidityExecutionAuthority,
    candidate: Candidate,
    rows_by_block: tuple[tuple[InboxRowV2, ...], ...],
    clock: Clock,
) -> ForkLocalL2Poststate | None:
    """Build an immutable normal/recovery fork without canonical pollution."""

    if (type(authority) is not InboxValidityExecutionAuthority
            or type(clock) is not Clock):
        return None
    protocol = authority.protocol
    history = protocol.versioned_history
    if type(history) is not VersionedSettlementHistory:
        return None
    pre_cursor = protocol.inbox_apply_router.next_queue_index
    pre_last = protocol.inbox_apply_router.last_applied_l2_block
    result = _execute_prepared_candidate_l2_replay_for_test(
        authority,
        candidate,
        rows_by_block,
        clock,
        persist=False,
    )
    if result is None:
        return None
    prestate_commitment, poststate_commitment = result
    release_hash = b"\x00" * 32
    if candidate.blocks[0].release_activation:
        router = history._router_authority
        registration = (
            router.registrations.get(
                candidate.blocks[0].release_protocol_version
            ) if type(router) is ActiveSettlementRouter else None
        )
        matches = tuple(
            manifest for manifest
            in (
                registration.release_manifests_by_adapter.values()
                if type(registration) is SettlementRegistration else ()
            )
            if authority._manifest_hash_matches(
                manifest, candidate.blocks[0].release_manifest_hash
            )
        )
        if len(matches) != 1:
            return None
        release_hash = matches[0].commitment
    return _sealed_fork_local_l2_poststate_for_test(
        authority,
        candidate=candidate,
        rows_by_block=rows_by_block,
        migration_output=None,
        prestate_commitment=prestate_commitment,
        poststate_commitment=poststate_commitment,
        pre_cursor=pre_cursor,
        post_cursor=candidate.tip.message_end,
        pre_last_applied_l2_block=pre_last,
        post_last_applied_l2_block=candidate.end_l2_block_number,
        target_protocol_version=history.protocol_version,
        target_manifest_hash=release_hash,
        clock=clock,
    )


def select_canonical_l2_poststate_for_test(
    poststate: ForkLocalL2Poststate,
) -> bool:
    """Switch the node-local canonical fork only after exact L1 success."""

    if (type(poststate) is not ForkLocalL2Poststate
            or poststate.seal != poststate.authority._opaque_seal(
                b"TAIKO_FORK_LOCAL_L2_POSTSTATE_SEAL_V1\x00",
                poststate.digest,
            )
            or l2_execution_state_commitment_for_test(poststate.protocol)
                != poststate.prestate_commitment):
        return False
    protocol = poststate.protocol
    history = protocol.versioned_history
    candidate = poststate.candidate
    expected_core = CanonicalCore(
        candidate.end_l2_block_number,
        candidate.tip.block_hash,
        candidate.tip.slot,
        candidate.end_state_root,
        candidate.tip.message_end,
        candidate.winning_data_commitment,
        candidate.next_base_fee,
        candidate.next_excess_blob_gas,
        candidate.end_terminal_root,
        candidate.end_terminal_count,
    )
    migration_output = poststate.migration_output
    if (type(history) is not VersionedSettlementHistory
            or history.protocol_version != poststate.target_protocol_version
            or protocol.forced_queue.cursor != poststate.post_cursor):
        return False
    if migration_output is not None:
        router = history._router_authority
        if type(router) is not ActiveSettlementRouter:
            return False
        registration = router.registrations.get(
            poststate.target_protocol_version
        )
        receipt = router.activation_receipts.get((
            migration_output.router_generation,
            migration_output.target_manifest_hash,
        ))
        predecessor = (
            None if type(registration) is not SettlementRegistration
            else router.registrations.get(registration.predecessor_version)
        )
        predecessor_protocol = (
            None if type(predecessor) is not SettlementRegistration
            else predecessor.settlement.live_protocol
        )
        if (migration_output.candidate is not candidate
                or migration_output.target_manifest_hash
                    != poststate.target_manifest_hash
                or protocol.core != migration_output.base_core
                or protocol.mode is not Mode.PREACTIVE
                or history.core != expected_core
                or router.active_version != poststate.target_protocol_version
                or type(registration) is not SettlementRegistration
                or type(predecessor_protocol) is not Protocol
                or (
                    receipt is not None
                    and (
                        type(receipt) is not MigrationActivationReceipt
                        or receipt.new_target != history.address
                        or receipt.new_protocol_version
                            != history.protocol_version
                        or receipt.new_authorization_id
                            != protocol.seat_authorization_id
                    )
                )
                or registration.settlement is not history
                or registration.release_manifest_hash
                    != poststate.target_manifest_hash
                # The actual L1 landing is observed only through the installed
                # canonical registration/history, never predicted by the
                # verifier statement or pre-landing fork snapshot.
                or registration.activation_block
                    != history.last_canonical_l1_block
                or migration_output.output_core != expected_core):
            return False
        result = _execute_verified_migration_l2_replay_for_test(
            protocol,
            migration_output,
            router,
            persist=True,
            expected_poststate_commitment=poststate.poststate_commitment,
        )
        if result is not None:
            # This is a node-local canonical-fork selection after observing
            # the L1 activation receipt. It is not part of Router acceptance.
            protocol.canonical = Canonical(
                copy.deepcopy(expected_core), history.last_canonical_l1_block
            )
            protocol.mode = Mode.NORMAL
            protocol.release_activation_pending = False
            protocol.pending_release_protocol_version = 0
            protocol.pending_release_manifest_hash = ""
            protocol.seat_generation = (
                receipt.seat_generation
                if type(receipt) is MigrationActivationReceipt
                else predecessor_protocol.seat_generation
            )
            protocol.first_v2_block_number = (
                predecessor_protocol.first_v2_block_number
            )
            protocol.last_canonical_execution_digest = (
                candidate_inbox_execution_digest(candidate)
            )
    else:
        if (protocol.last_canonical_execution_digest
                != candidate_inbox_execution_digest(candidate)
                or protocol.core != expected_core
                or history.core != expected_core
                or history.last_canonical_l1_block
                    != poststate.l1_block_number):
            return False
        result = _execute_prepared_candidate_l2_replay_for_test(
            poststate.authority,
            candidate,
            poststate.rows_by_block,
            Clock(poststate.l1_block_number, poststate.l1_timestamp),
            persist=True,
            expected_poststate_commitment=poststate.poststate_commitment,
        )
    return result is not None


def replay_candidate_queue_range_on_l2_for_test(
    authority: InboxValidityExecutionAuthority,
    candidate: Candidate,
    clock: Clock,
) -> ForkLocalL2Poststate | None:
    """Fixture convenience for reconstructing exact Inbox calldata rows."""

    if type(authority) is not InboxValidityExecutionAuthority:
        return None
    messages = authority.protocol.messages
    rows_by_block: list[tuple[InboxRowV2, ...]] = []
    for block in candidate.blocks:
        rows: list[InboxRowV2] = []
        for index in range(block.message_start, block.message_end):
            queued = messages[index]
            if type(queued) is Message and queued.kind is ForceKind.USER_TX:
                rows.append((index, 0, UINT32_MAX, "", None))
            elif type(queued) is BridgeQueueDescriptorV11:
                rows.append((
                    index,
                    5,
                    UINT32_MAX,
                    inbox_kind1_result(index, queued),
                    queued,
                ))
            else:
                return None
        rows_by_block.append(tuple(rows))
    return replay_prepared_candidate_on_l2_for_test(
        authority, candidate, tuple(rows_by_block), clock
    )


@dataclass
class InboxApplyRouterV2:
    """Lifetime dispatcher for mixed-domain forced-credit rows."""

    address: str = "inbox-apply"
    registrar: str = "terminal-domain-registrar"
    runtime_hash: str = "code:inbox-apply"
    configuration_hash: str = ""
    next_queue_index: int = 0
    last_applied_l2_block: int = -1
    routes: dict[str, InboxRoute] = field(default_factory=dict)
    _terminal_registrar_authority: object | None = field(
        default=None, init=False, compare=False, repr=False
    )

    def __post_init__(self) -> None:
        expected = f"config:inbox-apply:{self.registrar}"
        if (not self.address or not self.registrar
                or self.runtime_hash != "code:inbox-apply"
                or self.configuration_hash not in {"", expected}):
            raise ValueError("InboxApply lifetime deployment is invalid")
        object.__setattr__(self, "configuration_hash", expected)

    def __setattr__(self, name: str, value: object) -> None:
        if name in {
            "address", "registrar", "runtime_hash", "configuration_hash"
        } and name in self.__dict__:
            raise AttributeError(f"InboxApply {name} is immutable")
        object.__setattr__(self, name, value)

    def _bind_terminal_registrar(
        self, registrar: "TerminalDomainRegistrarV2"
    ) -> bool:
        if (type(registrar) is not TerminalDomainRegistrarV2
                or registrar.address != self.registrar
                or registrar.inbox_router is not self):
            return False
        existing = self._terminal_registrar_authority
        if existing is not None:
            return existing is registrar
        object.__setattr__(self, "_terminal_registrar_authority", registrar)
        return True

    def _register_route_from_registrar(
        self,
        domain_id: str,
        store: InboxCreditStoreV2,
        destination_bridge: str,
        store_codehash: str,
        *,
        registrar: "TerminalDomainRegistrarV2",
        manifest: ReleaseManifestV2,
    ) -> bool:
        if (registrar is not self._terminal_registrar_authority
                or type(registrar) is not TerminalDomainRegistrarV2
                or registrar.inbox_router is not self
                or manifest.destination_domain_id != domain_id
                or manifest.destination_bridge != destination_bridge
                or registrar.authority.releases.get(
                    manifest.protocol_version
                ) != manifest.commitment
                or not manifest.structurally_valid()
                or not domain_id
                or store.authorized_inbox_apply != self.address
                or store.destination_domain_id != domain_id
                or store.destination_bridge != destination_bridge
                or not store_codehash):
            return False
        if store.runtime_codehash != store_codehash:
            return False
        route = InboxRoute(
            store, destination_bridge, store_codehash,
            store.route_config_hash,
            manifest.protocol_version,
            manifest.commitment,
            manifest.execution_profile_hash,
            manifest.destination_chain_id,
        )
        existing = self.routes.get(domain_id)
        if existing is not None:
            return existing == route
        if any(row.store is store for row in self.routes.values()):
            return False
        if not store._bind_inbox_apply(self):
            return False
        self.routes[domain_id] = route
        return True

    def apply(
        self,
        batch: AuthenticatedInboxBatch,
        rows: tuple[InboxRowV2, ...],
    ) -> bool:
        if type(batch) is not AuthenticatedInboxBatch:
            return False
        if (batch.inbox is not self
                or not batch.authority.valid_for(batch, self, rows)):
            return False
        if not self._apply_verified_rows(
                rows,
                force_start=batch.force_start,
                l2_block_number=batch.l2_block_number,
                evm_timestamp=batch.evm_timestamp,
                authority=batch.authority,
                capability=_INBOX_APPLY_ROWS_CAPABILITY):
            return False
        batch.authority.consume(batch)
        return True

    def _apply_verified_rows(
        self,
        rows: tuple[InboxRowV2, ...],
        *,
        force_start: int,
        l2_block_number: int,
        evm_timestamp: int,
        authority: InboxValidityExecutionAuthority,
        capability: object,
    ) -> bool:
        """Execute proof-authenticated calldata; caller supplies no auth flag."""

        if (capability is not _INBOX_APPLY_ROWS_CAPABILITY
                or type(authority) is not InboxValidityExecutionAuthority
                or authority.protocol.inbox_apply_router is not self
                or authority._execution_frame is None):
            return False
        try:
            process_by = checked_u64_add(
                evm_timestamp,
                BRIDGE_PROCESS_TTL_SECONDS,
                "InboxApply processBy",
            )
        except ValueError:
            return False
        if (not 0 <= len(rows) <= MAX_FORCE_MESSAGES
                or force_start != self.next_queue_index
                or l2_block_number <= self.last_applied_l2_block
                or tuple(row[0] for row in rows)
                    != tuple(range(
                        self.next_queue_index,
                        self.next_queue_index + len(rows)))):
            return False
        staged: list[
            tuple[str, InboxCreditStoreV2 | None, str, InboxPin | None]
        ] = []
        seen_credits: set[tuple[str, str]] = set()
        for index, disposition, tx_index, result_hash, descriptor in rows:
            if disposition != 5:
                if (descriptor is not None
                        or disposition not in range(5)
                        or (disposition < 4 and
                            (tx_index != UINT32_MAX or result_hash))
                        or (disposition == 4 and
                            (not 0 <= tx_index < UINT32_MAX
                             or not result_hash))):
                    return False
                staged.append(("", None, "", None))
                continue
            if (type(descriptor) is not BridgeQueueDescriptorV11
                    or not descriptor.structurally_valid()
                    or tx_index != UINT32_MAX):
                return False
            domain_id = descriptor.destination_domain_id
            credit_id = descriptor.credit_id
            route = self.routes.get(domain_id)
            expected_result = inbox_kind1_result(index, descriptor)
            if (route is None or result_hash != expected_result
                    or route.store.runtime_codehash != route.store_codehash
                    or route.store.route_config_hash != route.store_config_hash
                    or route.store.authorized_inbox_apply != self.address
                    or route.store.destination_bridge
                        != route.destination_bridge
                    or route.store.destination_domain_id != domain_id
                    or (domain_id, credit_id) in seen_credits):
                return False
            seen_credits.add((domain_id, credit_id))
            existing = route.store.pins.get(credit_id)
            if existing is not None:
                if existing.result_hash != result_hash:
                    return False
            staged.append((domain_id, route.store, credit_id,
                           inbox_pin_from_descriptor(
                               descriptor,
                               queue_index=index,
                               result_hash=result_hash,
                               process_by=process_by,
                               route=route,
                           )))

        runs: list[
            tuple[InboxCreditStoreV2, list[tuple[str, InboxPin]]]
        ] = []
        for _, store, credit_id, pin in staged:
            if store is None:
                if runs:
                    runs.append((None, []))
                continue
            if not runs or runs[-1][0] is not store:
                runs.append((store, []))
            assert pin is not None
            runs[-1][1].append((credit_id, pin))
        journal: list[tuple[InboxCreditStoreV2, str, InboxPin | None]] = []
        count_journal: dict[int, tuple[InboxCreditStoreV2, int]] = {}
        for store, run in runs:
            if store is None:
                continue
            count_journal.setdefault(id(store), (store, store.pinned_count))
            for credit_id, _ in run:
                journal.append((store, credit_id, store.pins.get(credit_id)))
            returned = store._pin_batch_from_router(
                tuple(run), process_by=process_by, router=self)
            writes_match = all(
                store.pins.get(credit_id) == pin
                for credit_id, pin in run)
            if returned != INBOX_BATCH_OK_V2_WORD or not writes_match:
                for touched_store, credit_id, prior in reversed(journal):
                    if prior is None:
                        touched_store.pins.pop(credit_id, None)
                    else:
                        touched_store.pins[credit_id] = prior
                for touched_store, prior_count in count_journal.values():
                    touched_store.pinned_count = prior_count
                return False
        self.next_queue_index += len(rows)
        self.last_applied_l2_block = l2_block_number
        return True


@dataclass
class TerminalAccumulatorV2:
    """Protocol-lifetime append-only terminal vector with immutable old writers."""

    domains: dict[str, str]
    registrar: str = "terminal-domain-registrar"
    address: str = "terminal-accumulator"
    runtime_hash: str = "code:accumulator"
    configuration_hash: str = "cfg:accumulator"
    leaves: list[str] = field(default_factory=list)
    terminalized_pinned_count: dict[str, int] = field(default_factory=dict)
    append_return_length: int = 32
    append_return_padding_ok: bool = True
    _terminal_registrar_authority: object | None = field(
        default=None, init=False, compare=False, repr=False
    )
    _destination_bridge_authorities: dict[str, object] = field(
        default_factory=dict, init=False, compare=False, repr=False
    )
    _terminalized_credits: set[tuple[str, str]] = field(
        default_factory=set, init=False, compare=False, repr=False
    )

    def __post_init__(self) -> None:
        if (not self.registrar or not self.address
                or self.runtime_hash != "code:accumulator"
                or self.configuration_hash != "cfg:accumulator"):
            raise ValueError("terminal accumulator deployment is invalid")
        if (any(domain_id not in self.domains
                or type(count) is not int
                or not 0 <= count <= UINT64_MAX
                for domain_id, count
                in self.terminalized_pinned_count.items())):
            raise ValueError("terminal pinned counter is invalid")
        for domain_id in self.domains:
            self.terminalized_pinned_count.setdefault(domain_id, 0)

    def __setattr__(self, name: str, value: object) -> None:
        if name in {
            "registrar", "address", "runtime_hash", "configuration_hash"
        } and name in self.__dict__:
            raise AttributeError(f"terminal accumulator {name} is immutable")
        object.__setattr__(self, name, value)

    @property
    def count(self) -> int:
        return len(self.leaves)

    @property
    def root(self) -> str:
        return terminal_merkle_root(self.leaves)

    def _bind_terminal_registrar(
        self, registrar: "TerminalDomainRegistrarV2"
    ) -> bool:
        if (type(registrar) is not TerminalDomainRegistrarV2
                or registrar.address != self.registrar
                or registrar.accumulator is not self):
            return False
        existing = self._terminal_registrar_authority
        if existing is not None:
            return existing is registrar
        object.__setattr__(self, "_terminal_registrar_authority", registrar)
        return True

    def _register_domain_from_registrar(
        self,
        domain_id: str,
        bridge: str,
        *,
        registrar: "TerminalDomainRegistrarV2",
        manifest: ReleaseManifestV2,
    ) -> bool:
        if (registrar is not self._terminal_registrar_authority
                or type(registrar) is not TerminalDomainRegistrarV2
                or registrar.accumulator is not self
                or manifest.destination_domain_id != domain_id
                or manifest.destination_bridge != bridge
                or registrar.authority.releases.get(
                    manifest.protocol_version
                ) != manifest.commitment
                or not manifest.structurally_valid()):
            return False
        existing = self.domains.get(domain_id)
        if existing is not None:
            return (existing == bridge
                    and domain_id in self.terminalized_pinned_count)
        if not domain_id or not bridge or bridge in self.domains.values():
            return False
        self.domains[domain_id] = bridge
        self.terminalized_pinned_count[domain_id] = 0
        return True

    def _bind_destination_bridge_once(
        self, domain_id: str, bridge: object
    ) -> bool:
        if (type(bridge) is not DestinationBridgeLedger
                or bridge.terminal_accumulator is not self
                or bridge.local_domain_id != domain_id
                or self.domains.get(domain_id) != bridge.address):
            return False
        existing = self._destination_bridge_authorities.get(domain_id)
        if existing is not None:
            return existing is bridge
        self._destination_bridge_authorities[domain_id] = bridge
        return True

    def append_terminal(self, *, caller: DestinationBridgeLedger,
                        credit_id: str) -> int | None:
        registrar = self._terminal_registrar_authority
        route = (
            registrar.inbox_router.routes.get(caller.local_domain_id)
            if type(registrar) is TerminalDomainRegistrarV2 else None
        )
        pin = (
            route.store.pins.get(credit_id)
            if route is not None else None
        )
        key = (caller.local_domain_id, credit_id)
        if (self._destination_bridge_authorities.get(
                caller.local_domain_id
            ) is not caller
                or route is None
                or route.destination_bridge != caller.address
                or route.store is not caller.inbox_store
                or type(pin) is not InboxPin
                or key in self._terminalized_credits
                or self.count >= UINT64_MAX
                or not caller.terminal_commitment_gas_ok
                or caller.terminal_commitment_return_length
                    != TERMINAL_COMMITMENT_ABI_BYTES):
            return None
        commitment = caller.terminal_commitment_v2(credit_id)
        if commitment is None:
            return None
        (
            domain_id, bridge, terminal, terminal_index,
            liquidity_settlement_hash,
        ) = commitment
        if (self.domains.get(domain_id) != bridge or bridge != caller.address
                or not credit_id or terminal not in {"DONE", "FAILED"}
                or terminal_index != APPENDING_SENTINEL
                or (terminal == "DONE"
                    and liquidity_settlement_hash == "00" * 32)
                or (terminal == "FAILED"
                    and liquidity_settlement_hash != "00" * 32)):
            return None
        index = self.count
        self.leaves.append(_terminal_leaf_bytes(
            index, domain_id, bridge, credit_id, terminal,
            liquidity_settlement_hash,
        ).hex())
        self._terminalized_credits.add(key)
        self.terminalized_pinned_count[domain_id] = checked_u64_add(
            self.terminalized_pinned_count.get(domain_id, 0),
            1,
            "terminalized pinned count",
        )
        return index


@dataclass(frozen=True)
class ReleaseComponentV2:
    address: str
    runtime_hash: str
    config_hash: str


@dataclass(frozen=True)
class DestinationBridgeDescriptorV2:
    bridge: str
    facade_runtime_hash: str
    storage_layout_hash: str
    bridge_kernel_profile_hash: str
    inbox_credit_store: str
    terminal_accumulator: str
    terminal_domain_registrar: str
    destination_chain_id: int = 167_000
    native_quota_manager: str = DESTINATION_NATIVE_QUOTA_MANAGER
    native_liquidity_pool_policy: str = NATIVE_LIQUIDITY_POOL_POLICY
    native_liquidity_pool: str = NATIVE_LIQUIDITY_POOL
    native_liquidity_pool_runtime_hash: str = (
        NATIVE_LIQUIDITY_POOL_RUNTIME_HASH
    )
    native_liquidity_pool_configuration_hash: str = (
        NATIVE_LIQUIDITY_POOL_CONFIGURATION_HASH
    )
    v1_official_vaults: tuple[str, ...] = V1_OFFICIAL_VAULT_ADDRESSES
    privileged_target_denyset: tuple[str, ...] = (
        V2_PRIVILEGED_DESTINATION_ADDRESSES
    )
    post_call_gas_reserve: int = V2_POST_CALL_GAS_RESERVE
    role: str = BRIDGE_ROLE_DESTINATION_ONLY
    native_quota_manager_runtime_hash: str = (
        NATIVE_QUOTA_MANAGER_RUNTIME_HASH
    )
    native_quota_period: int = NATIVE_QUOTA_PERIOD_SECONDS
    native_eth_quota: int = 2 * DESTINATION_NATIVE_LIQUIDITY_FLOOR
    pauser: str = "bridge-pauser"
    signal_service: str = "signal-service"
    deployment_descriptor: ImmutableBridgeDeploymentDescriptorV2 | None = None

    def __post_init__(self) -> None:
        if self.deployment_descriptor is None:
            bridge_config = destination_bridge_component_config_hash(
                self,
                topology="IMMUTABLE_NONPROXY",
                account_runtime_hash=self.facade_runtime_hash,
            )
            object.__setattr__(self, "deployment_descriptor",
                ImmutableBridgeDeploymentDescriptorV2(
                    self.role,
                    self.destination_chain_id,
                    self.bridge,
                    self.facade_runtime_hash,
                    bridge_config,
                    self.storage_layout_hash,
                    self.pauser,
                    self.signal_service,
                    self.native_quota_manager,
                    self.native_quota_manager_runtime_hash,
                    native_quota_manager_configuration_hash(
                        address=self.native_quota_manager,
                        bridge=self.bridge,
                        quota_period=self.native_quota_period,
                        eth_quota=self.native_eth_quota,
                    ),
                    self.native_quota_period,
                    self.native_eth_quota,
                    tuple(sorted({
                        self.inbox_credit_store,
                        self.terminal_accumulator,
                        self.terminal_domain_registrar,
                    })),
                    EMPTY_V2_BRIDGE_STATE_COMMITMENT,
                )
            )

    @property
    def execution_hash(self) -> str:
        config_hash = destination_bridge_component_config_hash(
            self,
            topology=self.deployment_descriptor.topology,
            account_runtime_hash=self.facade_runtime_hash,
        )
        encoded = b"".join((
            _model_address20(self.bridge),
            _model_fixed_bytes32(self.facade_runtime_hash),
            _model_fixed_bytes32(config_hash),
            _model_fixed_bytes32(self.storage_layout_hash),
            _model_fixed_bytes32(self.bridge_kernel_profile_hash),
            _model_address20(self.inbox_credit_store),
            _model_address20(self.terminal_accumulator),
            _model_address20(self.terminal_domain_registrar),
            _model_address20(self.native_quota_manager),
            _model_address20(self.native_liquidity_pool),
        ))
        if len(encoded) != 248:
            raise AssertionError(
                "DestinationBridgeDescriptorV2 width drifted"
            )
        return keccak256(b"".join((
            D_DESTINATION_BRIDGE_EXECUTION,
            _model_uint(len(encoded), 4,
                        "destination Bridge descriptor length"),
            encoded,
        ))).hex()

    @property
    def invocation_policy_hash(self) -> str:
        return canonical_invocation_policy(
            self.privileged_target_denyset
        )[1]


def destination_bridge_component_config_hash(
    descriptor: DestinationBridgeDescriptorV2,
    *, topology: str, account_runtime_hash: str,
) -> str:
    if (type(descriptor) is not DestinationBridgeDescriptorV2
            or topology != "IMMUTABLE_NONPROXY"
            or account_runtime_hash != descriptor.facade_runtime_hash):
        raise ValueError("destination immutable Bridge config is invalid")
    config = b"".join((
        _model_fixed_bytes32(descriptor.storage_layout_hash),
        _model_fixed_bytes32(descriptor.bridge_kernel_profile_hash),
        _model_address20(descriptor.inbox_credit_store),
        _model_address20(descriptor.terminal_accumulator),
        _model_address20(descriptor.terminal_domain_registrar),
        _model_address20(descriptor.native_quota_manager),
        _model_address20(descriptor.native_liquidity_pool),
    ))
    if len(config) != 164:
        raise AssertionError("destination Bridge component config drifted")
    return keccak256(b"".join((
        D_COMPONENT_CONFIG,
        _model_uint(10, 1, "destination Bridge component kind"),
        _model_uint(len(config), 2,
                    "destination Bridge component config length"),
        config,
    ))).hex()


def destination_infrastructure_hash(
    components: tuple[ReleaseComponentV2, ...],
) -> str:
    if (type(components) is not tuple or len(components) != 10
            or any(type(row) is not ReleaseComponentV2
                   or not row.address or not row.runtime_hash
                   or not row.config_hash for row in components)):
        raise ValueError("destination infrastructure graph is invalid")
    encoded = b"".join(
        _model_address20(row.address)
        + _model_fixed_bytes32(row.runtime_hash)
        + _model_fixed_bytes32(row.config_hash)
        for row in components
    )
    if len(encoded) != 840:
        raise AssertionError("destination infrastructure width drifted")
    return keccak256(b"".join((
        D_DESTINATION_INFRASTRUCTURE,
        _model_uint(len(encoded), 4,
                    "destination infrastructure length"),
        encoded,
    ))).hex()


@dataclass(frozen=True)
class ReleaseManifestV2:
    protocol_version: int
    settlement_chain_id: int
    destination_chain_id: int
    destination_genesis_hash: str
    execution_profile_hash: str
    manifest_namespace: str
    destination_namespace: str
    anchor: str
    anchor_runtime_hash: str
    destination_domain_id: str
    destination_bridge: str
    destination_bridge_execution_hash: str
    destination_bridge_descriptor: DestinationBridgeDescriptorV2
    destination_infrastructure_hash: str
    migration_transition_verifier: MigrationTransitionVerifierDescriptor
    ingress_authorization_root: bytes
    native_liquidity_pool: str
    pool_runtime_hash: str
    pool_configuration_hash: str
    components: tuple[ReleaseComponentV2, ...]
    execution_profile: ExecutionProfile = field(compare=False, repr=False)

    @property
    def canonical_abi(self) -> bytes:
        """Exact static 58-word ReleaseManifestV2 ABI tuple."""

        descriptor = self.destination_bridge_descriptor
        words = (
            _model_uint(self.protocol_version, 32, "release protocol version"),
            _model_uint(self.settlement_chain_id, 32, "settlement chain id"),
            _model_uint(self.destination_chain_id, 32, "destination chain id"),
            _model_fixed_bytes32(self.destination_genesis_hash),
            _model_fixed_bytes32(self.execution_profile_hash),
            _model_fixed_bytes32(self.manifest_namespace),
            _model_fixed_bytes32(self.destination_namespace),
            bytes(12) + _model_address20(self.anchor),
            _model_fixed_bytes32(self.anchor_runtime_hash),
            _model_fixed_bytes32(self.destination_domain_id),
            bytes(12) + _model_address20(self.destination_bridge),
            _model_fixed_bytes32(self.destination_bridge_execution_hash),
            bytes(12) + _model_address20(descriptor.bridge),
            _model_fixed_bytes32(descriptor.facade_runtime_hash),
            _model_fixed_bytes32(self.components[9].config_hash),
            _model_fixed_bytes32(descriptor.storage_layout_hash),
            _model_fixed_bytes32(descriptor.bridge_kernel_profile_hash),
            bytes(12) + _model_address20(descriptor.inbox_credit_store),
            bytes(12) + _model_address20(descriptor.terminal_accumulator),
            bytes(12) + _model_address20(descriptor.terminal_domain_registrar),
            bytes(12) + _model_address20(descriptor.native_quota_manager),
            bytes(12) + _model_address20(descriptor.native_liquidity_pool),
            _model_fixed_bytes32(self.destination_infrastructure_hash),
            _model_fixed_bytes32(
                self.migration_transition_verifier.commitment
            ),
            self.ingress_authorization_root,
            bytes(12) + _model_address20(self.native_liquidity_pool),
            _model_fixed_bytes32(self.pool_runtime_hash),
            _model_fixed_bytes32(self.pool_configuration_hash),
            *(word for row in self.components for word in (
                bytes(12) + _model_address20(row.address),
                _model_fixed_bytes32(row.runtime_hash),
                _model_fixed_bytes32(row.config_hash),
            )),
        )
        encoded = b"".join(words)
        if (len(words) != RELEASE_MANIFEST_V2_ABI_WORDS
                or len(encoded) != RELEASE_MANIFEST_V2_BYTES):
            raise AssertionError("release manifest ABI geometry drifted")
        return encoded

    @property
    def commitment(self) -> bytes:
        return keccak256(RELEASE_MANIFEST_V2_TYPEHASH + self.canonical_abi)

    @property
    def registration_commitment(self) -> bytes:
        encoded = b"".join((
            _model_uint(self.protocol_version, 8,
                        "registration protocol version"),
            _model_fixed_bytes32(self.commitment),
            _model_uint(self.destination_chain_id, 32,
                        "registration destination chain id"),
            _model_fixed_bytes32(self.destination_namespace),
            _model_fixed_bytes32(self.destination_domain_id),
            _model_address20(self.destination_bridge),
            _model_fixed_bytes32(self.destination_infrastructure_hash),
            _model_fixed_bytes32(self.execution_profile_hash),
        ))
        if len(encoded) != 220:
            raise AssertionError(
                "destination registration commitment width drifted"
            )
        return keccak256(D_DESTINATION_REGISTRATION + encoded)

    @property
    def canonical_destination_descriptor(self) -> DestinationIngressDescriptor:
        if len(self.components) != 10:
            raise ValueError("release has no canonical destination topology")
        return DestinationIngressDescriptor(
            self.destination_chain_id,
            self.destination_genesis_hash,
            self.components[0].address,
            self.components[1].address,
            self.components[2].address,
            self.components[3].address,
            self.components[4].address,
            self.components[5].address,
            self.components[6].address,
            self.components[7].address,
            self.components[8].address,
            self.destination_bridge,
            self.destination_bridge_execution_hash,
            self.destination_infrastructure_hash,
            self.destination_namespace,
        )

    def structurally_valid(self) -> bool:
        addresses = tuple(row.address for row in self.components)
        descriptor = self.destination_bridge_descriptor
        deployment = descriptor.deployment_descriptor
        independent_accounts = addresses + (
            descriptor.native_quota_manager,
            descriptor.pauser,
            descriptor.signal_service,
        )
        try:
            expected_infrastructure_hash = destination_infrastructure_hash(
                self.components
            )
        except ValueError:
            return False
        try:
            expected_domain_id = (
                self.canonical_destination_descriptor.destination_domain_id
            )
        except ValueError:
            return False
        return (self.protocol_version > 0
                and 0 < self.settlement_chain_id <= UINT64_MAX
                and 0 < self.destination_chain_id <= UINT64_MAX
                and all((self.destination_genesis_hash,
                         self.execution_profile_hash,
                         self.manifest_namespace, self.destination_namespace,
                         self.anchor,
                         self.anchor_runtime_hash,
                         self.destination_domain_id, self.destination_bridge,
                         self.destination_bridge_execution_hash,
                         self.destination_infrastructure_hash))
                and type(self.ingress_authorization_root) is bytes
                and len(self.ingress_authorization_root) == 32
                and type(self.migration_transition_verifier)
                    is MigrationTransitionVerifierDescriptor
                and self.migration_transition_verifier.structurally_valid()
                and type(self.execution_profile) is ExecutionProfile
                and self.execution_profile.structurally_valid()
                and self.execution_profile.execution_profile_hash
                    == self.execution_profile_hash
                and self.execution_profile
                    .migration_transition_verifier_descriptor
                    == self.migration_transition_verifier
                and len(self.components) == 10
                and all(row.address and row.runtime_hash and row.config_hash
                        for row in self.components)
                and len(set(addresses)) == 10
                and len(set(independent_accounts))
                    == len(independent_accounts)
                and self.destination_infrastructure_hash
                    == expected_infrastructure_hash
                and self.destination_domain_id == expected_domain_id
                and self.components[8] == ReleaseComponentV2(
                    self.native_liquidity_pool,
                    self.pool_runtime_hash,
                    self.pool_configuration_hash,
                )
                and self.native_liquidity_pool
                    == descriptor.native_liquidity_pool
                and self.components[9].address == self.destination_bridge
                and descriptor.bridge == self.destination_bridge
                and descriptor.execution_hash
                    == self.destination_bridge_execution_hash
                and descriptor.inbox_credit_store
                    == self.components[4].address
                and descriptor.terminal_accumulator
                    == self.components[7].address
                and descriptor.terminal_domain_registrar
                    == self.components[6].address
                and descriptor.destination_chain_id
                    == self.destination_chain_id
                and descriptor.role
                    == BRIDGE_ROLE_DESTINATION_ONLY
                and bool(descriptor.native_quota_manager)
                and descriptor.native_quota_manager
                    == destination_native_quota_manager_address(
                        self.destination_bridge
                    )
                and descriptor.native_quota_manager_runtime_hash
                    == NATIVE_QUOTA_MANAGER_RUNTIME_HASH
                and descriptor.native_quota_period > 0
                and descriptor.native_eth_quota > 0
                and descriptor.native_liquidity_pool_policy
                    == NATIVE_LIQUIDITY_POOL_POLICY
                and descriptor.native_liquidity_pool
                    == NATIVE_LIQUIDITY_POOL
                and descriptor.native_liquidity_pool_runtime_hash
                    == NATIVE_LIQUIDITY_POOL_RUNTIME_HASH
                and descriptor
                    .native_liquidity_pool_configuration_hash
                    == NATIVE_LIQUIDITY_POOL_CONFIGURATION_HASH
                and descriptor.v1_official_vaults
                    == V1_OFFICIAL_VAULT_ADDRESSES
                and descriptor.privileged_target_denyset
                    == tuple(sorted({
                        "0x" + "00" * 20,
                        *(row.address for row in self.components),
                        descriptor.pauser,
                        descriptor.native_quota_manager,
                        descriptor.native_liquidity_pool,
                        *V2_PRIVILEGED_DESTINATION_ADDRESSES,
                    }, key=_model_address20))
                and bool(descriptor.invocation_policy_hash)
                and descriptor.post_call_gas_reserve
                    == V2_POST_CALL_GAS_RESERVE
                and type(deployment) is ImmutableBridgeDeploymentDescriptorV2
                and deployment.structurally_valid()
                and deployment.role == descriptor.role
                and deployment.chain_id == descriptor.destination_chain_id
                and deployment.bridge == descriptor.bridge
                and deployment.account_runtime_hash
                    == descriptor.facade_runtime_hash
                and deployment.account_runtime_hash
                    == self.components[9].runtime_hash
                and deployment.account_configuration_hash
                    == self.components[9].config_hash
                and deployment.storage_layout_hash
                    == descriptor.storage_layout_hash
                and deployment.pauser == descriptor.pauser
                and deployment.signal_service == descriptor.signal_service
                and deployment.native_quota_manager
                    == descriptor.native_quota_manager
                and deployment.native_quota_manager_runtime_hash
                    == descriptor.native_quota_manager_runtime_hash
                and deployment.native_quota_manager_configuration_hash
                    == native_quota_manager_configuration_hash(
                        address=descriptor.native_quota_manager,
                        bridge=descriptor.bridge,
                        quota_period=descriptor.native_quota_period,
                        eth_quota=descriptor.native_eth_quota,
                    )
                and deployment.native_quota_period
                    == descriptor.native_quota_period
                and deployment.native_eth_quota
                    == descriptor.native_eth_quota
                and deployment.v2_endpoints == tuple(sorted({
                    descriptor.inbox_credit_store,
                    descriptor.terminal_accumulator,
                    descriptor.terminal_domain_registrar,
                }))
                and deployment.initial_v2_state_commitment
                    == EMPTY_V2_BRIDGE_STATE_COMMITMENT
                and self.components[9].config_hash
                    == destination_bridge_component_config_hash(
                        descriptor,
                        topology=deployment.topology,
                        account_runtime_hash=deployment.account_runtime_hash,
                    ))


def historical_v2_privileged_policy_compatible(
    prior: ReleaseManifestV2,
    successor: ReleaseManifestV2,
) -> bool:
    """Prevent late privilege from reaching an old domain/Bridge context."""

    if (type(prior) is not ReleaseManifestV2
            or type(successor) is not ReleaseManifestV2
            or not prior.structurally_valid()
            or not successor.structurally_valid()):
        return False
    reuses_release_account = (
        prior.destination_domain_id == successor.destination_domain_id
        or prior.destination_bridge == successor.destination_bridge
    )
    lifetime_component_indices = (3, 5, 6, 7)
    lifetime_graph_exact = all(
        prior.components[index] == successor.components[index]
        for index in lifetime_component_indices
    )
    return lifetime_graph_exact and not reuses_release_account


def release_system_calldata(
    manifest: ReleaseManifestV2, retirement_queue_count: int,
) -> bytes:
    """Exact static activateRelease(manifest,uint64) calldata."""

    if (type(manifest) is not ReleaseManifestV2
            or not manifest.structurally_valid()
            or type(retirement_queue_count) is not int
            or not 0 <= retirement_queue_count <= UINT64_MAX):
        raise ValueError("release system calldata is not canonical")
    calldata = (
        ACTIVATE_RELEASE_V2_SELECTOR
        + manifest.canonical_abi
        + retirement_queue_count.to_bytes(32, "big")
    )
    if len(calldata) != ACTIVATE_RELEASE_V2_CALLDATA_BYTES:
        raise AssertionError("release activation calldata geometry drifted")
    return calldata


def release_system_calldata_hash(
    manifest: ReleaseManifestV2, retirement_queue_count: int,
) -> str:
    return keccak256(
        release_system_calldata(manifest, retirement_queue_count)
    ).hex()


@dataclass
class EndpointActivationStateV2:
    """Prestate of the fresh V2 deployment bundle authenticated by tx0."""

    store_domain_unset: bool = True
    store_pins_empty: bool = True
    store_sealer_live: bool = True
    bridge_account_absent: bool = True
    bridge_accounting_empty: bool = True
    bridge_sealer_live: bool = True

    @property
    def activatable(self) -> bool:
        return (self.store_domain_unset and self.store_pins_empty
                and self.store_sealer_live and self.bridge_account_absent
                and self.bridge_accounting_empty and self.bridge_sealer_live)

    def seal(self) -> bool:
        if not self.activatable:
            return False
        self.store_domain_unset = False
        self.store_sealer_live = False
        self.bridge_account_absent = False
        self.bridge_sealer_live = False
        return True


def endpoint_activation_projection(
    state: EndpointActivationStateV2,
) -> tuple[object, ...]:
    """Commit the exact endpoint-local prestate without object identity."""

    if type(state) is not EndpointActivationStateV2:
        raise ValueError("endpoint activation state has wrong type")
    return tuple(
        getattr(state, name)
        for name in EndpointActivationStateV2.__dataclass_fields__
    )


@dataclass(frozen=True)
class ObservedNativeQuotaManagerStateV2:
    """Exact fresh immutable V2-only quota-manager account and state."""

    address: str
    runtime_hash: str
    configuration_hash: str
    bridge: str
    erc20_vault: str
    quota_period: int
    quota: int
    available: int
    updated_at: int
    owner: str
    pending_owner: str

    def exact_for(
        self, deployment: ImmutableBridgeDeploymentDescriptorV2,
    ) -> bool:
        return (
            self.address == deployment.native_quota_manager
            and self.runtime_hash
                == deployment.native_quota_manager_runtime_hash
            and self.configuration_hash
                == deployment.native_quota_manager_configuration_hash
            and self.bridge == deployment.bridge
            and self.erc20_vault == ""
            and self.quota_period == deployment.native_quota_period
            and self.quota == deployment.native_eth_quota
            and self.available == self.quota
            and self.updated_at == 0
            and self.owner == "" and self.pending_owner == ""
        )

    @property
    def static_identity(self) -> tuple[object, ...]:
        return (
            self.address, self.runtime_hash, self.configuration_hash,
            self.bridge, self.erc20_vault, self.quota_period,
            self.quota, self.owner, self.pending_owner,
        )


@dataclass
class BridgeDeploymentStateV2:
    """Exact fresh immutable destination Bridge account under the L2 root."""

    address: str
    account_runtime_hash: str
    account_configuration_hash: str
    storage_layout_hash: str
    pauser: str
    signal_service: str
    quota_manager_state: ObservedNativeQuotaManagerStateV2
    v2_endpoints: tuple[str, ...]
    balance: int
    next_message_id: int
    status_entries: tuple[tuple[str, str], ...]
    pull_credit_entries: tuple[tuple[str, int], ...]
    total_liability: int
    terminal_index_entries: tuple[tuple[str, int], ...]
    v2_active: bool = False
    activation_surplus: int | None = None

    @property
    def v2_state_commitment(self) -> str:
        if (self.next_message_id == 0 and not self.status_entries
                and not self.pull_credit_entries
                and self.total_liability == 0
                and not self.terminal_index_entries):
            return EMPTY_V2_BRIDGE_STATE_COMMITMENT
        return "v2-state:bridge:" + hashlib.sha256(
            repr((self.next_message_id, self.status_entries,
                  self.pull_credit_entries, self.total_liability,
                  self.terminal_index_entries)).encode()
        ).hexdigest()

    def static_identity(self, manifest: ReleaseManifestV2) -> tuple[object, ...]:
        return (
            self.address, self.account_runtime_hash,
            self.account_configuration_hash, self.storage_layout_hash,
            self.pauser, self.signal_service,
            self.quota_manager_state.static_identity, *self.v2_endpoints,
            manifest.components[9].config_hash,
        )

    @property
    def mutable_state_commitment(self) -> str:
        return hashlib.sha256(
            b"TAIKO_BRIDGE_MUTABLE_STATE_V2\x00" + repr((
                self.balance, self.next_message_id, self.status_entries,
                self.pull_credit_entries, self.total_liability,
                self.terminal_index_entries, self.v2_active,
                self.activation_surplus,
                self.quota_manager_state.available,
                self.quota_manager_state.updated_at, self.v2_state_commitment,
            )).encode()
        ).hexdigest()

    @property
    def observation_commitment(self) -> str:
        return hashlib.sha256(
            b"TAIKO_OBSERVED_IMMUTABLE_BRIDGE_STATE_V2\x00"
            + repr((self.static_identity_projection,
                    self.mutable_state_commitment)).encode()
        ).hexdigest()

    @property
    def static_identity_projection(self) -> tuple[object, ...]:
        return (
            self.address, self.account_runtime_hash,
            self.account_configuration_hash, self.storage_layout_hash,
            self.pauser, self.signal_service,
            self.quota_manager_state.static_identity, self.v2_endpoints,
        )

    def authenticates(
        self, manifest: ReleaseManifestV2, *,
        known_identity: tuple[object, ...] | None = None,
        require_fresh: bool = True,
    ) -> bool:
        if (type(manifest) is not ReleaseManifestV2
                or not manifest.structurally_valid()):
            return False
        bridge_row = manifest.components[9]
        descriptor = manifest.destination_bridge_descriptor
        deployment = descriptor.deployment_descriptor
        exact = (
            type(deployment) is ImmutableBridgeDeploymentDescriptorV2
            and deployment.structurally_valid()
            and self.address == manifest.destination_bridge
            and self.address == deployment.bridge
            and self.account_runtime_hash == bridge_row.runtime_hash
            and self.account_runtime_hash == deployment.account_runtime_hash
            and self.account_configuration_hash
                == deployment.account_configuration_hash
            and self.storage_layout_hash == deployment.storage_layout_hash
            and self.pauser == deployment.pauser
            and self.signal_service == deployment.signal_service
            and self.v2_endpoints == deployment.v2_endpoints
            and type(self.quota_manager_state)
                is ObservedNativeQuotaManagerStateV2
            and self.quota_manager_state.exact_for(deployment)
            and type(self.balance) is int
            and self.balance >= 0
            and type(self.next_message_id) is int
            and 0 <= self.next_message_id <= UINT64_MAX
            and type(self.status_entries) is tuple
            and type(self.pull_credit_entries) is tuple
            and type(self.total_liability) is int
            and 0 <= self.total_liability <= self.balance
            and type(self.terminal_index_entries) is tuple
            and all(type(amount) is int and amount >= 0
                    for _, amount in self.pull_credit_entries)
            and sum(amount for _, amount in self.pull_credit_entries)
                <= self.total_liability
            and bridge_row.config_hash
                == destination_bridge_component_config_hash(
                    descriptor,
                    topology=deployment.topology,
                    account_runtime_hash=self.account_runtime_hash,
                )
        )
        fresh = (
            not self.v2_active and self.activation_surplus is None
            and self.next_message_id == 0
            and not self.status_entries and not self.pull_credit_entries
            and self.total_liability == 0 and not self.terminal_index_entries
            and self.v2_state_commitment
                == deployment.initial_v2_state_commitment
        )
        return (exact and (not require_fresh or fresh)
                and (known_identity is None
                     or known_identity == self.static_identity(manifest)))

    def upgrade_to_and_call(
        self, _implementation: object, _calldata: bytes = b"",
    ) -> bool:
        return False

    def transfer_ownership(self, _new_owner: str) -> bool:
        return False

    def accept_ownership(self, _caller: str) -> bool:
        return False

    def reinitialize(self, _version: int, _calldata: bytes = b"") -> bool:
        return False

    def _activate_from_registrar(
        self, manifest: ReleaseManifestV2, *,
        registrar: "TerminalDomainRegistrarV2", capability: object,
    ) -> "DestinationBridgeActivationReceiptV2 | None":
        frame = getattr(registrar, "_activation_frame", None)
        if (capability is not _DESTINATION_BRIDGE_ACTIVATION_CAPABILITY
                or type(registrar) is not TerminalDomainRegistrarV2
                or type(frame) is not tuple or len(frame) != 4
                or frame[0] != id(manifest)
                or frame[1] != manifest.commitment
                or frame[3] != release_system_calldata_hash(
                    manifest, frame[2]
                )
                or registrar.authority.releases.get(manifest.protocol_version)
                    != manifest.commitment
                or not self.authenticates(manifest, require_fresh=False)
                or self.v2_active
                or self.next_message_id != 0
                or self.status_entries or self.pull_credit_entries
                or self.total_liability != 0
                or self.terminal_index_entries):
            return None
        self.activation_surplus = self.balance
        self.v2_active = True
        pending = DestinationBridgeActivationReceiptV2(
            manifest.commitment,
            manifest.destination_domain_id,
            manifest.destination_bridge,
            registrar.active_destination_bridge,
            frame[2],
            self.activation_surplus,
            self.balance,
            self.observation_commitment,
            "PENDING",
            _DESTINATION_BRIDGE_ACTIVATION_CAPABILITY,
        )
        return replace(
            pending,
            seal=hashlib.sha256(
                b"TAIKO_DESTINATION_BRIDGE_ACTIVATION_RECEIPT_V2\x00"
                + pending.digest.encode()
            ).hexdigest(),
        )


_DESTINATION_BRIDGE_ACTIVATION_CAPABILITY = object()


@dataclass(frozen=True, eq=False)
class DestinationBridgeActivationReceiptV2:
    manifest_commitment: bytes
    destination_domain_id: str
    destination_bridge: str
    prior_active_bridge: str
    retirement_queue_count: int
    activation_surplus: int
    bridge_postbalance: int
    active_state_commitment: str
    seal: str
    _capability: object = field(compare=False, repr=False)

    @property
    def digest(self) -> str:
        return hashlib.sha256(
            b"TAIKO_DESTINATION_BRIDGE_ACTIVATION_DIGEST_V2\x00"
            + repr((
                self.manifest_commitment,
                self.destination_domain_id,
                self.destination_bridge,
                self.prior_active_bridge,
                self.retirement_queue_count,
                self.activation_surplus,
                self.bridge_postbalance,
                self.active_state_commitment,
            )).encode()
        ).hexdigest()

    def valid_for(
        self, manifest: ReleaseManifestV2,
        deployment: BridgeDeploymentStateV2,
    ) -> bool:
        return (
            self._capability is _DESTINATION_BRIDGE_ACTIVATION_CAPABILITY
            and type(manifest) is ReleaseManifestV2
            and type(deployment) is BridgeDeploymentStateV2
            and deployment.v2_active
            and type(deployment.activation_surplus) is int
            and self.activation_surplus == deployment.activation_surplus
            and 0 <= self.activation_surplus <= SEAT_UINT256_MAX
            and self.bridge_postbalance == deployment.balance
            and self.bridge_postbalance <= SEAT_UINT256_MAX
            and self.bridge_postbalance == self.activation_surplus
            and self.manifest_commitment == manifest.commitment
            and self.destination_domain_id == manifest.destination_domain_id
            and self.destination_bridge == manifest.destination_bridge
            and type(self.retirement_queue_count) is int
            and 0 <= self.retirement_queue_count <= UINT64_MAX
            and self.active_state_commitment
                == deployment.observation_commitment
            and self.seal == hashlib.sha256(
                b"TAIKO_DESTINATION_BRIDGE_ACTIVATION_RECEIPT_V2\x00"
                + self.digest.encode()
            ).hexdigest()
        )


def fresh_bridge_deployment_projection(
    manifest: ReleaseManifestV2, *, balance: int | None = None,
) -> BridgeDeploymentStateV2:
    """Derive the exact fresh Bridge storage projection for a manifest."""

    if (type(manifest) is not ReleaseManifestV2
            or not manifest.structurally_valid()):
        raise ValueError("test Bridge deployment manifest is invalid")
    descriptor = manifest.destination_bridge_descriptor
    deployment = descriptor.deployment_descriptor
    if (type(deployment) is not ImmutableBridgeDeploymentDescriptorV2
            or not deployment.structurally_valid()):
        raise ValueError("test immutable Bridge descriptor is invalid")
    observed_balance = 0 if balance is None else balance
    if (type(observed_balance) is not int
            or not 0 <= observed_balance <= SEAT_UINT256_MAX):
        raise ValueError("fresh test V2 Bridge balance is invalid")
    quota = ObservedNativeQuotaManagerStateV2(
        deployment.native_quota_manager,
        deployment.native_quota_manager_runtime_hash,
        deployment.native_quota_manager_configuration_hash,
        deployment.bridge,
        "",
        deployment.native_quota_period,
        deployment.native_eth_quota,
        deployment.native_eth_quota,
        0,
        "",
        "",
    )
    return BridgeDeploymentStateV2(
        deployment.bridge,
        deployment.account_runtime_hash,
        deployment.account_configuration_hash,
        deployment.storage_layout_hash,
        deployment.pauser,
        deployment.signal_service,
        quota,
        deployment.v2_endpoints,
        observed_balance,
        0,
        (),
        (),
        0,
        (),
        False,
        None,
    )


def bridge_deployment_state_for_test(
    manifest: ReleaseManifestV2, *, balance: int | None = None,
) -> BridgeDeploymentStateV2:
    """Fixture alias for the normative fresh deployment projection."""

    return fresh_bridge_deployment_projection(manifest, balance=balance)


@dataclass
class AnchorV4Model:
    address: str
    runtime_hash: str
    finalized_l1_manifest_hash: bytes
    active_release_manifest_hash: bytes = b""

    def authenticate(self, manifest: ReleaseManifestV2) -> bool:
        if (not manifest.structurally_valid()
                or manifest.anchor != self.address
                or manifest.anchor_runtime_hash != self.runtime_hash
                or manifest.commitment != self.finalized_l1_manifest_hash):
            return False
        self.active_release_manifest_hash = manifest.commitment
        return True


@dataclass
class ProtocolReleaseAuthorityV2:
    """Lifetime authority reached by the manifest Anchor in a system tx."""

    address: str = "release-authority"
    runtime_hash: str = "code:authority"
    configuration_hash: str = "cfg:authority"
    system_sender: str = "system:anchor"
    releases: dict[int, bytes] = field(default_factory=dict)
    release_manifests: dict[tuple[int, bytes], ReleaseManifestV2] = field(
        default_factory=dict
    )

    def __setattr__(self, name: str, value: object) -> None:
        if name in {
            "address", "runtime_hash", "configuration_hash", "system_sender"
        } and name in self.__dict__:
            raise AttributeError(f"release authority {name} is immutable")
        object.__setattr__(self, name, value)

    def activate(self, manifest: ReleaseManifestV2, *, caller: AnchorV4Model,
                 tx_origin: str) -> bool:
        manifest_hash = manifest.commitment
        if (not manifest.structurally_valid()
                or caller.address != manifest.anchor
                or caller.runtime_hash != manifest.anchor_runtime_hash
                or tx_origin != self.system_sender
                or caller.active_release_manifest_hash != manifest_hash):
            return False
        existing = self.releases.get(manifest.protocol_version)
        if existing is not None:
            if existing != manifest_hash:
                return False
        else:
            self.releases[manifest.protocol_version] = manifest_hash
        self.release_manifests[
            (manifest.protocol_version, manifest_hash)
        ] = manifest
        return True


_NATIVE_LIQUIDITY_POOL_CAPABILITY = object()


