@dataclass
class NativeLiquidityPoolV2:
    """Permissionless lifetime LP escrow; tx0 never prefunds a Bridge."""

    address: str = NATIVE_LIQUIDITY_POOL
    runtime_hash: str = NATIVE_LIQUIDITY_POOL_RUNTIME_HASH
    configuration_hash: str = NATIVE_LIQUIDITY_POOL_CONFIGURATION_HASH
    destination_chain_id: int = 167_000
    balance: int = 0
    active: bool = False
    next_ticket_nonce: int = 0
    tickets: dict[str, NativeLiquidityTicketV2] = field(default_factory=dict)
    reservations: dict[str, NativeLiquidityReservationV2] = field(
        default_factory=dict
    )
    reserved_count_by_domain: dict[str, int] = field(default_factory=dict)
    deposited_total: int = 0
    consumed_total: int = 0
    withdrawn_total: int = 0
    reclaimed_total: int = 0
    _registrar_authority: object | None = field(
        default=None, init=False, compare=False, repr=False
    )
    _bridge_authorities: dict[str, object] = field(
        default_factory=dict, init=False, compare=False, repr=False
    )

    def __post_init__(self) -> None:
        if (self.address != NATIVE_LIQUIDITY_POOL
                or self.runtime_hash != NATIVE_LIQUIDITY_POOL_RUNTIME_HASH
                or self.configuration_hash
                    != NATIVE_LIQUIDITY_POOL_CONFIGURATION_HASH
                or not 0 < self.destination_chain_id <= SEAT_UINT256_MAX
                or type(self.balance) is not int or self.balance < 0):
            raise ValueError("native liquidity Pool is invalid")

    def __setattr__(self, name: str, value: object) -> None:
        if name in {
            "address", "runtime_hash", "configuration_hash",
            "destination_chain_id",
            "_registrar_authority",
        } and name in self.__dict__:
            raise AttributeError(f"native liquidity Pool {name} is immutable")
        object.__setattr__(self, name, value)

    @property
    def ticket_liability(self) -> int:
        return sum(
            ticket.amount for ticket in self.tickets.values()
            if ticket.state in {"AVAILABLE", "RESERVED"}
        )

    def reserved_count(self, domain_id: str) -> int:
        return self.reserved_count_by_domain.get(domain_id, 0)

    def _assert_accounting_invariant(self) -> None:
        expected_counts: dict[str, int] = {}
        reserved_tickets: set[str] = set()
        for credit_id, reservation in self.reservations.items():
            ticket = self.tickets.get(reservation.ticket_id)
            if (credit_id != reservation.credit_id or ticket is None
                    or ticket.ticket_id in reserved_tickets
                    or ticket.state != "RESERVED"
                    or ticket.amount != reservation.amount):
                raise AssertionError("native liquidity reservation is split")
            reserved_tickets.add(ticket.ticket_id)
            expected_counts[reservation.destination_domain_id] = (
                expected_counts.get(reservation.destination_domain_id, 0) + 1
            )
        if (any(
                (ticket.state == "RESERVED")
                != (ticket.ticket_id in reserved_tickets)
                for ticket in self.tickets.values())
                or any(count <= 0 for count in self.reserved_count_by_domain.values())
                or self.reserved_count_by_domain != expected_counts
                or self.balance < self.ticket_liability):
            raise AssertionError("native liquidity accounting invariant failed")

    def _snapshot(self) -> dict[str, object]:
        return copy.deepcopy({
            "balance": self.balance,
            "active": self.active,
            "next_ticket_nonce": self.next_ticket_nonce,
            "tickets": self.tickets,
            "reservations": self.reservations,
            "reserved_count_by_domain": self.reserved_count_by_domain,
            "deposited_total": self.deposited_total,
            "consumed_total": self.consumed_total,
            "withdrawn_total": self.withdrawn_total,
            "reclaimed_total": self.reclaimed_total,
        })

    def _restore(self, snapshot: dict[str, object]) -> None:
        for key, value in snapshot.items():
            object.__setattr__(self, key, copy.deepcopy(value))
        self._assert_accounting_invariant()

    def _bind_registrar_once(
        self, registrar: "TerminalDomainRegistrarV2"
    ) -> bool:
        if (type(registrar) is not TerminalDomainRegistrarV2
                or registrar.liquidity_pool is not self):
            return False
        if self._registrar_authority is not None:
            return self._registrar_authority is registrar
        object.__setattr__(self, "_registrar_authority", registrar)
        return True

    def _activate_from_registrar(
        self, manifest: ReleaseManifestV2, *,
        registrar: "TerminalDomainRegistrarV2", capability: object,
    ) -> bool:
        descriptor = manifest.destination_bridge_descriptor
        frame = getattr(registrar, "_activation_frame", None)
        if (capability is not _NATIVE_LIQUIDITY_POOL_CAPABILITY
                or registrar is not self._registrar_authority
                or type(frame) is not tuple or len(frame) != 4
                or frame[0] != id(manifest)
                or frame[1] != manifest.commitment
                or manifest.destination_chain_id != self.destination_chain_id
                or descriptor.native_liquidity_pool != self.address
                or descriptor.native_liquidity_pool_runtime_hash
                    != self.runtime_hash
                or descriptor.native_liquidity_pool_configuration_hash
                    != self.configuration_hash):
            return False
        self.active = True
        return True

    def _bind_destination_bridge_once(
        self, domain_id: str, bridge: "DestinationBridgeLedger"
    ) -> bool:
        registrar = self._registrar_authority
        if (not self.active or type(registrar) is not TerminalDomainRegistrarV2
                or type(bridge) is not DestinationBridgeLedger
                or bridge.local_domain_id != domain_id
                or bridge.release_manifest.destination_bridge_descriptor
                    .native_liquidity_pool != self.address
                or registrar.accumulator.domains.get(domain_id) != bridge.address):
            return False
        existing = self._bridge_authorities.get(domain_id)
        if existing is not None:
            return existing is bridge
        self._bridge_authorities[domain_id] = bridge
        return True

    def deposit(
        self, *, owner: str, l1_recipient: str, amount: int
    ) -> str | None:
        """Create one permissionless exact-amount ticket after launch."""

        if (not self.active or not owner or not l1_recipient
                or type(amount) is not int or amount <= 0
                or amount > SEAT_UINT256_MAX - self.balance
                or self.next_ticket_nonce == UINT64_MAX):
            return None
        nonce = self.next_ticket_nonce
        ticket_id = keccak256(b"".join((
            b"slot-chain-liquidity-ticket-v1",
            _model_uint(self.destination_chain_id, 32,
                        "ticket destination chain id"),
            _model_address20(self.address),
            _model_address20(owner),
            _model_address20(l1_recipient),
            _model_uint(nonce, 8, "ticket sequence"),
        ))).hex()
        if ticket_id in self.tickets:
            return None
        self.next_ticket_nonce = checked_u64_add(
            nonce, 1, "native liquidity ticket nonce"
        )
        self.tickets[ticket_id] = NativeLiquidityTicketV2(
            ticket_id, owner, l1_recipient, amount
        )
        self.balance += amount
        self.deposited_total = seat_checked_add(
            self.deposited_total, amount, "native liquidity deposited total"
        )
        self._assert_accounting_invariant()
        return ticket_id

    def reserve(
        self,
        ticket_id: str,
        bridge: "DestinationBridgeLedger",
        message_: IBridgeMessageV1,
        source: SourceContextV2,
        destination: DestinationContextV2,
        *,
        caller: str,
        now: int,
    ) -> bool:
        ticket = self.tickets.get(ticket_id)
        try:
            credit_id = destination_credit_id_v2(message_, source, destination)
            amount = seat_checked_add(
                message_.value, message_.fee,
                "native liquidity reservation amount",
            )
        except ValueError:
            return False
        pin = bridge._pin(credit_id, destination.destination_domain_id)
        status = bridge.status.get(credit_id, "NEW")
        quote = bridge.inbox_store.liquidity_quote_v2(credit_id)
        reservation_state = bridge.liquidity_reservation_state_v2(credit_id)
        expected_quote = (
            None if pin is None else b"".join((
                _model_fixed_bytes32(pin.result_hash),
                _model_uint(pin.value, 32, "liquidity quote value"),
                _model_uint(pin.execution_fee, 32,
                            "liquidity quote execution fee"),
                _model_uint(pin.liquidity_fee, 32,
                            "liquidity quote liquidity fee"),
                _model_uint(pin.process_by, 32,
                            "liquidity quote processBy"),
            ))
        )
        if (not self.active or ticket is None or ticket.owner != caller
                or ticket.state != "AVAILABLE" or ticket.amount != amount
                or self._bridge_authorities.get(bridge.local_domain_id)
                    is not bridge
                or not bridge._delivery_context_valid(
                    message_, source, destination, require_pin=True
                )
                or quote != expected_quote or len(quote or b"") != 160
                or reservation_state is None
                or len(reservation_state) != 160
                or pin is None or type(now) is not int
                or now > pin.process_by
                or status not in {"NEW", "RETRIABLE"}
                or credit_id in bridge.terminal_index
                or credit_id in self.reservations):
            return False
        ticket.state = "RESERVED"
        self.reservations[credit_id] = NativeLiquidityReservationV2(
            ticket_id, bridge.local_domain_id, bridge.address, credit_id,
            amount, ticket.l1_recipient,
        )
        self.reserved_count_by_domain[bridge.local_domain_id] = checked_u64_add(
            self.reserved_count(bridge.local_domain_id), 1,
            "native liquidity reserved count",
        )
        self._assert_accounting_invariant()
        return True

    def _consume_from_bridge(
        self, credit_id: str, *, bridge: "DestinationBridgeLedger",
        capability: object,
    ) -> NativeLiquiditySettlementV2 | None:
        reservation = self.reservations.get(credit_id)
        ticket = None if reservation is None else self.tickets.get(
            reservation.ticket_id
        )
        if (capability is not _NATIVE_LIQUIDITY_POOL_CAPABILITY
                or self._bridge_authorities.get(bridge.local_domain_id)
                    is not bridge
                or bridge._active_execution_frame is None
                or reservation is None or ticket is None
                or reservation.destination_domain_id != bridge.local_domain_id
                or reservation.destination_bridge != bridge.address
                or ticket.state != "RESERVED"
                or self.balance < reservation.amount):
            return None
        self.reservations.pop(credit_id)
        ticket.state = "CONSUMED"
        self.reserved_count_by_domain[bridge.local_domain_id] -= 1
        if self.reserved_count_by_domain[bridge.local_domain_id] == 0:
            self.reserved_count_by_domain.pop(bridge.local_domain_id)
        self.balance -= reservation.amount
        bridge.balance = seat_checked_add(
            bridge.balance, reservation.amount,
            "destination Bridge LP settlement funding",
        )
        self.consumed_total = seat_checked_add(
            self.consumed_total, reservation.amount,
            "native liquidity consumed total",
        )
        self._assert_accounting_invariant()
        return NativeLiquiditySettlementV2(
            reservation.ticket_id,
            reservation.l1_recipient,
            reservation.amount,
        )

    def _release_from_bridge(
        self, credit_id: str, *, bridge: "DestinationBridgeLedger",
        capability: object,
    ) -> bool:
        reservation = self.reservations.get(credit_id)
        if reservation is None:
            return True
        ticket = self.tickets.get(reservation.ticket_id)
        if (capability is not _NATIVE_LIQUIDITY_POOL_CAPABILITY
                or self._bridge_authorities.get(bridge.local_domain_id)
                    is not bridge
                or bridge._active_execution_frame is None or ticket is None
                or ticket.state != "RESERVED"):
            return False
        self.reservations.pop(credit_id)
        ticket.state = "AVAILABLE"
        self.reserved_count_by_domain[bridge.local_domain_id] -= 1
        if self.reserved_count_by_domain[bridge.local_domain_id] == 0:
            self.reserved_count_by_domain.pop(bridge.local_domain_id)
        self._assert_accounting_invariant()
        return True

    def withdraw_ticket(
        self, ticket_id: str, *, caller: str, recipient: str
    ) -> int:
        ticket = self.tickets.get(ticket_id)
        if (not self.active or ticket is None or ticket.owner != caller
                or not recipient or ticket.state != "AVAILABLE"
                or self.balance < ticket.amount):
            return 0
        ticket.state = "WITHDRAWN"
        self.balance -= ticket.amount
        self.withdrawn_total = seat_checked_add(
            self.withdrawn_total, ticket.amount,
            "native liquidity withdrawn total",
        )
        self._assert_accounting_invariant()
        return ticket.amount

@dataclass
class TerminalDomainRegistrarV2:
    """Lifetime registrar; endpoints come only from an authenticated manifest."""

    authority: ProtocolReleaseAuthorityV2
    accumulator: TerminalAccumulatorV2
    inbox_router: InboxApplyRouterV2
    liquidity_pool: NativeLiquidityPoolV2 = field(
        default_factory=NativeLiquidityPoolV2
    )
    address: str = "terminal-domain-registrar"
    runtime_hash: str = "code:registrar"
    configuration_hash: str = "cfg:registrar"
    registrations: dict[int, str] = field(default_factory=dict)
    bridge_identities: dict[str, tuple[str, ...]] = field(default_factory=dict)
    bridge_activation_receipts: dict[
        str, DestinationBridgeActivationReceiptV2
    ] = field(default_factory=dict)
    active_destination_bridge: str = ""
    retirement_queue_watermarks: dict[str, int] = field(default_factory=dict)
    _activation_frame: tuple[int, bytes, int, str] | None = field(
        default=None, init=False, compare=False, repr=False
    )

    def __post_init__(self) -> None:
        if (not self.address
                or self.runtime_hash != "code:registrar"
                or self.configuration_hash != "cfg:registrar"
                or self.address != self.inbox_router.registrar
                or self.address != self.accumulator.registrar
                or not self.liquidity_pool._bind_registrar_once(self)
                or not self.inbox_router._bind_terminal_registrar(self)
                or not self.accumulator._bind_terminal_registrar(self)):
            raise ValueError("terminal registrar authority graph is split")

    def _activate_domain_from_release(self, manifest: ReleaseManifestV2,
                        store: InboxCreditStoreV2, *,
                        observed_l2_components:
                            tuple[ReleaseComponentV2, ...],
                        observed_bridge_descriptor:
                            DestinationBridgeDescriptorV2,
                        endpoint_state: EndpointActivationStateV2,
                        bridge_deployment: BridgeDeploymentStateV2,
                        retirement_queue_watermark: int) -> bool:
        protocol_version = manifest.protocol_version
        manifest_hash = manifest.commitment
        domain_id = manifest.destination_domain_id
        bridge = manifest.destination_bridge
        store_row = manifest.components[4] if len(manifest.components) == 10 \
            else ReleaseComponentV2("", "", "")
        lifetime_rows_exact = (
            len(manifest.components) == 10
            and manifest.components[3] == ReleaseComponentV2(
                self.inbox_router.address,
                self.inbox_router.runtime_hash,
                self.inbox_router.configuration_hash,
            )
            and manifest.components[5] == ReleaseComponentV2(
                self.authority.address,
                self.authority.runtime_hash,
                self.authority.configuration_hash,
            )
            and manifest.components[6] == ReleaseComponentV2(
                self.address, self.runtime_hash, self.configuration_hash,
            )
            and manifest.components[7] == ReleaseComponentV2(
                self.accumulator.address,
                self.accumulator.runtime_hash,
                self.accumulator.configuration_hash,
            )
            and manifest.components[8] == ReleaseComponentV2(
                self.liquidity_pool.address,
                self.liquidity_pool.runtime_hash,
                self.liquidity_pool.configuration_hash,
            )
        )
        if (type(self._activation_frame) is not tuple
                or len(self._activation_frame) != 4
                or self._activation_frame[0] != id(manifest)
                or self._activation_frame[1] != manifest_hash
                or self._activation_frame[2] != retirement_queue_watermark
                or self._activation_frame[3]
                    != release_system_calldata_hash(
                        manifest, retirement_queue_watermark
                    )
                or not manifest.structurally_valid()
                or not lifetime_rows_exact
                or type(retirement_queue_watermark) is not int
                or not self.inbox_router.next_queue_index
                    <= retirement_queue_watermark <= UINT64_MAX
                or manifest.destination_bridge_descriptor
                    .native_liquidity_pool
                    != self.liquidity_pool.address
                or manifest.destination_bridge_descriptor
                    .native_liquidity_pool_runtime_hash
                    != self.liquidity_pool.runtime_hash
                or manifest.destination_bridge_descriptor
                    .native_liquidity_pool_configuration_hash
                    != self.liquidity_pool.configuration_hash
                or self.authority.releases.get(protocol_version) != manifest_hash
                or protocol_version in self.registrations
                or observed_l2_components != manifest.components[3:]
                or observed_bridge_descriptor
                    != manifest.destination_bridge_descriptor
                or store_row.address != store.address
                or store_row.runtime_hash != store.runtime_codehash
                or store_row.config_hash != store.component_config_hash
                or domain_id in self.inbox_router.routes
                or domain_id in self.accumulator.domains
                or bridge in self.bridge_identities
                or bridge in self.bridge_activation_receipts
                or not endpoint_state.activatable
                or not bridge_deployment.authenticates(
                    manifest, require_fresh=True)):
            return False
        prior_routes = dict(self.inbox_router.routes)
        prior_domains = dict(self.accumulator.domains)
        prior_terminalized_pinned_count = dict(
            self.accumulator.terminalized_pinned_count
        )
        prior_store_writer = store._inbox_apply_authority
        endpoint_snapshot = copy.deepcopy(endpoint_state)
        deployment_snapshot = copy.deepcopy(bridge_deployment.__dict__)
        pool_snapshot = self.liquidity_pool._snapshot()
        activation_receipt: DestinationBridgeActivationReceiptV2 | None = None
        if (not self.inbox_router._register_route_from_registrar(
                domain_id, store, bridge, store_row.runtime_hash,
                registrar=self, manifest=manifest)
                or not self.accumulator._register_domain_from_registrar(
                    domain_id, bridge, registrar=self, manifest=manifest)
                or not endpoint_state.seal()
                or not self.liquidity_pool._activate_from_registrar(
                    manifest,
                    registrar=self,
                    capability=_NATIVE_LIQUIDITY_POOL_CAPABILITY,
                )
                or (activation_receipt :=
                    bridge_deployment._activate_from_registrar(
                        manifest,
                        registrar=self,
                        capability=_DESTINATION_BRIDGE_ACTIVATION_CAPABILITY,
                    )) is None):
            self.inbox_router.routes = prior_routes
            self.accumulator.domains = prior_domains
            self.accumulator.terminalized_pinned_count = (
                prior_terminalized_pinned_count
            )
            object.__setattr__(
                store, "_inbox_apply_authority", prior_store_writer
            )
            endpoint_state.__dict__.update(endpoint_snapshot.__dict__)
            bridge_deployment.__dict__.clear()
            bridge_deployment.__dict__.update(deployment_snapshot)
            self.liquidity_pool._restore(pool_snapshot)
            return False
        self.bridge_identities[bridge] = bridge_deployment.static_identity(
            manifest
        )
        self.bridge_activation_receipts[bridge] = activation_receipt
        self.registrations[protocol_version] = manifest.registration_commitment
        if self.active_destination_bridge:
            self.retirement_queue_watermarks[
                self.active_destination_bridge
            ] = retirement_queue_watermark
        self.active_destination_bridge = bridge
        return True


def release_manifest_fixture(protocol_version: int, domain_id: str,
                             bridge: str, store: InboxCreditStoreV2,
                             anchor: str | None = None, *,
                             router: ActiveSettlementRouter) -> ReleaseManifestV2:
    _ = domain_id  # Legacy fixture argument; the canonical graph derives it.
    anchor_address = anchor or f"anchor:v{protocol_version}"
    adapter_address = {
        "bridge:A": "bridge-inbox-adapter",
        "bridge:B": "bridge-inbox-adapter:d2",
        "bridge:replacement": "bridge-inbox-adapter:replacement",
    }.get(bridge, f"bridge-inbox-adapter:{bridge}")
    source_descriptor = canonical_source_bridge_descriptor(
        router.settlement_chain_context_id, router
    )
    source_configuration = bridge_credit_registry_configuration_hash(
        address=source_descriptor.bridge_credit_registry,
        runtime_hash=BRIDGE_CREDIT_REGISTRY_RUNTIME_HASH,
        domain_registrar=source_descriptor.source_domain_registrar,
        frozen_bridge=source_descriptor.source_bridge,
        support_registry_address=source_descriptor.support_registry_address,
        support_registry_runtime_hash=(
            source_descriptor.support_registry_runtime_hash
        ),
        support_registry_configuration_hash=(
            source_descriptor.support_registry_configuration_hash
        ),
        source_chain_id=1,
        source_domain_id=source_descriptor.source_domain_id,
        source_registration_epoch=(
            source_descriptor.source_registration_epoch
        ),
        frozen_bridge_execution_hash=source_descriptor.bridge_execution_hash,
        source_descriptor_id=source_descriptor.descriptor_id,
    )
    source_bridge_configuration = (
        source_bridge_configuration_hash_for_descriptor(
            source_descriptor,
            source_descriptor.bridge_credit_registry,
            BRIDGE_CREDIT_REGISTRY_RUNTIME_HASH,
            source_configuration,
        )
    )
    adapter_configuration = bridge_ingress_component_configuration_hash(
        router_address=router.address,
        router_runtime_hash=router.runtime_hash,
        router_configuration_hash=router.configuration_hash,
        queue_address=router.forced_queue.address,
        queue_runtime_hash=router.forced_queue.runtime_hash,
        queue_configuration_hash=router.forced_queue.config_hash,
        source_registry_address=source_descriptor.bridge_credit_registry,
        source_registry_runtime_hash=BRIDGE_CREDIT_REGISTRY_RUNTIME_HASH,
        source_registry_configuration_hash=source_configuration,
        source_bridge_address=source_descriptor.source_bridge,
        source_bridge_runtime_hash=source_descriptor.bridge_facade_runtime_hash,
        source_bridge_configuration_hash_=source_bridge_configuration,
        seal_authority=router.version_manager,
    )
    components, bridge_descriptor, _, descriptor = (
        canonical_destination_release_topology(
            router,
            adapter_address=adapter_address,
            adapter_configuration_hash=adapter_configuration,
            destination_bridge=bridge,
        )
    )
    object.__setattr__(store, "address", components[4].address)
    object.__setattr__(store, "runtime_codehash", components[4].runtime_hash)
    object.__setattr__(
        store, "destination_domain_id", descriptor.destination_domain_id
    )
    registered = router.registrations.get(protocol_version)
    execution_profile = (
        registered.execution_profile
        if registered is not None
        else execution_profile_for_test(
            protocol_version, f"profile:{protocol_version}"
        )
    )
    return ReleaseManifestV2(
        protocol_version, 1, descriptor.destination_chain_id,
        descriptor.destination_genesis_hash,
        execution_profile.execution_profile_hash,
        "manifest:v2", "domain-namespace:v2",
        anchor_address,
        f"code:{anchor_address}",
        descriptor.destination_domain_id, bridge,
        bridge_descriptor.execution_hash, bridge_descriptor,
        descriptor.destination_infrastructure_hash,
        execution_profile.migration_transition_verifier_descriptor,
        router.registrations[router.active_version].ingress_authorization_root,
        NATIVE_LIQUIDITY_POOL,
        NATIVE_LIQUIDITY_POOL_RUNTIME_HASH,
        NATIVE_LIQUIDITY_POOL_CONFIGURATION_HASH,
        components,
        execution_profile)


_RELEASE_SYSTEM_EXECUTION_CAPABILITY = object()


def activate_release_transaction(
        authority: ProtocolReleaseAuthorityV2,
        registrar: TerminalDomainRegistrarV2, *,
        manifest: ReleaseManifestV2,
        execution_authority: InboxValidityExecutionAuthority,
        execution_capability: object,
        anchor: AnchorV4Model, store: InboxCreditStoreV2,
        observed_l2_components: tuple[ReleaseComponentV2, ...] | None = None,
        observed_bridge_descriptor: DestinationBridgeDescriptorV2 | None = None,
        endpoint_state: EndpointActivationStateV2 | None = None,
        bridge_deployment: BridgeDeploymentStateV2 | None = None,
        retirement_queue_watermark: int,
        ) -> bool:
    """Model the single system transaction and its all-or-revert EVM calls."""
    releases = dict(authority.releases)
    release_manifests = dict(authority.release_manifests)
    registrations = dict(registrar.registrations)
    bridge_identities = dict(registrar.bridge_identities)
    bridge_activation_receipts = dict(registrar.bridge_activation_receipts)
    active_destination_bridge = registrar.active_destination_bridge
    retirement_queue_watermarks = dict(
        registrar.retirement_queue_watermarks
    )
    liquidity_pool_snapshot = registrar.liquidity_pool._snapshot()
    routes = dict(registrar.inbox_router.routes)
    domains = dict(registrar.accumulator.domains)
    terminalized_pinned_count = dict(
        registrar.accumulator.terminalized_pinned_count
    )
    state = endpoint_state or EndpointActivationStateV2()
    endpoint_snapshot = copy.deepcopy(state)
    if type(bridge_deployment) is not BridgeDeploymentStateV2:
        return False
    deployment = bridge_deployment
    deployment_snapshot = copy.deepcopy(deployment.__dict__)
    active_manifest = anchor.active_release_manifest_hash
    authenticated = (
        execution_capability is _RELEASE_SYSTEM_EXECUTION_CAPABILITY
        and type(execution_authority) is InboxValidityExecutionAuthority
        and execution_authority.protocol.inbox_apply_router
            is registrar.inbox_router
        and type(retirement_queue_watermark) is int
        and retirement_queue_watermark
            == execution_authority.protocol.forced_queue.count
        and registrar is registrar.inbox_router
            ._terminal_registrar_authority
        and execution_authority._release_activation_frame
            == (
                id(manifest), manifest.commitment,
                retirement_queue_watermark,
                release_system_calldata_hash(
                    manifest, retirement_queue_watermark
                ),
            )
        and authority is registrar.authority
        and anchor.authenticate(manifest)
        and authority.activate(
            manifest, caller=anchor, tx_origin=authority.system_sender
        )
    )
    activated = False
    if authenticated:
        registrar._activation_frame = (
            id(manifest), manifest.commitment,
            retirement_queue_watermark,
            release_system_calldata_hash(
                manifest, retirement_queue_watermark
            ),
        )
        try:
            activated = registrar._activate_domain_from_release(
                manifest, store,
                observed_l2_components=(
                    manifest.components[3:] if observed_l2_components is None
                    else observed_l2_components),
                observed_bridge_descriptor=(
                    manifest.destination_bridge_descriptor
                    if observed_bridge_descriptor is None
                    else observed_bridge_descriptor),
                endpoint_state=state,
                bridge_deployment=deployment,
                retirement_queue_watermark=retirement_queue_watermark,
            )
        finally:
            registrar._activation_frame = None
    if not activated:
        authority.releases = releases
        authority.release_manifests = release_manifests
        registrar.registrations = registrations
        registrar.bridge_identities = bridge_identities
        registrar.bridge_activation_receipts = bridge_activation_receipts
        registrar.active_destination_bridge = active_destination_bridge
        registrar.retirement_queue_watermarks = retirement_queue_watermarks
        registrar.liquidity_pool._restore(liquidity_pool_snapshot)
        deployment.__dict__.clear()
        deployment.__dict__.update(deployment_snapshot)
        registrar.inbox_router.routes = routes
        registrar.accumulator.domains = domains
        registrar.accumulator.terminalized_pinned_count = (
            terminalized_pinned_count
        )
        anchor.active_release_manifest_hash = active_manifest
        state.__dict__.update(endpoint_snapshot.__dict__)
        return False
    return True


def execute_release_activation_for_test(
    execution_authority: InboxValidityExecutionAuthority,
    authority: ProtocolReleaseAuthorityV2,
    registrar: TerminalDomainRegistrarV2,
    **kwargs: object,
) -> bool:
    """Drive the exact tx0 call chain from a modeled verifier frame."""

    manifest = kwargs.get("manifest")
    if (type(execution_authority) is not InboxValidityExecutionAuthority
            or type(manifest) is not ReleaseManifestV2
            or execution_authority.protocol.inbox_apply_router
                is not registrar.inbox_router
            or execution_authority._release_activation_frame is not None):
        return False
    watermark = kwargs.get(
        "retirement_queue_watermark",
        execution_authority.protocol.forced_queue.count,
    )
    if (type(watermark) is not int
            or not 0 <= watermark <= UINT64_MAX):
        return False
    kwargs["retirement_queue_watermark"] = watermark
    execution_authority._release_activation_frame = (
        id(manifest), manifest.commitment, watermark,
        release_system_calldata_hash(manifest, watermark),
    )
    try:
        if "bridge_deployment" not in kwargs:
            kwargs["bridge_deployment"] = bridge_deployment_state_for_test(
                manifest
            )
        return activate_release_transaction(
            authority,
            registrar,
            execution_authority=execution_authority,
            execution_capability=_RELEASE_SYSTEM_EXECUTION_CAPABILITY,
            **kwargs,
        )
    finally:
        execution_authority._release_activation_frame = None


@dataclass(frozen=True)
class SourceContextV2:
    """Exact ten-word public SourceContextV2 plus internal durable fields."""

    protocol_version: int
    kind: int
    credit_id: str
    msg_hash: str
    source_domain_id: str
    source_registration_epoch: int
    source_bridge: str
    source_bridge_execution_hash: str
    source_emitted_at_block: int
    queue_index: int
    enqueue_by: int
    refund_mode: str
    refund_vault: str
    refund_capsule_hash: str
    escrow_id: str

    @property
    def bridge_execution_hash(self) -> str:
        return self.source_bridge_execution_hash

    @property
    def emitted_at_block(self) -> int:
        return self.source_emitted_at_block

    @property
    def abi(self) -> bytes:
        encoded = b"".join((
            _model_uint(self.protocol_version, 32, "context version"),
            _model_uint(self.kind, 32, "context kind"),
            _model_fixed_bytes32(self.credit_id),
            _model_fixed_bytes32(self.msg_hash),
            _model_fixed_bytes32(self.source_domain_id),
            _model_uint(self.source_registration_epoch, 32,
                        "context source epoch"),
            bytes(12) + _model_address20(self.source_bridge),
            _model_fixed_bytes32(self.source_bridge_execution_hash),
            _model_uint(self.source_emitted_at_block, 32,
                        "context emission block"),
            _model_uint(self.queue_index, 32, "context queue index"),
        ))
        if len(encoded) != 10 * 32:
            raise AssertionError("SourceContextV2 ABI width drifted")
        return encoded

    @property
    def context_hash(self) -> str:
        typehash = keccak256(
            b"SourceContextV2(uint64 protocolVersion,uint8 kind,"
            b"bytes32 creditId,bytes32 msgHash,bytes32 sourceDomainId,"
            b"uint64 sourceRegistrationEpoch,address sourceBridge,"
            b"bytes32 sourceBridgeExecutionHash,uint64 emittedAtBlock,"
            b"uint64 queueIndex)"
        )
        return keccak256(typehash + self.abi).hex()


@dataclass(frozen=True)
class DestinationContextV2:
    """Exact five-word public DestinationContextV2 plus internal queue index."""

    destination_chain_id: int
    destination_domain_id: str
    destination_bridge: str
    release_manifest_hash: bytes
    execution_profile_hash: str
    queue_index: int

    @property
    def abi(self) -> bytes:
        encoded = b"".join((
            _model_uint(self.destination_chain_id, 32,
                        "destination context chain id"),
            _model_fixed_bytes32(self.destination_domain_id),
            bytes(12) + _model_address20(self.destination_bridge),
            _model_fixed_bytes32(self.release_manifest_hash),
            _model_fixed_bytes32(self.execution_profile_hash),
        ))
        if len(encoded) != 5 * 32:
            raise AssertionError("DestinationContextV2 ABI width drifted")
        return encoded

    @property
    def context_hash(self) -> str:
        typehash = keccak256(
            b"DestinationContextV2(uint256 destinationChainId,"
            b"bytes32 destinationDomainId,address destinationBridge,"
            b"bytes32 releaseManifestHash,bytes32 executionProfileHash)"
        )
        return keccak256(typehash + self.abi).hex()


@dataclass(frozen=True)
class BridgeInvocationContextV2:
    """Authenticated V2 context exposed only during the exact destination CALL."""

    protocol_version: int
    bridge_kind: str
    credit_id: str
    msg_hash: str
    source_domain_id: str
    source_registration_epoch: int
    source_bridge: str
    source_bridge_execution_hash: str
    emitted_at_block: int
    queue_index: int
    destination_domain_id: str
    destination_bridge: str
    release_manifest_commitment: bytes
    execution_profile_hash: str


@dataclass(frozen=True)
class BridgeInvocationPolicyV2:
    """A future Bridge-trusting endpoint's release/epoch activation fence."""

    protocol_version: int
    bridge_kind: str
    source_domain_id: str
    source_registration_epoch: int
    source_bridge: str
    source_bridge_execution_hash: str
    minimum_emitted_at_block: int
    destination_domain_id: str
    destination_bridge: str
    release_manifest_commitment: bytes
    execution_profile_hash: str

    def accepts(self, context: BridgeInvocationContextV2 | None) -> bool:
        return (
            type(context) is BridgeInvocationContextV2
            and context.protocol_version == self.protocol_version
            and context.bridge_kind == self.bridge_kind
            and context.source_domain_id == self.source_domain_id
            and context.source_registration_epoch
                == self.source_registration_epoch
            and context.source_bridge == self.source_bridge
            and context.source_bridge_execution_hash
                == self.source_bridge_execution_hash
            and context.emitted_at_block >= self.minimum_emitted_at_block
            and context.destination_domain_id == self.destination_domain_id
            and context.destination_bridge == self.destination_bridge
            and context.release_manifest_commitment
                == self.release_manifest_commitment
            and context.execution_profile_hash == self.execution_profile_hash
        )


def destination_credit_id_v2(
    message_: IBridgeMessageV1,
    source: SourceContextV2,
    destination: DestinationContextV2,
    *,
    liquidity_fee: int | None = None,
) -> str:
    if (type(message_) is not IBridgeMessageV1
            or type(source) is not SourceContextV2
            or type(destination) is not DestinationContextV2):
        raise ValueError("destination Bridge context has the wrong type")
    if source.credit_id and liquidity_fee is None:
        return source.credit_id
    exact_liquidity_fee = 0 if liquidity_fee is None else liquidity_fee
    expected = BridgeAdapter.credit_id(
        message_.source_chain_id,
        source.source_domain_id,
        source.source_registration_epoch,
        source.source_bridge,
        destination.destination_domain_id,
        bridge_message_hash(message_),
        exact_liquidity_fee,
    )
    if source.credit_id and source.credit_id != expected:
        raise ValueError("destination Bridge credit identity is inconsistent")
    return source.credit_id or expected


def destination_result_hash_v11(
    message_: IBridgeMessageV1,
    source: SourceContextV2,
    destination: DestinationContextV2,
    *,
    liquidity_fee: int = 1,
) -> str:
    credit_id = destination_credit_id_v2(
        message_, source, destination, liquidity_fee=liquidity_fee
    )
    return keccak256(b"".join((
        b"slot-chain-bridge-credit-result-v11",
        _model_uint(destination.queue_index, 8, "result queue index"),
        _model_fixed_bytes32(credit_id),
        _model_fixed_bytes32(bridge_message_hash(message_)),
        _model_uint(message_.source_chain_id, 32, "result source chain id"),
        _model_fixed_bytes32(source.source_domain_id),
        _model_uint(source.source_registration_epoch, 8,
                    "result source epoch"),
        _model_address20(source.source_bridge),
        _model_fixed_bytes32(source.bridge_execution_hash),
        _model_uint(source.emitted_at_block, 8, "result emission block"),
        _model_fixed_bytes32(destination.destination_domain_id),
        _model_uint(message_.destination_chain_id, 32,
                    "result destination chain id"),
        _model_uint(source.enqueue_by, 8, "result enqueue deadline"),
        _model_address20(message_.sender),
        _model_address20(message_.source_owner),
        _model_address20(message_.destination_owner),
        _model_uint(message_.value, 32, "result value"),
        _model_uint(message_.fee, 8, "result execution fee"),
        _model_uint(liquidity_fee, 8, "result liquidity fee"),
        _model_fixed_bytes32(message_.data_hash),
        _model_uint(1 if source.refund_mode == "DIRECT" else 0, 1,
                    "result refund mode"),
        _model_address20(source.refund_vault, zero_if_empty=True),
        _model_fixed_bytes32(
            source.refund_capsule_hash, zero_if_empty=True
        ),
        _model_fixed_bytes32(source.escrow_id),
    ))).hex()


def destination_contexts_for_authorization(
    authorization: CreditAuthorization,
    *,
    queue_index: int,
) -> tuple[SourceContextV2, DestinationContextV2]:
    if type(authorization) is not CreditAuthorization:
        raise ValueError("destination context authorization is invalid")
    credit_id = BridgeAdapter.credit_id(
        authorization.src_chain_id,
        authorization.source_domain_id,
        authorization.src_epoch,
        authorization.src_bridge,
        authorization.destination_domain_id,
        authorization.msg_hash,
        authorization.liquidity_fee,
    )
    return (
        SourceContextV2(
            authorization.protocol_version,
            ForceKind.BRIDGE_CREDIT.value,
            credit_id,
            authorization.msg_hash,
            authorization.source_domain_id,
            authorization.src_epoch,
            authorization.src_bridge,
            authorization.bridge_execution_hash,
            authorization.emitted_at_block,
            queue_index,
            authorization.enqueue_by,
            authorization.refund_mode,
            authorization.refund_vault,
            "",
            authorization.escrow_id,
        ),
        DestinationContextV2(
            authorization.destination_chain_id,
            authorization.destination_domain_id,
            authorization.destination_bridge,
            authorization.release_manifest_hash,
            authorization.execution_profile_hash,
            queue_index,
        ),
    )


def destination_delivery_context_for_test(
    destination: "DestinationBridgeLedger",
    message_: IBridgeMessageV1,
    *,
    queue_index: int,
    source_domain_id: str = "domain:remote-source",
    source_bridge: str = "bridge:remote-source",
    bridge_execution_hash: str = "execution:remote-source",
    emitted_at_block: int = 1,
    enqueue_by: int = UINT64_MAX,
    refund_mode: str = "DIRECT",
    refund_vault: str = "",
    refund_capsule_hash: str = "",
    liquidity_fee: int = 1,
) -> tuple[SourceContextV2, DestinationContextV2]:
    """Build the fixed source/destination projection used by proof fixtures."""

    route = DestinationContextV2(
        destination.destination_chain_id,
        destination.local_domain_id,
        destination.address,
        destination.release_manifest.commitment,
        destination.release_manifest.execution_profile_hash,
        queue_index,
    )
    initial = SourceContextV2(
        destination.release_manifest.protocol_version,
        ForceKind.BRIDGE_CREDIT.value,
        "",
        bridge_message_hash(message_),
        source_domain_id,
        1,
        source_bridge,
        bridge_execution_hash,
        emitted_at_block,
        queue_index,
        enqueue_by,
        refund_mode,
        refund_vault,
        refund_capsule_hash,
        "",
    )
    credit_id = destination_credit_id_v2(
        message_, initial, route, liquidity_fee=liquidity_fee
    )
    return replace(
        initial,
        escrow_id=bridge_escrow_id(credit_id),
        credit_id=credit_id,
    ), route


def install_destination_pin_for_test(
    destination: "DestinationBridgeLedger",
    message_: IBridgeMessageV1,
    source: SourceContextV2,
    route: DestinationContextV2,
    *,
    now: int,
    liquidity_fee: int = 1,
) -> bool:
    """Install one proof-derived pin for isolated downstream tests."""

    if (type(destination) is not DestinationBridgeLedger
            or type(now) is not int or now < 0
            or not destination._delivery_context_valid(
                message_, source, route, require_pin=False)):
        return False
    try:
        credit_id = destination_credit_id_v2(
            message_, source, route, liquidity_fee=liquidity_fee
        )
        result_hash = destination_result_hash_v11(
            message_, source, route, liquidity_fee=liquidity_fee
        )
    except ValueError:
        return False
    expected = InboxPin(
        result_hash,
        checked_u64_add(
            now, BRIDGE_PROCESS_TTL_SECONDS, "test Inbox pin processBy"
        ),
        liquidity_fee,
        route.queue_index,
        message_.source_chain_id,
        source.source_domain_id,
        source.source_registration_epoch,
        source.source_bridge,
        route.destination_domain_id,
        bridge_message_hash(message_),
        source.context_hash,
        message_.value,
        message_.fee,
    )
    existing = destination.inbox_store.pins.get(credit_id)
    if existing is not None and existing.result_hash != result_hash:
        return False
    if existing is None:
        destination.inbox_store.pins[credit_id] = expected
        destination.inbox_store.pinned_count = checked_u64_add(
            destination.inbox_store.pinned_count,
            1,
            "test Inbox Store pinned count",
        )
    return True


def reserve_destination_liquidity_for_test(
    destination: "DestinationBridgeLedger",
    message_: IBridgeMessageV1,
    source: SourceContextV2,
    route: DestinationContextV2,
    *,
    now: int,
    owner: str = "test-liquidity-provider",
    l1_recipient: str = "test-liquidity-provider:l1",
) -> str | None:
    """Deposit and reserve one exact LP ticket for a pinned delivery."""

    if (type(destination) is not DestinationBridgeLedger
            or type(now) is not int or now < 0):
        return None
    try:
        amount = seat_checked_add(
            message_.value, message_.fee,
            "test native liquidity reservation amount",
        )
    except ValueError:
        return None
    if amount == 0:
        return ""
    pool = destination.liquidity_pool
    ticket_id = pool.deposit(
        owner=owner, l1_recipient=l1_recipient, amount=amount,
    )
    if ticket_id is None:
        return None
    if not pool.reserve(
        ticket_id,
        destination,
        message_,
        source,
        route,
        caller=owner,
        now=now,
    ):
        if pool.withdraw_ticket(
                ticket_id, caller=owner, recipient=owner) != amount:
            raise AssertionError("test LP reservation rollback failed")
        return None
    return ticket_id


def destination_bridge_for_test(
    manifest: ReleaseManifestV2,
    store: InboxCreditStoreV2,
    accumulator: TerminalAccumulatorV2,
    *,
    applications: tuple[BridgeCallReceiverV2, ...] = (),
    balance: int = 0,
    quota: int = DESTINATION_NATIVE_LIQUIDITY_FLOOR,
    available_gas: int = 10_000_000,
    base_fee: int = 1,
    timestamp: int = GENESIS_TIMESTAMP,
) -> "DestinationBridgeLedger":
    """Construct one independent destination execution graph for tests."""

    # Isolated Bridge tests still use the production-shaped lifetime graph:
    # exact Registrar -> InboxApply route -> Store and Registrar -> Accumulator.
    if accumulator._terminal_registrar_authority is None:
        fixture_authority = ProtocolReleaseAuthorityV2()
        fixture_inbox = InboxApplyRouterV2()
        fixture_registrar = TerminalDomainRegistrarV2(
            fixture_authority, accumulator, fixture_inbox
        )
        fixture_authority.releases[manifest.protocol_version] = (
            manifest.commitment
        )
        fixture_authority.release_manifests[
            (manifest.protocol_version, manifest.commitment)
        ] = manifest
        fixture_inbox.routes[manifest.destination_domain_id] = InboxRoute(
            store,
            manifest.destination_bridge,
            store.runtime_codehash,
            store.route_config_hash,
            manifest.protocol_version,
            manifest.commitment,
            manifest.execution_profile_hash,
            manifest.destination_chain_id,
        )
        # Do not consume the Store's one-shot writer binding in this fixture:
        # some integration tests subsequently bind the same deployment to the
        # proof-authorized InboxApply object. Terminal append authenticates the
        # exact Registrar route independently of that write capability.
        fixture_registrar.registrations[manifest.protocol_version] = (
            manifest.registration_commitment
        )
        fixture_registrar.bridge_identities[manifest.destination_bridge] = ()
        fixture_registrar.active_destination_bridge = (
            manifest.destination_bridge
        )
        fixture_registrar.liquidity_pool.active = True

    environment = L2ExecutionEnvironmentV2(
        manifest.destination_chain_id,
        applications,
        available_gas,
        base_fee,
        timestamp,
    )
    descriptor = manifest.destination_bridge_descriptor
    quota_manager = FrozenNativeQuotaManagerV2(
        descriptor.native_quota_manager,
        manifest.destination_bridge,
        descriptor.native_quota_period,
        descriptor.native_eth_quota,
    )
    if type(quota) is not int or not 0 <= quota <= descriptor.native_eth_quota:
        raise ValueError("test destination quota state is invalid")
    quota_manager._state.available = min(quota, quota_manager._state.quota)
    if (type(balance) is not int
            or not 0 <= balance <= SEAT_UINT256_MAX):
        raise ValueError("test destination activation balance is invalid")
    surplus = balance
    activation_deployment = bridge_deployment_state_for_test(
        manifest, balance=surplus
    )
    activation_deployment.balance = balance
    activation_deployment.v2_active = True
    activation_deployment.activation_surplus = surplus
    registrar = accumulator._terminal_registrar_authority
    assert type(registrar) is TerminalDomainRegistrarV2
    registrar.liquidity_pool.active = True
    pending_activation_receipt = DestinationBridgeActivationReceiptV2(
        manifest.commitment,
        manifest.destination_domain_id,
        manifest.destination_bridge,
        "",
        0,
        surplus,
        balance,
        activation_deployment.observation_commitment,
        "PENDING",
        _DESTINATION_BRIDGE_ACTIVATION_CAPABILITY,
    )
    activation_receipt = replace(
        pending_activation_receipt,
        seal=hashlib.sha256(
            b"TAIKO_DESTINATION_BRIDGE_ACTIVATION_RECEIPT_V2\x00"
            + pending_activation_receipt.digest.encode()
        ).hexdigest(),
    )
    return DestinationBridgeLedger(
        address=manifest.destination_bridge,
        local_domain_id=manifest.destination_domain_id,
        paused=False,
        inbox_store=store,
        terminal_accumulator=accumulator,
        liquidity_pool=registrar.liquidity_pool,
        bridge_surplus_sink=manifest.execution_profile.bridge_surplus_sink,
        release_manifest=manifest,
        execution_environment=environment,
        quota_manager=quota_manager,
        activation_deployment=activation_deployment,
        activation_receipt=activation_receipt,
        v2_active=True,
        balance=balance,
    )


def set_bridge_eth_quota_available_for_test(
    bridge: object, available: int, *, updated_at: int | None = None,
    lane: str | None = None,
) -> None:
    """Fixture-only mutation of the real QuotaManager dynamic storage row."""

    if type(bridge) not in {SourceBridgeV2, DestinationBridgeLedger}:
        raise ValueError("test quota target is not an exact Bridge")
    manager = bridge.quota_manager
    environment = (
        bridge.native_environment
        if type(bridge) is SourceBridgeV2 else bridge.execution_environment
    )
    now = environment.block_timestamp if updated_at is None else updated_at
    selected_lane = NATIVE_QUOTA_LANE_V2 if lane is None else lane
    if (type(manager) is not FrozenNativeQuotaManagerV2
            or manager._bridge_authority is not bridge
            or type(available) is not int
            or available < 0
            or selected_lane != NATIVE_QUOTA_LANE_V2
            or available > manager._state.quota
            or type(now) is not int or now < 0):
        raise ValueError("test QuotaManager state is invalid")
    manager._state.available = available
    manager._state.updated_at = now


@dataclass(frozen=True)
class L2TransactionFrameV2:
    """Exact EVM transaction context issued only by one L2 environment."""

    environment: "L2ExecutionEnvironmentV2" = field(compare=False, repr=False)
    caller: str
    available_gas: int
    base_fee: int
    block_timestamp: int
    nonce: int
    operation: str








@dataclass
class BridgeCallReceiverV2:
    """One independently deployed L2 app account used by the call journal."""

    address: str
    runtime_hash: str = "code:l2-app:v1"
    configuration_hash: str = "config:l2-app:v1"
    fault_point: str | None = None
    gas_used: int = MIN_BRIDGE_INVOCATION_GAS
    exhausts_forwarded_gas: bool = False
    required_v2_policy: BridgeInvocationPolicyV2 | None = None
    received: list[str] = field(default_factory=list)
    observed_legacy_contexts: list[tuple[object, ...]] = field(
        default_factory=list
    )
    observed_v2_contexts: list[BridgeInvocationContextV2] = field(
        default_factory=list
    )
    native_balance: int = 0
    callback: Callable[["DestinationBridgeLedger"], None] | None = field(
        default=None, compare=False, repr=False
    )
    _environment_authority: object | None = field(
        default=None, init=False, compare=False, repr=False
    )

    def __setattr__(self, name: str, value: object) -> None:
        if (name in {
                "address", "runtime_hash", "configuration_hash",
                "required_v2_policy",
            }
                and self.__dict__.get("_environment_authority") is not None):
            raise AttributeError(f"L2 application {name} is deployment-fixed")
        object.__setattr__(self, name, value)

    def _bind_environment_once(self, environment: object) -> bool:
        if type(environment) is not L2ExecutionEnvironmentV2 or not self.address:
            return False
        if self._environment_authority is not None:
            return self._environment_authority is environment
        object.__setattr__(self, "_environment_authority", environment)
        return True

    def _transaction_snapshot(self) -> dict[str, object]:
        return {
            "received": list(self.received),
            "observed_legacy_contexts": list(
                self.observed_legacy_contexts
            ),
            "observed_v2_contexts": list(self.observed_v2_contexts),
            "native_balance": self.native_balance,
        }

    def _restore_transaction_snapshot(self, snapshot: dict[str, object]) -> None:
        self.received[:] = snapshot["received"]
        self.observed_legacy_contexts[:] = snapshot[
            "observed_legacy_contexts"
        ]
        self.observed_v2_contexts[:] = snapshot["observed_v2_contexts"]
        self.native_balance = snapshot["native_balance"]

    def _execute_from_environment(
        self,
        message_: IBridgeMessageV1,
        *,
        environment: "L2ExecutionEnvironmentV2",
        bridge: "DestinationBridgeLedger",
        frame: L2TransactionFrameV2,
        gas_requested: int,
    ) -> tuple[bool, int, bool]:
        if (environment is not self._environment_authority
                or frame is not environment._active_frame
                or bridge.execution_environment is not environment
                or message_.to != self.address
                or type(gas_requested) is not int or gas_requested < 0):
            return False, 0, False
        if self.fault_point == "revert":
            return False, min(self.gas_used, gas_requested), False
        if self.fault_point == "throw":
            raise RuntimeError("injected destination target fault")
        if self.exhausts_forwarded_gas or self.gas_used > gas_requested:
            # The requested gas was forwarded exactly; a callee-local OOG is
            # an ordinary CALL failure, not evidence that EIP-150 truncated it.
            return False, gas_requested, False
        if (self.required_v2_policy is not None
                and not self.required_v2_policy.accepts(
                    environment.bridge_context_v2
                )):
            return False, min(self.gas_used, gas_requested), False
        self.native_balance = seat_checked_add(
            self.native_balance,
            message_.value,
            "destination target native balance",
        )
        self.received.append(bridge_message_hash(message_))
        assert environment.legacy_bridge_context is not None
        assert environment.bridge_context_v2 is not None
        self.observed_legacy_contexts.append(
            environment.legacy_bridge_context
        )
        self.observed_v2_contexts.append(environment.bridge_context_v2)
        if self.callback is not None:
            self.callback(bridge)
        return (
            True,
            self.gas_used,
            False,
        )


@dataclass
class L2ExecutionEnvironmentV2:
    """Independent destination-chain accounts and exact EVM call journal."""

    chain_id: int
    applications: tuple[BridgeCallReceiverV2, ...] = field(
        default_factory=tuple, compare=False, repr=False
    )
    available_gas: int = 10_000_000
    base_fee: int = 1
    block_timestamp: int = GENESIS_TIMESTAMP
    eoa_balances: dict[str, int] = field(default_factory=dict)
    legacy_bridge_context: tuple[object, ...] | None = field(
        default=None, init=False, compare=False, repr=False
    )
    bridge_context_v2: BridgeInvocationContextV2 | None = field(
        default=None, init=False, compare=False, repr=False
    )
    _applications_by_address: dict[str, BridgeCallReceiverV2] = field(
        default_factory=dict, init=False, compare=False, repr=False
    )
    _active_frame: L2TransactionFrameV2 | None = field(
        default=None, init=False, compare=False, repr=False
    )
    _next_nonce: int = field(default=1, init=False, compare=False, repr=False)
    _bridge_authority: object | None = field(
        default=None, init=False, compare=False, repr=False
    )

    def __post_init__(self) -> None:
        if (type(self.chain_id) is not int
                or not 0 < self.chain_id <= UINT64_MAX
                or type(self.applications) is not tuple
                or type(self.available_gas) is not int
                or self.available_gas <= V2_POST_CALL_GAS_RESERVE
                or type(self.base_fee) is not int or self.base_fee < 0
                or type(self.block_timestamp) is not int
                or not 0 <= self.block_timestamp <= UINT64_MAX):
            raise ValueError("L2 execution environment context is invalid")
        applications: dict[str, BridgeCallReceiverV2] = {}
        for application in self.applications:
            if (type(application) is not BridgeCallReceiverV2
                    or not application.address
                    or application.address in applications
                    or not application.runtime_hash
                    or not application.configuration_hash
                    or not application._bind_environment_once(self)):
                raise ValueError("L2 application deployment is invalid")
            applications[application.address] = application
        object.__setattr__(self, "_applications_by_address", applications)

    def _bind_bridge_once(self, bridge: object) -> bool:
        if (type(bridge) is not DestinationBridgeLedger
                or bridge.execution_environment is not self):
            return False
        if self._bridge_authority is not None:
            return self._bridge_authority is bridge
        object.__setattr__(self, "_bridge_authority", bridge)
        return True

    def read_bridge_context_v2(self) -> BridgeInvocationContextV2:
        """The public view is defined only inside an active V2 call frame."""

        if (self._active_frame is None
                or type(self.bridge_context_v2)
                    is not BridgeInvocationContextV2):
            raise ValueError("V2 Bridge context is not active")
        return self.bridge_context_v2

    def __setattr__(self, name: str, value: object) -> None:
        if name in {
            "chain_id", "applications",
            "_active_frame", "_next_nonce",
        } and name in self.__dict__:
            raise AttributeError(f"L2 execution environment {name} is immutable")
        object.__setattr__(self, name, value)

    def _transaction_snapshot(self) -> dict[str, object]:
        return {
            "eoa_balances": dict(self.eoa_balances),
            "application_refs": dict(self._applications_by_address),
            "applications": {
                address: application._transaction_snapshot()
                for address, application in self._applications_by_address.items()
            },
        }

    def _restore_transaction_snapshot(self, snapshot: dict[str, object]) -> None:
        self.eoa_balances.clear()
        self.eoa_balances.update(snapshot["eoa_balances"])
        self._applications_by_address.clear()
        self._applications_by_address.update(snapshot["application_refs"])
        for address, application_snapshot in snapshot["applications"].items():
            self._applications_by_address[address]._restore_transaction_snapshot(
                application_snapshot
            )

    def deploy_application(
        self, application: BridgeCallReceiverV2
    ) -> bool:
        """Model a canonical CREATE/CREATE2 state transition, not admission."""

        if (self._active_frame is not None
                or type(application) is not BridgeCallReceiverV2
                or not application.address
                or application.address in self._applications_by_address
                or not application.runtime_hash
                or not application.configuration_hash
                or not application._bind_environment_once(self)):
            return False
        application.native_balance = seat_checked_add(
            application.native_balance,
            self.eoa_balances.pop(application.address, 0),
            "deployed L2 application balance",
        )
        self._applications_by_address[application.address] = application
        return True

    def _open_frame(self, caller: str, operation: str) -> L2TransactionFrameV2:
        if self._active_frame is not None or not caller:
            raise RuntimeError("L2 transaction frame is already active")
        frame = L2TransactionFrameV2(
            self,
            caller,
            self.available_gas,
            self.base_fee,
            self.block_timestamp,
            self._next_nonce,
            operation,
        )
        object.__setattr__(self, "_next_nonce", self._next_nonce + 1)
        object.__setattr__(self, "_active_frame", frame)
        return frame

    def _close_frame(self, frame: L2TransactionFrameV2) -> None:
        if self._active_frame is not frame:
            raise RuntimeError("L2 transaction frame identity changed")
        object.__setattr__(self, "_active_frame", None)

    def _invoke(
        self,
        bridge: "DestinationBridgeLedger",
        message_: IBridgeMessageV1,
        source: SourceContextV2,
        destination: DestinationContextV2,
        *,
        frame: L2TransactionFrameV2,
        gas_requested: int,
    ) -> tuple[bool, int, bool]:
        if (frame is not self._active_frame
                or frame.environment is not self
                or bridge.execution_environment is not self):
            raise RuntimeError("L2 call frame authority is split")
        object.__setattr__(self, "legacy_bridge_context", (
            bridge_message_hash(message_),
            message_.sender,
            message_.source_chain_id,
        ))
        object.__setattr__(self, "bridge_context_v2", BridgeInvocationContextV2(
            bridge.release_manifest.protocol_version,
            "V2_DIRECT",
            destination_credit_id_v2(message_, source, destination),
            bridge_message_hash(message_),
            source.source_domain_id,
            source.source_registration_epoch,
            source.source_bridge,
            source.bridge_execution_hash,
            source.emitted_at_block,
            destination.queue_index,
            destination.destination_domain_id,
            destination.destination_bridge,
            bridge.release_manifest.commitment,
            bridge.release_manifest.execution_profile_hash,
        ))
        try:
            application = self._applications_by_address.get(message_.to)
            if application is None:
                self.eoa_balances[message_.to] = seat_checked_add(
                    self.eoa_balances.get(message_.to, 0),
                    message_.value,
                    "destination EOA native balance",
                )
                return True, 0, False
            return application._execute_from_environment(
                message_,
                environment=self,
                bridge=bridge,
                frame=frame,
                gas_requested=gas_requested,
            )
        finally:
            object.__setattr__(self, "legacy_bridge_context", None)
            object.__setattr__(self, "bridge_context_v2", None)

    def process_bridge_message(
        self,
        bridge: "DestinationBridgeLedger",
        message_: IBridgeMessageV1,
        source: SourceContextV2,
        destination: DestinationContextV2,
        *,
        caller: str,
    ) -> str:
        try:
            frame = self._open_frame(caller, "PROCESS")
        except RuntimeError:
            return "REJECTED"
        try:
            return bridge._process_from_environment(
                message_, source, destination, frame=frame
            )
        finally:
            self._close_frame(frame)

    def retry_bridge_message(
        self,
        bridge: "DestinationBridgeLedger",
        message_: IBridgeMessageV1,
        source: SourceContextV2,
        destination: DestinationContextV2,
        *,
        caller: str,
        is_last_attempt: bool,
    ) -> str:
        try:
            frame = self._open_frame(caller, "RETRY")
        except RuntimeError:
            return "REJECTED"
        try:
            return bridge._retry_from_environment(
                message_, source, destination,
                is_last_attempt=is_last_attempt,
                frame=frame,
            )
        finally:
            self._close_frame(frame)

    def manual_fail_bridge_message(
        self,
        bridge: "DestinationBridgeLedger",
        message_: IBridgeMessageV1,
        source: SourceContextV2,
        destination: DestinationContextV2,
        *,
        caller: str,
    ) -> bool:
        try:
            frame = self._open_frame(caller, "MANUAL_FAIL")
        except RuntimeError:
            return False
        try:
            return bridge._manual_fail_from_environment(
                message_, source, destination, frame=frame
            )
        finally:
            self._close_frame(frame)

    def expire_bridge_credit(
        self,
        bridge: "DestinationBridgeLedger",
        credit_id: str,
    ) -> bool:
        try:
            frame = self._open_frame("permissionless-expirer", "EXPIRE")
        except RuntimeError:
            return False
        try:
            return bridge._expire_from_environment(credit_id, frame=frame)
        finally:
            self._close_frame(frame)

    def withdraw_bridge_credit(
        self,
        bridge: "DestinationBridgeLedger",
        *,
        caller: str,
        recipient: str,
    ) -> int:
        try:
            frame = self._open_frame(caller, "WITHDRAW")
        except RuntimeError:
            return 0
        try:
            return bridge._withdraw_pull_from_environment(
                recipient=recipient, frame=frame
            )
        finally:
            self._close_frame(frame)




    def _transfer_native(
        self,
        recipient: str,
        amount: int,
        *,
        frame: L2TransactionFrameV2,
        bridge: "DestinationBridgeLedger",
    ) -> bool:
        if (frame is not self._active_frame or not recipient
                or type(amount) is not int or amount < 0
                or bridge.execution_environment is not self):
            return False
        application = self._applications_by_address.get(recipient)
        if application is None:
            self.eoa_balances[recipient] = seat_checked_add(
                self.eoa_balances.get(recipient, 0),
                amount,
                "destination pull recipient balance",
            )
            return True
        if application.fault_point in {"revert", "receive_revert", "throw"}:
            return False
        application.native_balance = seat_checked_add(
            application.native_balance,
            amount,
            "destination pull application balance",
        )
        if application.callback is not None:
            application.callback(bridge)
        return True



@dataclass
class DestinationBridgeLedger:
    """Fresh immutable V2 destination Bridge with private accounting."""
    address: str = "bridge:A"
    local_domain_id: str = "domain:D1"
    paused: bool = False
    inbox_store: InboxCreditStoreV2 = field(default_factory=lambda:
        InboxCreditStoreV2("inbox-apply", "bridge:A", "domain:D1"))
    terminal_accumulator: TerminalAccumulatorV2 = field(default_factory=lambda:
        TerminalAccumulatorV2({"domain:D1": "bridge:A"}))
    release_manifest: "ReleaseManifestV2 | None" = field(
        default=None, compare=False, repr=False
    )
    activation_deployment: BridgeDeploymentStateV2 | None = field(
        default=None, compare=False, repr=False
    )
    activation_receipt: DestinationBridgeActivationReceiptV2 | None = field(
        default=None, compare=False, repr=False
    )
    execution_environment: L2ExecutionEnvironmentV2 | None = field(
        default=None, compare=False, repr=False
    )
    quota_manager: FrozenNativeQuotaManagerV2 | None = field(
        default=None, compare=False, repr=False
    )
    liquidity_pool: NativeLiquidityPoolV2 | None = field(
        default=None, compare=False, repr=False
    )
    bridge_surplus_sink: NativeEthSinkV2 | None = field(
        default=None, compare=False, repr=False
    )
    _pull_credits: dict[str, int] = field(
        default_factory=dict, init=False, repr=False
    )
    _total_pull_liability: int = field(default=0, init=False, repr=False)
    _status: dict[str, str] = field(
        default_factory=dict, init=False, repr=False
    )
    _terminal_index: dict[str, int] = field(
        default_factory=dict, init=False, repr=False
    )
    _terminal_settlements: dict[str, NativeLiquiditySettlementV2] = field(
        default_factory=dict, init=False, repr=False
    )
    balance: int = 0
    v2_active: bool = False
    retired: bool = False
    terminal_commitment_return_length: int = TERMINAL_COMMITMENT_ABI_BYTES
    terminal_commitment_gas_ok: bool = True
    entered: bool = field(default=False, compare=False)
    _active_execution_frame: L2TransactionFrameV2 | None = field(
        default=None, init=False, compare=False, repr=False
    )

    def __post_init__(self) -> None:
        manifest = self.release_manifest
        environment = self.execution_environment
        descriptor = (
            None if type(manifest) is not ReleaseManifestV2
            else manifest.destination_bridge_descriptor
        )
        if (type(manifest) is not ReleaseManifestV2
                or not manifest.structurally_valid()
                or type(descriptor) is not DestinationBridgeDescriptorV2
                or type(environment) is not L2ExecutionEnvironmentV2
                or type(self.activation_deployment)
                    is not BridgeDeploymentStateV2
                or type(self.activation_receipt)
                    is not DestinationBridgeActivationReceiptV2
                or not self.activation_receipt.valid_for(
                    manifest, self.activation_deployment
                )
                or not self.v2_active
                or not self.activation_deployment.v2_active
                or self.activation_deployment.balance != self.balance
                or self.activation_deployment.next_message_id != 0
                or self.activation_deployment.status_entries
                or self.activation_deployment.pull_credit_entries
                or self.activation_deployment.total_liability != 0
                or self.activation_deployment.terminal_index_entries
                or manifest.destination_bridge != self.address
                or manifest.destination_domain_id != self.local_domain_id
                or descriptor.bridge != self.address
                or descriptor.role != BRIDGE_ROLE_DESTINATION_ONLY
                or descriptor.destination_chain_id != environment.chain_id
                or manifest.destination_chain_id != environment.chain_id
                or descriptor.inbox_credit_store != self.inbox_store.address
                or self.inbox_store.destination_bridge != self.address
                or self.inbox_store.destination_domain_id
                    != self.local_domain_id
                or descriptor.terminal_accumulator
                    != manifest.components[7].address
                or self.terminal_accumulator.domains.get(self.local_domain_id)
                    != self.address
                or descriptor.native_quota_manager
                    != destination_native_quota_manager_address(self.address)
                or type(self.quota_manager)
                    is not FrozenNativeQuotaManagerV2
                or self.quota_manager.address
                    != descriptor.native_quota_manager
                or self.quota_manager.runtime_hash
                    != descriptor.native_quota_manager_runtime_hash
                or self.quota_manager.quota_period
                    != descriptor.native_quota_period
                or self.quota_manager.eth_quota_cap
                    != descriptor.native_eth_quota
                or self.quota_manager.eth_quota_cap == 0
                or type(self.liquidity_pool) is not NativeLiquidityPoolV2
                or self.liquidity_pool.address
                    != descriptor.native_liquidity_pool
                or self.bridge_surplus_sink
                    is not manifest.execution_profile.bridge_surplus_sink
                or type(self.bridge_surplus_sink) is not NativeEthSinkV2
                or not self.bridge_surplus_sink.structurally_valid()
                or descriptor.native_liquidity_pool_policy
                    != NATIVE_LIQUIDITY_POOL_POLICY
                or descriptor.v1_official_vaults
                    != V1_OFFICIAL_VAULT_ADDRESSES
                or self.balance
                    != self.activation_receipt.bridge_postbalance
                or self.balance != self.activation_receipt.activation_surplus
                or self.retired
                or self.total_pull_liability != 0
                or self.pull_credits or self.status or self.terminal_index
                or self._terminal_settlements):
            raise ValueError("destination Bridge manifest graph is invalid")
        if (not self.quota_manager._bind_bridge_once(self)
                or not environment._bind_bridge_once(self)
                or not self.terminal_accumulator
                    ._bind_destination_bridge_once(
                        self.local_domain_id, self
                    )
                or not self.liquidity_pool._bind_destination_bridge_once(
                    self.local_domain_id, self
                )):
            raise ValueError("destination Bridge execution authority is split")

    def __setattr__(self, name: str, value: object) -> None:
        if name in {
            "address", "local_domain_id", "inbox_store",
            "terminal_accumulator", "release_manifest",
            "execution_environment", "quota_manager",
            "liquidity_pool", "bridge_surplus_sink",
            "activation_deployment", "activation_receipt",
            "v2_active", "retired", "paused", "_active_execution_frame",
        } and name in self.__dict__:
            raise AttributeError(f"destination Bridge {name} is immutable")
        object.__setattr__(self, name, value)

    @property
    def pull_credits(self) -> MappingProxyType:
        return MappingProxyType(dict(self._pull_credits))

    @property
    def total_pull_liability(self) -> int:
        return self._total_pull_liability

    @property
    def status(self) -> MappingProxyType:
        return MappingProxyType(dict(self._status))

    @property
    def terminal_index(self) -> MappingProxyType:
        return MappingProxyType(dict(self._terminal_index))

    def _pin(self, credit_id: str, destination_domain_id: str) -> InboxPin | None:
        return self.inbox_store.read(
            credit_id, caller=self.address,
            destination_domain_id=destination_domain_id)

    @property
    def destination_chain_id(self) -> int:
        assert type(self.release_manifest) is ReleaseManifestV2
        return self.release_manifest.destination_chain_id

    def set_paused(
        self, paused: bool, *, caller: str, chain_id: int,
    ) -> bool:
        """Apply the deployment-pinned destination pauser on the L2 chain."""

        descriptor = self.release_manifest.destination_bridge_descriptor
        if (type(paused) is not bool or caller != descriptor.pauser
                or chain_id != self.destination_chain_id
                or not self.v2_active or self.retired or self.entered):
            return False
        object.__setattr__(self, "paused", paused)
        return True

    def reclaim_surplus(
        self, registrar: TerminalDomainRegistrarV2, *, caller: str,
    ) -> tuple[ReclaimResult, int]:
        """Permissionlessly send raw retired-Bridge surplus to the typed sink."""

        manifest = self.release_manifest
        successor_bridge = (
            registrar.active_destination_bridge
            if type(registrar) is TerminalDomainRegistrarV2 else ""
        )
        watermark = (
            registrar.retirement_queue_watermarks.get(self.address)
            if type(registrar) is TerminalDomainRegistrarV2 else None
        )
        route = (
            registrar.inbox_router.routes.get(self.local_domain_id)
            if type(registrar) is TerminalDomainRegistrarV2 else None
        )
        lifetime_rows_exact = (
            type(manifest) is ReleaseManifestV2
            and len(manifest.components) == 10
            and manifest.components[3] == ReleaseComponentV2(
                registrar.inbox_router.address,
                registrar.inbox_router.runtime_hash,
                registrar.inbox_router.configuration_hash,
            )
            and manifest.components[5] == ReleaseComponentV2(
                registrar.authority.address,
                registrar.authority.runtime_hash,
                registrar.authority.configuration_hash,
            )
            and manifest.components[6] == ReleaseComponentV2(
                registrar.address,
                registrar.runtime_hash,
                registrar.configuration_hash,
            )
            and manifest.components[7] == ReleaseComponentV2(
                registrar.accumulator.address,
                registrar.accumulator.runtime_hash,
                registrar.accumulator.configuration_hash,
            )
            and manifest.components[8] == ReleaseComponentV2(
                registrar.liquidity_pool.address,
                registrar.liquidity_pool.runtime_hash,
                registrar.liquidity_pool.configuration_hash,
            )
        ) if type(registrar) is TerminalDomainRegistrarV2 else False
        if (not caller or type(manifest) is not ReleaseManifestV2
                or not manifest.structurally_valid() or not lifetime_rows_exact
                or self.retired or not self.v2_active or self.entered
                or type(watermark) is not int
                or not successor_bridge or successor_bridge == self.address
                or successor_bridge not in registrar.bridge_identities
                or successor_bridge not in registrar.bridge_activation_receipts
                or registrar.inbox_router.next_queue_index < watermark
                or registrar.authority.releases.get(manifest.protocol_version)
                    != manifest.commitment
                or registrar.registrations.get(manifest.protocol_version)
                    != manifest.registration_commitment
                or route is None or route.store is not self.inbox_store
                or route.destination_bridge != self.address
                or registrar.accumulator is not self.terminal_accumulator
                or registrar.accumulator.domains.get(self.local_domain_id)
                    != self.address
                or self.total_pull_liability != 0
                or registrar.liquidity_pool.reserved_count(
                    self.local_domain_id
                ) != 0
                or registrar.accumulator.terminalized_pinned_count.get(
                    self.local_domain_id
                ) != self.inbox_store.pinned_count):
            return ReclaimResult.REJECTED, 0
        sink = self.bridge_surplus_sink
        profile = manifest.execution_profile
        if (type(profile) is not ExecutionProfile
                or profile.execution_profile_hash
                    != manifest.execution_profile_hash
                or sink is not profile.bridge_surplus_sink
                or type(sink) is not NativeEthSinkV2
                or sink.asset_id != "NATIVE_ETH"
                or not sink.address):
            return ReclaimResult.REJECTED, 0
        amount = self.balance
        sink_balance = sink.balance
        self.entered = True
        self.balance = 0
        try:
            try:
                accepted = sink._receive_from_bridge(self, amount)
            except BaseException:
                accepted = False
            if (not accepted or self.balance != 0
                    or sink.balance != sink_balance + amount):
                self.balance = amount
                sink.balance = sink_balance
                return ReclaimResult.REJECTED, 0
            object.__setattr__(self, "retired", True)
            result = (
                ReclaimResult.RECLAIMED_ZERO if amount == 0
                else ReclaimResult.RECLAIMED_VALUE
            )
            return result, amount
        finally:
            self.entered = False

    def _transaction_snapshot(self) -> dict[str, object]:
        return {
            "balance": self.balance,
            "quota_snapshot": self.quota_manager.snapshot(),
            "pull_credits": dict(self.pull_credits),
            "total_pull_liability": self.total_pull_liability,
            "status": dict(self.status),
            "terminal_index": dict(self.terminal_index),
            "terminal_settlements": dict(self._terminal_settlements),
            "liquidity_pool": self.liquidity_pool._snapshot(),
            "terminal_leaves": list(self.terminal_accumulator.leaves),
            "terminalized_pinned_count": dict(
                self.terminal_accumulator.terminalized_pinned_count
            ),
            "terminalized_credits": set(
                self.terminal_accumulator._terminalized_credits
            ),
        }

    def _restore_transaction_snapshot(
        self, snapshot: dict[str, object], *, capability: object,
    ) -> None:
        if capability is not _DESTINATION_BRIDGE_ROLLBACK_CAPABILITY:
            raise ValueError("destination Bridge rollback capability is wrong")
        self.balance = snapshot["balance"]
        if self.quota_manager.snapshot() != snapshot["quota_snapshot"]:
            self.quota_manager.restore(
                snapshot["quota_snapshot"],
                bridge=self,
                frame=self._active_execution_frame,
                capability=_NATIVE_QUOTA_ROLLBACK_CAPABILITY,
            )
        self._pull_credits.clear()
        self._pull_credits.update(snapshot["pull_credits"])
        self._total_pull_liability = snapshot["total_pull_liability"]
        self._status.clear()
        self._status.update(snapshot["status"])
        self._terminal_index.clear()
        self._terminal_index.update(snapshot["terminal_index"])
        self._terminal_settlements.clear()
        self._terminal_settlements.update(snapshot["terminal_settlements"])
        self.liquidity_pool._restore(snapshot["liquidity_pool"])
        self.terminal_accumulator.leaves[:] = snapshot["terminal_leaves"]
        self.terminal_accumulator.terminalized_pinned_count.clear()
        self.terminal_accumulator.terminalized_pinned_count.update(
            snapshot["terminalized_pinned_count"]
        )
        self.terminal_accumulator._terminalized_credits.clear()
        self.terminal_accumulator._terminalized_credits.update(
            snapshot["terminalized_credits"]
        )

    @property
    def ether_quota(self) -> int:
        assert type(self.quota_manager) is FrozenNativeQuotaManagerV2
        assert type(self.execution_environment) is L2ExecutionEnvironmentV2
        return self.quota_manager.available_quota(
            self.execution_environment.block_timestamp,
        )

    @staticmethod
    def _message_calldata_cost(data_length: int) -> int:
        if type(data_length) is not int or data_length < 0:
            raise ValueError("destination Message data length is invalid")
        return (((data_length + 31) // 32 * 32) + 416) * 16

    @classmethod
    def _invocation_gas_limit(cls, message_: IBridgeMessageV1) -> int:
        minimum = cls._message_calldata_cost(
            message_.data_length
        ) + V2_POST_CALL_GAS_RESERVE
        return max(minimum, message_.gas_limit) - minimum

    @classmethod
    def _required_available_gas(
        cls, message_: IBridgeMessageV1, gas_requested: int
    ) -> int:
        if type(gas_requested) is not int or gas_requested < 0:
            raise ValueError("destination requested gas is invalid")
        pre_call_cost = seat_checked_add(
            BRIDGE_GAS_OVERHEAD,
            cls._message_calldata_cost(message_.data_length),
            "V2 pre-call gas cost",
        )
        return seat_checked_add(
            pre_call_cost,
            V2_POST_CALL_GAS_RESERVE
                + ((gas_requested * 64 + 62) // 63),
            "V2 EIP-150 call threshold",
        )

    def _hard_prohibited_target(self, message_: IBridgeMessageV1) -> bool:
        assert type(self.release_manifest) is ReleaseManifestV2
        descriptor = self.release_manifest.destination_bridge_descriptor
        return (
            not message_.to
            or message_.to in descriptor.privileged_target_denyset
        )

    @staticmethod
    def _ordinary_invocation_prohibited(
        message_: IBridgeMessageV1,
    ) -> bool:
        return (
            message_.data_length >= 4
            and message_.data[:4] != ON_MESSAGE_INVOCATION_SELECTOR
        )

    def _credit_pull(self, owner: str, amount: int) -> None:
        if not owner or type(amount) is not int or amount < 0:
            raise ValueError("destination pull credit is invalid")
        if amount == 0:
            return
        self._pull_credits[owner] = seat_checked_add(
            self._pull_credits.get(owner, 0),
            amount,
            "destination owner pull credit",
        )
        self._total_pull_liability = seat_checked_add(
            self.total_pull_liability, amount, "destination pull liability"
        )

    def _withdraw_pull_from_environment(
        self,
        *,
        recipient: str,
        frame: L2TransactionFrameV2,
    ) -> int:
        if (not recipient
                or not self._enter_execution(
                    frame, "WITHDRAW", allow_paused=True
                )):
            return 0
        bridge_snapshot = self._transaction_snapshot()
        assert self.execution_environment is not None
        environment_snapshot = self.execution_environment._transaction_snapshot()
        try:
            amount = self._pull_credits.get(frame.caller, 0)
            if amount == 0 or amount > self.balance:
                return 0
            self._pull_credits.pop(frame.caller, None)
            self._total_pull_liability = self.total_pull_liability - amount
            self.balance -= amount
            try:
                transferred = self.execution_environment._transfer_native(
                    recipient,
                    amount,
                    frame=frame,
                    bridge=self,
                )
            except BaseException:
                transferred = False
            if not transferred:
                self._restore_transaction_snapshot(
                    bridge_snapshot,
                    capability=_DESTINATION_BRIDGE_ROLLBACK_CAPABILITY,
                )
                self.execution_environment._restore_transaction_snapshot(
                    environment_snapshot
                )
                return 0
            return amount
        finally:
            self._leave_execution(frame)

    def withdraw_pull_credit(self, caller: str, recipient: str) -> int:
        environment = self.execution_environment
        if type(environment) is not L2ExecutionEnvironmentV2:
            return 0
        return environment.withdraw_bridge_credit(
            self, caller=caller, recipient=recipient
        )

    def liquidity_reservation_state_v2(self, credit_id: str) -> bytes | None:
        status = self.status.get(credit_id, "NEW")
        codes = {"NEW": 0, "RETRIABLE": 1, "DONE": 2,
                 "FAILED": 3, "RECALLED": 4}
        if status not in codes:
            return None
        terminal_index = self.terminal_index.get(credit_id)
        terminal_plus_one = (
            0 if terminal_index is None else checked_u64_add(
                terminal_index, 1, "terminal index plus one"
            )
        )
        if ((status in {"NEW", "RETRIABLE"}) != (terminal_plus_one == 0)):
            return None
        encoded = b"".join((
            _model_fixed_bytes32(self.local_domain_id),
            bytes(12) + _model_address20(self.address),
            bytes(12) + _model_address20(self.inbox_store.address),
            _model_uint(codes[status], 32, "Bridge status"),
            _model_uint(terminal_plus_one, 32, "terminal index plus one"),
        ))
        if len(encoded) != 160:
            raise AssertionError("liquidityReservationStateV2 width drifted")
        return encoded

    def _delivery_context_valid(
        self,
        message_: IBridgeMessageV1,
        source: SourceContextV2,
        destination: DestinationContextV2,
        *,
        require_pin: bool,
    ) -> bool:
        try:
            bridge_message_preimage(BridgeAdmissionEnvelope(
                message_, 0, MAX_FORCE_MESSAGE_GAS, 0
            ))
            credit_id = destination_credit_id_v2(
                message_, source, destination
            )
        except ValueError:
            return False
        refund_exact = (
            source.refund_mode == "DIRECT"
            and not source.refund_vault
            and not source.refund_capsule_hash
        )
        if (not source.source_domain_id
                or source.protocol_version
                    != self.release_manifest.protocol_version
                or source.kind != ForceKind.BRIDGE_CREDIT.value
                or source.msg_hash != bridge_message_hash(message_)
                or source.source_domain_id == destination.destination_domain_id
                or not 0 < source.source_registration_epoch <= UINT64_MAX
                or not source.source_bridge or not source.bridge_execution_hash
                or not 0 < source.emitted_at_block <= UINT64_MAX
                or not 0 <= source.enqueue_by <= UINT64_MAX
                or not refund_exact
                or source.escrow_id != bridge_escrow_id(credit_id)
                or destination.destination_domain_id != self.local_domain_id
                or destination.destination_bridge != self.address
                or destination.destination_chain_id
                    != self.destination_chain_id
                or destination.release_manifest_hash
                    != self.release_manifest.commitment
                or destination.execution_profile_hash
                    != self.release_manifest.execution_profile_hash
                or not 0 <= destination.queue_index < UINT64_MAX
                or source.queue_index != destination.queue_index
                or message_.destination_chain_id
                    != self.destination_chain_id
                or message_.sender == self.address):
            return False
        if not require_pin:
            return True
        pin = self._pin(credit_id, destination.destination_domain_id)
        if pin is None:
            return False
        try:
            expected_result = destination_result_hash_v11(
                message_, source, destination,
                liquidity_fee=pin.liquidity_fee,
            )
        except ValueError:
            return False
        return pin.result_hash == expected_result

    def _terminalize(
        self,
        credit_id: str,
        terminal: str,
        *,
        frame: L2TransactionFrameV2,
    ) -> bool:
        if (frame is not self._active_execution_frame
                or self.execution_environment is None
                or frame is not self.execution_environment._active_frame
                or not self.entered
                or terminal not in {"DONE", "FAILED"}
                or credit_id in self.terminal_index):
            return False
        if (terminal == "FAILED"
                and not self.liquidity_pool._release_from_bridge(
                    credit_id,
                    bridge=self,
                    capability=_NATIVE_LIQUIDITY_POOL_CAPABILITY,
                )):
            return False
        status_existed = credit_id in self.status
        prior_status = self.status.get(credit_id)
        prior_leaf_count = self.terminal_accumulator.count
        prior_terminalized_count = (
            self.terminal_accumulator.terminalized_pinned_count.get(
                self.local_domain_id, 0
            )
        )
        terminalized_key = (self.local_domain_id, credit_id)
        prior_terminalized = (
            terminalized_key
            in self.terminal_accumulator._terminalized_credits
        )
        self._status[credit_id] = terminal
        self._terminal_index[credit_id] = APPENDING_SENTINEL
        try:
            index = self.terminal_accumulator.append_terminal(
                caller=self, credit_id=credit_id)
        except BaseException:
            index = None
        if (index is None
                or self.terminal_accumulator.append_return_length != 32
                or not self.terminal_accumulator.append_return_padding_ok
                or not 0 <= index < UINT64_MAX):
            self.terminal_accumulator.leaves = (
                self.terminal_accumulator.leaves[:prior_leaf_count]
            )
            self.terminal_accumulator.terminalized_pinned_count[
                self.local_domain_id
            ] = prior_terminalized_count
            if prior_terminalized:
                self.terminal_accumulator._terminalized_credits.add(
                    terminalized_key
                )
            else:
                self.terminal_accumulator._terminalized_credits.discard(
                    terminalized_key
                )
            if status_existed:
                assert prior_status is not None
                self._status[credit_id] = prior_status
            else:
                self._status.pop(credit_id, None)
            self._terminal_index.pop(credit_id, None)
            return False
        self._terminal_index[credit_id] = index
        return True

    def terminal_commitment_v2(
        self, credit_id: str
    ) -> tuple[str, str, str, int, str] | None:
        terminal = self.status.get(credit_id)
        index = self.terminal_index.get(credit_id)
        if terminal not in {"DONE", "FAILED"} or index is None:
            return None
        settlement = self._terminal_settlements.get(credit_id)
        try:
            settlement_hash = (
                "00" * 32 if terminal == "FAILED"
                else liquidity_settlement_hash_v1(
                    settlement.ticket_id,
                    settlement.l1_recipient,
                    settlement.settlement_amount,
                )
            )
        except (AttributeError, ValueError):
            return None
        return (
            self.local_domain_id, self.address, terminal, index,
            settlement_hash,
        )

    def _fund_success_from_pool(
        self, credit_id: str, message_: IBridgeMessageV1
    ) -> bool:
        try:
            amount = seat_checked_add(
                message_.value, message_.fee,
                "destination LP settlement amount",
            )
        except ValueError:
            return False
        if amount == 0:
            return False
        settlement = self.liquidity_pool._consume_from_bridge(
            credit_id,
            bridge=self,
            capability=_NATIVE_LIQUIDITY_POOL_CAPABILITY,
        )
        if settlement is None or settlement.settlement_amount != amount:
            return False
        self._terminal_settlements[credit_id] = settlement
        return True

    def accepts_message_target(self, target: str, *, version: str) -> bool:
        if version != "V2":
            return True
        descriptor = self.release_manifest.destination_bridge_descriptor
        return bool(target) and target not in descriptor.privileged_target_denyset



    def _consume_quota(self, debit: int, frame: L2TransactionFrameV2) -> bool:
        return self.quota_manager._consume_from_bridge(
            debit, bridge=self, frame=frame,
            capability=_NATIVE_QUOTA_CONSUME_CAPABILITY,
            lane=NATIVE_QUOTA_LANE_V2,
        )





    def _processor_fee(
        self,
        message_: IBridgeMessageV1,
        *,
        frame: L2TransactionFrameV2,
        gas_used: int,
    ) -> int:
        """Return the sender-authorized all-or-nothing success bounty."""

        _ = gas_used  # Exact gas metering is not a fee oracle in V2.
        if (frame.caller == message_.destination_owner
                or message_.fee == 0 or message_.gas_limit == 0):
            return 0
        return message_.fee

    def _settle_success(
        self,
        message_: IBridgeMessageV1,
        *,
        frame: L2TransactionFrameV2,
        gas_used: int,
        value_delivered: bool,
    ) -> None:
        total = seat_checked_add(
            message_.value, message_.fee, "destination Message value plus fee"
        )
        free_balance = self.balance - self.total_pull_liability
        required_pull = message_.fee if value_delivered else total
        if free_balance < required_pull:
            raise ValueError("destination liquidity or quota is insufficient")
        processor_fee = self._processor_fee(
            message_, frame=frame, gas_used=gas_used
        )
        owner_credit = message_.fee - processor_fee
        if not value_delivered:
            owner_credit = seat_checked_add(
                owner_credit,
                message_.value,
                "destination owner invocation refund",
            )
        if not self._consume_quota(total, frame):
            raise ValueError("destination native quota is insufficient")
        self._credit_pull(frame.caller, processor_fee)
        self._credit_pull(message_.destination_owner, owner_credit)

    def _has_success_capacity(self, message_: IBridgeMessageV1) -> bool:
        try:
            total = seat_checked_add(
                message_.value,
                message_.fee,
                "destination Message value plus fee",
            )
        except ValueError:
            return False
        return self.balance - self.total_pull_liability >= total

    def _enter_execution(
        self,
        frame: L2TransactionFrameV2,
        operation: str,
        *,
        allow_paused: bool = False,
    ) -> bool:
        environment = self.execution_environment
        if (type(environment) is not L2ExecutionEnvironmentV2
                or not self.v2_active
                or self.retired
                or frame.environment is not environment
                or frame is not environment._active_frame
                or frame.operation != operation
                or self.entered
                or (self.paused and not allow_paused)):
            return False
        self.entered = True
        object.__setattr__(self, "_active_execution_frame", frame)
        return True

    def _leave_execution(self, frame: L2TransactionFrameV2) -> None:
        if self._active_execution_frame is frame:
            object.__setattr__(self, "_active_execution_frame", None)
        self.entered = False

    def _process_from_environment(
        self,
        message_: IBridgeMessageV1,
        source: SourceContextV2,
        destination: DestinationContextV2,
        *,
        frame: L2TransactionFrameV2,
    ) -> str:
        if (not self._enter_execution(frame, "PROCESS")
                or not self._delivery_context_valid(
                    message_, source, destination, require_pin=True)):
            if self._active_execution_frame is frame:
                self._leave_execution(frame)
            return "REJECTED"
        bridge_snapshot = self._transaction_snapshot()
        assert self.execution_environment is not None
        environment_snapshot = self.execution_environment._transaction_snapshot()
        try:
            credit_id = destination_credit_id_v2(message_, source, destination)
            pin = self._pin(credit_id, destination.destination_domain_id)
            current = self.status.get(credit_id, "NEW")
            if (pin is None or current != "NEW"
                    or frame.block_timestamp > pin.process_by):
                return "REJECTED"

            if self._hard_prohibited_target(message_):
                if not self._terminalize(credit_id, "FAILED", frame=frame):
                    raise RuntimeError("destination FAILED terminal append reverted")
                return "FAILED"

            if self._ordinary_invocation_prohibited(message_):
                if not self._fund_success_from_pool(credit_id, message_):
                    return "UNFUNDED"
                if not self._has_success_capacity(message_):
                    return "REJECTED"
                self._settle_success(
                    message_, frame=frame,
                    gas_used=BRIDGE_GAS_OVERHEAD,
                    value_delivered=False,
                )
                if not self._terminalize(credit_id, "DONE", frame=frame):
                    raise RuntimeError("destination DONE terminal append reverted")
                return "DONE"

            # Match Bridge.sol: a zero-value, zero-calldata message succeeds
            # without issuing an external CALL.  Empty value transfers and
            # 1--3-byte fallback calldata still execute below.
            if message_.value == 0 and message_.data_length == 0:
                if not self._fund_success_from_pool(credit_id, message_):
                    return "UNFUNDED"
                if not self._has_success_capacity(message_):
                    return "REJECTED"
                self._settle_success(
                    message_, frame=frame,
                    gas_used=BRIDGE_GAS_OVERHEAD,
                    value_delivered=True,
                )
                if not self._terminalize(credit_id, "DONE", frame=frame):
                    raise RuntimeError("destination DONE terminal append reverted")
                return "DONE"

            if (frame.caller != message_.destination_owner
                    and message_.gas_limit == 0):
                return "REJECTED"
            requested = self._invocation_gas_limit(message_)
            if frame.caller != message_.destination_owner:
                if (requested == 0
                        or frame.available_gas
                            < self._required_available_gas(
                                message_, requested
                            )):
                    return "REJECTED"
            else:
                pre_call_cost = seat_checked_add(
                    BRIDGE_GAS_OVERHEAD,
                    self._message_calldata_cost(message_.data_length),
                    "V2 owner pre-call gas cost",
                )
                requested = max(
                    0,
                    frame.available_gas
                    - pre_call_cost
                    - V2_POST_CALL_GAS_RESERVE,
                )
            if not self._fund_success_from_pool(credit_id, message_):
                return "UNFUNDED"
            executed = (
                self.balance - self.total_pull_liability >= message_.value
            )
            gas_used = 0
            exhausted = False
            if executed:
                self.balance -= message_.value
                try:
                    executed, gas_used, exhausted = (
                        self.execution_environment._invoke(
                            self, message_, source, destination, frame=frame,
                            gas_requested=requested,
                        )
                    )
                except BaseException:
                    executed, gas_used, exhausted = False, 0, False
            if exhausted:
                raise RuntimeError("destination target exhausted forwarded gas")
            if not executed:
                self._restore_transaction_snapshot(
                    bridge_snapshot,
                    capability=_DESTINATION_BRIDGE_ROLLBACK_CAPABILITY,
                )
                self.execution_environment._restore_transaction_snapshot(
                    environment_snapshot
                )
                if frame.caller == message_.destination_owner:
                    self._status[credit_id] = "RETRIABLE"
                    return "RETRIABLE"
                return "NEW"
            self._settle_success(
                message_, frame=frame, gas_used=gas_used,
                value_delivered=True,
            )
            if not self._terminalize(credit_id, "DONE", frame=frame):
                raise RuntimeError("destination DONE terminal append reverted")
            return "DONE"
        except BaseException:
            self._restore_transaction_snapshot(
                bridge_snapshot,
                capability=_DESTINATION_BRIDGE_ROLLBACK_CAPABILITY,
            )
            self.execution_environment._restore_transaction_snapshot(
                environment_snapshot
            )
            return "REJECTED"
        finally:
            self._leave_execution(frame)

    def _retry_from_environment(
        self,
        message_: IBridgeMessageV1,
        source: SourceContextV2,
        destination: DestinationContextV2,
        *,
        is_last_attempt: bool,
        frame: L2TransactionFrameV2,
    ) -> str:
        if (not self._enter_execution(frame, "RETRY")
                or not self._delivery_context_valid(
                    message_, source, destination, require_pin=True)):
            if self._active_execution_frame is frame:
                self._leave_execution(frame)
            return "REJECTED"
        bridge_snapshot = self._transaction_snapshot()
        assert self.execution_environment is not None
        environment_snapshot = self.execution_environment._transaction_snapshot()
        try:
            credit_id = destination_credit_id_v2(message_, source, destination)
            pin = self._pin(credit_id, destination.destination_domain_id)
            if (pin is None or self.status.get(credit_id) != "RETRIABLE"
                    or frame.block_timestamp > pin.process_by):
                return "REJECTED"
            if self._hard_prohibited_target(message_):
                if is_last_attempt:
                    if not self._terminalize(
                            credit_id, "FAILED", frame=frame):
                        raise RuntimeError(
                            "destination FAILED terminal append reverted"
                        )
                    return "FAILED"
                return "REJECTED"
            if self._ordinary_invocation_prohibited(message_):
                if not self._fund_success_from_pool(credit_id, message_):
                    return "UNFUNDED"
                if not self._has_success_capacity(message_):
                    return "RETRIABLE"
                self._settle_success(
                    message_, frame=frame,
                    gas_used=BRIDGE_GAS_OVERHEAD,
                    value_delivered=False,
                )
                if not self._terminalize(credit_id, "DONE", frame=frame):
                    raise RuntimeError("destination DONE terminal append reverted")
                return "DONE"
            if message_.value == 0 and message_.data_length == 0:
                if not self._fund_success_from_pool(credit_id, message_):
                    return "UNFUNDED"
                if not self._has_success_capacity(message_):
                    return "RETRIABLE"
                self._settle_success(
                    message_, frame=frame,
                    gas_used=BRIDGE_GAS_OVERHEAD,
                    value_delivered=True,
                )
                if not self._terminalize(credit_id, "DONE", frame=frame):
                    raise RuntimeError("destination DONE terminal append reverted")
                return "DONE"
            if (frame.caller != message_.destination_owner
                    and (message_.gas_limit == 0 or is_last_attempt)):
                return "REJECTED"
            pre_call_cost = seat_checked_add(
                BRIDGE_GAS_OVERHEAD,
                self._message_calldata_cost(message_.data_length),
                "V2 retry pre-call gas cost",
            )
            requested = max(
                0,
                frame.available_gas
                - pre_call_cost
                - V2_POST_CALL_GAS_RESERVE,
            )
            if requested == 0:
                return "REJECTED"
            if not self._fund_success_from_pool(credit_id, message_):
                return "UNFUNDED"
            executed = (
                self.balance - self.total_pull_liability >= message_.value
            )
            gas_used = 0
            exhausted = False
            if executed:
                self.balance -= message_.value
                try:
                    executed, gas_used, exhausted = (
                        self.execution_environment._invoke(
                            self, message_, source, destination, frame=frame,
                            gas_requested=requested,
                        )
                    )
                except BaseException:
                    executed, gas_used, exhausted = False, 0, False
            if exhausted:
                raise RuntimeError("destination retry exhausted forwarded gas")
            if executed:
                self._settle_success(
                    message_, frame=frame, gas_used=gas_used,
                    value_delivered=True,
                )
                if not self._terminalize(credit_id, "DONE", frame=frame):
                    raise RuntimeError("destination DONE terminal append reverted")
                return "DONE"
            self._restore_transaction_snapshot(
                bridge_snapshot,
                capability=_DESTINATION_BRIDGE_ROLLBACK_CAPABILITY,
            )
            self.execution_environment._restore_transaction_snapshot(
                environment_snapshot
            )
            if not is_last_attempt:
                return "RETRIABLE"
            if not self._terminalize(credit_id, "FAILED", frame=frame):
                raise RuntimeError("destination FAILED terminal append reverted")
            return "FAILED"
        except BaseException:
            self._restore_transaction_snapshot(
                bridge_snapshot,
                capability=_DESTINATION_BRIDGE_ROLLBACK_CAPABILITY,
            )
            self.execution_environment._restore_transaction_snapshot(
                environment_snapshot
            )
            return "REJECTED"
        finally:
            self._leave_execution(frame)

    def _manual_fail_from_environment(
        self,
        message_: IBridgeMessageV1,
        source: SourceContextV2,
        destination: DestinationContextV2,
        *,
        frame: L2TransactionFrameV2,
    ) -> bool:
        if (not self._enter_execution(frame, "MANUAL_FAIL")
                or not self._delivery_context_valid(
                    message_, source, destination, require_pin=True)):
            if self._active_execution_frame is frame:
                self._leave_execution(frame)
            return False
        bridge_snapshot = self._transaction_snapshot()
        try:
            credit_id = destination_credit_id_v2(message_, source, destination)
            if (frame.caller != message_.destination_owner
                    or self.status.get(credit_id) != "RETRIABLE"
                    or not self._terminalize(
                        credit_id, "FAILED", frame=frame
                    )):
                self._restore_transaction_snapshot(
                    bridge_snapshot,
                    capability=_DESTINATION_BRIDGE_ROLLBACK_CAPABILITY,
                )
                return False
            return True
        finally:
            self._leave_execution(frame)

    def _expire_from_environment(
        self,
        credit_id: str,
        *,
        frame: L2TransactionFrameV2,
    ) -> bool:
        """Expire using only the local durable pin and the block context."""

        if not self._enter_execution(frame, "EXPIRE", allow_paused=True):
            return False
        bridge_snapshot = self._transaction_snapshot()
        try:
            pin = self._pin(credit_id, self.local_domain_id)
            current = self.status.get(credit_id, "NEW")
            if (not credit_id or pin is None
                    or current not in {"NEW", "RETRIABLE"}
                    or frame.block_timestamp <= pin.process_by
                    or not self._terminalize(
                        credit_id, "FAILED", frame=frame
                    )):
                self._restore_transaction_snapshot(
                    bridge_snapshot,
                    capability=_DESTINATION_BRIDGE_ROLLBACK_CAPABILITY,
                )
                return False
            return True
        finally:
            self._leave_execution(frame)

    def process(
        self,
        message_: IBridgeMessageV1,
        source: SourceContextV2,
        destination: DestinationContextV2,
        *,
        caller: str,
    ) -> str:
        environment = self.execution_environment
        if type(environment) is not L2ExecutionEnvironmentV2:
            return "REJECTED"
        return environment.process_bridge_message(
            self, message_, source, destination, caller=caller
        )

    def retry(
        self,
        message_: IBridgeMessageV1,
        source: SourceContextV2,
        destination: DestinationContextV2,
        *,
        caller: str,
        is_last_attempt: bool,
    ) -> str:
        environment = self.execution_environment
        if type(environment) is not L2ExecutionEnvironmentV2:
            return "REJECTED"
        return environment.retry_bridge_message(
            self, message_, source, destination,
            caller=caller, is_last_attempt=is_last_attempt,
        )

    def manual_fail(
        self,
        message_: IBridgeMessageV1,
        source: SourceContextV2,
        destination: DestinationContextV2,
        *,
        caller: str,
    ) -> bool:
        environment = self.execution_environment
        if type(environment) is not L2ExecutionEnvironmentV2:
            return False
        return environment.manual_fail_bridge_message(
            self, message_, source, destination, caller=caller
        )

    def expire_v2(self, credit_id: str) -> bool:
        environment = self.execution_environment
        if type(environment) is not L2ExecutionEnvironmentV2:
            return False
        return environment.expire_bridge_credit(self, credit_id)


PASS: list[str] = []


def check(name: str, condition: bool) -> None:
    assert condition, f"FAILED: {name}"
    PASS.append(name)


def payable_reverted(call: Callable[[], object]) -> bool:
    try:
        call()
    except (TypeError, ValueError, RuntimeError):
        return True
    return False


def clock(number: int, l2_slot: int) -> Clock:
    return Clock(number, GENESIS_TIMESTAMP + l2_slot)


def message(enqueued_l2: int, ident: str, gas: int = 100_000, size: int = 100,
            *, kind: ForceKind = ForceKind.USER_TX
            ) -> Message | BridgeAdmissionEnvelope:
    if kind is ForceKind.BRIDGE_CREDIT:
        return bridge_message(
            enqueued_l2,
            ident,
            gas_limit=MAX_FORCE_MESSAGE_GAS,
            size=size,
        )
    accounted_gas = (
        max(gas, 21_000, MIN_FORCE_ACCOUNTED_GAS)
    )
    row = Message(
        GENESIS_TIMESTAMP + enqueued_l2,
        accounted_gas,
        size,
        ident,
        kind=kind,
        sender="sender",
        valid_until=GENESIS_TIMESTAMP + enqueued_l2 + DATA_TTL_SECONDS,
        prepaid=canonical_ingress_deposit(accounted_gas, size),
        raw_tx_length=size,
        l2_chain_id=167_000,
        gas_limit=gas,
        max_fee=1_000_000,
        refund_address="sender",
    )
    return row


def bridge_message(
    enqueued_l2: int,
    ident: str,
    *,
    src_owner: str = "alice",
    dest_owner: str = "alice",
    to: str = "bridge-recipient",
    bridge_from: str = "alice",
    message_id: int = 0,
    value: int = 10,
    fee: int = 2,
    liquidity_fee: int = 1,
    gas_limit: int = MAX_FORCE_MESSAGE_GAS,
    source_chain_id: int = 1,
    destination_chain_id: int = 167_000,
    valid_until: int = UINT64_MAX,
    gas: int = MAX_FORCE_MESSAGE_GAS,
    size: int | None = None,
    data: bytes | None = None,
    prepaid: int | None = None,
) -> BridgeAdmissionEnvelope:
    """Construct an admission envelope from a complete raw Bridge Message."""

    if data is None:
        exact_size = 100 if size is None else size
        seed = ident.encode() or b"\x00"
        data = (seed * ((exact_size + len(seed) - 1) // len(seed)))[
            :exact_size
        ]
    elif size is not None and size != len(data):
        raise ValueError("Bridge Message size does not match raw data")
    if (type(data) is not bytes
            or len(data) > MAX_FORCE_MESSAGE_BYTES):
        raise ValueError("Bridge Message data exceeds the static bound")
    raw_message = IBridgeMessageV1(
        message_id,
        fee,
        gas_limit,
        bridge_from,
        source_chain_id,
        src_owner,
        destination_chain_id,
        dest_owner,
        to,
        value,
        data,
    )
    row = BridgeAdmissionEnvelope(
        raw_message,
        GENESIS_TIMESTAMP + enqueued_l2,
        MAX_FORCE_MESSAGE_GAS,
        (
            canonical_ingress_deposit(MAX_FORCE_MESSAGE_GAS, len(data))
            if prepaid is None else prepaid
        ),
        valid_until=valid_until,
        refund_address=bridge_from,
        liquidity_fee=liquidity_fee,
    )
    bridge_message_calldata(row)
    return row


def bridge_queue_descriptor_for_test(
    enqueued_l2: int,
    ident: str,
    destination_domain_id: str,
    *,
    refund_mode: str = "DIRECT",
    refund_vault: str = "",
    refund_capsule_hash: str = "",
) -> BridgeQueueDescriptorV11:
    """Build a structurally exact durable leaf for isolated consumer tests."""

    envelope = bridge_message(enqueued_l2, ident)
    preimage = bridge_message_preimage(envelope)
    descriptor = BridgeQueueDescriptorV11(
        envelope.enqueued_at,
        envelope.accounted_gas,
        preimage.data_length,
        envelope.payload_hash,
        envelope.prepaid,
        preimage.sender,
        preimage.fee,
        preimage.source_chain_id,
        preimage.source_owner,
        preimage.destination_chain_id,
        preimage.destination_owner,
        preimage.value,
        preimage.data_hash,
        "source-domain:test",
        1,
        "bridge:A",
        "source-execution:test",
        1,
        destination_domain_id,
        GENESIS_TIMESTAMP + enqueued_l2 + MAX_BRIDGE_ENQUEUE_DELAY,
        refund_mode,
        "permissionless-enqueuer",
        refund_vault,
        refund_capsule_hash,
        "",
        bridge_liquidity_fee=envelope.liquidity_fee,
        due_at=envelope.due_at,
    )
    descriptor = replace(
        descriptor, escrow_id=bridge_escrow_id(descriptor.credit_id)
    )
    if not descriptor.structurally_valid():
        raise AssertionError("isolated Bridge descriptor fixture is invalid")
    return descriptor


def make_header_oracle(
    messages: list[Message] | None = None,
) -> L1HeaderOracle:
    queue = list(messages or [])
    root = model_force_root(queue)
    headers = {
        n: L1Header(
            f"{n:064x}", GENESIS_TIMESTAMP + n,
            f"state-{n}", root, len(queue),
        )
        for n in range(1, 20_000)
    }
    return L1HeaderOracle(
        L1_HEADER_ORACLE_ADDRESS,
        L1_HEADER_ORACLE_RUNTIME_HASH,
        L1_HEADER_ORACLE_CONFIGURATION_HASH,
        headers,
    )


def protocol(tip_slot: int = 1_000, cursor: int = 0, seat: bool = True,
             mode: Mode = Mode.NORMAL, messages: list[Message] | None = None,
             forced_queue: QueueContinuity | None = None,
             inbox_apply_router: InboxApplyRouterV2 | None = None,
             header_oracle: L1HeaderOracle | None = None,
             migration_gate: MigrationGate | None = None,
             settlement_address: str = "model-settlement") -> Protocol:
    msgs = list(messages or [])
    if forced_queue is None:
        root = model_force_root(msgs)
        forced_queue = QueueContinuity(
            "model-forced-queue", root, len(msgs), cursor,
            sum(row.prepaid for row in msgs),
            max((row.due_at for row in msgs), default=0), msgs,
            active_settlement_address=settlement_address)
    else:
        assert not messages or forced_queue.descriptors == msgs
        msgs = forced_queue.descriptors
    if inbox_apply_router is None:
        inbox_apply_router = InboxApplyRouterV2(next_queue_index=cursor)
    if header_oracle is None:
        header_oracle = make_header_oracle(msgs)
    if migration_gate is None:
        migration_gate = MigrationGate()
    canonical = Canonical(CanonicalCore(900, "a" * 64, tip_slot, "b" * 64, cursor), 900)
    result = Protocol(
        canonical, header_oracle, forced_queue, inbox_apply_router,
        settlement_address=settlement_address, mode=mode,
        migration_gate=migration_gate,
    )
    if seat:
        installed_at = GENESIS_TIMESTAMP + tip_slot
        primary = SeatTerm(
            b"P" * 32, b"p" * 32, b"o" * 32,
            "aggregator", "aggregator-payout", 1, installed_at,
        )
        standby = SeatTerm(
            b"S" * 32, b"s" * 32, b"q" * 32,
            "standby", "standby-payout", 2, installed_at,
        )
        result.install_seat_term_for_test(primary, rank=0, start_primary=True)
        result.install_seat_term_for_test(standby, rank=1, start_primary=False)
    return result


def routed_ingress_for_test(
    protocol_: Protocol, *, protocol_version: int = 1,
    release_profile_ingress_specs: tuple[
        tuple[ForceKind, str, str], ...
    ] | None = None,
) -> ActiveSettlementRouter:
    """Build the exact Router graph used by executable model properties."""

    if protocol_.versioned_history is not None:
        history = protocol_.versioned_history
        router = getattr(history, "_router_authority", None)
        if type(router) is ActiveSettlementRouter:
            return router
        raise ValueError("test Protocol already has an unrouted history")
    execution_profile = execution_profile_for_test(
        protocol_version, f"profile:ingress:{protocol_version}"
    )
    history = VersionedSettlementHistory(
        protocol_.settlement_address,
        f"runtime:ingress:{protocol_version}",
        protocol_version,
        execution_profile.execution_profile_hash,
        copy.deepcopy(protocol_.core),
        protocol_.canonical.canonicalized_at_block,
        protocol_.forced_queue,
        migration_gate=protocol_.migration_gate,
        live_protocol=protocol_,
        inbox_apply_descriptor=protocol_.inbox_apply_descriptor,
        header_oracle=protocol_.header_oracle,
        execution_profile=execution_profile,
        release_profile_ingress_specs=(
            release_profile_ingress_specs
            if release_profile_ingress_specs is not None
            else (
                (ForceKind.USER_TX, "kind0-adapter", ""),
                (
                    ForceKind.BRIDGE_CREDIT,
                    "bridge-inbox-adapter",
                    "bridge:A",
                ),
            )
        ),
    )
    protocol_.versioned_history = history
    router = deploy_active_settlement_router(
        history,
        "version-manager",
        protocol_.forced_queue,
        protocol_.inbox_apply_router,
        protocol_.migration_gate,
        protocol_.header_oracle,
    )
    if not router.bootstrap(
        history,
        sequence=0,
        clock=Clock(
            protocol_.canonical.canonicalized_at_block,
            GENESIS_TIMESTAMP + protocol_.core.tip_slot,
        ),
        caller=router.version_manager,
    ):
        raise AssertionError("failed to route property-test Protocol")
    return router


def deploy_active_settlement_router(
    settlement: VersionedSettlementHistory,
    version_manager: str,
    forced_queue: QueueContinuity,
    inbox_apply_router: InboxApplyRouterV2,
    migration_gate: MigrationGate,
    header_oracle: L1HeaderOracle,
    **kwargs: object,
) -> ActiveSettlementRouter:
    """Trusted launch factory precommitting the canonical bytes32 manifest."""

    if type(settlement) is not VersionedSettlementHistory:
        raise ValueError("launch factory requires an exact Settlement profile")
    router = ActiveSettlementRouter(
        version_manager,
        forced_queue,
        inbox_apply_deployment_descriptor(inbox_apply_router),
        migration_gate,
        header_oracle,
        **kwargs,
    )
    preview = settlement_registration(
        router,
        settlement,
        activation_block=0,
        predecessor_version=0,
        release_manifest_hash=None,
    )
    object.__setattr__(
        router,
        "bootstrap_release_manifest_hash",
        preview.release_manifest_hash,
    )
    return router


def source_bridge_for_test(
    router: ActiveSettlementRouter,
) -> SourceBridgeV2:
    """Build exact release/support authorities and cross the 214-block delay."""

    manager = router._version_manager_authority
    if manager is None:
        manager = ProtocolVersionManager(router.version_manager, router)
    if type(manager) is not ProtocolVersionManager:
        raise AssertionError("Router has no exact ProtocolVersionManager")
    registration = router.registrations[router.active_version]
    if not router._install_profile_deployments(
            registration, manager=manager):
        raise AssertionError("release deployments are not installed")
    source = router._source_bridge_authority
    credit_registry = router._bridge_credit_registry_authority
    if (type(source) is not SourceBridgeV2
            or type(credit_registry) is not BridgeCreditRegistryV2
            or source.credit_registry is not credit_registry
            or credit_registry.source_bridge is not source):
        raise AssertionError("Router has no exact split source Bridge graph")
    registry = credit_registry.domain_registry
    if (registry.router is not router
            or registry.manager is not manager
            or type(registry.release_authority_descriptor)
                is not DestinationReleaseAuthorityDescriptor):
        raise AssertionError("source Bridge authority graph is split")
    canonical = router.canonical_at(
        router.active_version, registration.settlement.current_sequence
    )
    if canonical is None:
        raise AssertionError("support registry lacks canonical history")
    stage_clock = Clock(canonical.canonicalized_at_block, GENESIS_TIMESTAMP)
    confirm_clock = Clock(
        canonical.canonicalized_at_block + F_L1,
        GENESIS_TIMESTAMP,
    )
    for manifest in registration.release_manifests_by_adapter.values():
        live = registration.settlement.live_protocol
        execution_authority = (
            live._inbox_execution_authority
            if type(live) is Protocol else None
        )
        if type(execution_authority) is not InboxValidityExecutionAuthority:
            raise AssertionError("release has no exact L2 execution authority")
        if (not registry.stage(
                    source.source_domain_id,
                    source.frozen_bridge_execution_hash,
                    manifest,
                    manager=manager,
                    clock=stage_clock,
                )):
            raise AssertionError("failed to finalize canonical Bridge support")
        entry = registry.entries.get((
            source.source_domain_id,
            source.frozen_bridge_execution_hash,
            manifest.destination_domain_id,
        ))
        if (entry is None
                or (entry.confirmed_at_block is None
                    and not (
                        type(registry.registration_mpt_verifier)
                            is TestRegistrationMptVerifier
                        and registry.confirm(
                            source.source_domain_id,
                            source.frozen_bridge_execution_hash,
                            manifest.destination_domain_id,
                            clock=confirm_clock,
                            canonical_sequence=canonical.canonical_sequence,
                            proof=issue_registration_mpt_proof_for_test(
                                registry.registration_mpt_verifier,
                                registry.registration_storage_statement(
                                    source.source_domain_id,
                                    source.frozen_bridge_execution_hash,
                                    manifest.destination_domain_id,
                                    canonical_sequence=(
                                        canonical.canonical_sequence
                                    ),
                                ),
                            ),
                        )
                    ))):
            raise AssertionError("failed to confirm canonical Bridge support")
    return source


def derive_ingress_destination_domain(
    adapter: BridgeAdapter, registration: SettlementRegistration
) -> str:
    """Return only the acyclic domain precommitted by the active profile."""

    if type(adapter) is not BridgeAdapter:
        raise ValueError("destination domain requires an exact Bridge adapter")
    authorization = registration.ingress_authorizations_by_address.get(
        adapter.address
    )
    if (type(authorization) is not ProfileIngressAuthorization
            or authorization.kind is not ForceKind.BRIDGE_CREDIT
            or authorization.runtime_hash != adapter.runtime_hash
            or authorization.configuration_hash
                != adapter.configuration_hash
            or authorization.source_registry_address
                != adapter.credit_registry.address
            or authorization.source_registry_runtime_hash
                != adapter.credit_registry.runtime_hash
            or authorization.source_registry_configuration_hash
                != adapter.credit_registry.configuration_hash
            or authorization.source_registry_domain_registrar
                != adapter.credit_registry.domain_registrar
            or authorization.source_bridge_address
                != adapter.source_bridge.address
            or authorization.source_bridge_runtime_hash
                != adapter.source_bridge.runtime_hash
            or authorization.source_bridge_configuration_hash
                != adapter.source_bridge.configuration_hash
            or authorization.source_chain_id
                != adapter.source_bridge.source_chain_id
            or authorization.source_domain_id
                != adapter.source_bridge.source_domain_id
            or authorization.source_registration_epoch
                != adapter.source_bridge.source_registration_epoch
            or authorization.frozen_bridge_execution_hash
                != adapter.source_bridge.frozen_bridge_execution_hash):
        raise ValueError("adapter is not an exact release-owned ingress tuple")
    return authorization.destination_domain_id


def profile_authorization_descriptor(
    authorization: ProfileIngressAuthorization,
) -> DestinationIngressDescriptor:
    if (type(authorization) is not ProfileIngressAuthorization
            or authorization.kind is not ForceKind.BRIDGE_CREDIT):
        raise ValueError("destination descriptor requires a Bridge authorization")
    return DestinationIngressDescriptor(
        authorization.destination_chain_id,
        authorization.destination_genesis_hash,
        authorization.adapter_address,
        authorization.router_address,
        authorization.terminal_signal_verifier,
        authorization.inbox_apply_router,
        authorization.inbox_credit_store,
        authorization.protocol_release_authority,
        authorization.terminal_domain_registrar,
        authorization.terminal_accumulator,
        authorization.destination_bridge,
        authorization.destination_bridge_execution_hash,
        authorization.destination_infrastructure_hash,
        authorization.destination_namespace,
    )


def activate_ingress_adapter_for_test(
    router: ActiveSettlementRouter,
    *,
    kind: ForceKind,
    clock: Clock,
    address: str | None = None,
    source_bridge: SourceBridgeV2 | None = None,
    destination_bridge: str = "bridge:A",
) -> Kind0IngressAdapter | BridgeAdapter:
    """Exercise release-factory and permissionless ingress activation."""

    manager = router._version_manager_authority
    if manager is None:
        manager = ProtocolVersionManager(router.version_manager, router)
    if type(manager) is not ProtocolVersionManager:
        raise AssertionError("Router has no exact ProtocolVersionManager")
    registration = router.registrations[router.active_version]
    if not router._install_profile_deployments(
            registration, manager=manager):
        raise AssertionError("release deployments are unavailable")
    expected_address = address or (
        "kind0-adapter"
        if kind is ForceKind.USER_TX
        else "bridge-inbox-adapter"
    )
    authorization = registration.ingress_authorizations_by_address.get(
        expected_address
    )
    if (type(authorization) is not ProfileIngressAuthorization
            or authorization.kind is not kind):
        raise ValueError("unsupported forced-ingress kind")
    adapter = router._profile_deployments_by_version[
        router.active_version
    ].get(authorization.authorization_id)
    if kind is ForceKind.USER_TX:
        if type(adapter) is not Kind0IngressAdapter:
            raise AssertionError("release Kind0 was not atomically bound")
        return adapter
    if type(adapter) is BridgeAdapter:
        exact_source = source_bridge_for_test(router)
        if (adapter.source_bridge is not exact_source
                or (source_bridge is not None
                    and source_bridge is not exact_source)
                or adapter.credit_registry is not exact_source.credit_registry
                or authorization.destination_bridge != destination_bridge
                or adapter.credit_registry.domain_registry.router is not router):
            raise ValueError("Bridge adapter is absent from exact support profile")
        finalized = adapter.source_bridge.support_final_clock(clock.timestamp)
        activation_clock = Clock(
            max(clock.block_number, finalized.block_number), clock.timestamp
        )
        if not router.activate_profile_bridge_adapter(
                adapter,
                protocol_version=router.active_version,
                executor="permissionless-executor",
                clock=activation_clock):
            raise AssertionError("failed to activate release Bridge adapter")
        return adapter
    raise AssertionError("release Bridge deployment is missing")


def open_source_credit_for_test(
    bridge: SourceBridgeV2,
    envelope: BridgeAdmissionEnvelope,
    *,
    clock: Clock,
    enqueue_by: int,
    caller: str | None = None,
) -> str:
    receipt = bridge.send_message(
        envelope,
        clock=clock,
        enqueue_by=enqueue_by,
        caller=envelope.sender if caller is None else caller,
        msg_value=(envelope.bridge_value + envelope.bridge_fee
                   + envelope.bridge_liquidity_fee),
    )
    return receipt.credit_id


def block(p: Protocol, c: Clock, ident: str, *, slot: int | None = None,
          signed: bool = True, message_end: int | None = None,
          dispositions_ok: bool = True, discretionary: bool = True,
          release_activation: bool | None = None) -> Block:
    if slot is None:
        slot = (c.l2_slot if p.mode is Mode.RECOVERY
                else c.l2_slot)
    if p.mode is Mode.RECOVERY and p.recovery:
        r = p.recovery
        anchor_number, force_root, cutoff = r.anchor_number, r.force_root, r.force_cutoff
        version, root = r.admission_version, r.admission_root
    else:
        anchor_number = (p.normal_anchor_number if p.normal_anchor_number is not None
                         else min(c.block_number - 1, slot))
        header = p.header_oracle.header(anchor_number)
        force_root, cutoff = header.force_root, header.force_cutoff
        version = p.normal_admission_version if p.normal_admission_version is not None else p.admission_version
        root = p.normal_admission_root or p.admission_root
    header = p.header_oracle.header(anchor_number)
    start = p.core.message_cursor
    if release_activation is None:
        release_activation = p.release_activation_pending
    force_gas_budget = (ACTIVATION_FORCE_GAS_BUDGET if release_activation
                        else FORCE_GAS_BUDGET)
    end = (p._prefix_end(start, cutoff, gas_budget=force_gas_budget)
           if message_end is None else message_end)
    context = (p.recovery.recovery_id if p.mode is Mode.RECOVERY and p.recovery
               else normal_context_id(p.canonical.base_hash, version, root,
                                      anchor_number, header.block_hash))
    return Block(slot, GENESIS_TIMESTAMP + slot,
                 f"{abs(hash(ident)) % (1 << 256):064x}", p.core.tip_hash,
                 slot // 384, signed, start, end, anchor_number, header.block_hash,
                 header.timestamp, force_root, cutoff,
                 context,
                 version, root,
                 inbox_pre_cursor=start, inbox_post_cursor=end,
                 force_gas_budget=force_gas_budget,
                 release_activation=release_activation,
                 release_protocol_version=(
                     p.pending_release_protocol_version
                     if release_activation else 0),
                 release_manifest_hash=(
                     p.pending_release_manifest_hash
                     if release_activation else ""),
                 dispositions_ok=dispositions_ok, discretionary_body=discretionary)


def candidate(p: Protocol, c: Clock, ident="candidate", *, tier=Tier.NORMAL_SIGNED,
              signed=True, slot=None, message_end=None, discretionary=True,
              force_range_proof_ok=True, recovery_fields_zero=True,
              available_payload_hashes: frozenset[str] | None = None,
              release_activation: bool | None = None,
              beneficiary: str = "prover") -> Candidate:
    b = block(p, c, ident, slot=slot, signed=signed, message_end=message_end,
              discretionary=discretionary,
              release_activation=release_activation)
    r = p.recovery
    next_due = p.next_due_at(b.message_end, b.force_cutoff)
    if available_payload_hashes is None:
        # Availability is a candidate proof witness.  It is deliberately
        # independent of the admission-only test oracle retained on Message;
        # that oracle is neither stored in the durable leaf nor committed by
        # forceRoot.
        available_payload_hashes = frozenset(
            row.payload_hash for row in p.messages
            if type(row) is Message and row.kind is ForceKind.USER_TX
        )
    result = Candidate(
        ident, p.canonical.base_hash, (b,), tier,
        f"state:{ident}", "empty", next_due,
        p.core.l2_block_number + 1,
        available_payload_hashes=available_payload_hashes,
        beneficiary=beneficiary,
        proof_ok=True, force_range_proof_ok=force_range_proof_ok,
        episode=r.episode if r else 0,
        recovery_revision=r.revision if r else 0,
        recovery_id=r.recovery_id if r else "",
        recovery_fields_zero=recovery_fields_zero,
        end_terminal_root=p.core.terminal_root,
        end_terminal_count=p.core.terminal_count,
    )
    history = p.versioned_history
    authority = p._inbox_execution_authority
    if (type(history) is VersionedSettlementHistory
            and type(authority) is InboxValidityExecutionAuthority):
        rows_by_block: list[tuple[InboxRowV2, ...]] = []
        committed_blocks: list[Block] = []
        for candidate_block in result.blocks:
            rows: list[InboxRowV2] = []
            for index in range(
                    candidate_block.message_start,
                    candidate_block.message_end):
                queued = p.messages[index]
                if type(queued) is Message \
                        and queued.kind is ForceKind.USER_TX:
                    rows.append((index, 0, UINT32_MAX, "", None))
                elif type(queued) is BridgeQueueDescriptorV11:
                    rows.append((
                        index,
                        5,
                        UINT32_MAX,
                        inbox_kind1_result(index, queued),
                        queued,
                    ))
                else:
                    rows = []
                    break
            exact_rows = tuple(rows)
            rows_by_block.append(exact_rows)
            descriptors = tuple(
                p.messages[
                    candidate_block.message_start:candidate_block.message_end
                ]
            )
            committed_blocks.append(replace(
                candidate_block,
                inbox_descriptor_commitment=inbox_descriptor_commitment(
                    descriptors
                ),
                inbox_system_calldata_hash=inbox_system_calldata_hash(
                    exact_rows
                ),
                anchor_system_tx_position=ANCHOR_SYSTEM_TX_POSITION,
                inbox_system_tx_position=INBOX_SYSTEM_TX_POSITION,
            ))
        result = replace(result, blocks=tuple(committed_blocks))
        if all(
            len(rows) == block.message_end - block.message_start
            for rows, block in zip(rows_by_block, result.blocks)
        ):
            try:
                proof = authority.verify_candidate_proof(result, c)
                result = authority.prepare_candidate_execution(
                    result, tuple(rows_by_block), c, proof
                )
            except ValueError:
                pass
    return result


def migration_activation_candidate(
    router: ActiveSettlementRouter,
    settlement: VersionedSettlementHistory,
    clock: Clock,
    target_manifest_hash: bytes,
    ident: str = "migration-activation",
    beneficiary: str = "migration-prover",
) -> tuple[Candidate, tuple[InboxRowV2, ...]]:
    """Build the complete one-block public input consumed by the verifier."""

    old_registration = router.registrations.get(router.active_version)
    old = old_registration.settlement if old_registration else None
    old_protocol = old.live_protocol if old is not None else None
    if (type(old_registration) is not SettlementRegistration
            or type(old_protocol) is not Protocol
            or settlement.live_protocol is None
            or type(clock) is not Clock
            or type(target_manifest_hash) is not bytes
            or len(target_manifest_hash) != 32):
        raise ValueError("migration candidate fixture graph is incomplete")
    preview = settlement_registration(
        router,
        settlement,
        activation_block=clock.block_number,
        predecessor_version=router.active_version,
        release_manifest_hash=target_manifest_hash,
    )
    target_authority = (
        settlement.live_protocol._inbox_execution_authority
    )
    if (type(target_authority) is not InboxValidityExecutionAuthority
            or preview.release_manifest.commitment != target_manifest_hash):
        raise ValueError("migration candidate has no observed deployment")
    anchor_number = max(1, clock.block_number - F_L1)
    header = router.header_oracle.header(anchor_number)
    start = old.core.message_cursor
    end = old_protocol._prefix_end(
        start,
        header.force_cutoff,
        gas_budget=ACTIVATION_FORCE_GAS_BUDGET,
    )
    descriptors = tuple(router.forced_queue.descriptors[start:end])
    rows = tuple(
        (
            index,
            0,
            UINT32_MAX,
            "",
            None,
        )
        if type(descriptor) is Message
        and descriptor.kind is ForceKind.USER_TX
        else (
            index,
            5,
            UINT32_MAX,
            inbox_kind1_result(index, descriptor),
            descriptor,
        )
        for index, descriptor in enumerate(descriptors, start)
    )
    slot = old.core.tip_slot + 1
    if slot > clock.l2_slot + CLOCK_SKEW:
        raise ValueError("migration activation slot is not currently provable")
    block_hash = hashlib.sha256(
        f"migration:{ident}:{settlement.protocol_version}:{slot}".encode()
    ).hexdigest()
    block = Block(
        slot=slot,
        evm_timestamp=GENESIS_TIMESTAMP + slot,
        block_hash=block_hash,
        parent_hash=old.core.tip_hash,
        window=slot // 384,
        scheduled_signature_ok=False,
        message_start=start,
        message_end=end,
        anchor_number=anchor_number,
        anchor_hash=header.block_hash,
        anchor_timestamp=header.timestamp,
        force_root=header.force_root,
        force_cutoff=header.force_cutoff,
        context_id=(
            f"migration:{old_protocol.canonical.base_hash}:"
            f"{settlement.protocol_version}"
        ),
        admission_version=old_protocol.admission_version,
        admission_root=old_protocol.admission_root,
        inbox_pre_cursor=start,
        inbox_post_cursor=end,
        force_gas_budget=ACTIVATION_FORCE_GAS_BUDGET,
        release_activation=True,
        release_protocol_version=settlement.protocol_version,
        release_manifest_hash=target_manifest_hash.hex(),
        dispositions_ok=True,
        discretionary_body=False,
        inbox_descriptor_commitment=inbox_descriptor_commitment(descriptors),
        inbox_system_calldata_hash=inbox_system_calldata_hash(rows),
        anchor_system_tx_position=ANCHOR_SYSTEM_TX_POSITION,
        inbox_system_tx_position=INBOX_SYSTEM_TX_POSITION,
    )
    proved = Candidate(
        ident,
        old_protocol.canonical.base_hash,
        (block,),
        Tier.ESCAPE_UNSIGNED,
        f"state:{ident}",
        f"data:{ident}",
        old_protocol.next_due_at(end, header.force_cutoff),
        old.core.l2_block_number + 1,
        proof_ok=True,
        force_range_proof_ok=True,
        beneficiary=beneficiary,
        end_terminal_root=old.core.terminal_root,
        end_terminal_count=old.core.terminal_count,
        available_payload_hashes=frozenset(
            row.payload_hash
            for row in descriptors
            if type(row) is Message and row.kind is ForceKind.USER_TX
        ),
    )
    return proved, rows


def activate_normal(p: Protocol, c: Clock) -> None:
    arm_clock = Clock(c.block_number - 1, c.timestamp - 12)
    check("normal context arms", p.arm_normal_context(arm_clock) == "ARMED")
    check("normal context activates", p.activate_normal_context(c) == "ACTIVATED")


def open_recovery(p: Protocol, block_number=1_100) -> Clock:
    trigger = clock(block_number, p.core.tip_slot + DELTA_FINAL_LAG + 1)
    check("P1 objective sync opens recovery", p.sync(trigger))
    return trigger


def recovery_submit_clock(p: Protocol) -> Clock:
    assert p.recovery is not None
    return clock(p.recovery.anchor_number + F_L1, p.recovery.escape_slot + 1)


def escape_candidate(p: Protocol, c: Clock, ident="escape") -> Candidate:
    assert p.recovery is not None
    return candidate(p, c, ident, tier=Tier.ESCAPE_UNSIGNED, signed=False,
                     slot=p.recovery.escape_slot, discretionary=False,
                     recovery_fields_zero=False)


def test_canonical_outputs_and_migration() -> None:
    p = protocol(mode=Mode.PREACTIVE)
    pre = Clock(950, GENESIS_TIMESTAMP - 100)
    check("P2 preactivation slot saturates", pre.l2_slot == 0)
    check("P3 preactive rejects", p.submit(candidate(p, clock(1_100, 1_100)), clock(1_100, 1_100)) == "REJECTED_PREACTIVE")
    check("P4 migration requires the unique Router verifier path",
          not hasattr(p, "activate_migration") and p.mode is Mode.PREACTIVE)
    check("P4a migration has no caller-asserted system-account booleans",
          "activate_migration" not in Protocol.__dict__)
    check("P4g launch never surrenders authority to an unproved target",
          p.mode is Mode.PREACTIVE
          and "MIGRATION_ACTIVATION_PROOF_ADOPTED_ATOMICALLY"
              not in p.events)
    latch = L2ActivationLatch()
    check("P4e legacy calls cannot activate or invoke V2 system ingress",
          not latch.activate_from_anchor(
              custom_system_tx=False, slot_chain_fork_active=False,
              l1_cutover_authenticated=False)
          and not latch.inbox_apply(custom_system_tx=False)
          and not latch.bridge_v2_call()
          and not latch.active)
    check("P4f first post-cutover custom anchor activates the L2 latch",
          latch.activate_from_anchor(
              custom_system_tx=True, slot_chain_fork_active=True,
              l1_cutover_authenticated=True)
          and latch.inbox_apply(custom_system_tx=True)
          and latch.bridge_v2_call()
          and not latch.inbox_apply(custom_system_tx=False))
    preactive_protocol = protocol(mode=Mode.PREACTIVE)
    preactive_now = clock(1_100, 1_100)
    preactive_router = routed_ingress_for_test(preactive_protocol)
    preactive_source = source_bridge_for_test(preactive_router)
    preactive_adapter = activate_ingress_adapter_for_test(
        preactive_router,
        kind=ForceKind.BRIDGE_CREDIT,
        clock=preactive_now,
        source_bridge=preactive_source,
    )
    preactive_kind0 = activate_ingress_adapter_for_test(
        preactive_router,
        kind=ForceKind.USER_TX,
        clock=preactive_now,
    )
    preactive_source_clock = preactive_source.support_final_clock(
        preactive_now.timestamp
    )
    preactive_envelope = bridge_message(
        1_100, "preactive", value=1, fee=1
    )
    preactive_id = preactive_source.send_message(
        preactive_envelope,
        clock=preactive_source_clock,
        enqueue_by=preactive_now.timestamp + MAX_BRIDGE_ENQUEUE_DELAY,
        caller=preactive_envelope.sender,
        msg_value=(
            preactive_envelope.bridge_value + preactive_envelope.bridge_fee
            + preactive_envelope.bridge_liquidity_fee
        ),
    ).credit_id
    check("P4b preactive bridge ingress cannot create a queue credit",
          payable_reverted(lambda: preactive_adapter.enqueue(
              preactive_source_clock, envelope=preactive_envelope,
              caller="relayer", deposit=1))
          and not preactive_adapter.records)
    preactive_user = message(1_100, "preactive-user")
    check("P4d preactive kind-0 ingress cannot create a queue leaf",
          payable_reverted(lambda: preactive_kind0.enqueue(
              clock(1_100, 1_100), preactive_user,
              caller=preactive_user.sender,
              deposit=preactive_user.prepaid))
          and not preactive_protocol.messages)
    dirty = protocol(
        mode=Mode.PREACTIVE, messages=[message(1_100, "dirty")]
    )
    check("P4c a nonempty preactive queue has no direct activation surface",
          not hasattr(dirty, "activate_migration")
          and dirty.mode is Mode.PREACTIVE
          and len(dirty.messages) == 1)
    # The production cutover path is exercised by the version-manager
    # migration properties below.  This local instance checks only the
    # post-cutover ingress invariant; no test-only Protocol transition exists.
    p = protocol(tip_slot=1_051)
    post_router = routed_ingress_for_test(p)
    post_kind0 = activate_ingress_adapter_for_test(
        post_router,
        kind=ForceKind.USER_TX,
        clock=clock(1_101, 1_101),
    )
    check("P5 an activated settlement enables only routed ingress",
          not p.release_activation_pending
          and post_kind0.enqueue(
              clock(1_101, 1_101), preactive_user,
              caller=preactive_user.sender, deposit=preactive_user.prepaid)
              == "QUEUED:0")
    q = protocol()
    c = clock(1_100, 1_100)
    activate_normal(q, c)
    cand = candidate(q, c, "explicit-output")
    check("P6 activated candidate accepted", q.submit(cand, c) == "ACCEPTED")
    close = Clock(1_234, q.normal_deadline)
    q.sync(close)
    check("P7 L1 stamps landing block and proof advances EVM height/context",
          q.canonical.canonicalized_at_block == 1_234
          and q.core.state_root == "state:explicit-output"
          and q.core.l2_block_number == 901
          and q.core.next_base_fee == 101)


def test_admission_freeze_and_tier_canonicalization() -> None:
    p = protocol()
    c = clock(1_100, 1_100)
    activate_normal(p, c)
    first = candidate(p, c, "first")
    check("P8 normal candidate accepted", p.submit(first, c) == "ACCEPTED")
    frozen = (p.normal_admission_version, p.normal_admission_root)
    p.tombstone()
    check("P9 version and root move together", frozen != (p.admission_version, p.admission_root))
    replacement = candidate(p, clock(1_101, 1_101), "frozen")
    check("P10 open normal retains pair", p.submit(replacement, clock(1_101, 1_101)) in {"ACCEPTED", "IGNORED"})
    q = protocol()
    preopen = candidate(q, c, "preopen")
    check("P11 pre-activation signatures are not candidates",
          q.submit(preopen, c) == "REJECTED")
    activate_normal(q, c)
    malformed = candidate(q, c, "unused", recovery_fields_zero=False)
    check("P11 tier-1 unused recovery fields must be zero", q.submit(malformed, c) == "REJECTED")
    bad_time = candidate(q, c, "bad-time")
    bad_time = replace(
        bad_time,
        blocks=(replace(bad_time.blocks[0], evm_timestamp=bad_time.blocks[0].evm_timestamp + 1),),
    )
    check("P11a signed slot must equal EVM header time",
          q.submit(bad_time, c) == "REJECTED")
    armed = protocol()
    arm_clock = clock(1_099, 1_088)
    assert armed.arm_normal_context(arm_clock) == "ARMED"
    fork_a, fork_b = armed.snapshot(), armed.snapshot()
    fork_header = fork_b.header_oracle.header(1_099)
    object.__setattr__(
        fork_b,
        "header_oracle",
        fork_b.header_oracle.fork_for_test({
            1_099: replace(fork_header, block_hash="f" * 64)
        }),
    )
    assert fork_a.activate_normal_context(c) == "ACTIVATED"
    assert fork_b.activate_normal_context(c) == "ACTIVATED"
    check("P11b reorged arm blocks cannot share a slash context",
          fork_a.normal_context_id != fork_b.normal_context_id)
    surviving = armed.snapshot()
    assert surviving.activate_normal_context(c) == "ACTIVATED"
    check("P11c surviving arm block deliberately preserves its context",
          surviving.normal_context_id == fork_a.normal_context_id)
    stale_arm = protocol()
    assert stale_arm.arm_normal_context(clock(100, 100)) == "ARMED"
    check("P11d arm hash must remain natively readable",
          stale_arm.activate_normal_context(clock(356, 356)) == "REJECTED")
    check("P11e stale arm is permissionlessly replaced",
          stale_arm.arm_normal_context(clock(356, 356)) == "REARMED"
          and stale_arm.normal_arm_block_number == 356)


def test_force_merkle_bounds_and_auth() -> None:
    p = protocol()
    c = clock(1_100, 1_100)
    p_router = routed_ingress_for_test(p)
    kind0_adapter = activate_ingress_adapter_for_test(
        p_router, kind=ForceKind.USER_TX, clock=c
    )
    bad = replace(message(1_100, "bad"), outer_authorized=False)
    check("P12 outer sender authorization required",
          payable_reverted(lambda: kind0_adapter.enqueue(
              c, bad, caller=bad.sender, deposit=bad.prepaid)))
    for i in range(100):
        row = message(
            1_100, f"m{i}", gas=MIN_FORCE_ACCOUNTED_GAS, size=1
        )
        assert kind0_adapter.enqueue(
            c, row, caller=row.sender, deposit=row.prepaid
        ) == f"QUEUED:{i}"
    check("P13 per-block count cap", p._prefix_end(0, 100) == 64)
    check("P14 range proof has a fixed bound",
          FORCE_TREE_DEPTH == 64 and MAX_FORCE_RANGE_PROOF_HASHES == 257)
    anchored = protocol(messages=[message(1_100, "a")])
    activate_normal(anchored, c)
    good = candidate(anchored, c, "good")
    forged = replace(good, force_range_proof_ok=False)
    check("P15 skip/reorder proof rejects", anchored.submit(forged, c) == "REJECTED")
    bridge = message(1_100, "bridge", kind=ForceKind.BRIDGE_CREDIT)
    bridge_protocol = protocol()
    bridge_router = routed_ingress_for_test(bridge_protocol)
    bridge_adapter = activate_ingress_adapter_for_test(
        bridge_router, kind=ForceKind.BRIDGE_CREDIT, clock=c
    )
    bridge_clock = bridge_adapter.source_bridge.support_final_clock(c.timestamp)
    bridge_id = open_source_credit_for_test(
        bridge_adapter.source_bridge,
        bridge,
        clock=bridge_clock,
        enqueue_by=bridge_clock.timestamp + MAX_BRIDGE_ENQUEUE_DELAY,
    )
    check("P16 non-expiring bridge credit admits atomically",
          bridge_adapter.enqueue(
              bridge_clock, envelope=bridge, caller="permissionless",
              deposit=bridge.prepaid) == "QUEUED:0"
          and bridge_adapter.records[bridge_id].index == 0
          and type(bridge_router.forced_queue.descriptors[0])
              is BridgeQueueDescriptorV11)
    check("P17 gas geometry",
          ANCHOR_GAS_MAX + FORCE_GAS_BUDGET + SYSTEM_GAS_MARGIN
              <= L2_BLOCK_GAS_LIMIT
          and ANCHOR_ACTIVATION_GAS_MAX + ACTIVATION_FORCE_GAS_BUDGET
              + SYSTEM_GAS_MARGIN <= L2_BLOCK_GAS_LIMIT)
    activation_tx = SystemTransactionV2(
        SYSTEM_TX_TYPE, 167_000, SYSTEM_KIND_ANCHOR, 0,
        ANCHOR_ACTIVATION_GAS_MAX, "anchor:v2", 0,
        ANCHOR_ACTIVATION_SELECTOR)
    steady_tx = replace(
        activation_tx, system_nonce=1, gas_limit=ANCHOR_GAS_MAX,
        selector=ANCHOR_STEADY_SELECTOR)
    inbox_tx = replace(
        activation_tx, system_kind=SYSTEM_KIND_INBOX_APPLY,
        gas_limit=INBOX_APPLY_GAS_MAX, to="inbox-apply",
        selector=INBOX_APPLY_SELECTOR)
    check("P17a one unsigned system envelope covers activation and steady Anchor",
          activation_tx.valid(
              block_number=100, first_v2_block_number=100,
              launch_imported_l2_block_number=99,
              first_activation=True, l2_chain_id=167_000)
          and steady_tx.valid(
              block_number=101, first_v2_block_number=100,
              launch_imported_l2_block_number=99,
              first_activation=False, l2_chain_id=167_000)
          and not replace(activation_tx, signed=True).valid(
              block_number=100, first_v2_block_number=100,
              launch_imported_l2_block_number=99,
              first_activation=True, l2_chain_id=167_000)
          and not replace(activation_tx, gas_limit=ANCHOR_GAS_MAX).valid(
              block_number=100, first_v2_block_number=100,
              launch_imported_l2_block_number=99,
              first_activation=True, l2_chain_id=167_000)
          and not activation_tx.valid(
              block_number=100, first_v2_block_number=100,
              launch_imported_l2_block_number=99,
              first_activation=True, l2_chain_id=167_001)
          and not activation_tx.valid(
              block_number=100, first_v2_block_number=99,
              launch_imported_l2_block_number=99,
              first_activation=True, l2_chain_id=167_000))
    system_rules = SystemExecutionRulesV2(
        "system:inbox", "system:inbox", "system:inbox", 0, 0, 0, 0, 0,
        20, 100, 21_000 + 4 * 20 + 16 * 100,
        True, True, True, True)
    check("P17d kind-1 and accountless system execution are fully distinct",
          inbox_tx.valid(
              block_number=100, first_v2_block_number=100,
              launch_imported_l2_block_number=99,
              first_activation=True, l2_chain_id=167_000)
          and system_rules.valid(inbox_tx)
          and not replace(inbox_tx, signed=True).valid(
              block_number=100, first_v2_block_number=100,
              launch_imported_l2_block_number=99,
              first_activation=True, l2_chain_id=167_000)
          and not replace(
              system_rules, sender_nonce_after=1).valid(inbox_tx))
    activation_backlog = protocol(messages=[
        message(0, f"activation-backlog-{index}", gas=5_000_000)
        for index in range(4)])
    activation_backlog.release_activation_pending = True
    activation_backlog.pending_release_protocol_version = 1
    activation_backlog.pending_release_manifest_hash = "manifest:1"
    activation_clock = clock(1_100, 1_100)
    assert activation_backlog.arm_normal_context(
        clock(1_099, 1_099)) == "ARMED"
    assert activation_backlog.activate_normal_context(
        activation_clock) == "ACTIVATED"
    activation_candidate = candidate(
        activation_backlog, activation_clock, "activation-prefix",
        discretionary=False)
    activation_first = activation_candidate.tip
    activation_second = replace(
        activation_first, slot=activation_first.slot + 1,
        evm_timestamp=activation_first.evm_timestamp + 1,
        block_hash="activation-second", parent_hash=activation_first.block_hash,
        message_start=activation_first.message_end, message_end=4,
        inbox_pre_cursor=activation_first.message_end, inbox_post_cursor=4,
        force_gas_budget=FORCE_GAS_BUDGET, release_activation=False,
        release_protocol_version=0, release_manifest_hash="")
    activation_candidate = replace(
        activation_candidate,
        blocks=(activation_first, activation_second),
        end_l2_block_number=activation_backlog.core.l2_block_number + 2,
        next_due_at=activation_backlog.next_due_at(4, 4))
    activation_end = activation_first.message_end
    invalid_20m_block = replace(
        activation_first, message_end=4, inbox_post_cursor=4,
        force_gas_budget=FORCE_GAS_BUDGET)
    invalid_20m_candidate = replace(
        activation_candidate, blocks=(invalid_20m_block,),
        next_due_at=activation_backlog.next_due_at(4, 4))
    check("P17c activation uses its explicit 13m maximal-prefix budget",
          activation_end == 2
          and activation_backlog._prefix_end(activation_end, 4) == 4
          and not activation_backlog._valid_normal(
              invalid_20m_candidate, activation_clock)
          and activation_backlog.submit(
              activation_candidate, activation_clock) == "ACCEPTED"
          and ANCHOR_ACTIVATION_GAS_MAX
              + sum(row.accounted_gas
                    for row in activation_backlog.messages[:activation_end])
              + SYSTEM_GAS_MARGIN <= L2_BLOCK_GAS_LIMIT)
    too_long = replace(message(1_100, "too-long"),
                       valid_until=c.timestamp + MAX_FORCE_VALIDITY_SECONDS + 1)
    bounded_protocol = protocol()
    bounded_router = routed_ingress_for_test(bounded_protocol)
    bounded_adapter = activate_ingress_adapter_for_test(
        bounded_router, kind=ForceKind.USER_TX, clock=c
    )
    check("P17a user payload validity is bounded",
          payable_reverted(lambda: bounded_adapter.enqueue(
              c, too_long, caller=too_long.sender,
              deposit=too_long.prepaid)))
    check("P17b depth-64 frontier leaves final index unused",
          MAX_FORCE_QUEUE_ITEMS == (1 << 64) - 1)
    surplus_protocol = protocol(messages=[message(1_100, "forced-surplus")])
    surplus_queue = surplus_protocol.forced_queue
    routed_ingress_for_test(surplus_protocol)
    original_liability = surplus_queue.accounted_liabilities
    surplus_commit_clock = clock(1_101, 1_101)
    activate_normal(surplus_protocol, surplus_commit_clock)
    surplus_candidate = candidate(
        surplus_protocol,
        surplus_commit_clock,
        "forced-surplus-consumption",
        beneficiary="surplus-prover",
    )
    surplus_protocol._commit(surplus_candidate, surplus_commit_clock)
    check("P17d forced ETH is surplus and cannot DoS queue liabilities",
          surplus_queue.force_eth(1)
          and surplus_queue.accounted_liabilities == original_liability
          and surplus_queue.withdraw_claimable("surplus-prover")
              == original_liability
          and surplus_queue.escrow_balance == 1
          and surplus_queue.accounted_liabilities == 0)


def test_late_close_and_constant_boundary() -> None:
    p = protocol()
    opened = clock(1_100, 1_100)
    p_router = routed_ingress_for_test(p)
    p_adapter = activate_ingress_adapter_for_test(
        p_router, kind=ForceKind.USER_TX, clock=opened
    )
    activate_normal(p, opened)
    best = candidate(p, opened, "ordinary")
    check("P18 normal accepts", p.submit(best, opened) == "ACCEPTED")
    enqueue_l2 = opened.l2_slot + 1
    append_clock = clock(1_101, enqueue_l2)
    late_message = message(enqueue_l2, "late")
    check("P19 post-open append admits", p_adapter.enqueue(
        append_clock, late_message, caller=late_message.sender,
        deposit=late_message.prepaid) == "QUEUED:0")
    delayed = clock(1_300, enqueue_l2 + FORCE_DELAY + 1)
    before = p.core.tip_hash
    check("P20 delayed close transitions", p.sync(delayed))
    check("P21 newly due omitted head never commits", p.core.tip_hash == before and p.mode is Mode.RECOVERY)

    q = protocol(tip_slot=100, messages=[message(0, "covered")])
    accepted_at = clock(150, FORCE_DELAY - W_SETTLE_SECONDS - T_INCLUDE_MAX_SECONDS - 1)
    activate_normal(q, accepted_at)
    covered = candidate(q, accepted_at, "covered")
    check("P22 horizon-covering candidate accepted", q.submit(covered, accepted_at) == "ACCEPTED")
    close = Clock(400, q.normal_deadline)
    check("P23 covered best commits", q.sync(close) and q.core.tip_hash == covered.tip.block_hash)
    many = protocol(messages=[message(i, str(i)) for i in range(200_000)])
    queries = many.boundary_queries
    many.force_due(clock(500, 0))
    check("P24 due decision is one boundary read for 200k backlog", many.boundary_queries == queries + 1)
    check("P25 force geometry includes landing horizon", FORCE_DELAY >= W_SETTLE_SECONDS + T_INCLUDE_MAX_SECONDS)

    old_anchor = protocol(tip_slot=100)
    enqueue = clock(100, 100)
    old_router = routed_ingress_for_test(old_anchor)
    old_adapter = activate_ingress_adapter_for_test(
        old_router, kind=ForceKind.USER_TX, clock=enqueue
    )
    post_anchor = message(100, "post-anchor")
    assert old_adapter.enqueue(
        enqueue, post_anchor, caller=post_anchor.sender,
        deposit=post_anchor.prepaid
    ) == "QUEUED:0"
    submit_at = clock(250, 300)
    activate_normal(old_anchor, submit_at)
    omitted = candidate(old_anchor, submit_at, "old-anchor-omits")
    check("P26 current-root boundary rejects post-anchor due omission",
          old_anchor.submit(omitted, submit_at) == "REJECTED")

    gap = protocol(tip_slot=100, seat=False)
    gap_clock = clock(200, 100 + G_MAX)
    activate_normal(gap, gap_clock)
    exact_gap = candidate(gap, gap_clock, "exact-gap", slot=100 + G_MAX)
    check("P26a exact tier-1 parent gap is accepted",
          gap.submit(exact_gap, gap_clock) == "ACCEPTED")
    beyond = protocol(tip_slot=100, seat=False)
    assert beyond.arm_normal_context(clock(199, 100 + G_MAX - 12)) == "ARMED"
    check("P26aa gap beyond G_MAX objectively enters recovery",
          beyond.activate_normal_context(clock(200, 100 + G_MAX + 1)) == "SYNCED"
          and beyond.mode is Mode.RECOVERY)
    evidence_path_blocks = (
        MAX_ARM_AGE_BLOCKS
        + (W_SETTLE_SECONDS + CLOCK_SKEW + 384 + EVIDENCE_DELAY_SECONDS
           + REORG_MARGIN_SECONDS + L1_SLOT_SECONDS - 1) // L1_SLOT_SECONDS
        + 2
    )
    check("P26ab G_MAX and EIP-2935 geometries are pinned",
          G_MAX == DELTA_FINAL_LAG
          and (G_MAX + CLOCK_SKEW + 383) // 384 <= MAX_WINDOWS_PER_CANDIDATE
          and evidence_path_blocks < EIP2935_HISTORY_ENTRIES)

    lost = replace(message(0, "lost"), payload_available=False,
                   valid_until=GENESIS_TIMESTAMP + 10)
    expired = protocol(tip_slot=0, messages=[lost])
    expired_clock = clock(10, 20)
    activate_normal(expired, expired_clock)
    check("P26b expired payload is consumable from durable descriptor",
          expired.submit(candidate(expired, expired_clock, "expired-meta"),
                         expired_clock) == "ACCEPTED")
    unexpired = protocol(tip_slot=0, messages=[
        replace(lost, valid_until=GENESIS_TIMESTAMP + 100)])
    activate_normal(unexpired, expired_clock)
    check("P26c unavailable unexpired payload rejects",
          unexpired.submit(candidate(
              unexpired, expired_clock, "missing-bytes",
              available_payload_hashes=frozenset()),
                           expired_clock) == "REJECTED")


def test_recovery_refresh_and_historical_immutability() -> None:
    p = protocol(seat=False, messages=[message(0, "forced")])
    ingress_router = routed_ingress_for_test(p)
    ingress_adapter = activate_ingress_adapter_for_test(
        ingress_router,
        kind=ForceKind.USER_TX,
        clock=clock(1_099, p.core.tip_slot),
    )
    trigger = open_recovery(p)
    original = copy.deepcopy(p.recovery)
    parent_before = p.header_oracle.header(original.anchor_number)
    during = clock(trigger.block_number + 1, trigger.l2_slot + 1)
    during_message = message(during.l2_slot, "during")
    check("P27 append during recovery admits", ingress_adapter.enqueue(
        during, during_message, caller=during_message.sender,
        deposit=during_message.prepaid) == "QUEUED:1")
    check("P28 append defers beyond live round", p.messages[-1].due_at == original.expires_at + 1)
    check(
        "P29 historical parent is never rewritten",
        p.header_oracle.header(original.anchor_number) == parent_before,
    )
    early = clock(original.anchor_number + F_L1 - 1, original.escape_slot + 1)
    check("P30 insufficient depth rejects", p.submit(escape_candidate(p, early), early) == "REJECTED")
    old = escape_candidate(p, recovery_submit_clock(p), "old")
    late = Clock(5_000, original.expires_at + 1)
    check("P31 expiry rolls before parsing", p.submit(old, late) == "SYNCED")
    check("P32 refreshed round has current queue and current start", p.recovery.force_cutoff == 2 and p.recovery.round_start_slot == late.l2_slot)
    fresh_clock = recovery_submit_clock(p)
    check("P33 stale proof rejects", p.submit(old, fresh_clock) == "REJECTED")
    fresh = escape_candidate(p, fresh_clock, "fresh")
    p.canonical_state_witness_available = False
    check("P33a a state root alone cannot reconstruct a lost prestate",
          p.submit(fresh, fresh_clock) == "REJECTED")
    p.canonical_state_witness_available = True
    p.canonical_code_preimages_available = False
    check("P33b trie nodes without code preimages cannot execute the prestate",
          p.submit(fresh, fresh_clock) == "REJECTED")
    p.canonical_code_preimages_available = True
    check("P34 current deterministic target commits", p.submit(fresh, fresh_clock) == "COMMITTED")

    stale = protocol(seat=False)
    open_recovery(stale)
    assert stale.recovery is not None
    stale_clock = clock(stale.recovery.anchor_number + F_L1,
                        stale.recovery.round_start_slot + DELTA_TIP + 1)
    stale_signed = candidate(stale, stale_clock, "stale-signed",
                             tier=Tier.RECOVERY_SIGNED,
                             slot=stale.recovery.round_start_slot,
                             recovery_fields_zero=False)
    check("P34a stale tier-2 tip rejects",
          stale.submit(stale_signed, stale_clock) == "REJECTED")


def test_registry_liability_and_release_units() -> None:
    active = [Generation(f"builder-{i}", 100 + (i // 2), i, 0) for i in range(64)]
    registry = RegistryLifecycle(active)
    # Builders 0 and 1 tie at minimum bond; greatest registration index loses.
    newcomer = Generation("new", 101, 1000, ENTRY_DELAY_WINDOWS)
    check("P35 full-table replacement is delayed and strict", registry.admit(newcomer, 0))
    check("P36 deterministic tie victim moves to liability", registry.liabilities[0].registration_index == 1)
    check("P37 displaced generation remains retained", len(registry.active) == 64 and len(registry.liabilities) == 1)
    check("P37a liability generation cannot extend reservations",
          not registry.reserve("builder-1", 1, 0))
    retained = registry.liability_ring[0]
    assert retained is not None
    reuse = Generation("builder-1", 50_000, 9_999,
                       retained[1] + ENTRY_DELAY_WINDOWS)
    check("P37b retained address cannot be reused", not registry.admit(reuse, retained[1]))
    assert registry.release_liability(0, retained[1])
    check("P37c address reuse after safe release gets a new generation",
          registry.admit(reuse, retained[1]))
    low = Generation("low", 1, 1001, ENTRY_DELAY_WINDOWS)
    check("P38 lower bond cannot displace", not registry.admit(low, 0))
    for j in range(3):
        assert registry.admit(Generation(f"high-{j}", 10_000 + j, 2000 + j,
                                         ENTRY_DELAY_WINDOWS), 0)
    check("P39 per-window replacement rate is hard", not registry.admit(
        Generation("fifth", 20_000, 3000, ENTRY_DELAY_WINDOWS), 0))
    check("P40 liability residence is strictly below ring horizon",
          MAX_LIABILITY_RESIDENCE_WINDOWS < MAX_LIVE_WINDOWS)
    check("P41 tranche release compares slots with slots",
          not tranche_releasable(5, 384 * 6 - 1, 10_000, 9_000)
          and tranche_releasable(5, 384 * 6, 10_000, 9_000))

    churn = RegistryLifecycle([
        Generation(f"base-{i}", 100 + i, i, 0, 16) for i in range(64)
    ])
    serial = 10_000
    for window in range(MAX_LIVE_WINDOWS + 1):
        for _ in range(MAX_REPLACEMENTS_PER_WINDOW):
            serial += 1
            assert churn.admit(
                Generation(f"churn-{serial}", 1_000_000 + serial, serial,
                           window + ENTRY_DELAY_WINDOWS,
                           window + MAX_TRANCHE_AHEAD_WINDOWS),
                window,
            )
    check("P41a max-churn ring reuses only released positions",
          churn.movement_sequence == 4 * (MAX_LIVE_WINDOWS + 1)
          and len(churn.liabilities) == MAX_LIABILITY_GENERATIONS)

    bounded_gate = MigrationGate()
    assert bounded_gate._bootstrap_from_router(1)
    bounded = RegistryLifecycle(
        [Generation("long-lived", 10, 0, 0)], migration_gate=bounded_gate)
    for current_window in range(2_000):
        assert bounded.reserve("long-lived", current_window + 16,
                               current_window)
        assert len(bounded.open_reservations) <= 17
    check("P41b historical reservations enter evidence-safe liability",
          len(bounded.open_reservations) == 17
          and bounded.settle_reservations_before(2_015) == 16
          and len(bounded.open_reservations) == 1)

    churn_gate = MigrationGate()
    assert churn_gate._bootstrap_from_router(1)
    reservation_churn = RegistryLifecycle(
        [Generation(f"seat-{index}", index + 1, index, 0)
         for index in range(64)], migration_gate=churn_gate)
    next_registration = 64
    for current_window in range(MAX_TRANCHE_AHEAD_WINDOWS + 1):
        for generation in tuple(reservation_churn.active):
            for target_window in range(
                    current_window,
                    current_window + MAX_TRANCHE_AHEAD_WINDOWS + 1):
                assert reservation_churn.reserve(
                    generation.address, target_window, current_window)
        for move in range(MAX_REPLACEMENTS_PER_WINDOW):
            newcomer = Generation(
                f"replacement-{current_window}-{move}",
                10_000 + next_registration, next_registration,
                current_window + ENTRY_DELAY_WINDOWS)
            next_registration += 1
            assert reservation_churn.admit(newcomer, current_window)
            for target_window in range(
                    current_window,
                    current_window + MAX_TRANCHE_AHEAD_WINDOWS + 1):
                assert reservation_churn.reserve(
                    newcomer.address, target_window, current_window)
    check("P41c replacement converts future reservations to claim-only liability",
          MAX_LIVE_RESERVATIONS == 1_088
          and len(reservation_churn.open_reservations)
              == MAX_LIVE_RESERVATIONS
          and len(reservation_churn.liable_reservations) == 2_180
          and all(row[1] >= MAX_TRANCHE_AHEAD_WINDOWS
                  for row in reservation_churn.open_reservations))


def test_data_gc_reorg_and_geometry() -> None:
    p = protocol()
    c = clock(1_100, 1_100)
    expiry = c.timestamp + P_PROVE_MAX + W_SETTLE_SECONDS + REORG_MARGIN_SECONDS
    check("P42 session opens", p.open_session(c, "alice", "alice", expiry) == "OPENED")
    check("P43 wrong owner cannot post", p.post_data(c, "alice", "mallory", body_root="x", same_tx_blobhash=True, kzg_opening_ok=True) == "REJECTED")
    check("P44 authenticated chunk posts", p.post_data(c, "alice", "alice", body_root="x", same_tx_blobhash=True, kzg_opening_ok=True) == "POSTED")
    check("P45 immutable seal", p.seal_session(c, "alice", "alice") and p.post_data(c, "alice", "alice", body_root="y", same_tx_blobhash=True, kzg_opening_ok=True) == "REJECTED")
    for i in range(20):
        p.sessions[f"expired-{i:02}"] = DataSession(f"expired-{i:02}", str(i), c.timestamp - 1)
    check("P46 one GC call is bounded", p.gc_sessions(c) <= MAX_GC_STEPS)
    pre = protocol().snapshot()
    post = pre.snapshot()
    activate_normal(post, c)
    post.submit(candidate(post, c, "reorg"), c)
    post.sync(Clock(1_200, post.normal_deadline))
    post = pre.snapshot()
    check("P47 replay truncates all effects", post.identical(pre))
    end_to_end = T_INCLUDE_MAX_SECONDS + ESCAPE_OFFSET + T_INCLUDE_MAX_SECONDS + CLOCK_SKEW
    check("P48 recovery fits final lag", end_to_end <= DELTA_FINAL_LAG)
    check("P49 escape covers depth and proof", ESCAPE_OFFSET >= T_DEPTH_MAX + P_PROVE_MAX)
    check("P50 candidate totals are independent", MAX_FORCE_CANDIDATE_MESSAGES == 256 and MAX_FORCE_CANDIDATE_GAS == 80_000_000)

    delayed = protocol()
    opened = clock(1_100, 1_100)
    data_expiry = opened.timestamp + P_PROVE_MAX + W_SETTLE_SECONDS + REORG_MARGIN_SECONDS
    assert delayed.open_session(opened, "late-data", "alice", data_expiry) == "OPENED"
    assert delayed.post_data(opened, "late-data", "alice", body_root="body",
                             same_tx_blobhash=True, kzg_opening_ok=True) == "POSTED"
    assert delayed.seal_session(opened, "late-data", "alice")
    activate_normal(delayed, opened)
    base = candidate(delayed, opened, "data-best")
    data_block = replace(base.tip, data_records=(("late-data", 0),))
    with_data = replace(
        base,
        blocks=(data_block,),
        session_refs=(SessionRef("late-data", 1, delayed.sessions["late-data"].root),),
    )
    assert delayed.submit(with_data, opened) == "ACCEPTED"
    after_expiry = Clock(2_000, data_expiry + 1)
    old_tip = delayed.core.tip_hash
    check("P50a delayed close cannot commit expired data",
          delayed.sync(after_expiry) and delayed.core.tip_hash == old_tip)
    delayed.gc_sessions(after_expiry)
    check("P50b GC retained the best until sync cleared it",
          "late-data" not in delayed.sessions)

    bridge_protocol = protocol()
    prepared_clock = clock(1_099, 4_600)
    bridge_router = routed_ingress_for_test(bridge_protocol)
    source = source_bridge_for_test(bridge_router)
    adapter = activate_ingress_adapter_for_test(
        bridge_router, kind=ForceKind.BRIDGE_CREDIT, clock=prepared_clock,
        source_bridge=source, destination_bridge="bridge:A",
    )
    d2_protocol = protocol()
    d2_router = routed_ingress_for_test(
        d2_protocol,
        release_profile_ingress_specs=(
            (ForceKind.USER_TX, "kind0-adapter", ""),
            (
                ForceKind.BRIDGE_CREDIT,
                "bridge-inbox-adapter:d2",
                "bridge:B",
            ),
        ),
    )
    source_d2 = source_bridge_for_test(d2_router)
    adapter_d2 = activate_ingress_adapter_for_test(
        d2_router, kind=ForceKind.BRIDGE_CREDIT, clock=prepared_clock,
        source_bridge=source_d2, destination_bridge="bridge:B",
        address="bridge-inbox-adapter:d2",
    )
    enqueue_by = prepared_clock.timestamp + MAX_BRIDGE_ENQUEUE_DELAY
    bridge_envelopes: dict[tuple[int, str], BridgeAdmissionEnvelope] = {}

    def open_credit(msg_hash: str,
                    ingress_adapter: BridgeAdapter = adapter,
                    ledger: SourceBridgeV2 = source) -> str:
        envelope = bridge_message(
            4_601,
            msg_hash,
            message_id=ledger.next_message_id,
            liquidity_fee=(
                3 if msg_hash == "msg-b"
                else 4 if msg_hash == "msg-d2" else 1
            ),
        )
        source_clock = ledger.support_final_clock(prepared_clock.timestamp)
        credit_id = ledger.send_message(
            envelope,
            clock=source_clock, enqueue_by=enqueue_by,
            caller=envelope.sender,
            msg_value=(envelope.bridge_value + envelope.bridge_fee
                       + envelope.bridge_liquidity_fee),
        ).credit_id
        bridge_envelopes[(id(ledger), msg_hash)] = envelope
        return credit_id

    credit_a = open_credit("msg")
    credit_b = open_credit("msg-b")
    credit_a_reused = open_credit("msg-reused")
    credit_d2 = open_credit(
        "msg-d2", ingress_adapter=adapter_d2, ledger=source_d2)
    d1_domain = adapter.destination_domain_id
    d2_domain = adapter_d2.destination_domain_id
    check("P50e fixed source generation still separates exact messages",
          len({credit_a, credit_b, credit_a_reused}) == 3)
    transition_clock = Clock(
        max(
            1_100,
            source.support_final_clock(prepared_clock.timestamp).block_number,
        ),
        GENESIS_TIMESTAMP + 4_601,
    )
    bridge_envelope = bridge_envelopes[(id(source), "msg")]
    bridge_deposit = bridge_envelope.prepaid
    common = dict(
        envelope=bridge_envelope,
        caller="relayer", deposit=bridge_deposit)
    check("P50c router sync persists and fully refunds without an adapter record",
          adapter.enqueue(
              transition_clock, **common) == "SYNCED_REFUNDED"
          and adapter.refunds["relayer"] == bridge_deposit
          and adapter.balance == bridge_deposit
          and adapter.withdraw_refund("relayer") == bridge_deposit
          and adapter.balance == 0 and not adapter.records
          and bridge_protocol.mode is Mode.RECOVERY)
    stamped_protocol = protocol(seat=False)
    stamped_router = routed_ingress_for_test(stamped_protocol)
    stamped_adapter = activate_ingress_adapter_for_test(
        stamped_router, kind=ForceKind.BRIDGE_CREDIT, clock=prepared_clock
    )
    stamp_status, ingress_stamp = stamped_router.sync_ingress(
        clock=prepared_clock, caller_adapter=stamped_adapter
    )
    assert ingress_stamp is not None
    assert stamped_protocol.migration_gate._arm_from_manager(
        1, 1, 2, "manifest:2", caller="version-manager")
    stale_reverted = False
    try:
        stamped_row = message(
            1_100, "stale-stamp", kind=ForceKind.BRIDGE_CREDIT
        )
        stamped_router.append_from_adapter(
            stamped_row,
            clock=prepared_clock,
            stamp=ingress_stamp,
            deposit=stamped_row.prepaid,
            caller_adapter=stamped_adapter,
        )
    except ValueError:
        stale_reverted = True
    check("P50cu payable ingress cannot rerun sync or use a stale stamp",
          stamp_status == "ACTIVE" and stale_reverted
          and stamped_protocol.forced_queue.count == 0)
    check("P50d clean retry queues exactly once and funded duplicates reject",
          adapter.enqueue(
              transition_clock, **common) == "QUEUED:0"
          and adapter.enqueue(
              transition_clock, **{**common, "deposit": 0}) == "QUEUED:0"
          and payable_reverted(lambda: adapter.enqueue(
              transition_clock, **common))
          and len(bridge_protocol.messages) == 1)
    common_b = {
        **common,
        "envelope": bridge_envelopes[(id(source), "msg-b")],
    }
    check("P50g a second exact message queues independently",
          adapter.enqueue(
              transition_clock, **common_b) == "QUEUED:1")
    common_reused = {
        **common,
        "envelope": bridge_envelopes[(id(source), "msg-reused")],
    }
    check("P50h a third exact message queues independently",
          adapter.enqueue(
              transition_clock, **common_reused) == "QUEUED:2"
          and bridge_protocol.forced_queue.escrow_balance
              == 3 * bridge_deposit)
    check("P50af the fresh SourceBridge has no generic sweep exit",
          not hasattr(source, "ordinary_payout")
          and source.balance >= source.total_live_liability)

    domain_credit = open_credit(
        "msg-d2-extra", ingress_adapter=adapter_d2, ledger=source_d2)
    check("P50i destination replacement has a distinct credit identity",
          domain_credit not in {credit_a, credit_b, credit_a_reused})
    check("P50f absent, mismatched, clone and unbounded direct reads reject",
          payable_reverted(lambda: adapter.enqueue(
              transition_clock, **{**common, "envelope": replace(
                  common["envelope"], message=replace(
                      common["envelope"].message, sender="clone")) }))
          and payable_reverted(lambda: adapter.enqueue(
              transition_clock, **{**common, "envelope": replace(
                  common["envelope"], message=replace(
                      common["envelope"].message, message_id=999)) }))
          and payable_reverted(lambda: adapter.enqueue(
              transition_clock, **{**common, "envelope": replace(
                  common["envelope"], message=replace(
                      common["envelope"].message,
                      data=common["envelope"].message.data + b"x")) })))

    invalid_protocol = protocol(tip_slot=100)
    invalid_clock = clock(100, 100)
    invalid_router = routed_ingress_for_test(invalid_protocol)
    invalid_source = source_bridge_for_test(invalid_router)
    invalid_adapter = activate_ingress_adapter_for_test(
        invalid_router, kind=ForceKind.BRIDGE_CREDIT, clock=invalid_clock,
        source_bridge=invalid_source,
    )
    invalid_source_clock = invalid_source.support_final_clock(
        invalid_clock.timestamp
    )
    invalid_envelope = bridge_message(
        invalid_clock.l2_slot, "invalid", value=1, fee=1
    )
    invalid_id = invalid_source.send_message(
        invalid_envelope, clock=invalid_source_clock,
        enqueue_by=invalid_clock.timestamp + MAX_BRIDGE_ENQUEUE_DELAY,
        caller=invalid_envelope.sender,
        msg_value=(invalid_envelope.bridge_value + invalid_envelope.bridge_fee
                   + invalid_envelope.bridge_liquidity_fee),
    ).credit_id
    check("P50j static-invalid credit leaves no queue or adapter state",
          payable_reverted(lambda: invalid_adapter.enqueue(
              invalid_source_clock,
              envelope=replace(
                  invalid_envelope,
                  accounted_gas=MAX_FORCE_MESSAGE_GAS + 1),
              caller="relayer",
              deposit=1))
          and not invalid_protocol.messages and not invalid_adapter.records)

    support_core = CanonicalCore(
        100, "block:registration", 100, "state:registration", 0,
        terminal_root="terminal:registration", terminal_count=0)
    shared_queue = QueueContinuity(
        "forced-queue", model_force_root([]), 0, 0, 0, UINT64_MAX)
    support_inbox_apply = InboxApplyRouterV2(next_queue_index=0)
    support_header_oracle = make_header_oracle([])
    support_profile = execution_profile_for_test(2, "profile:2")
    support_settlement = VersionedSettlementHistory(
        "settlement:2", "runtime:2", 2,
        support_profile.execution_profile_hash,
        copy.deepcopy(support_core), 40, shared_queue,
        execution_profile=support_profile,
        inbox_apply_descriptor=inbox_apply_deployment_descriptor(
            support_inbox_apply
        ),
        header_oracle=support_header_oracle)
    support_router = deploy_active_settlement_router(
        support_settlement,
        "version-manager", shared_queue, support_inbox_apply,
        support_settlement.migration_gate, support_header_oracle)
    assert support_router.bootstrap(
        support_settlement, sequence=7,
        clock=Clock(40, GENESIS_TIMESTAMP + support_core.tip_slot),
        caller=support_router.version_manager)
    support_manager = ProtocolVersionManager(
        support_router.version_manager, support_router
    )
    support_registration = support_router.registrations[
        support_router.active_version
    ]
    support_manifest = support_registration.release_manifest
    support_authorization = support_registration.ingress_authorizations_by_address[
        support_manifest.components[0].address
    ]
    support_authority = ProtocolReleaseAuthorityV2()
    support_anchor = AnchorV4Model(
        support_manifest.anchor,
        support_manifest.anchor_runtime_hash,
        support_manifest.commitment,
    )
    assert support_anchor.authenticate(support_manifest)
    assert support_authority.activate(
        support_manifest,
        caller=support_anchor,
        tx_origin=support_authority.system_sender,
    )
    support = BridgeDomainRegistry(
        support_router,
        support_manager,
        release_authority_descriptor_from_manifest(support_manifest),
        TestRegistrationMptVerifier(
            canonical_registration_mpt_verifier_descriptor()
        ),
    )
    support_domain = support_manifest.destination_domain_id
    support_stage_clock = Clock(40, GENESIS_TIMESTAMP + support_core.tip_slot)
    support_confirm_clock = Clock(
        40 + F_L1, GENESIS_TIMESTAMP + support_core.tip_slot
    )
    assert not support.stage(
        support_authorization.source_domain_id,
        support_authorization.frozen_bridge_execution_hash,
        support_manifest,
        manager=object(),
        clock=support_stage_clock,
    )
    assert not support.stage(
        "domain:substituted",
        support_authorization.frozen_bridge_execution_hash,
        support_manifest,
        manager=support_manager,
        clock=support_stage_clock,
    )
    assert support.stage(
        support_authorization.source_domain_id,
        support_authorization.frozen_bridge_execution_hash,
        support_manifest,
        manager=support_manager,
        clock=support_stage_clock,
    )
    support_statement = support.registration_storage_statement(
        support_authorization.source_domain_id,
        support_authorization.frozen_bridge_execution_hash,
        support_domain,
        canonical_sequence=7,
    )
    assert type(support.registration_mpt_verifier) \
        is TestRegistrationMptVerifier
    valid_support_nodes = issue_registration_mpt_proof_for_test(
        support.registration_mpt_verifier,
        support_statement,
        account_nodes=(b"canonical-account-node-0", b"canonical-account-node-1"),
        storage_nodes=(b"canonical-storage-node-0", b"canonical-storage-node-1"),
    )
    support_proof = dict(
        clock=support_confirm_clock,
        canonical_sequence=7,
        proof=valid_support_nodes,
    )
    assert not support.final(
        support_authorization.source_domain_id,
        support_authorization.frozen_bridge_execution_hash,
        support_domain,
        support_confirm_clock,
    )
    assert not support.confirm(
        support_authorization.source_domain_id,
        support_authorization.frozen_bridge_execution_hash,
        support_domain,
        **{**support_proof, "proof": replace(
            valid_support_nodes, _test_seal="attacker-seal"
        )})
    wrong_root_nodes = issue_registration_mpt_proof_for_test(
        support.registration_mpt_verifier,
        replace(support_statement, state_root="attacker-root"),
    )
    wrong_value_nodes = issue_registration_mpt_proof_for_test(
        support.registration_mpt_verifier,
        replace(
            support_statement,
            expected_value=b"x" * 32,
        ),
    )
    oversized_nodes = CanonicalMptMembershipProof(
        tuple(
            b"x" for _ in range(MAX_REGISTRATION_PROOF_NODES)
        ),
        (b"y",),
    )
    oversized_node = CanonicalMptMembershipProof(
        (b"x" * (MAX_REGISTRATION_PROOF_NODE_BYTES + 1),),
        (b"y",),
    )
    oversized_total = CanonicalMptMembershipProof(
        tuple(b"x" * MAX_REGISTRATION_PROOF_NODE_BYTES for _ in range(79)),
        (b"y",),
    )
    support.registration_mpt_verifier.returndata_override = b"x" * 31
    short_mpt_return_rejected = not support.confirm(
        support_authorization.source_domain_id,
        support_authorization.frozen_bridge_execution_hash,
        support_domain,
        **support_proof,
    )
    support.registration_mpt_verifier.returndata_override = b"x" * 33
    long_mpt_return_rejected = not support.confirm(
        support_authorization.source_domain_id,
        support_authorization.frozen_bridge_execution_hash,
        support_domain,
        **support_proof,
    )
    support.registration_mpt_verifier.returndata_override = None
    support.registration_mpt_verifier.raise_on_verify = True
    mpt_revert_rejected = not support.confirm(
        support_authorization.source_domain_id,
        support_authorization.frozen_bridge_execution_hash,
        support_domain,
        **support_proof,
    )
    support.registration_mpt_verifier.raise_on_verify = False
    check("P50bf registration proof is bound to routed state and exact bounds",
          short_mpt_return_rejected
          and long_mpt_return_rejected
          and mpt_revert_rejected
          and not support.confirm(
              support_authorization.source_domain_id,
              support_authorization.frozen_bridge_execution_hash,
              support_domain,
              **{**support_proof, "proof": wrong_root_nodes})
          and not support.confirm(
              support_authorization.source_domain_id,
              support_authorization.frozen_bridge_execution_hash,
              support_domain,
              **{**support_proof, "proof": oversized_nodes})
          and not support.confirm(
              support_authorization.source_domain_id,
              support_authorization.frozen_bridge_execution_hash,
              support_domain,
              **{**support_proof, "proof": oversized_node})
          and not support.confirm(
              support_authorization.source_domain_id,
              support_authorization.frozen_bridge_execution_hash,
              support_domain,
              **{**support_proof, "proof": oversized_total})
          and not support.confirm(
              support_authorization.source_domain_id,
              support_authorization.frozen_bridge_execution_hash,
              support_domain,
              **{**support_proof, "proof": wrong_value_nodes}))
    assert support.confirm(
        support_authorization.source_domain_id,
        support_authorization.frozen_bridge_execution_hash,
        support_domain,
        **support_proof)
    support_final_clock = Clock(
        support_confirm_clock.block_number + SUPPORT_FINALITY_BLOCKS,
        support_confirm_clock.timestamp,
    )
    check("P50u bridge endpoint support waits for active-profile finality",
          not support.final(
              support_authorization.source_domain_id,
              support_authorization.frozen_bridge_execution_hash,
              support_domain,
              replace(
                  support_final_clock,
                  block_number=support_final_clock.block_number - 1,
              ))
          and support.final(
              support_authorization.source_domain_id,
              support_authorization.frozen_bridge_execution_hash,
              support_domain,
              support_final_clock))
    check("P50an source execution and destination substitutions fail closed",
          not support.stage(
              support_authorization.source_domain_id,
              "execution:substituted",
              support_manifest,
              manager=support_manager,
              clock=support_stage_clock)
          and support.final_entry(
              support_authorization.source_domain_id,
              support_authorization.frozen_bridge_execution_hash,
              "domain:substituted",
              support_final_clock) is None)
